#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char filename[256];
    int width;
    int height;
} ImageMetaData;

ImageMetaData* create_image_metadata_array(int num_images) {
    if (num_images <= 0) {
        fprintf(stderr, "Error: Number of images must be greater than zero.\n");
        return NULL;
    }

    // Calculate the required memory size
    size_t total_size = num_images * sizeof(ImageMetaData);
    if (total_size / sizeof(ImageMetaData) != num_images) {
        fprintf(stderr, "Error: Integer overflow detected during memory allocation calculation.\n");
        return NULL;
    }

    ImageMetaData* metadata_array = (ImageMetaData*)malloc(total_size);
    if (!metadata_array) {
        fprintf(stderr, "Memory allocation failed. Retrying with reduced batch size...\n");

        // Retry logic
        int retry_count = 0;
        const int max_retries = 5;
        while (!metadata_array && retry_count < max_retries) {
            num_images /= 2; // Reduce the batch size by half each time
            total_size = num_images * sizeof(ImageMetaData);
            if (total_size / sizeof(ImageMetaData) != num_images) {
                fprintf(stderr, "Error: Integer overflow detected during memory allocation calculation.\n");
                return NULL;
            }
            metadata_array = (ImageMetaData*)malloc(total_size);
            retry_count++;
        }

        if (!metadata_array) {
            fprintf(stderr, "Memory allocation failed after multiple attempts. Exiting...\n");
            return NULL;
        }
    }

    // Initialize the metadata array
    for (int i = 0; i < num_images; i++) {
        printf("Enter details for image %d:\n", i + 1);
        printf("Filename: ");
        fgets(metadata_array[i].filename, sizeof(metadata_array[i].filename), stdin);
        metadata_array[i].filename[strcspn(metadata_array[i].filename, "\n")] = '\0'; // Remove newline

        int width, height;
        do {
            printf("Width (positive integer): ");
            scanf("%d", &width);
        } while (width <= 0);
        metadata_array[i].width = width;

        do {
            printf("Height (positive integer): ");
            scanf("%d", &height);
        } while (height <= 0);
        metadata_array[i].height = height;
    }

    return metadata_array;
}

void free_image_metadata_array(ImageMetaData* array) {
    if (array) {
        free(array);
    }
}

int main() {
    int num_images;
    printf("Enter the number of images: ");
    scanf("%d", &num_images);

    ImageMetaData* metadata = create_image_metadata_array(num_images);
    if (metadata) {
        // Process the image metadata
        for (int i = 0; i < num_images; i++) {
            printf("Image %d - Filename: %s, Width: %d, Height: %d\n", i + 1, metadata[i].filename, metadata[i].width, metadata[i].height);
        }
        free_image_metadata_array(metadata);
    }

    return 0;
}
```

