#define MIN_INT 0
#define MAX_INT 1000

typedef struct {
    int value;
} record;

long* allocate_long_array(size_t size) {
    long* array = (long*)calloc(size, sizeof(long));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* allocate_int_array(size_t size) {
    int* array = (int*)calloc(size, sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

record* allocate_record_array(size_t size) {
    record* array = (record*)calloc(size, sizeof(record));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

uint64_t read_entropy() {
    FILE* urandom = fopen("/dev/urandom", "rb");
    if (!urandom) {
        perror("Failed to open /dev/urandom");
        exit(EXIT_FAILURE);
    }
    uint64_t entropy;
    fread(&entropy, sizeof(entropy), 1, urandom);
    fclose(urandom);
    return entropy;
}

uint64_t xorshift128plus(uint64_t* state) {
    uint64_t x = state[0];
    uint64_t y = state[1];
    x ^= x << 23;
    y ^= y ^ (x >> 17);
    y ^= y << 5;
    state[0] = y;
    return y + x;
}

void fill_record_array(record* array, size_t size, uint64_t* prng_state) {
    for (size_t i = 0; i < size; ++i) {
        array[i].value = xorshift128plus(prng_state) % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }
}

void free_arrays(long* long_array, int* int_array, record* record_array, size_t size) {
    free(long_array);
    free(int_array);
    free(record_array);
}

int main() {
    size_t long_size = 1024;
    size_t int_size = 1024;
    size_t record_size = 1024;

    long* long_array = allocate_long_array(long_size);
    int* int_array = allocate_int_array(int_size);
    record* record_array = allocate_record_array(record_size);

    uint64_t prng_state[2] = {read_entropy(), read_entropy()};
    fill_record_array(record_array, record_size, prng_state);

    free_arrays(long_array, int_array, record_array, record_size);

    return 0;
}
