    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%d,%s\n", line_number, content);
    fclose(log);
}

int process_file(const char* input_file, const char* output_file, int verbose) {
    FILE* in = fopen(input_file, "r");
    if (in == NULL) {
        perror("Failed to open input file");
        return 1;
    }

    if (output_file != NULL) {
        // Open output file for processing
    } else {
        // Use standard output for processing
    }

    char buffer[4096];
    int line_number = 0;

    while (fgets(buffer, sizeof(buffer), in) != NULL && line_number < MAX_LINES) {
        line_number++;
        if (verbose) {
            log_line(line_number, buffer);
        }
        // Process the line
    }

    fclose(in);

    return 0;
}

int main(int argc, char* argv[]) {
    const char* input_file = NULL;
    const char* output_file = NULL;
    int verbose = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            usage();
            return 0;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (input_file == NULL) {
        usage();
        return 1;
    }

    return process_file(input_file, output_file, verbose);
}
