#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Helper function to find and print the largest integer in the array
void printLargest(int *arr, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }
    int max = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to read integers from standard input, validating and allocating memory
int *readIntegers(int *size) {
    int *array = NULL;
    *size = 0;
    int capacity = 16; // Initial capacity, can be adjusted based on performance needs
    array = (int *)malloc(capacity * sizeof(int));

    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter integers (-1000 to 1000), enter a non-integer to stop:\n");

    while (1) {
        int num;
        if (scanf("%d", &num) != 1) {
            break; // Stop reading on non-integer input
        }
        if (num < -1000 || num > 1000) {
            printf("Integer out of range. Please enter a valid integer.\n");
            continue;
        }

        array[(*size)++] = num;

        // Resize array if needed
        if (*size == capacity) {
            capacity *= 2;
            int *newArray = (int *)realloc(array, capacity * sizeof(int));
            if (!newArray) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(array);
                exit(EXIT_FAILURE);
            }
            array = newArray;
        }
    }

    // Resize array to exact size
    array = (int *)realloc(array, (*size) * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    return array;
}

int main() {
    int size;
    int *numbers = readIntegers(&size);

    if (numbers) {
        printLargest(numbers, size);
        free(numbers);
    }

    return 0;
}
```

### Explanation of the Code:

1. **`readIntegers` Function**:
   - Dynamically allocates memory to store integers.
   - Reads integers from standard input until a non-integer is encountered or an integer out of the specified range is entered.
   - Uses `realloc` to resize the array when more space is needed, reducing the number of allocations and minimizing fragmentation.

2. **`printLargest` Function**:
   - Iterates through the array to find and print the largest integer.
   - Handles cases where the array might be empty.

3. **Memory Management**:
   - Initializes with an initial capacity and doubles it as needed, which is efficient for dynamically growing arrays without a large upfront cost.
   - Frees the allocated memory after use to prevent memory leaks.

4. **Error Handling**:
   - Checks for successful memory allocations using `malloc` and `realloc`.
   - Exits gracefully with error messages if memory allocation fails.

5. **Integration and Usability**:
   - Designed as a standalone function that can be easily integrated into any C codebase.
   - Provides clear output indicating the largest integer found or handling edge cases like an empty array.

This implementation balances efficiency, usability, and maintainability while ensuring robust error handling and effective memory management.']

