#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_IP_LEN 16
#define ERROR_LOG "error.log"

typedef struct {
    unsigned char ip[4];
} HostInfo;

int validate_ip(const char *ip) {
    struct in_addr addr;
    return inet_pton(AF_INET, ip, &addr) > 0;
}

HostInfo* create_host_info(const char *ip) {
    if (!validate_ip(ip)) {
        FILE *log = fopen(ERROR_LOG, "a");
        fprintf(log, "Invalid IP address: %s\n", ip);
        fclose(log);
        return NULL;
    }

    HostInfo *host_info = (HostInfo*)malloc(sizeof(HostInfo));
    if (!host_info) {
        FILE *log = fopen(ERROR_LOG, "a");
        fprintf(log, "Memory allocation failed\n");
        fclose(log);
        return NULL;
    }

    struct in_addr addr;
    inet_pton(AF_INET, ip, &addr);
    memcpy(host_info->ip, &addr.s_addr, sizeof(addr.s_addr));

    return host_info;
}

void destroy_host_info(HostInfo *host_info) {
    free(host_info);
}
