import hashlib

def process_large_binary_file(file_path, chunk_size=4096, reference_hash=None):
    hasher = hashlib.sha256()

    try:
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                hasher.update(data)

        computed_hash = hasher.hexdigest()

        if reference_hash and computed_hash != reference_hash:
            raise ValueError("Hash mismatch")

        return computed_hash

    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {file_path} was not found.")

    except PermissionError:
        raise PermissionError(f"Permission denied to read the file at {file_path}.")

    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the file: {e}")

# Example usage
file_path = 'large_binary_file.bin'
reference_hash = 'expected_sha256_hash_here'
try:
    result_hash = process_large_binary_file(file_path, reference_hash=reference_hash)
    print(f"Computed SHA-256 hash: {result_hash}")
except Exception as e:
    print(e)
```

This code snippet defines a function `process_large_binary_file` that reads a large binary file in chunks and computes the SHA-256 hash. It handles potential memory constraints by processing only a specified chunk size at a time, ensuring efficient memory usage. The function also includes error handling for common issues like file not found or permission denied. The computed hash is compared against a provided reference hash if one is given, raising an exception if they do not match.']

