        scheduleCacheUpdate();
    }

    private void scheduleCacheUpdate() {
        scheduler.scheduleAtFixedRate(this::updateCache, CACHE_UPDATE_INTERVAL, CACHE_UPDATE_INTERVAL, TimeUnit.MINUTES);
    }

    private Map<String, String> updateCache() {
        // Logic to update the cache with the latest type weaknesses
        return loadTypeWeaknessesFromExternalSource();
