        CompletableFuture<String> nameFuture = fetchPokemonDetails(pokemonName);
        CompletableFuture<Map<String, String>> weaknessesFuture = CompletableFuture.supplyAsync(this::loadTypeWeaknessesFromCache);

        return CompletableFuture.allOf(nameFuture, weaknessesFuture)
                .thenApply(v -> {
                    try {
                        String name = nameFuture.get();
                        Map<String, String> typeWeaknesses = weaknessesFuture.get();

                        // Use a switch statement to determine the weaknesses based on the Pokemon's type
                        String weakness = determineWeakness(pokemonName, typeWeaknesses);

                        return "Report for " + name + ": Weakness is " + weakness;
                    } catch (Exception e) {
                        return "Error generating report: " + e.getMessage();
                    }
                });
    }

    private CompletableFuture<String> fetchPokemonDetails(String pokemonName) {
        // Asynchronously retrieve the Pokemon's name and type from an external API endpoint
        return CompletableFuture.supplyAsync(() -> {
            try {
                String url = API_ENDPOINT.replace("{pokemonName}", pokemonName);
                // Logic to make HTTP request to the API and parse the response
                return "Eevee"; // Mocked result for demonstration
            } catch (Exception e) {
                // Handle network delays and potential connectivity issues gracefully
                return null;
            }
        });
    }

    private String determineWeakness(String pokemonName, Map<String, String> typeWeaknesses) {
        // Use a switch statement to determine the weaknesses based on the Pokemon's type
        // Design the switch statement to be extensible and maintainable
        try {
            return typeWeaknesses.get(pokemonName);
        } catch (Exception e) {
            // Implement error handling for potential exceptions during API calls and cache updates
            return "Unknown";
        }
    }

    public void shutdown() {
        scheduler.shutdown();
    }
}
