use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use url::Url;

#[derive(Debug)]
struct Endpoint {
    url: Url,
    credentials: Option<String>,
}

fn process_config_file(file_path: &str) -> Result<Vec<Endpoint>, String> {
    let mut endpoints = Vec::new();
    let content = match std::fs::read_to_string(file_path) {
        Ok(content) => content,
        Err(e) => return Err(format!("Failed to read file: {}", e)),
    };

    for line in content.lines() {
        if let Some((url, credentials)) = parse_endpoint(line) {
            if url.host_str().is_none() {
                return Err("Invalid URL format".to_string());
            }
            endpoints.push(Endpoint { url, credentials });
        } else {
            return Err("Invalid endpoint format".to_string());
        }
    }

    Ok(endpoints)
}

fn parse_endpoint(line: &str) -> Option<(Url, Option<String>)> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() < 1 {
        return None;
    }

    let url_str = parts[0];
    if let Ok(url) = Url::parse(url_str) {
        let credentials = parts.get(1).map(|c| c.to_string());
        Some((url, credentials))
    } else {
        None
    }
}

fn main() {
    match process_config_file("endpoints.txt") {
        Ok(endpoints) => println!("Endpoints: {:?}", endpoints),
        Err(e) => eprintln!("Error: {}", e),
    }
}
```

