['```cpp
#include <iostream>
#include <memory>

struct Node {
    int value;
    std::shared_ptr<Node> next;
    std::shared_ptr<Node> prev;

    Node(int val) : value(val), next(nullptr), prev(nullptr) {}
};

void insertOrAppend(std::shared_ptr<Node>& head, int targetValue, int newValue) {
    if (!head) {
        throw std::runtime_error("List is empty.");
    }

    std::shared_ptr<Node> current = head;
    while (current) {
        if (current->value == targetValue) {
            auto newNode = std::make_shared<Node>(newValue);
            newNode->next = current->next;
            newNode->prev = current;
            if (current->next) {
                current->next->prev = newNode;
            }
            current->next = newNode;
            return;
        }
        current = current->next;
    }

    auto newNode = std::make_shared<Node>(newValue);
    newNode->prev = current;
    if (current) {
        current->next = newNode;
    } else {
        head = newNode; // List was empty
    }
}

int main() {
    try {
        auto head = std::make_shared<Node>(1);
        insertOrAppend(head, 1, 2);
        insertOrAppend(head, 2, 3);
        insertOrAppend(head, 4, 5);

        auto current = head;
        while (current) {
            std::cout << current->value << " ";
            current = current->next;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
