using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DynamicQueryBuilder
{
    public static string ConstructQuery(List<string> columns, List<string> tables, List<string> joinConditions, List<SearchCriteria> searchCriteria)
    {
        StringBuilder query = new StringBuilder();
        query.Append("SELECT ");
        query.Append(string.Join(", ", columns));
        query.Append(" FROM ");
        query.Append(string.Join(" INNER JOIN ", tables));
        if (joinConditions.Count > 0)
        {
            query.Append(" WHERE ");
            query.Append(string.Join(" AND ", joinConditions));
        }
        foreach (var criteria in searchCriteria)
        {
            query.Append(" AND ");
            query.Append(criteria.Field);
            query.Append(" = @");
            query.Append(criteria.ParameterName);
        }
        return query.ToString();
    }

    public static void ExecuteQuery(SqlConnection connection, List<SearchCriteria> searchCriteria, params object[] parameters)
    {
        string query = ConstructQuery(new List<string> { "*" }, new List<string> { "Table1" }, new List<string> { "Table1.TableId = Table2.TableId" }, searchCriteria);
        using (SqlCommand command = new SqlCommand(query, connection))
        {
            for (int i = 0; i < parameters.Length; i++)
            {
                command.Parameters.AddWithValue($"@Param{i}", parameters[i]);
            }
            try
            {
                connection.Open();
                SqlDataReader reader = command.ExecuteReader(CommandBehavior.CloseConnection);
                while (reader.Read())
                {
                    // Process the data here
                }
            }
            catch (SqlException ex)
            {
                Console.WriteLine("SQL Error: " + ex.Message);
            }
        }
    }

    public static void LogExecutionTime(Action action)
    {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.Start();
        action();
        stopwatch.Stop();
        Console.WriteLine($"Query Execution Time: {stopwatch.ElapsedMilliseconds} ms");
    }
}

public class SearchCriteria
{
    public string Field { get; set; }
    public string ParameterName { get; set; }
}
```

