        **data,
        'id': resource_id,
        'last_modified': '2021-04-30T12:00:00Z'
    }

    # Rate limiting (simple example)
    if redis_client.incr(f"request_count:{resource_id}") > 5:
        return jsonify({"error": "Rate limit exceeded"}), 429

    # Simulate external validation
    response = requests.post(external_service_url, json=updated_resource)
    if response.status_code != 200:
        return jsonify({"error": "External validation failed"}), 503

    redis_client.set(f"resource:{resource_id}", str(updated_resource))
