using System;
using System.IO;
using System.Xml.XPath;

public class XmlHelper
{
    public static XPathNavigator GetFirstMatchingElement(string xmlDocument, string elementName)
    {
        if (string.IsNullOrEmpty(xmlDocument) || string.IsNullOrEmpty(elementName))
        {
            throw new ArgumentException("XML document and element name cannot be null or empty.");
        }

        var navigator = XPathDocument.Create(new System.IO.StringReader(xmlDocument)).CreateNavigator();
        var nodeIterator = navigator.Select($"//{elementName}");

        if (!nodeIterator.MoveNext())
        {
            throw new InvalidOperationException($"No elements found with the name '{elementName}'.");
        }

        if (nodeIterator.MoveNext())
        {
            throw new InvalidOperationException($"Multiple elements found with the name '{elementName}'.");
        }

        return nodeIterator.Current;
    }
}

public class EnvironmentHelper
{
    public static void CreateAndSetDirectory(string environmentVariable, string directoryName)
    {
        if (string.IsNullOrEmpty(environmentVariable) || string.IsNullOrEmpty(directoryName))
        {
            throw new ArgumentException("Environment variable and directory name cannot be null or empty.");
        }

        if (!Environment.GetEnvironmentVariable(environmentVariable) is string existingPath)
        {
            var path = Path.Combine(Environment.CurrentDirectory, directoryName);
            try
            {
                Directory.CreateDirectory(path);
            }
            catch (IOException ex)
            {
                throw new IOException($"Failed to create directory: {ex.Message}", ex);
            }

            Environment.SetEnvironmentVariable(environmentVariable, path);
        }
        else if (!Directory.Exists(existingPath))
        {
            throw new InvalidOperationException($"The environment variable '{environmentVariable}' is set but the directory does not exist.");
        }
    }
}
