public class WebPageService
{
    private readonly HttpClient _httpClient;
    private readonly AuthService _authService;

    public WebPageService(HttpClient httpClient, AuthService authService)
    {
        _httpClient = httpClient;
        _authService = authService;
    }

    public async Task<HttpResponseMessage> UpdateElementContentAsync(string pageSectionId, string elementId, string htmlContent, string userId)
    {
        // Validate inputs
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent) || string.IsNullOrEmpty(userId))
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.BadRequest);
        }

        if (!_authService.HasPermission(userId, pageSectionId, "Update"))
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.Forbidden);
        }

        try
        {
            // Update HTML content using a service layer
            string updatedHtmlContent = await ServiceLayer.UpdateElementAsync(pageSectionId, elementId, htmlContent);

            // Compress the updated HTML content
            byte[] compressedHtmlBytes = CompressString(updatedHtmlContent);
            int originalLength = updatedHtmlContent.Length;
            int compressedLength = compressedHtmlBytes.Length;

            // Calculate compression ratio
            double compressionRatio = (double)compressedLength / originalLength * 100;

            // Construct response content
            var responseContent = new StringContent($"{{\"success\":true,\"updatedContentLength\":{originalLength},\"compressionRatio\":{compressionRatio}%}}");
            responseContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");

            return new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = responseContent };
        }
        catch (Exception ex)
        {
            // Log detailed error information
            Console.WriteLine($"Error updating element content: {ex}");

            // Provide meaningful error messages to the client
            return new HttpResponseMessage(System.Net.HttpStatusCode.InternalServerError) 
            { 
                Content = new StringContent("{\"success\":false,\"error\":\"Internal server error\"}") 
            };
        }
    }

    private static byte[] CompressString(string s)
    {
        using (var compressedStream = new MemoryStream())
        using (var gzipStream = new GZipStream(compressedStream, CompressionMode.Compress))
        {
            var bytes = System.Text.Encoding.UTF8.GetBytes(s);
            gzipStream.Write(bytes, 0, bytes.Length);
            gzipStream.Close();
            return compressedStream.ToArray();
        }
    }
}

