    private Map<String, Bitmap> themeCache = new HashMap<>();

    public MoSTState loadStateFromFile(String filePath) {
        File file = new File(filePath);
        if (file.exists() && file.canRead()) {
            try (FileInputStream fis = new FileInputStream(file)) {
                Object obj = deserialize(fis);
                if (obj instanceof MoSTState) {
                    return (MoSTState) obj;
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }
        }
        return null;
    }

    private Object deserialize(FileInputStream fis) throws IOException, ClassNotFoundException {
        // Implementation of deserialization logic
        return new Object(); // Placeholder
    }

    public void addToThemeCache(String key, Bitmap bitmap) {
        themeCache.put(key, bitmap);
    }

    public Bitmap getFromThemeCache(String key) {
        Bitmap bitmap = themeCache.get(key);
        if (bitmap != null && System.currentTimeMillis() - bitmap.getLastUsedTime() > THEME_CACHE_EXPIRY_MS) {
            themeCache.remove(key);
            bitmap.recycle();
            bitmap = null;
        }
        return bitmap;
    }

    public void initializeDefaultThemeDir() {
        File defaultDir = new File(DEFAULT_THEME_DIR);
        if (!defaultDir.exists()) {
            defaultDir.mkdir();
        }
    }

    public Bitmap parsePngFile(String cacheRootDir, String fileName) {
        File pngFile = new File(cacheRootDir + "/" + fileName);
        try {
            return BitmapFactory.decodeStream(new FileInputStream(pngFile));
        } catch (FileNotFoundException e) {
            e.printStackTrace();
            return null;
        }
    }
