// Constants defining categories using regular expressions
const CATEGORY_CONSTANTS = {
    ELECTRONICS: /electronics/i,
    CLOTHING: /clothing/i,
    BOOKS: /books/i
};

// Cache for product data to optimize load times
let productCache = {};

async function fetchProducts(query) {
    try {
        const response = await fetch('https://api.example.com/products');
        if (!response.ok) throw new Error('Network response was not ok');
        return await response.json();
    } catch (error) {
        console.error('Error fetching products:', error);
        return [];
    }
}

function filterAndSortProducts(products, query) {
    const { category, sort } = parseQuery(query);

    // Filter products based on category
    let filteredProducts = products.filter(product => 
        CATEGORY_CONSTANTS[category] && CATEGORY_CONSTANTS[category].test(product.name)
    );

    // Sort products by name or another criterion if specified
    if (sort === 'name') {
        filteredProducts.sort((a, b) => a.name.localeCompare(b.name));
    }

    return filteredProducts;
}

function parseQuery(queryString) {
    const queryParams = new URLSearchParams(queryString);
    return {
        category: queryParams.get('category') || 'ALL',
        sort: queryParams.get('sort') || 'name'
    };
}

async function processProductQuery(query) {
    if (productCache[query]) {
        console.log('Using cached data');
        return filterAndSortProducts(productCache[query], query);
    }

    const products = await fetchProducts();
    productCache[query] = products;
    return filterAndSortProducts(products, query);
}

// Example usage
processProductQuery('?category=electronics&sort=name').then(console.log);
