function generateFooter(sections) {
  if (!Array.isArray(sections) || sections.length === 0) {
    console.error('Invalid input: sections must be a non-empty array');
    return '<footer></footer>';
  }

  const defaultSection = { html: '© Year Your Company' };
  const safeHtml = (html) => {
    if (typeof html !== 'string') return '';
    // Basic sanitization, replace < and > with &lt; and &gt;
    return html.replace(/</g, '&lt;').replace(/>/g, '&gt;');
  };

  const renderSection = async (section) => {
    try {
      if (section.fetchUrl) {
        const response = await fetch(section.fetchUrl);
        section.html = await response.text();
      }
      return `<div ${Object.entries(section.attributes || {}).map(([key, value]) => `${key}="${value}"`).join(' ')}>${safeHtml(section.html)}</div>`;
    } catch (error) {
      console.error(`Error fetching or rendering section: ${error.message}`);
      return '';
    }
  };

  const promises = sections.map(async (section) => renderSection({ ...defaultSection, ...section }));
  const renderedSections = await Promise.all(promises);

  return `<footer>${renderedSections.join('')}</footer>`;
}
