app.controller('DialogController', ['$scope', '$http', 'fieldService', function($scope, $http, fieldService) {
    $scope.refreshFields = function(resourceId, url, fieldsToRefresh) {
        var forwardList = [];
        for (var i = 0; i < fieldsToRefresh.length; i++) {
            forwardList.push(fieldsToRefresh[i]);
        }

        while (forwardList.length > 0) {
            var fieldName = forwardList.shift();
            $scope.$parent.refreshField(fieldName, resourceId).then(function(response) {
                if (response.data.status === 'success') {
                    $scope[fieldName] = response.data.value;
                }
            }).catch(function(error) {
                console.error('Error refreshing field:', error);
            });
        }
    };
}]);

// Define a service to handle the communication with the parent window
app.service('fieldService', ['$window', function($window) {
    this.refreshField = function(fieldName, resourceId) {
        return new Promise(function(resolve, reject) {
            $window.parent.postMessage({
                type: 'refreshField',
                fieldName: fieldName,
                resourceId: resourceId
            }, '*');

            window.addEventListener('message', function(event) {
                if (event.origin !== event.source.location.origin) {
                    return;
                }
                if (event.data.type === 'fieldRefreshed' && event.data.fieldName === fieldName) {
                    resolve({ status: event.data.status, value: event.data.value });
                }
            }, false);
        });
    };
}]);
