import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class StreamProcessor {
    private final ConcurrentHashMap<String, Boolean> streamStates = new ConcurrentHashMap<>();
    private static final Logger LOGGER = Logger.getLogger(StreamProcessor.class.getName());
    private int maxConcurrentStreams;
    private int currentStreams;

    public StreamProcessor(int maxConcurrentStreams) {
        this.maxConcurrentStreams = maxConcurrentStreams;
    }

    public void startStream(String streamId) {
        if (currentStreams >= maxConcurrentStreams) {
            LOGGER.warning("Maximum concurrent streams reached. Cannot start new stream.");
            return;
        }
        synchronized (streamStates) {
            if (!streamStates.containsKey(streamId)) {
                streamStates.put(streamId, true);
                currentStreams++;
                LOGGER.info("Stream " + streamId + " started. Current active streams: " + currentStreams);
            } else {
                LOGGER.warning("Stream " + streamId + " is already active.");
            }
        }
    }

    public void pauseStream(String streamId) {
        synchronized (streamStates) {
            if (streamStates.containsKey(streamId)) {
                streamStates.put(streamId, false);
                LOGGER.info("Stream " + streamId + " paused.");
            } else {
                LOGGER.warning("Stream " + streamId + " is not active.");
            }
        }
    }

    public void resumeStream(String streamId) {
        synchronized (streamStates) {
            if (streamStates.containsKey(streamId)) {
                if (!streamStates.get(streamId)) {
                    streamStates.put(streamId, true);
                    LOGGER.info("Stream " + streamId + " resumed.");
                } else {
                    LOGGER.warning("Stream " + streamId + " is already running.");
                }
            } else {
                LOGGER.warning("Stream " + streamId + " not found. Cannot resume.");
            }
        }
    }

    public void stopStream(String streamId) {
        synchronized (streamStates) {
            if (streamStates.containsKey(streamId)) {
                streamStates.remove(streamId);
                currentStreams--;
                LOGGER.info("Stream " + streamId + " stopped. Current active streams: " + currentStreams);
            } else {
                LOGGER.warning("Stream " + streamId + " not found.");
            }
        }
    }

    public boolean isStreamActive(String streamId) {
        return streamStates.getOrDefault(streamId, false);
    }
}
