const net = require('net');
const { pipeline } = require('stream/promises');

async function readFromNetworkStream(host, port, bytesToRead) {
    return new Promise((resolve, reject) => {
        const client = net.connect(port, host, () => {
            const buffer = Buffer.alloc(bytesToRead);
            let bytesRead = 0;

            client.on('data', (chunk) => {
                chunk.copy(buffer, bytesRead);
                bytesRead += chunk.length;
                if (bytesRead === bytesToRead) {
                    resolve(buffer);
                }
            });

            client.on('end', () => {
                reject(new Error('Connection closed before expected'));
            });

            client.on('error', (err) => {
                reject(err);
            });
        });

        client.on('close', () => {
            client.destroy();
        });
    });
}

async function writeBufferToStream(stream, buffer) {
    return new Promise((resolve, reject) => {
        pipeline(buffer, stream)
            .then(() => resolve())
            .catch(reject);
    });
}

async function processNetworkData(host, port, bytesToRead) {
