        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(logFile, "[%s] Starting modification of file: %s\n", timestamp, filename);

    int semicolonCount = 0;
    for (int i = 0; filename[i]; i++) {
        if (filename[i] == ';') {
            semicolonCount++;
        }
    }

    char newFilename[256];
    snprintf(newFilename, sizeof(newFilename), "%s.%d.js", filename, semicolonCount);

    fprintf(logFile, "[%s] New filename: %s\n", timestamp, newFilename);
    fclose(logFile);
}

void executeJavaScriptFile(const char* filename) {
    FILE *logFile = fopen("execution_log.txt", "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(logFile, "[%s] Starting execution of file: %s\n", timestamp, filename);

    if (access(filename, F_OK) != 0) {
        fprintf(logFile, "[%s] Error: File not found.\n", timestamp);
        return;
    }

    // Simulate JavaScript execution
    int result = system(filename);
    if (result == -1) {
        fprintf(logFile, "[%s] Error: Failed to execute file.\n", timestamp);
    } else {
        fprintf(logFile, "[%s] File executed successfully.\n", timestamp);
    }

    fclose(logFile);
}

int main() {
    modifyJavaScriptFile("example.js");
    executeJavaScriptFile("modified_example.1.js");
    return 0;
}
