import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class SessionIDGenerator {
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private static final ConcurrentMap<Integer, String> SESSION_MAP = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        int userId = 12345; // Example user ID
        String sessionId = generateSessionId(userId);
        System.out.println("Generated Session ID: " + sessionId);

        // Simulate session validation
        validateSessionId(userId, sessionId);
    }

    public static String generateSessionId(int userId) {
        long startTime = System.currentTimeMillis();
        byte[] randomBytes = new byte[32]; // 256 bits for 64 characters
        SECURE_RANDOM.nextBytes(randomBytes);

        String sessionId = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes).substring(0, 64);

        SESSION_MAP.put(userId, sessionId);

        long endTime = System.currentTimeMillis();
        long timeTaken = endTime - startTime;
        System.out.println("Time taken to generate session ID: " + timeTaken + " ms");

        return sessionId;
    }

    public static void validateSessionId(int userId, String sessionId) {
        if (SESSION_MAP.get(userId).equals(sessionId)) {
            System.out.println("Session ID validation successful.");
        } else {
            System.out.println("Session ID validation failed.");
        }
    }
}
