            System.out.println("Service stopped");
            sendStopMessage();
        } catch (Exception e) {
            logError("Failed to stop service", e);
        }
    }

    private void sendStopMessage() {
        for (MessagingSystem system : messagingSystems) {
            try {
                system.sendMessage("ServiceStopped");
                return; // Send to first successful system
            } catch (Exception e) {
                // Log error and continue to next system
            }
        }
        logError("Failed to send stop message", new Exception("All systems failed"));
    }

    private void logError(String message, Exception e) {
        System.err.println(message + " - " + e.getMessage());
    }

    public static void main(String[] args) {
        MessagingSystem[] systems = {
            new KafkaMessagingSystem(),
            new RabbitMQMessagingSystem()
        };
        ServiceManager manager = new ServiceManager(systems);
        manager.startService();
        try {
            Thread.sleep(5000); // Let service run for 5 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        manager.stopService();
    }
}

