['```rust
use hyper::{
    client::{Client, HttpConnector},
    body::Body,
    http::{Request, Method},
    Body as HyperBody, Uri,
};
use hyper_tls::HttpsConnector;
use log::{info, error};
use std::{
    collections::{HashMap, HashSet},
    sync::Mutex,
    time::{Duration, Instant},
};

struct CustomClient {
    client: Client<HttpConnector>,
    ca_bundle_path: String,
    cert_cache: Mutex<HashMap<String, bool>>,
    rate_limit: RateLimiter,
}

struct RateLimiter {
    limits: HashMap<String, (Instant, u32)>,
    max_requests_per_minute: u32,
}

impl CustomClient {
    fn new(ca_bundle_path: String, max_requests_per_minute: u32) -> Self {
        let https = HttpsConnector::new_with_native_certs().unwrap();
        let client = Client::builder()
            .build::<_, HyperBody>(https);
        CustomClient {
            client,
            ca_bundle_path,
            cert_cache: Mutex::new(HashMap::new()),
            rate_limit: RateLimiter {
                limits: HashMap::new(),
                max_requests_per_minute,
            },
        }
    }

    fn create_request_builder(&self, url: &str) -> RequestBuilder {
        let uri = Uri::from_str(url).unwrap();
        Request::builder()
            .method(Method::GET)
            .uri(uri)
            .body(Body::empty())
            .unwrap()
    }

    async fn send_request(
        &self,
        request: Request<Body>,
    ) -> Result<Response<HyperBody>, hyper::Error> {
        let uri = request.uri().clone();
        if !self.rate_limit.can_send(&uri) {
            error!("Rate limit exceeded for endpoint {}", uri);
            return Err(hyper::Error::new(
                hyper::error::Kind::Other,
                "Rate limit exceeded",
            ));
        }

        let response = self.client.request(request).await?;
        Ok(response)
    }
}

impl RateLimiter {
    fn can_send(&mut self, uri: &Uri) -> bool {
        let now = Instant::now();
        if let Some((last_sent, count)) = self.limits.get_mut(uri.to_string().as_str()) {
            if *count < 10 && now.duration_since(*last_sent) < Duration::from_secs(60) {
                *count += 1;
                return true;
            } else if now.duration_since(*last_sent) >= Duration::from_secs(60) {
                self.limits.insert(uri.to_string(), (now, 1));
                return true;
            }
        } else {
            self.limits.insert(uri.to_string(), (now, 1));
            return true;
        }
        false
    }
}

#[tokio::main]
async fn main() {
    let client = CustomClient::new("/path/to/ca_bundle".to_string(), 10);
    let request_builder = client.create_request_builder("https://example.com");
    let response = client.send_request(request_builder.body(Body::empty()).unwrap()).await;
    match response {
        Ok(res) => info!("Response: {:?}", res),
        Err(e) => error!("Error: {}", e),
    }
}
```']

