        .arg("main.rs") // Replace with your crate file
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn subprocess");

    let output = child.wait_with_output().expect("Failed to read subprocess output");
    let exit_code = output.status.code().unwrap_or(-1);

    // Calculate resident set size before and after compilation
    let rss_before = get_resident_set_size();
    compile_rust_file();
    let rss_after = get_resident_set_size();

    let elapsed_time = start_time.elapsed();
    println!("Compilation took: {:?}", elapsed_time);
    println!("RSS before compilation: {} bytes", rss_before);
    println!("RSS after compilation: {} bytes", rss_after);

    exit_code
}

