function updateUserStatus($userId, $newStatus) {
    // Define authorized IP range
    $authorizedIPs = ['192.168.0.0/16', '10.0.0.0/8'];

    // Check if current client IP is authorized
    if (!in_array($_SERVER['REMOTE_ADDR'], $authorizedIPs)) {
        error_log('Unauthorized access attempt from IP: ' . $_SERVER['REMOTE_ADDR']);
        return false;
    }

    // Validate user session (pseudo-code, replace with actual session validation logic)
    if (!validateUserSession()) {
        error_log('Invalid session for user ID: ' . $userId);
        return false;
    }

    // Connect to the database
    try {
        $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Prevent concurrent updates (pseudo-code, replace with actual locking mechanism)
        $pdo->beginTransaction();
        $stmt = $pdo->prepare("SELECT last_modified FROM users WHERE id = :id FOR UPDATE");
        $stmt->execute(['id' => $userId]);

        $lastModified = $stmt->fetchColumn();

        // Update user status and set new last modified values
        $stmt = $pdo->prepare("UPDATE users SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id AND last_modified = :last_modified");
        $stmt->execute([
            'status' => $newStatus,
            'ip' => $_SERVER['REMOTE_ADDR'],
            'id' => $userId,
            'last_modified' => $lastModified
        ]);

        if ($stmt->rowCount() === 0) {
            error_log('Concurrent update conflict for user ID: ' . $userId);
            return false;
        }

        $pdo->commit();
    } catch (PDOException $e) {
        error_log('Database error: ' . $e->getMessage());
        if ($pdo !== null) {
            $pdo->rollBack();
        }
        return false;
    }

    return true;
}

// Example usage
