<?php

class FileAndSecurityUtils {
    // Constants for default character sets and hashing algorithms
    const CHAR_SET_WEAK = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    const CHAR_SET_MEDIUM = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';
    const CHAR_SET_STRONG = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+{}|:"<>?`~';
    const HASH_WEAK = 'md5';
    const HASH_MEDIUM = 'sha1';
    const HASH_STRONG = 'sha256';

    /**
     * Generates a secure random string based on the specified length and strength.
     *
     * @param int $length The desired length of the random string.
     * @param string $strength The security level ('low', 'medium', 'high').
     * @return string The generated secure random string.
     */
    public static function generateSecureRandomString($length, $strength) {
        switch ($strength) {
            case 'low':
                $charset = self::CHAR_SET_WEAK;
                $hashAlgorithm = self::HASH_WEAK;
                break;
            case 'medium':
                $charset = self::CHAR_SET_MEDIUM;
                $hashAlgorithm = self::HASH_MEDIUM;
                break;
            case 'high':
                $charset = self::CHAR_SET_STRONG;
                $hashAlgorithm = self::HASH_STRONG;
                break;
            default:
                throw new InvalidArgumentException('Invalid strength parameter');
        }

        $randomString = substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 0, $length);
        return hash($hashAlgorithm, $randomString);
    }

    /**
     * Reads the contents of a file synchronously from the specified directory.
     *
     * @param string $filePath The path to the file.
     * @return string The contents of the file.
     */
    public static function readFileContents($filePath) {
        if (!file_exists($filePath)) {
            throw new FileNotFoundException('File not found');
        }

        $stream = fopen($filePath, 'r');
        if ($stream === false) {
            throw new IOException('Failed to open file');
        }

        $contents = '';
        while (($line = fgets($stream)) !== false) {
            $contents .= $line;
        }

        fclose($stream);
        return $contents;
    }
}
