    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    u_char ip[4];
    memcpy(ip, &(ipv4->sin_addr), 4);

    freeaddrinfo(res);
    return ip;
}

int main() {
    struct DNSResolver resolver;
    const char *hostname = "example.com";
    u_char *ipAddress = resolve(&resolver, hostname);

    if (ipAddress != NULL) {
        printf("IP Address: %d.%d.%d.%d\n", ipAddress[0], ipAddress[1], ipAddress[2], ipAddress[3]);
        free(ipAddress);
    } else {
        printf("Failed to resolve IP address.\n");
    }

    return 0;
}
