import time

def process_logging_config(file_path):
    entries = []
    highest_sequence_number = -1
    highest_entry_timestamp = None
    highest_entry_message = None

    try:
        with open(file_path, 'r') as file:
            for line in file:
                parts = line.strip().split()
                if len(parts) == 3:
                    timestamp, sequence_number_str, message = parts
                    try:
                        timestamp = int(timestamp)
                        sequence_number = int(sequence_number_str)
                        if highest_sequence_number >= 0 and sequence_number <= highest_sequence_number:
                            print(f"Warning: Sequence number out of order or missing. Skipping entry.")
                            continue
                        entries.append((timestamp, message))
                        highest_sequence_number = sequence_number
                        highest_entry_timestamp = timestamp
                        highest_entry_message = message
                    except ValueError:
                        print("Error: Invalid data format in line.")
    except FileNotFoundError:
        print(f"Error: File not found at {file_path}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    if entries:
        entries.sort(key=lambda x: x[0])
        return highest_entry_timestamp, highest_entry_message
    else:
        print("No valid entries found in the file.")
        return None, None

# Example usage:
timestamp, message = process_logging_config('path_to_your_log_file.txt')
if timestamp is not None and message is not None:
    print(f"Highest sequence number entry: Timestamp={timestamp}, Message={message}")
