State** updateStateList(State** stateList, int* numOfStates, FSA* fsa, int lastStateId, int* errorCode) {
    if (*numOfStates == 0 || *numOfStates > MAX_STATES) {
        *errorCode = -1; // Invalid number of states
        return NULL;
