        if (!validateFSA(fsa, lastStateId + i)) {
            *errorCode = -2; // Invalid FSA state
            return NULL;
        }
    }

    size_t newSize = (*numOfStates) * sizeof(State*);
    if (checkIntegerOverflow(newSize, 1)) {
        *errorCode = -3; // Integer overflow during memory allocation
        return NULL;
    }

    State** newStateList = realloc(*stateList, newSize);
    if (newStateList == NULL && *stateList != NULL) {
        printf("Failed to resize state list\n");
