int initOctree(int featureSize, int numLeafNodes, int dataCapacity, int maxSizeLimit, OctTreeNode** root) {
    if (featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
        return -1; // Invalid parameters
    }

    size_t requiredMemory = static_cast<size_t>(numLeafNodes * sizeof(OctTreeNode));
    if (requiredMemory > static_cast<size_t>(std::numeric_limits<int>::max())) {
        return -2; // Integer overflow in memory calculation
    }
    if (static_cast<long long>(requiredMemory) > maxSizeLimit) {
        return -3; // Memory limit exceeded
    }

    *root = new OctTreeNode[numLeafNodes];
    if (*root == nullptr) {
        return -4; // Memory allocation failed
    }

    for (int i = 0; i < numLeafNodes; ++i) {
        (*root)[i].children.resize(8); // Assuming a binary tree for simplicity
    }

    return 0; // Success
}

int main() {
    int featureSize = 10;
    int numLeafNodes = 1024;
    int dataCapacity = 512;
    int maxSizeLimit = 1024 * 1024 * 1024; // 1GB

    OctTreeNode* root;
    int errorCode = initOctree(featureSize, numLeafNodes, dataCapacity, maxSizeLimit, &root);

    if (errorCode == 0) {
        std::cout << "Octree initialized successfully." << std::endl;
        // Clean up allocated memory
        delete[] root;
    } else {
        switch (errorCode) {
            case -1:
                std::cerr << "Invalid parameters provided." << std::endl;
                break;
            case -2:
                std::cerr << "Integer overflow in memory calculation." << std::endl;
                break;
            case -3:
                std::cerr << "Memory limit exceeded." << std::endl;
                break;
            case -4:
                std::cerr << "Memory allocation failed." << std::endl;
                break;
