#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000
#define ROLLING_WINDOW_SECONDS 30

typedef struct {
    time_t timestamp;
    double amount;
    int account_id;
} Transaction;

double prng() {
    return ((double)rand()) / RAND_MAX;
}

void adjust_transaction(Transaction *transaction, double volatility_range) {
    transaction->amount *= (1.0 + prng() * 2 * volatility_range - volatility_range);
}

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int head;
    int count;
    pthread_mutex_t lock;
} RollingWindow;

RollingWindow rolling_window_init() {
    RollingWindow window;
    pthread_mutex_init(&window.lock, NULL);
    return window;
}

void add_transaction(RollingWindow *window, Transaction transaction) {
    pthread_mutex_lock(&window->lock);
    int next_head = (window->head + 1) % MAX_TRANSACTIONS;
    if (next_head != window->count) {
        window->transactions[next_head] = transaction;
        window->head = next_head;
        if (window->count < MAX_TRANSACTIONS) {
            window->count++;
        }
    }
    pthread_mutex_unlock(&window->lock);
}

Transaction get_highest_transaction(RollingWindow *window) {
    Transaction highest;
    double max_amount = -1.0;
    int account_id = -1;
    pthread_mutex_lock(&window->lock);
    for (int i = 0; i < window->count; i++) {
        if (window->transactions[i].amount > max_amount) {
            max_amount = window->transactions[i].amount;
            highest = window->transactions[i];
        }
    }
    pthread_mutex_unlock(&window->lock);
    return highest;
}

int main() {
    RollingWindow window = rolling_window_init();
    srand(time(NULL));

    // Simulate transactions
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        Transaction transaction;
        transaction.timestamp = time(NULL) - ROLLING_WINDOW_SECONDS + i;
        transaction.amount = 100.0 * prng();
        transaction.account_id = rand() % 100;
        add_transaction(&window, transaction);
    }

    // Get highest adjusted transaction
    Transaction highest = get_highest_transaction(&window);
    printf("Highest Adjusted Transaction: Account ID=%d, Amount=%.2f\n", highest.account_id, highest.amount);

    pthread_mutex_destroy(&window.lock);
    return 0;
}
