using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float minValueFloat;
    private float maxValueFloat;
    private int minValueInt;
    private int maxValueInt;
    private readonly System.Random random = new System.Random();

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot exceed maximum value.");

        minValueFloat = minValue;
        maxValueFloat = maxValue;
        minValueInt = Mathf.RoundToInt(minValue);
        maxValueInt = Mathf.RoundToInt(maxValue) - 1;
    }

    public float GetRandomFloat()
    {
        return (float)(random.NextDouble() * (maxValueFloat - minValueFloat)) + minValueFloat;
    }

    public int GetRandomInt()
    {
        return random.Next(minValueInt, maxValueInt + 1);
    }

    public override string ToString()
    {
        if (minValueFloat == minValueInt && maxValueFloat == maxValueInt)
            return $"[{minValueInt}, {maxValueInt})";
        else
            return $"[{minValueFloat}, {maxValueFloat}]";
    }
}
```

