#include <stdio.h>
#include <stdlib.h>

#define MAX_LOG_SIZE 1024 * 1024 * 1024 // 1 GB

int countLogEntries(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(fileSize + 1);
    if (!buffer) {
        perror("Failed to allocate memory for log file");
        fclose(file);
        return -1;
    }

    size_t bytesRead = fread(buffer, sizeof(char), fileSize, file);
    if (bytesRead != fileSize) {
        perror("Failed to read log file");
        free(buffer);
        fclose(file);
        return -1;
    }
    buffer[bytesRead] = '\0';

    int entryCount = 0;
    char* currentLine = buffer;
    while (*currentLine != '\0') {
        if (*currentLine == '\n') {
            entryCount++;
        }
        currentLine++;
    }

    free(buffer);
    fclose(file);

    return entryCount;
}
