function traverseDOM(element, selector, includeElement) {
    let matchingElements = [];

    function recurse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE) {
            let matchesSelector = document.querySelector(`${selector}[id="${currentNode.id}"]`) || 
                                  document.querySelector(`${selector}.${currentNode.className}`);
            if (matchesSelector && includeElement(matchesSelector)) {
                matchingElements.push(currentNode.id ? `#${currentNode.id}` : `.${currentNode.className}`);
            }
        }

        for (let child of currentNode.childNodes) {
            recurse(child);
        }
    }

    recurse(element);
    return matchingElements;
}
