public class Report
{
    public ImageMetadata Metadata { get; set; }
    public byte[] MD5Hash { get; set; }
    public List<string> LogEntries { get; set; }
}

public static async Task<Report> ProcessTiffAndGenerateReport(string filePath, string logFilePath)
{
    // Parse TIFF image file
    ImageMetadata metadata = new ImageMetadata();
    try
    {
        using (FileStream fs = File.OpenRead(filePath))
        {
            byte[] tiffBytes = await fs.ReadAllBytesAsync();
            // Assuming a method that parses TIFF data and populates metadata
            metadata.BitsPerSample = ParseBitsPerSample(tiffBytes);
            metadata.SamplesPerPixel = ParseSamplesPerPixel(tiffBytes);
            metadata.ExtraSamples = ParseExtraSamples(tiffBytes);
        }
    }
    catch (Exception ex)
    {
        LogError(logFilePath, $"Failed to parse TIFF file: {ex.Message}");
        throw;
    }

    // Retrieve external service response
    ExternalServiceResponse externalResponse = null;
    int retryCount = 0;
    while (externalResponse == null && retryCount < 3)
    {
        try
        {
            using (HttpClient client = new HttpClient())
            {
                HttpResponseMessage response = await client.GetAsync("https://api.example.com/metadata?file=" + filePath);
                if (response.IsSuccessStatusCode)
                {
                    externalResponse = await response.Content.ReadAsAsync<ExternalServiceResponse>();
                }
            }
        }
        catch
        {
            retryCount++;
            await Task.Delay(500); // Wait before retrying
        }
    }

    if (externalResponse == null)
    {
        LogError(logFilePath, "Failed to retrieve external service response after retries");
        throw new InvalidOperationException("External service failed to respond");
    }

    // Compute MD5 hash of concatenated metadata and external response
    byte[] concatBytes = CombineBytes(metadata.ToByteArray(), externalResponse.ToByteArray());
    byte[] md5Hash = ComputeMD5Hash(concatBytes);

    // Return report object
    return new Report
    {
        Metadata = metadata,
        MD5Hash = md5Hash,
        LogEntries = File.Exists(logFilePath) ? File.ReadAllLines(logFilePath).ToList() : new List<string>()
    };
}

private static int ParseBitsPerSample(byte[] tiffBytes)
