        if (strchr("aeiouAEIOU", filename[i])) {
            count++;
        }
    }
    return count;
}

char* generate_new_filename(const char* input_filename) {
    size_t len = strlen(input_filename);
    if (len == 0 || len > MAX_FILENAME_LENGTH) {
        return NULL; // Invalid filename length
    }

    for (size_t i = 0; i < len; i++) {
        if (!isprint(input_filename[i])) {
            return NULL; // Non-printable characters found
        }
    }

    int num_digits_to_append = count_vowels(input_filename);
    if (num_digits_to_append > MAX_DIGITS_TO_APPEND) {
        num_digits_to_append = MAX_DIGITS_TO_APPEND;
    }

    size_t new_len = len + num_digits_to_append + 5; // +5 for ".data", ".text", or ".mixed"
    char* new_filename = (char*)malloc(new_len * sizeof(char));
    if (!new_filename) {
        return NULL; // Memory allocation failed
    }

    strncpy(new_filename, input_filename, len);
    new_filename[len] = '\0'; // Null-terminate the string

    const char* file_type = get_file_type(input_filename);
    strncat(new_filename, file_type, 5);

    for (int i = 1; i <= num_digits_to_append; i++) {
        new_filename[len + i - 1] = '0' + i;
    }
    new_filename[new_len - 1] = '\0'; // Null-terminate the string

    return new_filename;
}
