// Function to derive AES key from password using SHA-256
unsigned char* derive_aes_key(const unsigned char* password, size_t password_len) {
    unsigned char* key = (unsigned char*)malloc(KEY_SIZE);
    if (!key) return NULL;
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, password, password_len, 1, key, NULL);
    return key;
}

// Function to initialize AES-256-CBC cipher
EVP_CIPHER_CTX* init_cipher(const unsigned char* key, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    return ctx;
}

