        // Execute a command to get the version of the tool
        std::string command = "third_party_tool --version";
        FILE* pipe = popen(command.c_str(), "r");
        if (!pipe) throw std::runtime_error("popen() failed!");
        char buffer[128];
        std::string result;
        while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
            result += buffer;
        }
        pclose(pipe);
        return result;
    } catch (const std::exception& e) {
        // Log the error internally
        std::cerr << "Error during version retrieval: " << e.what() << std::endl;
        return "";
    }
}

