#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <signal.h>

#define MAX_ARGS 6
#define MAX_ARG_LEN 1024
#define LOG_FILE "execution_log.txt"
#define OUTPUT_FILE "output.txt"

// Function to validate command and arguments
int is_valid_char(char ch) {
    return (isalnum(ch) || ch == '-' || ch == '_' || ch == '.' || ch == '/');
}

int validate_command(char *command, char **args) {
    for (int i = 0; i < strlen(command); i++) {
        if (!is_valid_char(command[i])) {
            return 0;
        }
    }
    for (int i = 1; args[i] != NULL; i++) {
        for (int j = 0; args[i][j] != '\0'; j++) {
            if (!is_valid_char(args[i][j])) {
                return 0;
            }
        }
    }
    return 1;
}

// Function to execute command in the background
int execute_command(char *command, char **args) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        int fd = open(OUTPUT_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fd == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        dup2(fd, STDOUT_FILENO);
        close(fd);

        char *full_command[MAX_ARGS];
        full_command[0] = command;
        int arg_index = 1;
        for (; args[arg_index] != NULL; arg_index++) {
            full_command[arg_index] = args[arg_index];
        }
        full_command[arg_index] = NULL;

        if (execvp(command, full_command) == -1) {
            perror("execvp");
            exit(EXIT_FAILURE);
        }
    } else {
        // Parent process
        return 1;
    }
}

// Function to log execution details
void log_execution(int success, char *command) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("fopen");
        return;
    }
    fprintf(log, "%s: %s\n", success ? "SUCCESS" : "FAILURE", command);
    fclose(log);
}

int main(int argc, char **argv) {
    if (argc < 2 || argc > MAX_ARGS) {
        printf("Usage: %s <command> [arg1] [arg2] [arg3] [arg4]\n", argv[0]);
        return 0;
    }

    if (!validate_command(argv[1], &argv[1])) {
        printf("Invalid command or arguments.\n");
        return 0;
    }

    if (execute_command(argv[1], &argv[1]) == 0) {
        return 0;
    }

    log_execution(1, argv[1]);
    return 1;
}
