            return;
        }

        // Check for dependencies
        if (!CheckDependencies())
        {
            Log("Error: Necessary application server components are not installed or configured correctly.", LogLevel.Error);
            return;
        }

        using (Process process = new Process())
        {
            process.StartInfo.FileName = "iisreset"; // Example command to add the site
            process.StartInfo.Arguments = $"/site:{siteName} /physicalPath:\"{directoryPath}\"";
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.CreateNoWindow = true;

            try
            {
                process.Start();
                process.WaitForExit(_timeoutSeconds * 1000);
                string output = process.StandardOutput.ReadToEnd();
                string error = process.StandardError.ReadToEnd();

                if (!string.IsNullOrEmpty(error))
                {
                    Log($"Error: {error}", LogLevel.Error);
                }
                else
                {
                    Log("Site added successfully.", LogLevel.Info);
                }
            }
            catch (Exception ex)
            {
                Log($"Exception: {ex.Message}", LogLevel.Error);
            }
        }

        // Cleanup resources
