using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;

public class ThemeCache
{
    private Dictionary<string, byte[]> cache = new Dictionary<string, byte[]>(new LruCacheEvictionPolicy());
    private string cacheDirectory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "ThemeCache");

    public void Add(string key, byte[] data)
    {
        if (!Directory.Exists(cacheDirectory))
        {
            Directory.CreateDirectory(cacheDirectory);
        }

        var filePath = Path.Combine(cacheDirectory, key);
        File.WriteAllBytes(filePath, data);

        lock (cache)
        {
            cache[key] = data;
        }
    }

    public byte[] Get(string key)
    {
        if (cache.TryGetValue(key, out var data))
        {
            return data;
        }

        var filePath = Path.Combine(cacheDirectory, key);
        if (File.Exists(filePath))
        {
            data = File.ReadAllBytes(filePath);

            lock (cache)
            {
                cache[key] = data;
            }
        }

        return data;
    }
}

public class LruCacheEvictionPolicy : IEqualityComparer<string>
{
    public bool Equals(string x, string y)
    {
        return string.Equals(x, y);
    }

    public int GetHashCode(string obj)
    {
        return obj.GetHashCode();
    }
}

public static class AesEncryption
{
    public static byte[] Encrypt(byte[] data, string password)
    {
        using (var aes = Aes.Create())
        {
            var iv = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(iv);
            }

            aes.Key = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(password));
            aes.IV = iv;

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            using (var ms = new MemoryStream())
            using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
                return ms.ToArray();
            }
        }
    }

    public static byte[] Decrypt(byte[] encryptedData, string password)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(password));

            int ivLength = 16;
            if (encryptedData.Length <= ivLength)
            {
                throw new ArgumentException("Encrypted data is too short to contain IV.");
            }

            byte[] iv = new byte[ivLength];
            Buffer.BlockCopy(encryptedData, 0, iv, 0, ivLength);

            aes.IV = iv;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var ms = new MemoryStream())
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
            {
                cs.Write(encryptedData, ivLength, encryptedData.Length - ivLength);
                return ms.ToArray();
            }
        }
    }
}

public class ThemeClient
{
    private TcpClient client;
    private NetworkStream stream;

    public void Connect(string server, int port)
    {
        client = new TcpClient(server, port);
        stream = client.GetStream();
    }

    public DataTableReader QueryDatabase(byte[] encryptedQuery, byte[] encryptionKey)
    {
        var encryptedData = AesEncryption.Encrypt(encryptedQuery, BitConverter.ToString(encryptionKey).Replace("-", ""));
        using (var writer = new BinaryWriter(stream))
        {
            writer.Write(encryptedData.Length);
            writer.Write(encryptedData);
        }

        var lengthBuffer = new byte[4];
        stream.Read(lengthBuffer, 0, lengthBuffer.Length);
        int dataLength = BitConverter.ToInt32(lengthBuffer, 0);

        var encryptedResponse = new byte[dataLength];
        stream.Read(encryptedResponse, 0, dataLength);

        var decryptedResponse = AesEncryption.Decrypt(encryptedResponse, BitConverter.ToString(encryptionKey).Replace("-", ""));
        using (var reader = new BinaryReader(new MemoryStream(decryptedResponse)))
        {
            DataTable dt = new DataTable();
            int columnCount = reader.ReadInt32();
            for (int i = 0; i < columnCount; i++)
            {
                string columnName = reader.ReadString();
                Type dataType = Type.GetType(reader.ReadString());
                dt.Columns.Add(columnName, dataType);
            }

            while (true)
            {
                bool hasRow = reader.ReadBoolean();
                if (!hasRow)
                    break;

                DataRow row = dt.NewRow();
                for (int i = 0; i < columnCount; i++)
                {
                    object value = null;
                    switch (dt.Columns[i].DataType)
                    {
                        case typeof(string):
                            value = reader.ReadString();
                            break;
                        case typeof(int):
                            value = reader.ReadInt32();
                            break;
                        // Add more cases for other data types as needed
                    }
                    row[i] = value;
                }
                dt.Rows.Add(row);
            }

            return dt.CreateDataReader();
        }
    }
}
