using System.Text;

public class MessageProcessor
{
    private readonly Dictionary<string, (byte[] Key, byte[] IV)> _keyPairs;

    public MessageProcessor(Dictionary<string, (byte[] Key, byte[] IV)> keyPairs)
    {
        _keyPairs = keyPairs;
    }

    public async Task<(string message, bool isIntegrityVerified)> ProcessMessageAsync(string encodedMessage)
    {
        try
        {
            var header = ExtractHeader(encodedMessage);
            var decodedBytes = DecodeBase64(encodedMessage);

            if (decodedBytes == null)
                return ("Invalid Base64", false);

            var keyPair = _keyPairs.FirstOrDefault(x => x.Key.Equals(header)).Value;
            if (keyPair.Key == null || keyPair.IV == null)
                return ("Key or IV not found for header", false);

            var decryptedBytes = await DecryptAsync(decodedBytes, keyPair.Key, keyPair.IV);
            var isIntegrityVerified = VerifyHmacSha256(decryptedBytes, encodedMessage);

            if (!isIntegrityVerified)
                return ("Integrity verification failed", false);

            return (Encoding.UTF8.GetString(decryptedBytes), true);
        }
        catch (Exception ex)
        {
            return ($"Error processing message: {ex.Message}", false);
        }
    }

    public (string message, bool isIntegrityVerified) ProcessMessage(string encodedMessage)
    {
        try
        {
            var header = ExtractHeader(encodedMessage);
            var decodedBytes = DecodeBase64(encodedMessage);

            if (decodedBytes == null)
                return ("Invalid Base64", false);

            var keyPair = _keyPairs.FirstOrDefault(x => x.Key.Equals(header)).Value;
            if (keyPair.Key == null || keyPair.IV == null)
                return ("Key or IV not found for header", false);

            var decryptedBytes = Decrypt(decodedBytes, keyPair.Key, keyPair.IV);
            var isIntegrityVerified = VerifyHmacSha256(decryptedBytes, encodedMessage);

            if (!isIntegrityVerified)
                return ("Integrity verification failed", false);

            return (Encoding.UTF8.GetString(decryptedBytes), true);
        }
        catch (Exception ex)
        {
            return ($"Error processing message: {ex.Message}", false);
        }
    }

    private string ExtractHeader(string encodedMessage)
    {
        // Implement header extraction logic
        return encodedMessage.Split('.')[0];
    }

    private byte[] DecodeBase64(string encodedMessage)
    {
        try
        {
            var base64UrlEncoded = encodedMessage.Replace('-', '+').Replace('_', '/');
            base64UrlEncoded += new string('=', 3 - (base64UrlEncoded.Length % 4));
            return Convert.FromBase64String(base64UrlEncoded);
        }
        catch
        {
            return null;
        }
    }

    private async Task<byte[]> DecryptAsync(byte[] data, byte[] key, byte[] iv)
    {
        using (var tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Mode = CipherMode.CBC;
            tripleDES.Padding = PaddingMode.PKCS7;
            tripleDES.Key = key;
            tripleDES.IV = iv;

            using (var decryptor = tripleDES.CreateDecryptor(key, iv))
            {
                var memoryStream = new MemoryStream(data);
                var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
                return await cryptoStream.ReadAllBytesAsync();
            }
        }
    }

    private byte[] Decrypt(byte[] data, byte[] key, byte[] iv)
    {
        using (var tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Mode = CipherMode.CBC;
            tripleDES.Padding = PaddingMode.PKCS7;
            tripleDES.Key = key;
            tripleDES.IV = iv;

            using (var decryptor = tripleDES.CreateDecryptor(key, iv))
            {
                var memoryStream = new MemoryStream(data);
                var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
                return cryptoStream.ReadAllBytes();
            }
        }
    }

    private bool VerifyHmacSha256(byte[] data, string originalMessage)
    {
        // Implement HMAC-SHA256 verification logic
        using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes("secretKey")))
        {
            var hash = hmac.ComputeHash(data);
            var base64Hash = Convert.ToBase64String(hash);
            return base64Hash.Equals(originalMessage.Split('.')[1]);
        }
    }
}
