using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashService
{
    private readonly ExternalDataSource _externalDataSource;

    public HashService(ExternalDataSource externalDataSource)
    {
        _externalDataSource = externalDataSource ?? throw new ArgumentNullException(nameof(externalDataSource));
    }

    public async Task<string> ComputeHashAsync(string input, CancellationToken cancellationToken)
    {
        try
        {
            // Fetch metadata from the external data source
            var metadata = await _externalDataSource.GetMetadataAsync(input, cancellationToken);

            if (metadata == null)
            {
                throw new InvalidOperationException("Failed to fetch metadata for the given input.");
            }

            // Prepare the data to hash
            var dataToHash = $"{input}{metadata}";

            // Compute SHA-1 hash
            using (var sha1 = SHA1.Create())
            {
                var hashBytes = sha1.ComputeHash(Encoding.UTF8.GetBytes(dataToHash));
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }
        catch (Exception ex)
        {
            LogError(ex, input);
            throw;
        }
    }

    private void LogError(Exception ex, string input)
    {
        // Implement logging logic here
        Console.WriteLine($"Error computing hash for input '{input}': {ex.Message}");
    }
}

public interface ExternalDataSource
{
    Task<string> GetMetadataAsync(string input, CancellationToken cancellationToken);
}

public class MockExternalDataSource : ExternalDataSource
{
    public async Task<string> GetMetadataAsync(string input, CancellationToken cancellationToken)
    {
        // Simulate fetching metadata from an external source
        await Task.Delay(100, cancellationToken); // Simulate latency
        return $"metadata_for_{input}";
    }
}

// Usage example
public class Program
{
    public static async Task Main(string[] args)
    {
        var dataSource = new MockExternalDataSource();
        var hashService = new HashService(dataSource);

        try
        {
            var result = await hashService.ComputeHashAsync("exampleInput", CancellationToken.None);
            Console.WriteLine($"SHA-1 Hash: {result}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
```

