using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DataDecryptor
{
    private readonly Dictionary<string, byte[]> _encryptionKeys;
    private readonly ILogger _logger;

    public DataDecryptor(IEnumerable<byte[]> encryptionKeys)
    {
        _encryptionKeys = encryptionKeys.ToDictionary(key => Convert.ToBase64String(key), key => key);
        _logger = new ConsoleLogger(); // Simplified for example purposes
    }

    public async Task<byte[]> DecryptDataAsync(string keyId, byte[] iv, byte[] ciphertext)
    {
        if (!_encryptionKeys.ContainsKey(keyId))
            throw new ArgumentException("Invalid encryption key ID", nameof(keyId));

        var key = _encryptionKeys[keyId];
        if (iv.Length != Aes.BlockSize / 8 || ciphertext.Length % Aes.BlockSize != 0)
            throw new ArgumentException("Invalid IV or ciphertext length", nameof(ciphertext));

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var memoryStream = new MemoryStream(ciphertext))
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            {
                var decryptedData = await ReadFullyAsync(cryptoStream);
                _logger.LogDecryptionResult(keyId, iv, true);
                return decryptedData;
            }
        }
    }

    private static async Task<byte[]> ReadFullyAsync(Stream input)
    {
        using (var memoryStream = new MemoryStream())
        {
            while (input.Position < input.Length)
            {
                var buffer = new byte[8192];
                int bytesRead = await input.ReadAsync(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                    break;
                memoryStream.Write(buffer, 0, bytesRead);
            }
            return memoryStream.ToArray();
        }
    }

    public void RotateKey(string oldKeyId, byte[] newKey)
    {
        _encryptionKeys[Convert.ToBase64String(newKey)] = newKey;
        if (_encryptionKeys.Count > 1)
        {
            _encryptionKeys.Remove(oldKeyId);
        }
        else
        {
            throw new InvalidOperationException("Cannot rotate the last encryption key");
        }
        _logger.LogKeyRotation(oldKeyId, Convert.ToBase64String(newKey));
    }

    private interface ILogger
    {
        void LogDecryptionResult(string keyId, byte[] iv, bool success);
        void LogKeyRotation(string oldKeyId, string newKeyId);
    }

    private class ConsoleLogger : ILogger
    {
        public void LogDecryptionResult(string keyId, byte[] iv, bool success)
        {
            var message = $"Decryption attempt: Key ID={keyId}, IV={Convert.ToBase64String(iv)}, Success={success}";
            Console.WriteLine($"{DateTime.Now}: {message}");
        }

        public void LogKeyRotation(string oldKeyId, string newKeyId)
        {
            Console.WriteLine($"{DateTime.Now}: Rotated encryption key from {oldKeyId} to {newKeyId}");
        }
    }
}
