import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class ConfigManagerFactory {

    private static final byte[] SIGNATURE = {0x1A, 0x2B, 0x3C, 0x4D};

    public static ConfigManager deserializeConfig(byte[] data) {
        if (!isValidSignature(data)) {
            return null;
        }

        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {

            return (ConfigManager) ois.readObject();

        } catch (IOException | ClassNotFoundException e) {
            // Handle exceptions, possibly log them and return null
            return null;
        }
    }

    private static boolean isValidSignature(byte[] data) {
        if (data.length < SIGNATURE.length) {
            return false;
        }
        for (int i = 0; i < SIGNATURE.length; i++) {
            if (data[i] != SIGNATURE[i]) {
                return false;
            }
        }
        return true;
    }
}
