#define MAX_URLS 10000
#define MAX_URL_LENGTH 256
#define LOG_FILE "app.log"

typedef struct {
    char *url;
    int valid;
} URL;

URL urls[MAX_URLS];
int url_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void *process_url(void *arg) {
    int index = *(int *)arg;
    CURL *curl;
    CURLcode res;

    if (index < url_count && urls[index].valid) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, urls[index].url);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                log_message("Failed to upload file for URL: %s", urls[index].url);

            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();

        // Simulate file upload and return the URL
        char *uploaded_file_url = (char *)malloc(MAX_URL_LENGTH);
        snprintf(uploaded_file_url, MAX_URL_LENGTH, "https://example.com/files/%d", index);
        log_message("Uploaded file URL for %s: %s", urls[index].url, uploaded_file_url);
        return uploaded_file_url;
    }

    return NULL;
}

void find_and_print_longest_url() {
    int max_length = 0;
    char *longest_url = NULL;

    for (int i = 0; i < url_count; i++) {
        if (strlen(urls[i].url) > max_length) {
            max_length = strlen(urls[i].url);
            longest_url = urls[i].url;
        }
    }

    log_message("Longest URL: %s", longest_url);
}

void read_urls_from_stdin() {
    char url[MAX_URL_LENGTH];
    while (fgets(url, sizeof(url), stdin) != NULL) {
        url[strcspn(url, "\n")] = '\0'; // Remove newline character

        if (url_count < MAX_URLS) {
            urls[url_count].url = strdup(url);
            urls[url_count].valid = 1;
            url_count++;
        } else {
            log_message("URL limit reached. Ignoring additional URLs.");
            break;
        }
    }
}

int main() {
    read_urls_from_stdin();

    pthread_t threads[MAX_URLS];
    int thread_ids[MAX_URLS];

    for (int i = 0; i < url_count && i < MAX_URLS; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_url, &thread_ids[i]) != 0) {
            log_message("Failed to create thread for URL processing.");
            break;
        }
    }

    for (int i = 0; i < url_count && i < MAX_URLS; i++) {
        pthread_join(threads[i], NULL);
    }

    find_and_print_longest_url();

    // Free allocated memory
    for (int i = 0; i < url_count; i++) {
        free(urls[i].url);
    }

    return 0;
}
