const configManager = {
  cache: {},

  async updateConfig(jsonString) {
    const updates = JSON.parse(jsonString);
    for (const update of updates) {
      switch (update.action) {
        case 'add':
          this.addKey(update.key, update.value);
          break;
        case 'set':
          this.setKey(update.key, update.value);
          break;
        case 'delete':
          this.deleteKey(update.key);
          break;
        default:
          console.error(`Unknown action: ${update.action}`);
      }
    }
  },

  async addKey(key, value) {
    if (await this.validateKey(key)) {
      process.env[key] = value;
      this.cache[key] = value;
    } else {
      console.error(`Invalid key: ${key}`);
    }
  },

  async setKey(key, value) {
    if (await this.validateKey(key)) {
      process.env[key] = value;
      this.cache[key] = value;
    } else {
      console.error(`Invalid key: ${key}`);
    }
  },

  deleteKey(key) {
    if (this.cache.hasOwnProperty(key)) {
      delete process.env[key];
      delete this.cache[key];
    }
  },

  async validateKey(key) {
    // Simulate external data source check
    const isValid = await this.checkExternalDataSource(key);
    return isValid;
  },

  async checkExternalDataSource(key) {
    if (this.cache.hasOwnProperty(key)) {
      return true; // Key is in cache, assume valid
    }

    try {
      // Fetch from external data source
      const response = await fetch(`https://api.example.com/validate?key=${key}`);
      const result = await response.json();
      this.cache[key] = result.valid;
      return result.valid;
    } catch (error) {
      console.error('Failed to validate key:', error);
      return false;
    }
  }
};

// Example usage:
