  {"action": "add", "key": "NEW_KEY", "value": "new_value"},
  {"action": "set", "key": "EXISTING_KEY", "value": "updated_value"},
  {"action": "delete", "key": "DELETABLE_KEY"}
]`;

configManager.updateConfig(jsonInput);
