use tokio;
use std::collections::HashMap;
use log::{info, error};
use std::sync::{Arc, Mutex};

#[tokio::main]
async fn main() {
    env_logger::init();

    let args: Vec<String> = std::env::args().collect();
    let tasks = parse_args(&args);

    let resource_limits = Arc::new(Mutex::new(ResourceLimits {
        max_concurrent_tasks: 10,
        total_memory_usage: 512 * 1024 * 1024, // 512 MB
    }));

    for task in tasks {
        let resource_limits_clone = Arc::clone(&resource_limits);
        tokio::spawn(async move {
            match execute_task(task, &resource_limits_clone).await {
                Ok(_) => info!("Task completed successfully: {:?}", task),
                Err(e) => error!("Failed to complete task {:?}: {}", task, e),
            }
        });
    }

    // Simulate worker scaling
    tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
}

fn parse_args(args: &Vec<String>) -> Vec<Operation> {
    args[1..]
        .iter()
        .map(|arg| Operation::new(arg))
        .collect()
}

enum Operation {
    FetchData(String),
    ProcessData(String),
    StoreData(String),
}

impl Operation {
    fn new(description: &str) -> Self {
        match description {
            "fetch" => Operation::FetchData("data_source".to_string()),
            "process" => Operation::ProcessData("data".to_string()),
            "store" => Operation::StoreData("database".to_string()),
            _ => panic!("Unknown operation"),
        }
    }
}

struct ResourceLimits {
    max_concurrent_tasks: usize,
    total_memory_usage: u64, // in bytes
}

async fn execute_task(task: Operation, resource_limits: &Arc<Mutex<ResourceLimits>>) -> Result<(), String> {
    let mut limits = resource_limits.lock().unwrap();

    if limits.max_concurrent_tasks == 0 {
        return Err("Resource limits exceeded".to_string());
    }

    limits.max_concurrent_tasks -= 1;
    // Simulate task execution and memory usage
    tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;

    match &task {
        Operation::FetchData(_) => {
            info!("Fetching data from source");
        }
        Operation::ProcessData(_) => {
            info!("Processing data");
        }
        Operation::StoreData(_) => {
            info!("Storing data to database");
        }
    }

    limits.max_concurrent_tasks += 1;
    Ok(())
}
