use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;
use uuid::Uuid;

fn create_unique_directory(dir_name: &str, parent_dir_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var_key = "MY_UNIQUE_DIR";
    if let Ok(env_var_value) = env::var(env_var_key) {
        return fs::create_dir_all(&env_var_value).map_err(|e| e.into());
    }

    let parent_path = Path::new(parent_dir_path);
    if !parent_path.exists() {
        return Err("Parent directory does not exist".into());
    }

    let mut unique_name = dir_name.to_string();
    loop {
        if validate_directory_name(&unique_name) {
            let full_path = parent_path.join(unique_name);
            if fs::create_dir_all(&full_path).is_err() {
                // Race condition or another process created it
                continue;
            }
            env::set_var(env_var_key, full_path.to_str().unwrap());
            return Ok(());
        } else {
            unique_name = format!("{}-{}", dir_name, Uuid::new_v4().simple().to_string());
        }
    }
}

fn validate_directory_name(name: &str) -> bool {
    !name.is_empty() && !name.contains(&[' ', '*', '?', '<', '>', '|', ':'])
}
```

