#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NUMBER 1000

typedef struct {
    int *array;
    size_t count;
} IntegerList;

void* read_file(void* arg) {
    IntegerList *list = (IntegerList*)arg;
    FILE *file = fopen("input.csv", "r");
    if (!file) return NULL;

    char line[128];
    while (fgets(line, sizeof(line), file)) {
        int number = atoi(line);
        if (number > 0 && number <= MAX_NUMBER) {
            list->array = realloc(list->array, ++list->count * sizeof(int));
            list->array[list->count - 1] = number;
        } else {
            fprintf(stderr, "Invalid input: %s", line);
        }
    }

    fclose(file);
    return NULL;
}

int find_largest(const IntegerList *list) {
    if (list->count == 0) return 0;

    int largest = list->array[0];
    for (size_t i = 1; i < list->count; ++i) {
        if (list->array[i] > largest) {
            largest = list->array[i];
        }
    }

    free(list->array);
    return largest;
}

int main() {
    IntegerList list = {NULL, 0};
    pthread_t thread;

    pthread_create(&thread, NULL, read_file, &list);
    // Perform other computations while file is being read

    pthread_join(thread, NULL);

    int largest = find_largest(&list);
    printf("Largest integer: %d\n", largest);

    return 0;
}
