logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ConfigUpdater:
    def __init__(self, config_file_path, api_url):
        self.config_file_path = config_file_path
        self.api_url = api_url
        self.config_data = None

    def fetch_config(self):
        try:
            response = get(self.api_url)
            response.raise_for_status()
            return response.json()
        except HTTPError as e:
            logging.error(f"Failed to fetch configuration from API: {e}")
            raise
        except Exception as e:
            logging.error(f"An unexpected error occurred while fetching config: {e}")
            raise

    def validate_config(self, new_config):
        # Placeholder for actual validation logic
        pass

    def update_config_file(self, new_config):
        with open(self.config_file_path, 'r+') as file:
            try:
                current_content = json.load(file)
                updated_content = {**current_content, **new_config}
                file.seek(0)
                json.dump(updated_content, file, indent=4)
                file.truncate()
                logging.info("Configuration file updated successfully.")
            except json.JSONDecodeError as e:
                logging.error(f"Failed to parse current config: {e}")
                raise
            except Exception as e:
                logging.error(f"An unexpected error occurred while updating the config file: {e}")
                raise

    def log_changes(self, changes):
        for key, value in changes.items():
            logging.info(f"Changed {key} from None to {value}")

    def retry_on_failure(func, max_retries=5, delay=2):
        def wrapper(*args, **kwargs):
            retries = 0
            while retries < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logging.error(f"Attempt {retries + 1} failed: {e}")
                    sleep(delay)
                    retries += 1
            raise Exception("Max retries exceeded")
        return wrapper

    @retry_on_failure
    def update(self):
        new_config = self.fetch_config()
        if not self.config_data:
            self.config_data = {}
        changes = {key: (self.config_data.get(key), value) for key, value in new_config.items() if self.config_data.get(key) != value}
        if changes:
            self.validate_config(new_config)
            self.log_changes(changes)
            self.update_config_file(new_config)
            self.config_data = new_config

# Example usage
config_updater = ConfigUpdater('server_config.json', 'https://api.example.com/config')
config_updater.update()
