typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNFAPIList(int N) {
    if (N <= 0 || N > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Handle integer overflow
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(0)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand();
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    return list;
}
