import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.CompletableFuture;

public class ConnectionManager {

    private AsynchronousSocketChannel channel;
    private int connectionTimeout;
    private int retryInterval;

    public ConnectionManager(int timeout, int interval) {
        this.connectionTimeout = timeout;
        this.retryInterval = interval;
    }

    public CompletableFuture<Void> establishConnection(String address, int port) {
        return CompletableFuture.runAsync(() -> {
            while (true) {
                try {
                    channel = AsynchronousSocketChannel.open();
                    channel.connect(new InetSocketAddress(address, port)).get(connectionTimeout);
                    System.out.println("Connected to " + address + ":" + port);
                    break;
                } catch (Exception e) {
                    System.err.println("Failed to connect, retrying in " + retryInterval + "ms");
                    try {
                        Thread.sleep(retryInterval);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        });
    }

    public void closeConnection() {
        if (channel != null && channel.isOpen()) {
            try {
                channel.close();
            } catch (Exception e) {
                System.err.println("Error closing connection");
            }
        }
    }
}
