#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

namespace ImageProcessing {
    class ImageGenerator {
    public:
        struct ImageMetaData {
            std::string filename;
            int width;
            int height;

            ImageMetaData(const std::string& fn, int w, int h) : filename(fn), width(w), height(h) {}
        };

        ImageGenerator() : rng(std::random_device{}()) {}

        ~ImageGenerator() {}

        static std::mt19937 rng;

        void setSeed(uint64_t seed) {
            rng.seed(seed);
        }

        bool validateParameters(int numImages, int minWidth, int maxWidth, int minHeight, int maxHeight) const {
            return numImages > 0 && minWidth >= 0 && maxWidth >= minWidth && minHeight >= 0 && maxHeight >= minHeight;
        }

        ImageMetaData* generateImageMetadata(int numImages, int minWidth, int maxWidth, int minHeight, int maxHeight) {
            if (!validateParameters(numImages, minWidth, maxWidth, minHeight, maxHeight)) {
                throw std::invalid_argument("Invalid parameters");
            }

            const size_t arraySize = static_cast<size_t>(numImages);
            const size_t elementSize = sizeof(ImageMetaData);

            if (arraySize > std::numeric_limits<size_t>::max() / elementSize) {
                throw std::overflow_error("Memory allocation too large");
            }

            ImageMetaData* metadataArray = new (std::nothrow) ImageMetaData[arraySize];
            if (!metadataArray) {
                throw std::bad_alloc();
            }

            for (size_t i = 0; i < arraySize; ++i) {
                int width = rng() % (maxWidth - minWidth + 1) + minWidth;
                int height = rng() % (maxHeight - minHeight + 1) + minHeight;
                metadataArray[i] = ImageMetaData("image" + std::to_string(i) + ".jpg", width, height);
            }

            return metadataArray;
        }
    };

    std::mt19937 ImageGenerator::rng;
}

int main() {
    try {
        ImageProcessing::ImageGenerator generator;
        generator.setSeed(42);

        int numImages = 5;
        int minWidth = 100;
        int maxWidth = 800;
        int minHeight = 100;
        int maxHeight = 600;

        ImageProcessing::ImageGenerator::ImageMetaData* metadataArray = generator.generateImageMetadata(numImages, minWidth, maxWidth, minHeight, maxHeight);

        for (int i = 0; i < numImages; ++i) {
            std::cout << "File: " << metadataArray[i].filename << ", Width: " << metadataArray[i].width << ", Height: " << metadataArray[i].height << std::endl;
        }

        delete[] metadataArray;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
