using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Xml.Linq;

public class GameConfig
{
    public int TileSize { get; private set; }
    public (int Width, int Height) WorldDimensions { get; private set; }
    public float CharacterSpeed { get; private set; }
    public List<int> TextureResolutions { get; private set; }

    public static async Task<GameConfig> LoadFromXmlAsync(string filePath)
    {
        try
        {
            var xmlDoc = await XDocument.LoadAsync(filePath, LoadOptions.PreserveWhitespace);
            return new GameConfig(xmlDoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to load configuration: {ex.Message}");
            throw;
        }
    }

    private GameConfig(XDocument xmlDoc)
    {
        TileSize = int.Parse(xmlDoc.Root.Element("TileSize").Value);
        WorldDimensions = (int.Parse(xmlDoc.Root.Element("WorldWidth").Value), int.Parse(xmlDoc.Root.Element("WorldHeight").Value));
        CharacterSpeed = float.Parse(xmlDoc.Root.Element("CharacterSpeed").Value);

        var resolutionsElement = xmlDoc.Root.Element("TextureResolutions");
        if (resolutionsElement != null)
        {
            TextureResolutions = resolutionsElement.Elements()
                .Select(e => int.Parse(e.Value))
                .ToList();
        }
        else
        {
            TextureResolutions = new List<int> { 1024, 768 }; // Default values
        }
    }

    public void ApplyConfigurations()
    {
        // Apply configurations to the game engine or other components
        Console.WriteLine($"Tile Size: {TileSize}");
        Console.WriteLine($"World Dimensions: {WorldDimensions.Width}x{WorldDimensions.Height}");
        Console.WriteLine($"Character Speed: {CharacterSpeed}");
        foreach (var res in TextureResolutions)
        {
            Console.WriteLine($"Texture Resolution: {res}");
        }
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var config = await GameConfig.LoadFromXmlAsync("path_to_your_config_file.xml");
        config.ApplyConfigurations();
    }
}
