class FileLoader {
  constructor(baseDirectory, cacheInterval = 3600) {
    this.baseDirectory = baseDirectory;
    this.cacheInterval = cacheInterval * 1000; // Convert to milliseconds
    this.fileCache = {};
    this.fetchQueue = [];
    this.isFetching = false;
  }

  loadFiles(filePaths) {
    filePaths.forEach(filePath => {
      const fullPath = this.resolvePath(filePath);
      if (!this.isFileAccessible(fullPath)) {
        console.error(`File access denied: ${fullPath}`);
        return;
      }
      if (this.fileCache[filePath] && Date.now() - this.fileCache[filePath].lastAccessed < this.cacheInterval) {
        // Use cached version
        this.executeScript(this.fileCache[filePath].content);
      } else {
        this.fetchQueue.push(fullPath);
      }
    });
    this.processFetchQueue();
  }

  resolvePath(filePath) {
    if (!path.isAbsolute(filePath)) {
      filePath = path.resolve(this.baseDirectory, filePath);
    }
    return filePath;
  }

  isFileAccessible(filePath) {
    const relativePath = path.relative(this.baseDirectory, filePath);
    return relativePath.startsWith('..') || fs.existsSync(filePath);
  }

  processFetchQueue() {
    if (this.isFetching || this.fetchQueue.length === 0) return;

    const batch = this.fetchQueue.splice(0, 5); // Fetch up to 5 files in parallel
    this.isFetching = true;

    Promise.all(batch.map(fullPath => this.fetchFile(fullPath)))
      .then(results => {
        results.forEach(({ content, filePath }) => {
          this.fileCache[filePath] = { content, lastAccessed: Date.now() };
          this.executeScript(content);
        });
      })
      .catch(error => {
        console.error('Failed to load files:', error);
      })
      .finally(() => {
        this.isFetching = false;
        this.processFetchQueue();
      });
  }

  async fetchFile(fullPath) {
    try {
      const content = await fs.promises.readFile(fullPath, 'utf-8');
      return { content, filePath: fullPath };
    } catch (error) {
      console.error(`Failed to load file: ${fullPath}`, error);
      throw error;
    }
  }

  executeScript(content) {
    // Implement script execution logic here
    eval(content); // Example of dynamic script execution
  }
}

// Usage example
const loader = new FileLoader('/path/to/base/directory');
loader.loadFiles(['script1.js', 'subdir/script2.js']);
