<?php

class OAuthService {
    private $client;
    private $accessToken;
    private $cache;

    public function __construct($environment, $validateCerts = true) {
        $this->client = new HttpClient($environment, $validateCerts);
        $this->cache = new Cache();
    }

    public function authenticate($clientId, $clientSecret, $redirectUri, $code) {
        try {
            $response = $this->client->post('https://oauth-provider.com/token', [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'client_id' => $clientId,
                    'client_secret' => $clientSecret,
                    'redirect_uri' => $redirectUri,
                    'code' => $code
                ]
            ]);

            if ($response->getStatusCode() == 200) {
                $data = json_decode($response->getBody(), true);
                $this->accessToken = $data['access_token'];
                $_SESSION['access_token'] = $this->accessToken;
                return $data;
            } else {
                throw new Exception('Authentication failed: ' . $response->getStatusCode());
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            throw $e;
        }
    }

    public function getUserInfo() {
        if (!isset($_SESSION['access_token'])) {
            throw new Exception('User is not authenticated');
        }

        $accessToken = $_SESSION['access_token'];

        if ($this->cache->has('user_info')) {
            return $this->cache->get('user_info');
        }

        try {
            $response = $this->client->get('https://oauth-provider.com/user', [
                'headers' => [
                    'Authorization' => 'Bearer ' . $accessToken
                ]
            ]);

            if ($response->getStatusCode() == 200) {
                $data = json_decode($response->getBody(), true);
                $userInfo = ['id' => $data['id'], 'name' => $data['name'], 'email' => $data['email']];
                $this->cache->set('user_info', $userInfo, 3600); // Cache for 1 hour
                return $userInfo;
            } else {
                throw new Exception('Failed to fetch user info: ' . $response->getStatusCode());
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            throw $e;
        }
    }

    public function refreshToken() {
        try {
            $refreshToken = $_SESSION['refresh_token'];

            $response = $this->client->post('https://oauth-provider.com/token', [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    'client_id' => $_SESSION['client_id'],
                    'client_secret' => $_SESSION['client_secret'],
                    'refresh_token' => $refreshToken
                ]
            ]);

            if ($response->getStatusCode() == 200) {
                $data = json_decode($response->getBody(), true);
                $this->accessToken = $data['access_token'];
                $_SESSION['access_token'] = $this->accessToken;
                return $data;
            } else {
                throw new Exception('Token refresh failed: ' . $response->getStatusCode());
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            throw $e;
        }
    }
}

class HttpClient {
    private $client;

    public function __construct($environment, $validateCerts) {
        if ($environment == 'production') {
            $this->client = new GuzzleHttp\Client(['verify' => $validateCerts]);
        } else {
            $this->client = new GuzzleHttp\Client(['verify' => false]);
        }
    }

    public function get($uri, $options = []) {
        return $this->client->get($uri, $options);
    }

    public function post($uri, $options = []) {
        return $this->client->post($uri, $options);
    }
}

