class UnionFind {
private:
    vector<int> parent;
    vector<double> rank;
public:
    UnionFind(int n) : parent(n), rank(n, 1.0) {
        for (int i = 0; i < n; ++i)
            parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]); // Path compression
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x), rootY = find(y);
        if (rootX == rootY) return;

        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
            rank[rootX] += rank[rootY];
        } else {
            parent[rootX] = rootY;
            rank[rootY] += rank[rootX];
        }
    }
};

Result filterAndGroupTransactions(const vector<Transaction>& transactions) {
    int n = transactions.size();
    UnionFind uf(n);
    unordered_map<int, double> weightSums;

    priority_queue<pair<int, Transaction>, vector<pair<int, Transaction>>, greater<>> pq;
    for (int i = 0; i < n; ++i)
        pq.push({transactions[i].timestamp, transactions[i]});

    Result result = {0, -1};
    int maxWeightSetTime = 0;

    while (!pq.empty()) {
        auto [timestamp, currentTransaction] = pq.top();
        pq.pop();

        // Remove transactions older than 5 seconds
        while (!pq.empty() && pq.top().first < timestamp) {
            auto [_, oldTransaction] = pq.top();
            uf.unionSets(oldTransaction.id - 1, n);
            pq.pop();
        }

        int root = uf.find(currentTransaction.id - 1);
        if (weightSums.find(root) == weightSums.end())
            weightSums[root] = currentTransaction.weight;
        else
            weightSums[root] += currentTransaction.weight;

        // Update result if necessary
        if (weightSums[root] > result.maxWeightSum) {
            result.maxWeightSum = weightSums[root];
            result.maxWeightId = currentTransaction.id;
        }

        // Record the time taken for processing this disjoint set
        auto start = chrono::high_resolution_clock::now();
        uf.unionSets(currentTransaction.id - 1, n);
        auto end = chrono::high_resolution_clock::now();
        maxWeightSetTime = max(maxWeightSetTime, chrono::duration_cast<chrono::milliseconds>(end - start).count());
    }

    cout << "Maximum Weight Set Time: " << maxWeightSetTime << " ms" << endl;
    return result;
}
```

This code snippet provides a C++ implementation of a function to filter and group financial transactions based on their timestamps, transaction IDs, and weights. It uses a Union-Find data structure with path compression and rank-based union to efficiently manage disjoint sets of transactions. The function calculates the maximum weighted sum and tracks the time taken for processing each disjoint set in milliseconds. The implementation includes comments explaining key parts of the filtering process and the use of the Union-Find data structure.']

