int is_directory(const char *path) {
    struct stat path_stat;
    if (stat(path, &path_stat) != 0)
        return -1; // Error in stat()
    if (S_ISDIR(path_stat.st_mode))
        return 1;
    else
        return 0; // Not a directory
}

int file_exists(const char *filename) {
    if (access(filename, F_OK) == 0)
        return 1; // File exists
    else
        return 0; // File does not exist
}

const char* generate_unique_filename(const char *dir_path, int max_files) {
    static char filename[MAX_FILENAME_LENGTH];
    int i = 1;
    while (i <= max_files) {
        snprintf(filename, sizeof(filename), "%s/%d", dir_path, i);
        if (!file_exists(filename)) {
            return filename; // Return the first available unique filename
        }
        i++;
    }
    return NULL; // No more unique filenames available within the limit
}

int main() {
    const char *dir_path = "/path/to/directory";
    int max_files = 10;

    if (!is_directory(dir_path)) {
        fprintf(stderr, "Error: Provided path is not a directory\n");
        return 1;
    }

    const char *unique_filename = generate_unique_filename(dir_path, max_files);
    if (unique_filename != NULL) {
        printf("Generated unique filename: %s\n", unique_filename);
    } else {
        printf("Could not generate a unique filename within the specified limit.\n");
    }

    return 0;
}
