void init_cipher(const char *password, EVP_CIPHER_CTX **ctx) {
    unsigned char key[32];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(key, &sha256);

    *ctx = EVP_CIPHER_CTX_new();
    if (!*ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(*ctx);
        exit(EXIT_FAILURE);
    }
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

int execute_command_in_background(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return -1;
    } else if (pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    }
    return pid;
}
