            fprintf(stderr, "Invalid input for dimensions\n");
            free(metadata);
            return NULL;
        }

        // Basic bounds checking
        if (tempWidth <= 0 || tempHeight <= 0) {
            fprintf(stderr, "Dimensions must be positive\n");
            free(metadata);
            return NULL;
        }

        metadata[i].width = tempWidth;
        metadata[i].height = tempHeight;

        // Clear input buffer for the next loop
        while (getchar() != '\n');
    }

    return metadata;
