// Function to allocate memory for network packets
unsigned char* allocatePacketPayloads(const size_t* packet_lengths, int num_packets) {
    if (num_packets <= 0 || !packet_lengths) {
        return NULL;
    }

    // Calculate total required memory
    size_t total_memory = 0;
    for (int i = 0; i < num_packets; ++i) {
        if (packet_lengths[i] > SIZE_MAX - total_memory) {
            // Handle potential integer overflow
            fprintf(stderr, "Packet length exceeds available memory.\n");
            return NULL;
        }
        total_memory += packet_lengths[i];
    }

    // Allocate memory for all packets
    unsigned char* payload_block = malloc(total_memory);
    if (!payload_block) {
        // Memory allocation failed
        fprintf(stderr, "Failed to allocate memory for network packets.\n");
        return NULL;
    }

    // Initialize the allocated memory block
    size_t current_position = 0;
    for (int i = 0; i < num_packets; ++i) {
        memcpy(payload_block + current_position, packet_lengths[i], packet_lengths[i]);
        current_position += packet_lengths[i];
    }

    return payload_block;
}

// Example usage
int main() {
