#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    int count;
    int active_count;
    int inactive_count;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    list->active_count = 0;
    list->inactive_count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(DynamicList *list, RX_UE_INFORMATION_TAG ue_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }

    new_pdu->ue_tag = ue_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_flag = crc_flag;

    list->list[list->count] = new_pdu;
    list->count++;
    if (crc_flag == CRC_FLAG_ACTIVE) {
        list->active_count++;
    } else {
        list->inactive_count++;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void *purge_inactive(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    pthread_mutex_lock(&list->mutex);

    for (int i = list->count - 1; i >= 0; i--) {
        if (list->list[i]->crc_flag == CRC_FLAG_INACTIVE) {
            free(list->list[i]);
            memmove(&list->list[i], &list->list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->count - i - 1));
            list->count--;
            list->inactive_count--;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < list->count; i++) {
        free(list->list[i]);
    }

    list->count = 0;
    list->active_count = 0;
    list->inactive_count = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
