int check_memory_usage() {
    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        return -1; // Failed to get system information
    }
    long total_memory = info.totalram;
    long used_memory = info.totalswap + (total_memory - info.freeram);
    double memory_usage = ((double)used_memory / total_memory) * 100;
    if (memory_usage > 90) {
        printf("Memory usage is above 90%\n");
        return 1; // Memory usage too high
    }
    return 0; // Memory usage acceptable
}

