    if (num_elements > MAX_ELEMENTS) {
        printf("Number of elements requested exceeds the maximum limit\n");
        return NULL;
    }

    int retry_count = 0;
    while (retry_count < MAX_RETRIES) {
        NFAPI_CRC_INDICATION_PDU_T* array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array != NULL) {
            pthread_mutex_lock(&mutex);
