        if (check_memory_usage() != 0) {
            printf("Memory allocation failed due to high memory usage. Retrying with reduced number of elements.\n");
            num_elements /= 2;
        } else {
            printf("Memory allocation failed for unknown reason. Retrying...\n");
            retry_count++;
        }
    }

    printf("Failed to allocate memory after maximum retries\n");
    return NULL;
