NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        pthread_mutex_lock(&array_mutex);
        array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&array_mutex);

        if (array != NULL) {
            srand(time(NULL)); // Seed for random number generation

            for (size_t i = 0; i < num_elements; ++i) {
                array[i].RX_UE_INFORMATION_TAG = i + 1;
                array[i].RNTI = rand() % 65536;
                array[i].CRCFLAG = rand() % 256;
            }

            return array;
        } else {
            num_elements /= 2; // Reduce the number of elements on failure
        }
        retries++;
    }

    return NULL;
}

void process_batch(NFAPI_CRC_INDICATION_PDU_T *array, size_t start_index, size_t end_index) {
    pthread_mutex_lock(&array_mutex);
    for (size_t i = start_index; i < end_index; ++i) {
        // Process each element in the batch
    }
    pthread_mutex_unlock(&array_mutex);
}

int main() {
    time_t start_time, end_time;
    size_t total_elements = MAX_ELEMENTS;
    NFAPI_CRC_INDICATION_PDU_T *array;

    array = allocate_and_initialize_array(total_elements);

    if (array == NULL) {
        // Handle allocation failure
        return -1;
    }

    for (size_t batch_start = 0; batch_start < total_elements; batch_start += BATCH_SIZE) {
        size_t batch_end = batch_start + BATCH_SIZE > total_elements ? total_elements : batch_start + BATCH_SIZE;

        start_time = time(NULL);
        process_batch(array, batch_start, batch_end);
        end_time = time(NULL);

        printf("Batch processed from index %zu to %zu in %ld seconds\n", batch_start, batch_end - 1, end_time - start_time);
    }

    free(array);
    return 0;
}
