#include <stdlib.h>
#include <string.h>

typedef struct PacketNode {
    int timestamp;
    char source_ip[16];
    char destination_ip[16];
    size_t payload_size;
    char *payload;
    struct PacketNode *next;
} PacketNode;

PacketNode* create_packet_node(int timestamp, const char *source_ip, const char *destination_ip, const char *payload, size_t payload_size) {
    PacketNode *node = (PacketNode *)malloc(sizeof(PacketNode));
    if (node == NULL) {
        return NULL; // Memory allocation failed
    }

    node->timestamp = timestamp;
    strncpy(node->source_ip, source_ip, sizeof(node->source_ip) - 1);
    strncpy(node->destination_ip, destination_ip, sizeof(node->destination_ip) - 1);
    node->payload_size = payload_size;
    node->payload = (char *)malloc(payload_size);
    if (node->payload == NULL) {
        free(node);
        return NULL; // Memory allocation for payload failed
    }

    memcpy(node->payload, payload, payload_size);
    node->next = NULL;

    return node;
}

void destroy_packet_node(PacketNode *node) {
    if (node != NULL) {
        free(node->payload);
        free(node);
    }
}

PacketNode* process_packets(const char *packet_data, size_t data_length) {
    PacketNode *head = NULL;
    PacketNode **current = &head;

    const char *data_end = packet_data + data_length;
    while (packet_data < data_end) {
        int timestamp = *(int *)packet_data;
        packet_data += sizeof(int);

        char source_ip[16];
        strncpy(source_ip, packet_data, sizeof(source_ip));
        packet_data += sizeof(char) * 15; // Assuming IP address is exactly 15 characters long

        char destination_ip[16];
        strncpy(destination_ip, packet_data, sizeof(destination_ip));
        packet_data += sizeof(char) * 15; // Assuming IP address is exactly 15 characters long

        size_t payload_size = *(size_t *)packet_data;
        packet_data += sizeof(size_t);

        if (payload_size > data_end - packet_data) {
            break; // Packet size exceeds remaining data
        }

        PacketNode *new_node = create_packet_node(timestamp, source_ip, destination_ip, packet_data, payload_size);
        if (new_node == NULL) {
            while (*current != NULL) {
                PacketNode *temp = *current;
                *current = temp->next;
                destroy_packet_node(temp);
            }
            break; // Error creating node
        }

        *current = new_node;
        current = &(*current)->next;
        packet_data += payload_size;
    }

    return head;
}
