#define MAX_PACKETS 10000
#define MAX_MEMORY_USAGE (1024 * 1024 * 10) // 10 MB

typedef struct {
    uint64_t timestamp;
    size_t length;
    uint8_t protocol_id;
} PacketHeader;

PacketHeader* process_packets(const void* packet_data, size_t data_size, size_t packet_size, size_t* packet_count) {
    if (packet_size < sizeof(PacketHeader)) {
        return NULL; // Invalid packet size
    }

    size_t max_packets = MAX_MEMORY_USAGE / packet_size;
    if (max_packets > MAX_PACKETS || max_packets == 0) {
        return NULL; // Maximum memory usage or overflow
    }

    PacketHeader* headers = (PacketHeader*)malloc(max_packets * sizeof(PacketHeader));
    if (!headers) {
        return NULL; // Memory allocation failed
    }

    size_t count = 0;
    const uint8_t* data_end = packet_data + data_size;
    while (data_data < data_end && count < max_packets) {
        PacketHeader header;
        memcpy(&header, data_data, sizeof(PacketHeader));
        headers[count++] = header;

        data_data += packet_size;
    }

    *packet_count = count;
    return headers;
}
