void executeExternalCommand(char *command, char *args[], FILE *outputFile, FILE *errorFile) {
    pid_t pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Fork failed\n");
        return;
    } else if (pid == 0) {
        // Child process
        dup2(outputFile->fd, STDOUT_FILENO);
        dup2(errorFile->fd, STDERR_FILENO);
        close(outputFile->fd);
        close(errorFile->fd);
        execvp(command, args);
        fprintf(stderr, "Execvp failed\n");
        exit(1);
    } else {
        // Parent process
        waitpid(pid, NULL, 0);
        fclose(outputFile);
        fclose(errorFile);
    }
}

int convertJPEGtoPDF(char *sourceFile, char *outputFile) {
    FILE *output = fopen(outputFile, "w");
    if (!output) {
        perror("Failed to open output file");
        return 1;
    }

    char *command = "convert";
    char *args[] = {command, sourceFile, outputFile, NULL};

    executeExternalCommand(command, args, stdout, stderr);

    fclose(output);
    remove(sourceFile); // Clean up temporary file
    return 0;
}
