#include <stdint.h>

#define MAX_PACKET_SIZE 1024
#define MIN_PACKET_SIZE 1
#define HEADER_SIZE sizeof(uint32_t)
#define MAX_MEMORY_REQUEST (1 << 30) // 1 GB

typedef struct Packet {
    uint32_t payload_size;
    char payload[MAX_PACKET_SIZE];
} Packet;

uint64_t calculate_total_memory(Packet *packets, size_t num_packets) {
    uint64_t total_memory = 0;

    for (size_t i = 0; i < num_packets; ++i) {
        if (packets[i].payload_size < MIN_PACKET_SIZE || packets[i].payload_size > MAX_PACKET_SIZE) {
            return -1; // Invalid payload size
        }

        uint64_t required_memory = HEADER_SIZE + packets[i].payload_size;

        if (required_memory > UINT64_MAX - total_memory) {
            return -1; // Integer overflow detected
        }

        total_memory += required_memory;
    }

    if (total_memory > MAX_MEMORY_REQUEST) {
        return -1; // Exceeds maximum memory request limit
    }

    return total_memory;
}

int main() {
    Packet packets[] = {
        {500, "Data1"},
        {200, "Data2"},
        {300, "Data3"}
    };
    size_t num_packets = sizeof(packets) / sizeof(packets[0]);

    uint64_t total_memory = calculate_total_memory(packets, num_packets);

    if (total_memory == -1) {
        printf("Memory calculation error.\n");
    } else {
        printf("Total memory required: %llu bytes\n", total_memory);
    }

    return 0;
}
