AudioCollection* create_audio_collection(size_t initial_capacity) {
    AudioCollection *collection = (AudioCollection*)malloc(sizeof(AudioCollection));
    if (collection == NULL) {
        return NULL; // Handle memory allocation failure
    }
    collection->headers = (AudioSampleHeader*)calloc(initial_capacity, sizeof(AudioSampleHeader));
    if (collection->headers == NULL) {
        free(collection);
        return NULL; // Handle memory allocation failure
    }
    collection->sample_count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_audio_collection(AudioCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    free(collection->headers);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_sample(AudioCollection *collection, uint32_t frame_count) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->sample_count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        AudioSampleHeader *new_headers = realloc(collection->headers, new_capacity * sizeof(AudioSampleHeader));
        if (new_headers == NULL) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Handle memory allocation failure
        }
        collection->headers = new_headers;
        collection->capacity = new_capacity;
    }
    AudioSampleHeader *header = &collection->headers[collection->sample_count++];
    header->frame_count = frame_count;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

