            total_memory += count * 20; // Example header size for TCP
            break;
        case PROTOCOL_UDP:
            total_memory += count * 8;  // Example header size for UDP
            break;
        // Handle other protocols as needed
        default:
            fprintf(stderr, "Error: Unsupported protocol\n");
            return -1;
    }

    if (total_memory > SIZE_MAX) {
