ImageBufferManager* createImageBufferManager(size_t initialCapacity) {
    ImageBufferManager* manager = (ImageBufferManager*)malloc(sizeof(ImageBufferManager));
    if (manager == NULL) {
        return NULL; // Memory allocation failed
    }
    manager->metadataList = (ImageMetadata**)calloc(initialCapacity, sizeof(ImageMetadata*));
    if (manager->metadataList == NULL) {
        free(manager);
        return NULL; // Memory allocation failed
    }
    manager->allocatedSize = initialCapacity;
    manager->usedSize = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyImageBufferManager(ImageBufferManager* manager) {
    if (manager == NULL) {
        return;
    }
    for (size_t i = 0; i < manager->usedSize; ++i) {
        free(manager->metadataList[i]->filePath);
        free(manager->metadataList[i]);
    }
    free(manager->metadataList);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addImageMetadataAsync(ImageBufferManager* manager, const char* filePath) {
    if (manager == NULL || filePath == NULL) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->usedSize >= manager->allocatedSize) {
        size_t newCapacity = manager->allocatedSize * 2;
        ImageMetadata** newMetadataList = (ImageMetadata**)realloc(manager->metadataList, newCapacity * sizeof(ImageMetadata*));
        if (newMetadataList == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->metadataList = newMetadataList;
        manager->allocatedSize = newCapacity;
    }

    ImageMetadata* metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (metadata == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    metadata->filePath = strdup(filePath);
    if (metadata->filePath == NULL) {
        free(metadata);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    metadata->width = 0;
    metadata->height = 0;

    manager->metadataList[manager->usedSize++] = metadata;
    pthread_mutex_unlock(&manager->lock);

    // Asynchronously fetch image data and update width/height

    return 0;
}

int main() {
    ImageBufferManager* bufferManager = createImageBufferManager(10);
    if (bufferManager == NULL) {
        fprintf(stderr, "Failed to create ImageBufferManager\n");
        return 1;
    }

    addImageMetadataAsync(bufferManager, "path/to/image1.jpg");
    addImageMetadataAsync(bufferManager, "path/to/image2.jpg");

    // Simulate asynchronous processing and image data fetching
    // ...

    destroyImageBufferManager(bufferManager);
    return 0;
