#include <stdio.h>
#include <stdlib.h>

#define MAX_SUB_PACKETS 1024

typedef struct Packet {
    int sub_packet_count;
    int *sub_packets;
} Packet;

typedef struct PacketAggregation {
    int packet_count;
    Packet **packets;
} PacketAggregation;

Packet *create_packet(int sub_packet_count, int *sub_packets) {
    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    packet->sub_packet_count = sub_packet_count;
    packet->sub_packets = (int *)malloc(sub_packet_count * sizeof(int));
    if (!packet->sub_packets) {
        free(packet);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < sub_packet_count; i++) {
        packet->sub_packets[i] = sub_packets[i];
    }

    return packet;
}

PacketAggregation *create_packet_aggregation(int max_sub_packets) {
    PacketAggregation *aggregation = (PacketAggregation *)malloc(sizeof(PacketAggregation));
    if (!aggregation) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    aggregation->packet_count = 0;
    aggregation->packets = (Packet **)malloc(max_sub_packets * sizeof(Packet *));
    if (!aggregation->packets) {
        free(aggregation);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    return aggregation;
}

void add_packet_to_aggregation(PacketAggregation *aggregation, Packet *packet) {
    if (aggregation->packet_count >= MAX_SUB_PACKETS) {
        fprintf(stderr, "Too many packets for aggregation\n");
        return;
    }

    aggregation->packets[aggregation->packet_count++] = packet;
}

void destroy_packet(Packet *packet) {
    free(packet->sub_packets);
    free(packet);
}

void destroy_packet_aggregation(PacketAggregation *aggregation) {
    for (int i = 0; i < aggregation->packet_count; i++) {
        destroy_packet(aggregation->packets[i]);
    }
    free(aggregation->packets);
    free(aggregation);
}
