#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1 GB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
sem_t memory_semaphore;
size_t total_memory_used = 0;

void* create_and_populate_linked_list(void* arg) {
    int N = *(int*)arg; // Number of elements to create
    size_t required_memory = N * sizeof(Node);

    if (total_memory_used + required_memory > MAX_MEMORY_LIMIT) {
        printf("Memory limit exceeded\n");
        return NULL;
    }

    sem_wait(&memory_semaphore);
    for (int i = 0; i < N; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed\n");
            sem_post(&memory_semaphore);
            return NULL;
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        new_node->data.RNTI = rand() % 500; // Example value
        new_node->data.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
        new_node->next = head;
        head = new_node;
        total_memory_used += sizeof(Node);
    }
    sem_post(&memory_semaphore);
    return NULL;
}

int main() {
    int N = 1000; // Example value

    if (sem_init(&memory_semaphore, 0, 1) != 0) {
        printf("Semaphore initialization failed\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, create_and_populate_linked_list, &N) != 0) {
        printf("Thread creation failed\n");
        sem_destroy(&memory_semaphore);
        return 1;
    }

    pthread_join(thread_id, NULL);

    sem_destroy(&memory_semaphore);

    // Clean up allocated memory
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
