#include <stdbool.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000
#define MEMORY_LIMIT 1048576 // 1 MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rnti;
    bool crcFlag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t currentMemoryUsage;
    size_t maxMemoryUsage;
    int currentSize;
    int maxSize;
    pthread_mutex_t lock;
} LinkedList;

bool initLinkedList(LinkedList *list, int maxSize, size_t maxMemoryUsage) {
    if (maxSize <= 0 || maxMemoryUsage <= 0) {
        return false; // Invalid input
    }
    list->head = NULL;
    list->currentMemoryUsage = 0;
    list->maxMemoryUsage = maxMemoryUsage;
    list->currentSize = 0;
    list->maxSize = maxSize;
    pthread_mutex_init(&list->lock, NULL);
    return true;
}

bool addElement(LinkedList *list, int rnti) {
    if (list->currentSize >= list->maxSize || list->currentMemoryUsage + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->maxMemoryUsage) {
        return false; // Reached size or memory limit
    }
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *newElement = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElement) {
        pthread_mutex_unlock(&list->lock);
        return false; // Memory allocation failed
    }
    newElement->rnti = rnti;
    newElement->crcFlag = false;
    newElement->next = list->head;
    list->head = newElement;
    list->currentMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->currentSize++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool removeElement(LinkedList *list, int rnti) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;
    while (current != NULL) {
        if (current->rnti == rnti) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->currentMemoryUsage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            list->currentSize--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false; // Element not found
}

bool updateCRCFlag(LinkedList *list, int rnti, bool crcFlag) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            current->crcFlag = crcFlag;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false; // Element not found
}
