#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PROFILES_PER_NODE 1000
#define PROFILE_SIZE 1024

typedef struct UserProfile {
    char username[50];
    int age;
    char email[100];
} UserProfile;

typedef struct Node {
    UserProfile profiles[MAX_PROFILES_PER_NODE];
    int profile_count;
    struct Node* next_node;
} Node;

Node* head = NULL;

// Function to add a new user profile
void add_user_profile(const char* username, int age, const char* email) {
    Node* current = head;
    while (current != NULL) {
        if (current->profile_count < MAX_PROFILES_PER_NODE) {
            strcpy(current->profiles[current->profile_count].username, username);
            current->profiles[current->profile_count].age = age;
            strcpy(current->profiles[current->profile_count].email, email);
            current->profile_count++;
            return;
        }
        current = current->next_node;
    }

    // If no node has space, create a new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strcpy(new_node->profiles[0].username, username);
    new_node->profiles[0].age = age;
    strcpy(new_node->profiles[0].email, email);
    new_node->profile_count = 1;
    new_node->next_node = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next_node != NULL) {
            temp = temp->next_node;
        }
        temp->next_node = new_node;
    }
}

// Function to retrieve user profile
UserProfile* get_user_profile(const char* username) {
    Node* current = head;
    while (current != NULL) {
        for (int i = 0; i < current->profile_count; i++) {
            if (strcmp(current->profiles[i].username, username) == 0) {
                return &current->profiles[i];
            }
        }
        current = current->next_node;
    }
    return NULL;
}

// Function to serialize user profiles
void serialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->profile_count, sizeof(int), 1, file);
        fwrite(current->profiles, sizeof(UserProfile), MAX_PROFILES_PER_NODE, file);
        current = current->next_node;
    }

    fclose(file);
}

// Function to deserialize user profiles
void deserialize_profiles(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    while (!feof(file)) {
        int count;
        fread(&count, sizeof(int), 1, file);
        if (count <= 0) break;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        new_node->profile_count = count;
        fread(new_node->profiles, sizeof(UserProfile), MAX_PROFILES_PER_NODE, file);
        new_node->next_node = head;

        head = new_node;
    }

    fclose(file);
}

// Function to free all allocated memory
void free_profiles() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next_node;
        free(current);
        current = next;
    }
    head = NULL;
}
