    if (desired_images < loaded_images || desired_images > MAX_IMAGES) {
        fprintf(stderr, "Invalid number of images requested\n");
        return;
    }

    size_t new_size = desired_images * sizeof(ImageMetadata);

    // Allocate memory in chunks to improve scalability
    if (!image_list || new_size > allocated_images * sizeof(ImageMetadata)) {
        image_list = safe_realloc(image_list, new_size);
        allocated_images = new_size / sizeof(ImageMetadata);
    }

    // Load metadata into the new memory
    for (int i = loaded_images; i < desired_images; i++) {
        image_list[i].width = rand() % 1920 + 640;
        image_list[i].height = rand() % 1080 + 480;
        snprintf(image_list[i].format, sizeof(image_list[i].format), "JPEG");
    }

    loaded_images = desired_images;
}

