    image_list = (ImageMetadata*)malloc(MAX_IMAGES * sizeof(ImageMetadata));
    if (!image_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }
    allocated_images = MAX_IMAGES;

    // Load metadata
    load_image_metadata();

    // Manage metadata dynamically
    manage_image_metadata();

    // Free allocated memory
