    for (int i = 0; i < N; ++i) {
        pdus[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG + i;
        pdus[i].rnti = RNTI + i;
        pdus[i].crc_indication_rel8_tag = (rand() % 256);
    }

    return pdus;
}

unsigned char* compute_md5(const char* str, size_t len) {
    unsigned char* digest = (unsigned char*)malloc(MD5_DIGEST_LENGTH * sizeof(unsigned char));
    if (!digest) {
        return NULL;
    }

    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str, len);
    MD5_Final(digest, &md5);

    return digest;
}

void free_md5_digest(unsigned char* digest) {
    free(digest);
}

