        }
        free(pdus);
    }

    const char* input = "Hello, World!";
    size_t len = strlen(input);
    unsigned char* md5_digest = compute_md5(input, len);
    if (md5_digest) {
        printf("MD5 Digest: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            printf("%02x", md5_digest[i]);
        }
        free_md5_digest(md5_digest);
    }

    return 0;
}
