#include <string.h>

#define MAX_FILENAME_LEN 256
#define MIN_WIDTH 1
#define MAX_WIDTH 4096
#define MIN_HEIGHT 1
#define MAX_HEIGHT 4096

typedef struct {
    char filename[MAX_FILENAME_LEN];
    int width;
    int height;
} IMAGE_METADATA_T;

int safe_multiply(int a, int b, size_t *result) {
    if (b > SIZE_MAX / a) {
        return -1; // Overflow
    }
    *result = (size_t)a * b;
    return 0;
}

int processImageMetadata(const char *filename, IMAGE_METADATA_T **metadata, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Count the number of entries
    int entry_count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        entry_count++;
    }
    rewind(file);

    if (entry_count == 0) {
        fprintf(stderr, "No image entries found in the file.\n");
        fclose(file);
        return -1;
    }

    size_t total_size;
    if (safe_multiply(entry_count, sizeof(IMAGE_METADATA_T), &total_size) != 0) {
        fprintf(stderr, "Error calculating memory size.\n");
        fclose(file);
        return -1;
    }

    *metadata = (IMAGE_METADATA_T *)malloc(total_size);
    if (!*metadata) {
        perror("Failed to allocate memory for metadata");
        fclose(file);
        return -1;
    }

    *count = entry_count;

    // Read the entries
    size_t offset = 0;
    while (fgets(line, sizeof(line), file)) {
        sscanf(line, "%s %d %d", (*metadata + offset)->filename, &(*metadata + offset)->width, &(*metadata + offset)->height);
        if ((*metadata + offset)->width < MIN_WIDTH || (*metadata + offset)->width > MAX_WIDTH ||
            (*metadata + offset)->height < MIN_HEIGHT || (*metadata + offset)->height > MAX_HEIGHT) {
            fprintf(stderr, "Invalid dimensions in entry %zu\n", offset);
            free(*metadata);
            fclose(file);
            return -1;
        }
        offset++;
    }

    fclose(file);
    return 0;
}
