#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
    clock_t last_log_time;
} DynamicArray;

DynamicArray* create_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*) malloc(sizeof(DynamicArray));
    if (!array) {
        return NULL; // Memory allocation failed
    }
    array->elements = (NFAPI_CRC_INDICATION_PDU_T*) calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        free(array);
        return NULL; // Memory allocation failed
    }
    array->capacity = initial_capacity;
    array->count = 0;
    array->last_log_time = clock();
    return array;
}

void destroy_array(DynamicArray *array) {
    if (array) {
        free(array->elements);
        free(array);
    }
}

int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!array) {
        return -1; // Invalid array
    }

    time_t current_time = clock();
    double elapsed_time = (double)(current_time - array->last_log_time) / CLOCKS_PER_SEC;
    if (elapsed_time >= 5.0) { // Log every 5 seconds
        array->last_log_time = current_time;
        printf("Attempting to add element at time: %.2f\n", elapsed_time);
    }

    if (array->count >= MAX_ELEMENTS) {
        return -2; // Array full
    }

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            return -3; // Memory reallocation failed
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    array->elements[array->count++] = element;
    return 0; // Success
}

int main() {
    DynamicArray *array = create_array(10);
    if (!array) {
        fprintf(stderr, "Failed to create array\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = (unsigned short)(rand() % 65536),
            .CRC_INDICATION_REL8_TAG = 'C' + rand() % ('9' - 'C')
        };
        int result = add_element(array, element);
        if (result == -1) {
            fprintf(stderr, "Invalid array\n");
        } else if (result == -2) {
            printf("Array full\n");
        } else if (result == -3) {
            fprintf(stderr, "Memory reallocation failed\n");
        }
    }

    destroy_array(array);
    return EXIT_SUCCESS;
}
