    list->max_memory_limit = max_memory;
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (node == NULL) {
        perror("Failed to allocate memory for list node");
        return NULL;
    }
    node->ue_info_tag = ue_info_tag;
    node->rnti = rnti;
    node->crc_flag = crc_flag;
    node->timestamp = time(NULL);
    node->data_length = sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(RX_UE_INFORMATION_TAG) + sizeof(uint16_t) + sizeof(CRC_INDICATION_REL8_TAG) + sizeof(time_t) + sizeof(size_t);
    node->next = NULL;
    return node;
}

void add_node(DynamicLinkedList* list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    pthread_mutex_lock(&list->lock);
    if (list->total_memory_used + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->max_memory_limit) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(ue_info_tag, rnti, crc_flag);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->total_memory_used += new_node->data_length;
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(DynamicLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->total_memory_used = 0;
    pthread_mutex_unlock(&list->lock);
}
