fn manage_linked_list(max_size: usize) -> Result<(), std::io::Error> {
    create_directory_if_not_exists("nfaapi_data")?;

    let dir_path = env::var_os("DIRECTORY_PATH").unwrap();
    let file_path = dir_path.join(format!("data_{}.bin", Instant::now().epoc()));

    fs::File::create(&file_path)?;

    let data: Arc<Mutex<LinkedList<NFAPI_CRC_INDICATION_PDU_T>>> = Arc::new(Mutex::new(LinkedList::new()));
    let mut guard = data.lock().unwrap();

    for _ in 0..max_size {
