            rx_ue_information_tag: rand::random(),
            rnti: rand::random(),
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag: rand::random() },
        };

        if guard.len() < max_size {
            guard.push_back(new_data);
        } else {
            break;
        }
    }

    drop(guard);

    let data_to_write: Vec<u8> = guard.iter().flat_map(|item| item.to_vec()).collect();
