#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONCURRENT_IMAGES 10000
#define MAX_PIXELS_PER_IMAGE 10000000
#define TOTAL_MEMORY_LIMIT 2 * 1024 * 1024 * 1024

typedef struct {
    int width;
    int height;
    unsigned char* pixel_data;
} IMG_T;

IMG_T* image_pool[MAX_CONCURRENT_IMAGES];
int image_count = 0;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void segment_raw_data(unsigned char* raw_data, int data_size) {
    pthread_mutex_lock(&pool_mutex);

    for (int i = 0; i < data_size; ) {
        if (image_count >= MAX_CONCURRENT_IMAGES) {
            // Handle saturation by buffering or throttling
            printf("Processing queue saturated. Buffering or throttling required.\n");
            pthread_mutex_unlock(&pool_mutex);
            return;
        }

        int width = raw_data[i++];
        int height = raw_data[i++];

        if (width * height > MAX_PIXELS_PER_IMAGE || width * height < 0) {
            printf("Invalid image dimensions.\n");
            continue;
        }

        unsigned char* pixel_data = (unsigned char*)malloc(width * height);
        if (!pixel_data) {
            printf("Memory allocation failed for new image structure.\n");
            pthread_mutex_unlock(&pool_mutex);
            return;
        }

        for (int j = 0; j < width * height; ++j) {
            pixel_data[j] = raw_data[i++];
        }

        IMG_T* img = (IMG_T*)malloc(sizeof(IMG_T));
        if (!img) {
            printf("Memory allocation failed for image structure.\n");
            free(pixel_data);
            pthread_mutex_unlock(&pool_mutex);
            return;
        }

        img->width = width;
        img->height = height;
        img->pixel_data = pixel_data;

        image_pool[image_count++] = img;

        if (image_count * sizeof(IMG_T) + image_count * MAX_PIXELS_PER_IMAGE > TOTAL_MEMORY_LIMIT) {
            printf("Total memory allocation exceeds limit.\n");
            for (int j = 0; j < image_count; ++j) {
                free(image_pool[j]->pixel_data);
                free(image_pool[j]);
            }
            image_count = 0;
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
    }

    pthread_mutex_unlock(&pool_mutex);
}

void process_images() {
    pthread_mutex_lock(&pool_mutex);

    for (int i = 0; i < image_count; ++i) {
        IMG_T* img = image_pool[i];
        // Process the image
        printf("Processing image with width %d and height %d\n", img->width, img->height);
        free(img->pixel_data);
        free(img);
    }

    image_count = 0;

    pthread_mutex_unlock(&pool_mutex);
}

int main() {
    unsigned char raw_data[] = {10, 5, 255, 0, 0, 255, 10, 7, 0, 255, 255, 0};
    int data_size = sizeof(raw_data) / sizeof(raw_data[0]);

    segment_raw_data(raw_data, data_size);
    process_images();

    return 0;
}
