#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_IP_LEN 46

int resolve_dns(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return status;
    }

    *ip_address = (u_char *)malloc(MAX_IP_LEN);
    if (*ip_address == NULL) {
        perror("Failed to allocate memory for IP address");
        freeaddrinfo(res);
        return -1;
    }

    p = res;
    while (p != NULL) {
        void *addr;
        char ip_str[MAX_IP_LEN];

        // Get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // Convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ip_str, sizeof(ip_str));
        printf("IP address: %s\n", ip_str);

        // Copy the IP to the output buffer
        strcpy((char *)*ip_address, ip_str);
        break;

        p = p->ai_next;
    }

    freeaddrinfo(res);
    return 0;
}

int main() {
    u_char *ip_address;
    int result = resolve_dns("www.example.com", &ip_address);
    if (result == 0) {
        printf("Resolved IP address: %s\n", ip_address);
        free(ip_address);
    } else {
        fprintf(stderr, "Failed to resolve DNS for www.example.com\n");
    }
    return 0;
}
