typedef struct LinkedList {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void appendNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void generateRandomData(NFAPI_CRC_INDICATION_PDU_T* data) {
    data->RX_UE_INFORMATION_TAG = rand();
    data->RNTI = rand() % 65536; // RNTI is a 16-bit integer
    data->CRC_INDICATION_REL8_TAG = (rand() & 1); // Randomly set CRCFLAG
}

int populateLinkedList(LinkedList* list, size_t maxCount) {
    if (list == NULL || maxCount == 0) return -1;

    for (size_t i = 0; i < maxCount; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        generateRandomData(&data);
        appendNode(list, data);
    }
    return 0;
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));
    LinkedList myList;
    initLinkedList(&myList);

    size_t maxCount = 100; // Example maximum count
    if (populateLinkedList(&myList, maxCount) != 0) {
        fprintf(stderr, "Failed to populate linked list\n");
    }

    freeLinkedList(&myList);
    return 0;
}
