#define MAX_ENTRIES 10000

typedef struct {
    int width;
    int height;
    char filePath[256];
} ImageMetadata;

ImageMetadata* allocateMemory(int numEntries) {
    if (numEntries <= 0 || numEntries > MAX_ENTRIES) {
        fprintf(stderr, "Invalid number of entries.\n");
        return NULL;
    }
    ImageMetadata* metadata = malloc(numEntries * sizeof(ImageMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    return metadata;
}

int computeSHA256(const char* filename, unsigned char hash[SHA256_DIGEST_LENGTH]) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    const int bufferSize = 4096;
    char buffer[bufferSize];
    while (size_t bytesRead = fread(buffer, 1, bufferSize, file)) {
        if (!SHA256_Update(&sha256, buffer, bytesRead)) {
            fclose(file);
            return -1;
        }
    }
    fclose(file);

    if (!SHA256_Final(hash, &sha256)) {
        return -1;
    }

    return 0;
}

void processImageMetadata(int numEntries, ImageMetadata* metadata) {
    for (int i = 0; i < numEntries; ++i) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        if (computeSHA256(metadata[i].filePath, hash) == -1) {
            printf("Failed to compute SHA-256 for file: %s\n", metadata[i].filePath);
            continue;
        }

        // Process the hash as needed
        printf("File: %s, Hash: ", metadata[i].filePath);
        for (int j = 0; j < SHA256_DIGEST_LENGTH; ++j) {
            printf("%02x", hash[j]);
        }
        printf("\n");
    }
}

int main() {
    int numEntries = 5;
    ImageMetadata* metadata = allocateMemory(numEntries);
    if (metadata == NULL) {
        return -1;
    }

    // Populate metadata with image information
    strcpy(metadata[0].filePath, "image1.jpg");
    metadata[0].width = 800;
    metadata[0].height = 600;

    strcpy(metadata[1].filePath, "image2.jpg");
    metadata[1].width = 1024;
    metadata[1].height = 768;

    // Add more entries as needed

    processImageMetadata(numEntries, metadata);

    free(metadata);
    return 0;
}
