typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void populateNfapiPduList(Node** head) {
    if (*head != NULL) {
        printf("Error: List is not empty\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pduData;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        // Initialize pduData with random values
        pduData.RX_UE_INFORMATION_TAG = rand() % 1000;
        pduData.RNTI = rand() % 500;
        pduData.CRC_INDICATION_REL8_TAG = rand() % 256;
        pduData.CRCFLAG = (rand() % 2) ? 0 : 1;

        Node* newNode = createNode(pduData);
        newNode->next = *head;
        *head = newNode;
    }
}

int main() {
    Node* head = NULL;
    populateNfapiPduList(&head);

    // Clean up memory
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
