#define MAX_IP_SIZE 16

typedef unsigned char u_char;

int dns_test_runner(const char* hostname, u_char* ip_array, size_t max_size, FILE* log_file) {
    struct sockaddr_in address;
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        fprintf(log_file, "Failed to create socket for DNS resolution\n");
        return -1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_port = htons(80);

    int ret = inet_pton(AF_INET, hostname, &address.sin_addr);
    if (ret <= 0) {
        fprintf(log_file, "Invalid IP address/ Address not supported\n");
        close(sock);
        return -1;
    }

    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    memcpy(&dest_addr.sin_addr, &address.sin_addr, sizeof(address.sin_addr));

    time_t start_time = time(NULL);

    ret = connect(sock, (struct sockaddr*)&dest_addr, sizeof(dest_addr));
    if (ret == -1) {
        fprintf(log_file, "Connection to %s failed\n", hostname);
        close(sock);
        return -1;
    }

    socklen_t addr_len = sizeof(address);
    ret = getsockname(sock, (struct sockaddr*)&address, &addr_len);
    if (ret == -1) {
        fprintf(log_file, "Failed to get socket name for %s\n", hostname);
        close(sock);
        return -1;
    }

    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &address.sin_addr, ip_str, INET_ADDRSTRLEN);

    if (max_size >= strlen(ip_str) + 1) {
        strcpy((char*)ip_array, ip_str);
    } else {
        fprintf(log_file, "Buffer too small for IP address\n");
        close(sock);
        return -1;
    }

    time_t end_time = time(NULL);
    double duration = difftime(end_time, start_time);

    fprintf(log_file, "Resolved %s to %s in %.2f seconds\n", hostname, ip_str, duration);

    close(sock);
    return 0;
}

int main() {
    FILE* log_file = fopen("dns_test_runner.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    u_char ip_array[MAX_IP_SIZE];

    // Test case 1
    int result = dns_test_runner("www.google.com", ip_array, MAX_IP_SIZE, log_file);
    if (result != 0) {
        fprintf(log_file, "Test case 1 failed\n");
    } else {
        fprintf(log_file, "Test case 1 passed: IP address is %s\n", (char*)ip_array);
    }

    // Test case 2
    result = dns_test_runner("nonexistentdomain123456789.com", ip_array, MAX_IP_SIZE, log_file);
    if (result != 0) {
        fprintf(log_file, "Test case 2 failed\n");
    } else {
        fprintf(log_file, "Test case 2 passed: IP address is %s\n", (char*)ip_array);
    }

    fclose(log_file);
    return 0;
}
