// Define a structure for network packets
typedef struct {
    int segment_count;
    int *segment_sizes;
} NetworkPacket;

// Function to calculate total buffer size safely
size_t calculate_total_size(NetworkPacket packet) {
    size_t total_size = 0;
    for (int i = 0; i < packet.segment_count; ++i) {
        if (total_size > SIZE_MAX - packet.segment_sizes[i]) {
            // Handle overflow by returning a large value or an error code
            return SIZE_MAX;
        }
        total_size += packet.segment_sizes[i];
    }
    return total_size;
}

// Function to aggregate network segments into a single buffer
int aggregate_segments(NetworkPacket packet, char *buffer) {
    size_t total_size = calculate_total_size(packet);
    if (total_size == SIZE_MAX) {
        // Handle error due to overflow or invalid input
        return -1; // Error code for overflow
    }

    // Aggregate segments into the buffer
    char *current_position = buffer;
    for (int i = 0; i < packet.segment_count; ++i) {
        memcpy(current_position, &packet.segment_sizes[i], packet.segment_sizes[i]);
        current_position += packet.segment_sizes[i];
    }
    return total_size;
}

// Example usage
int main() {
    NetworkPacket packet = {3, (int[]){100, 200, 50}};
    char *buffer = (char *)malloc(calculate_total_size(packet));

    if (aggregate_segments(packet, buffer) == -1) {
        printf("Error in aggregating segments.\n");
    } else {
        printf("Segments aggregated successfully.\n");
    }

    free(buffer);
    return 0;
}
