#define MAX_PACKET_SIZE 1500
#define CACHE_SIZE 10

typedef struct {
    int size;
    int next;
} PayloadCache;

PayloadCache cache[CACHE_SIZE];
int cache_head = 0;
int cache_tail = 0;
int cache_count = 0;

void addToCache(int size) {
    if (cache_count < CACHE_SIZE) {
        cache[cache_tail].size = size;
        cache[cache_tail].next = -1; // Indicate end of list
        cache_count++;
        cache_tail = (cache_tail + 1) % CACHE_SIZE;
    }
}

int isValidPayloadSize(int size) {
    return size > 0 && size <= MAX_PACKET_SIZE;
}

size_t safeAdd(size_t a, size_t b) {
    if (b > SIZE_MAX - a)
        exit(EXIT_FAILURE); // Handle integer overflow
    return a + b;
}

void* concatenatePackets(int packet_sizes[], int count) {
    size_t total_size = 0;
    for (int i = 0; i < count; i++) {
        if (!isValidPayloadSize(packet_sizes[i])) {
            fprintf(stderr, "Invalid payload size\n");
            exit(EXIT_FAILURE);
        }
        addToCache(packet_sizes[i]);
        total_size = safeAdd(total_size, packet_sizes[i]);
    }

    void* buffer = malloc(total_size);
    if (buffer == NULL) {
        perror("Failed to allocate memory for packets");
        exit(EXIT_FAILURE);
    }

    char* ptr = buffer;
    for (int i = 0; i < count; i++) {
        memcpy(ptr, /* Get packet data here */, packet_sizes[i]); // Assuming packet data is available
        ptr += packet_sizes[i];
    }

    return buffer;
}

void freeBuffer(void* buffer) {
    free(buffer);
}
