    size_t max_size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Aggregator;

void aggregator_init(Aggregator* agg, size_t max_size) {
    agg->head = NULL;
    agg->tail = NULL;
    agg->total_size = 0;
    agg->max_size = max_size;
    pthread_mutex_init(&agg->mutex, NULL);
    pthread_cond_init(&agg->cond, NULL);
}

void aggregator_destroy(Aggregator* agg) {
    Packet* current = agg->head;
    while (current != NULL) {
        Packet* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&agg->mutex);
    pthread_cond_destroy(&agg->cond);
}

void aggregator_add_packet(Aggregator* agg, void* payload, size_t length) {
    pthread_mutex_lock(&agg->mutex);
    while (agg->total_size + length > agg->max_size) {
        pthread_cond_wait(&agg->cond, &agg->mutex);
    }
    Packet* new_packet = malloc(sizeof(Packet));
    if (new_packet == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_packet->payload = payload;
    new_packet->length = length;
    new_packet->next = NULL;
    if (agg->tail != NULL) {
        agg->tail->next = new_packet;
    } else {
        agg->head = new_packet;
    }
    agg->tail = new_packet;
    agg->total_size += length;
    pthread_cond_signal(&agg->cond);
    pthread_mutex_unlock(&agg->mutex);
}

void* aggregator_get_payload(Aggregator* agg) {
    pthread_mutex_lock(&agg->mutex);
    while (agg->head == NULL) {
        pthread_cond_wait(&agg->cond, &agg->mutex);
    }
    Packet* packet = agg->head;
    void* payload = packet->payload;
    size_t length = packet->length;
    agg->head = packet->next;
    if (agg->tail == packet) {
        agg->tail = NULL;
    }
    agg->total_size -= length;
    free(packet);
    pthread_cond_signal(&agg->cond);
    pthread_mutex_unlock(&agg->mutex);
    return payload;
}

// Additional functions for decoding, decrypting, and logging can be implemented here
