#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} LinkedList;

void init_list(LinkedList* list, size_t max_size) {
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Insertion successful
}

void destroy_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
