#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields as per your requirements
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} DoublyLinkedList;

// Function to initialize the doubly linked list
void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a new node at the end of the list
void add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Memory allocation failed");
        return;
    }
    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a node from the list by data
void remove_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data == data) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->size--;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to clean up old entries
void cleanup_old_entries(DoublyLinkedList* list, size_t max_size) {
    while (list->size > max_size) {
        Node* toRemove = list->head;
        if (toRemove != NULL) {
            remove_node(list, toRemove->data);
        }
    }
}

// Function to destroy the list
void destroy_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    DoublyLinkedList myList;
    init_list(&myList);

    NFAPI_CRC_INDICATION_PDU_T pdu1, pdu2;
    // Initialize pdu1 and pdu2 with valid data

    add_node(&myList, pdu1);
    add_node(&myList, pdu2);

    cleanup_old_entries(&myList, 10); // Assuming a maximum size of 10 entries

    destroy_list(&myList);

    return 0;
}
