#include <condition_variable>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

class ConcurrentLinkedListManager {
private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> linkedList;
    std::mutex mutex;
    std::condition_variable condVar;
    size_t maxSize;

public:
    ConcurrentLinkedListManager(size_t initialMaxSize) : maxSize(initialMaxSize) {}

    void addItem() {
        std::unique_lock<std::mutex> lock(mutex);
        condVar.wait(lock, [this] { return linkedList.size() < maxSize; });

        NFAPI_CRC_INDICATION_PDU_T newItem;
        newItem.RX_UE_INFORMATION_TAG = getRandomRX_UE_INFORMATION_TAG();
        newItem.RNTI = getRandomRNTI();
        newItem.CRCFLAG = getRandomCRCFLAG();

        linkedList.push_back(newItem);
    }

    void removeItem() {
        std::unique_lock<std::mutex> lock(mutex);
        condVar.wait(lock, [this] { return !linkedList.empty(); });

        linkedList.pop_front();
    }

private:
    int getRandomRX_UE_INFORMATION_TAG() {
        // Simulate fetching from external data source
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 1000);
        return dis(gen);
    }

    int getRandomRNTI() {
        // Simulate fetching from external data source
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 256);
        return dis(gen);
    }

    bool getRandomCRCFLAG() {
        // Simulate random setting
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 1);
        return dis(gen) == 1;
    }
};

int main() {
    ConcurrentLinkedListManager manager(10); // Set initial max size to 10

    // Simulate adding and removing items
    for (size_t i = 0; i < 20; ++i) {
        manager.addItem();
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        if (linkedList.size() > 5) {
            manager.removeItem();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    return 0;
}
```

