typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    ECB_MODE,
    CBC_MODE,
    CFB_MODE,
    OFB_MODE,
    NULL_ENCRYPTION
} ENCRYPTION_MODE;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    ENCRYPTION_MODE mode;
} CryptoContext;

CryptoContext* create_crypto_context(ENCRYPTION_MODE mode, int buffer_size) {
    CryptoContext *context = (CryptoContext*)malloc(sizeof(CryptoContext));
    if (!context) {
        return NULL; // Memory allocation failed
    }

    context->mode = mode;
    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) {
        free(context);
        return NULL; // OpenSSL initialization failed
    }

    switch (mode) {
        case ECB_MODE:
            if (1 != EVP_EncryptInit_ex(context->ctx, EVP_des_ecb(), NULL, NULL, NULL)) {
                EVP_CIPHER_CTX_free(context->ctx);
                free(context);
                return NULL;
            }
            break;
        // Add cases for other modes
        default:
            EVP_CIPHER_CTX_free(context->ctx);
            free(context);
            return NULL; // Unsupported mode
    }

    return context;
}

int populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T *list, int num_structures) {
    if (num_structures <= 0 || list == NULL) {
        return -1; // Invalid input
    }

    for (int i = 0; i < num_structures; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        list[i].RNTI = rand() % UINT16_MAX;
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 256);
    }

    return 0; // Success
}

void encrypt_data(CryptoContext *context, uint8_t *data, int data_size) {
    if (!context || !data) {
        return; // Invalid input
    }

    switch (context->mode) {
        case ECB_MODE:
            EVP_EncryptUpdate(context->ctx, data, &data_size, data, data_size);
            break;
        // Add cases for other modes
    }
}

void decrypt_data(CryptoContext *context, uint8_t *data, int data_size) {
    if (!context || !data) {
        return; // Invalid input
    }

    switch (context->mode) {
        case ECB_MODE:
            EVP_DecryptUpdate(context->ctx, data, &data_size, data, data_size);
            break;
        // Add cases for other modes
    }
}

void free_crypto_context(CryptoContext *context) {
    if (context) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
    }
}
