    if (!img) return NULL;
    img->width = width;
    img->height = height;
    strncpy(img->format, format, 4);
    img->pixel_data = (unsigned char *)malloc(width * height * 3); // Assuming RGB
    if (!img->pixel_data) {
        free(img);
        return NULL;
    }
    return img;
}

void destroy_image(Image *img) {
    if (img) {
        free(img->pixel_data);
        free(img);
    }
}

ImageList* create_image_list(int count, int max_width, int max_height) {
    ImageList *list = (ImageList *)malloc(sizeof(ImageList));
    if (!list) return NULL;
    list->count = count;
    list->images = (Image **)malloc(count * sizeof(Image *));
    if (!list->images) {
        free(list);
        return NULL;
    }
    for (int i = 0; i < count; ++i) {
        list->images[i] = create_image(max_width, max_height, "JPEG");
        if (!list->images[i]) {
            destroy_image_list(list);
            return NULL;
        }
    }
    return list;
}

void destroy_image_list(ImageList *list) {
    if (list) {
        for (int i = 0; i < list->count; ++i) {
            destroy_image(list->images[i]);
        }
        free(list->images);
        free(list);
    }
