        // Handle RSA separately as it involves key generation and signing
        RSA *rsa = RSA_generate_key(2048, 65537, NULL, NULL);
        CipherService *service = malloc(sizeof(CipherService));
        service->key = EVP_PKEY_new_from_RSA(rsa, 1);
        service->cipher_ctx = NULL; // No specific cipher for RSA
        return service;
    }

    // Initialize cipher context
    CipherService *service = malloc(sizeof(CipherService));
    service->cipher_ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(service->cipher_ctx, cipher, NULL, NULL, NULL);

    // Load and verify keys from external key management service
    // ...

    return service;
}

void encrypt_data(const CipherService* service, const unsigned char* indata, size_t inlen, unsigned char** outdata, size_t *outlen) {
    if (service->cipher_ctx != NULL) {
        EVP_EncryptUpdate(service->cipher_ctx, *outdata, (int*)outlen, indata, inlen);
        EVP_EncryptFinal_ex(service->cipher_ctx, (*outdata)+(*outlen), outlen);
    } else {
        // Handle RSA encryption
        RSA_sign(NID_sha256, indata, inlen, *outdata, outlen, service->key);
    }
}

void decrypt_data(const CipherService* service, const unsigned char* indata, size_t inlen, unsigned char** outdata, size_t *outlen) {
    if (service->cipher_ctx != NULL) {
        EVP_DecryptUpdate(service->cipher_ctx, *outdata, (int*)outlen, indata, inlen);
        EVP_DecryptFinal_ex(service->cipher_ctx, (*outdata)+(*outlen), outlen);
    } else {
        // Handle RSA decryption
        int ret = RSA_verify(NID_sha256, indata, inlen, *outdata, *outlen, service->key);
        if (ret != 1) {
            // Handle signature verification failure gracefully
            // ...
        }
    }
}

void free_cipher_service(CipherService* service) {
    if (service->cipher_ctx != NULL) EVP_CIPHER_CTX_free(service->cipher_ctx);
    if (service->key != NULL) EVP_PKEY_free(service->key);
    free(service);
}
