#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>

typedef struct {
    char *temp_file_path;
    sem_t *semaphore;
} SemaphoreWrapper;

SemaphoreWrapper* initialize_semaphore(const char *name, unsigned int initial_value) {
    SemaphoreWrapper *sw = (SemaphoreWrapper *)malloc(sizeof(SemaphoreWrapper));
    if (!sw) {
        perror("Failed to allocate memory for SemaphoreWrapper");
        return NULL;
    }

    // Create a unique temporary file path
    sw->temp_file_path = tempnam(NULL, "sem_");
    if (!sw->temp_file_path) {
        perror("Failed to create temporary file for semaphore state");
        free(sw);
        return NULL;
    }

    // Open the temporary file with proper permissions
    int fd = open(sw->temp_file_path, O_CREAT | O_EXCL | O_RDWR, 0600);
    if (fd == -1) {
        perror("Failed to open temporary file for semaphore state");
        free(sw->temp_file_path);
        free(sw);
        return NULL;
    }

    // Initialize the semaphore
    sw->semaphore = sem_open(name, O_CREAT | O_RDWR, 0600, initial_value);
    if (sw->semaphore == SEM_FAILED) {
        perror("Failed to initialize semaphore");
        close(fd);
        unlink(sw->temp_file_path);
        free(sw->temp_file_path);
        free(sw);
        return NULL;
    }

    // Store the initial value in the temporary file
    if (write(fd, &initial_value, sizeof(unsigned int)) != sizeof(unsigned int)) {
        perror("Failed to write semaphore initial value to temporary file");
        sem_close(sw->semaphore);
        sem_unlink(name);
        close(fd);
        unlink(sw->temp_file_path);
        free(sw->temp_file_path);
        free(sw);
        return NULL;
    }

    close(fd);
    return sw;
}

void destroy_semaphore(SemaphoreWrapper *sw) {
    if (!sw) {
        return;
    }

    // Close the semaphore
    sem_close(sw->semaphore);

    // Unlink the semaphore from the system
    sem_unlink(sw->temp_file_path);

    // Delete the temporary file
    unlink(sw->temp_file_path);

    free(sw->temp_file_path);
    free(sw);
}

// Example usage
int main() {
    SemaphoreWrapper *sw = initialize_semaphore("/my_semaphore", 1);
    if (!sw) {
        return EXIT_FAILURE;
    }

    // Perform semaphore operations
    sem_wait(sw->semaphore);
    // Critical section
    sem_post(sw->semaphore);

    destroy_semaphore(sw);
    return EXIT_SUCCESS;
}
