    for (long i = 0; i < N; i++) {
        indicators[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        indicators[i].RNTI = rand() % 65535;
        indicators[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    vendor_autoloader_init();
    if (!vendor_autoloader_is_initialized()) {
        log_error("Vendor autoloader initialization failed");
        free(indicators);
        return NULL;
    }

