#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/time.h>

#define MAX_QUERY_LIMIT 100
#define MAX_SESSIONS 10

typedef struct {
    u_char *ip_address;
    time_t last_resolved;
} DNSEntry;

typedef struct {
    char hostname[256];
    int query_limit;
    int current_queries;
    time_t last_query_time;
    DNSEntry cache[MAX_QUERY_LIMIT];
} Session;

Session sessions[MAX_SESSIONS];

u_char* resolve_dns(const char *hostname, int session_id) {
    if (session_id < 0 || session_id >= MAX_SESSIONS) {
        return NULL; // Invalid session ID
    }

    Session *session = &sessions[session_id];
    time_t now = time(NULL);

    // Check cache for recent resolution
    for (int i = 0; i < session->query_limit; i++) {
        if (strcmp(session->cache[i].hostname, hostname) == 0 && difftime(now, session->cache[i].last_resolved) <= 3600) {
            return session->cache[i].ip_address;
        }
    }

    // Check query limit and timeout
    if (session->current_queries >= session->query_limit || difftime(now, session->last_query_time) < 1) {
        return NULL; // Exceeded query limit or too soon since last query
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL; // DNS resolution failed
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(ipv4->sin_addr), ip_str, INET_ADDRSTRLEN);

        // Allocate memory for the IP address
        u_char *ip_address = (u_char *)malloc(INET_ADDRSTRLEN);
        if (ip_address == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            freeaddrinfo(res);
            return NULL; // Memory allocation failed
        }

        memcpy(ip_address, ip_str, INET_ADDRSTRLEN);
        ip_address[INET_ADDRSTRLEN - 1] = '\0'; // Null-terminate the IP address

        // Add to cache
        for (int i = 0; i < session->query_limit; i++) {
            if (session->cache[i].hostname[0] == '\0') {
                strcpy(session->cache[i].hostname, hostname);
                session->cache[i].ip_address = ip_address;
                session->cache[i].last_resolved = now;
                break;
            }
        }

        // Update session statistics
        session->current_queries++;
        session->last_query_time = now;

        freeaddrinfo(res);
        return ip_address; // DNS resolution successful
    }

    fprintf(stderr, "No valid IP address found\n");
    freeaddrinfo(res);
    return NULL; // No valid IP address found
}
