#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    LOG_NONE,
    LOG_DEBUG,
    LOG_INFO
} LoggingLevel;

void log_event(LoggingLevel level, const char* message) {
    // External logging API integration here
    printf("%s: %s\n", (level == LOG_DEBUG ? "DEBUG" : (level == LOG_INFO ? "INFO" : "ERROR")), message);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu_list(int rnti_count, unsigned int* rntis, LoggingLevel log_level) {
    if (rnti_count <= 0 || rnti_count > MAX_STRUCTURES) {
        log_event(LOG_ERROR, "Invalid RNTI count");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(rnti_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_event(LOG_ERROR, "Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < rnti_count; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_STRUCTURES;
        list[i].RNTI = rntis[i];
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        log_event(log_level, "Created structure with RNTI: %u", list[i].RNTI);
    }

    return list;
}

int main() {
    unsigned int rntis[] = {101, 102, 103};
    int rnti_count = sizeof(rntis) / sizeof(rntis[0]);

    NFAPI_CRC_INDICATION_PDU_T* list = create_nfaapi_crc_indication_pdu_list(rnti_count, rntis, LOG_DEBUG);
