['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a packet
typedef struct Packet {
    size_t length;
    char* payload;
} Packet;

// Define the memory pool structure
typedef struct MemoryPool {
    void* base;
    size_t allocated_size;
    size_t max_size;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
void init_memory_pool(MemoryPool* pool, size_t size) {
    pool->base = malloc(size);
    if (pool->base == NULL) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(1);
    }
    pool->allocated_size = 0;
    pool->max_size = size;
    pthread_mutex_init(&pool->lock, NULL);
}

// Function to allocate memory from the memory pool
void* allocate_from_pool(MemoryPool* pool, size_t size) {
    void* result;
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated_size + size > pool->max_size) {
        fprintf(stderr, "Memory pool overflow\n");
        result = NULL;
    } else {
        result = ((char*)pool->base) + pool->allocated_size;
        pool->allocated_size += size;
    }
    pthread_mutex_unlock(&pool->lock);
    return result;
}

// Function to process a stream of network packets
void process_packets(MemoryPool* pool, Packet** packets, int num_packets) {
    size_t total_length = 0;
    for (int i = 0; i < num_packets; i++) {
        // Validate payload length to prevent integer overflow
        if ((SIZE_MAX - total_length) < packets[i]->length) {
            fprintf(stderr, "Payload size too large\n");
            continue;
        }
        total_length += packets[i]->length;
    }

    void* buffer = allocate_from_pool(pool, total_length);
    if (buffer == NULL) {
        return; // Skip processing if memory allocation fails
    }

    char* current_ptr = (char*)buffer;
    for (int i = 0; i < num_packets; i++) {
        memcpy(current_ptr, packets[i]->payload, packets[i]->length);
        current_ptr += packets[i]->length;
    }
}

// Example usage
int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 1024 * 1024); // 1MB memory pool

    Packet packets[] = {
        {5, "Hello"},
        {3, "World"}
    };
    process_packets(&pool, packets, 2);

    pthread_mutex_destroy(&pool.lock);
    free(pool.base);
    return 0;
}
