#include <iostream>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>

class UniqueIdentifierGenerator {
private:
    std::mt19937_64 generator;
    std::uniform_int_distribution<> distribution;
    std::mutex mutex;

public:
    UniqueIdentifierGenerator() : distribution(0, INT_MAX) {
        // Initialize the seed with a combination of hardware random numbers and system entropy
        uint64_t seed = static_cast<uint64_t>(std::chrono::system_clock::now().time_since_epoch().count());
        std::random_device rd;
        seed ^= rd() + (rd() << 1u) + (rd() << 2u);
        generator.seed(seed);
    }

    uint32_t generateIdentifier() {
        std::lock_guard<std::mutex> lock(mutex);
        return distribution(generator);
    }
};

int main() {
    UniqueIdentifierGenerator idGenerator;
    for (size_t i = 0; i < 10; ++i) {
        std::cout << "Generated ID: " << idGenerator.generateIdentifier() << std::endl;
    }
    return 0;
}
```

