pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
