               temp->data.CRC_INDICATION_REL8_TAG, temp->data.CRCFLAG);
        Node* next = temp->next;
        free(temp);
        temp = next;
    }

    return 0;
}

int main() {
    int N = 5; // Number of structures to create
    if (create_linked_list(N, MAX_STRUCTS) != 0) {
        printf("Failed to create linked list.\n");
    }
    return 0;
}
