    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structs;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} UE_Collection;

UE_Collection* create_UE_collection(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_STRUCTS) {
        return NULL; // Invalid capacity
    }

    UE_Collection *collection = malloc(sizeof(UE_Collection));
    if (!collection) {
        perror("Memory allocation failed");
        return NULL;
    }

    collection->structs = realloc(collection->structs, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->structs) {
        free(collection);
        perror("Memory reallocation failed");
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_UE_collection(UE_Collection *collection) {
    if (collection) {
        free(collection->structs);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_to_collection(UE_Collection *collection, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        collection->structs = realloc(collection->structs, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!collection->structs) {
            pthread_mutex_unlock(&collection->mutex);
            perror("Memory reallocation failed");
            return -1;
        }
        collection->capacity = new_capacity;
    }

    collection->structs[collection->count++] = *new_struct;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

