#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

typedef struct ip_node {
    u_char *ip;
    struct ip_node *next;
} ip_node_t;

typedef struct dns_request {
    char hostname[256];
    ip_node_t **result;
    pthread_cond_t cond;
    pthread_mutex_t mutex;
    int complete;
} dns_request_t;

void *dns_lookup(void *arg) {
    dns_request_t *req = (dns_request_t *)arg;
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(req->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        *req->result = NULL;
    } else {
        *req->result = NULL;
        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            char *ipver;

            // get the pointer to the address itself,
            // different fields in IPv4 and IPv6:
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
                ipver = "IPv4";
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
                ipver = "IPv6";
            }

            // convert the IP to a string and print it:
            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
            printf("%s: %s\n", ipver, ipstr);

            // Add IP to linked list
            ip_node_t *new_ip = (ip_node_t *)malloc(sizeof(ip_node_t));
            new_ip->ip = strdup(ipstr);
            new_ip->next = *req->result;
            *req->result = new_ip;
        }
        freeaddrinfo(res); // free the linked list allocated by getaddrinfo
    }

    pthread_mutex_lock(&req->mutex);
    req->complete = 1;
    pthread_cond_signal(&req->cond);
    pthread_mutex_unlock(&req->mutex);

    return NULL;
}

int main() {
    dns_request_t request;
    ip_node_t *result = NULL;

    // Initialize mutex and condition variable
    pthread_mutex_init(&request.mutex, NULL);
    pthread_cond_init(&request.cond, NULL);
    request.complete = 0;

    strcpy(request.hostname, "example.com");
    request.result = &result;

    pthread_t thread;
    if (pthread_create(&thread, NULL, dns_lookup, &request) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Wait for the DNS lookup to complete
    pthread_mutex_lock(&request.mutex);
    while (!request.complete) {
        pthread_cond_wait(&request.cond, &request.mutex);
    }
    pthread_mutex_unlock(&request.mutex);

    // Print the result
    ip_node_t *node = result;
    while (node != NULL) {
        printf("IP: %s\n", node->ip);
        free(node->ip);
        ip_node_t *temp = node;
        node = node->next;
        free(temp);
    }

    // Clean up
    pthread_mutex_destroy(&request.mutex);
    pthread_cond_destroy(&request.cond);

    return EXIT_SUCCESS;
}
