#define MAX_PACKETS 1024

typedef struct Packet {
    int payload_size;
    char* payload;
} Packet;

Packet* packet_buffer[MAX_PACKETS];
int buffer_index = 0;
int buffer_size = 0;

pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

void process_packet(const char* data, int length) {
    if (buffer_size >= MAX_PACKETS) {
        fprintf(stderr, "Packet buffer full!\n");
        return;
    }

    Packet* new_packet = malloc(sizeof(Packet));
    if (!new_packet) {
        fprintf(stderr, "Memory allocation failed for packet!\n");
        return;
    }

    new_packet->payload_size = length;
    new_packet->payload = malloc(length);
    if (!new_packet->payload) {
        free(new_packet);
        fprintf(stderr, "Memory allocation failed for packet payload!\n");
        return;
    }

    memcpy(new_packet->payload, data, length);

    pthread_mutex_lock(&buffer_lock);
    packet_buffer[buffer_index++] = new_packet;
    buffer_size++;
    pthread_mutex_unlock(&buffer_lock);
}

void* packet_processor_thread(void* arg) {
    while (1) {
        Packet* packet = NULL;

        pthread_mutex_lock(&buffer_lock);
        if (buffer_index > 0) {
            packet = packet_buffer[--buffer_index];
            buffer_size--;
        }
        pthread_mutex_unlock(&buffer_lock);

        if (!packet) {
            // No more packets to process, sleep for a while
            sleep(1);
            continue;
        }

        // Process the packet here
        printf("Processing packet with payload size: %d\n", packet->payload_size);

        // Free the packet
        free(packet->payload);
        free(packet);
    }

    return NULL;
}

int main() {
    pthread_t processor_thread;

    // Start the packet processing thread
    if (pthread_create(&processor_thread, NULL, packet_processor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create packet processor thread!\n");
        return 1;
    }

    // Simulate reading packets from an external data source
    for (int i = 0; i < 1000; i++) {
        char payload[256];
        int payload_size = snprintf(payload, sizeof(payload), "Packet %d", i);

        process_packet(payload, payload_size);
    }

    // Wait for the processor thread to finish
    pthread_join(processor_thread, NULL);

    return 0;
}
