typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr && size != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T** manage_dynamic_array(int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T** array = safe_malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    int retries = 0;

    while (array == NULL && retries < RETRY_LIMIT) {
        num_elements /= 2;
        array = safe_malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        retries++;
    }

    if (array == NULL) {
        fprintf(stderr, "Failed to allocate memory after %d retries\n", RETRY_LIMIT);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_elements; i++) {
        array[i] = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            fprintf(stderr, "Failed to allocate memory for element %d\n", i);
            // Clean up previously allocated elements
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            exit(EXIT_FAILURE);
        }

        array[i]->RX_UE_INFORMATION_TAG = rand();
        array[i]->RNTI = rand() % 65536;
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i]->CRCFLAG = (unsigned char)rand();
    }

    return array;
}

void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T** array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(array[i]);
    }
    free(array);
}

int main() {
    srand(time(NULL));

    int requested_elements = 5000;
    NFAPI_CRC_INDICATION_PDU_T** array = manage_dynamic_array(requested_elements);

    // Use the dynamic array...

    free_dynamic_array(array, requested_elements);
    return 0;
}
