#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define MAX_MEMORY_LIMIT (1024 * 1024 * 10) // 10 MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UnionFind {
    int* parent;
    int* rank;
    int size;
} UnionFind;

NFAPI_CRC_INDICATION_PDU_T* createLinkedList(int N, int max_memory_limit) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        printf("Invalid structure count\n");
        return NULL;
    }

    size_t memory_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (memory_size > max_memory_limit) {
        printf("Memory limit exceeded\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(memory_size);
    if (head == NULL) {
        printf("Failed to allocate memory\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        head[i].RX_UE_INFORMATION_TAG = rand();
        head[i].RNTI = (unsigned short)rand();
        head[i].CRCFLAG = rand() % 2;
    }

    return head;
}

void initializeUnionFind(UnionFind* uf, int size) {
    uf->parent = (int*)malloc(size * sizeof(int));
    uf->rank = (int*)malloc(size * sizeof(int));
    uf->size = size;

    for (int i = 0; i < size; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void unionOperation(UnionFind* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointPairs(NFAPI_CRC_INDICATION_PDU_T* head, int N) {
    UnionFind uf;
    initializeUnionFind(&uf, N);

    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (head[i].RNTI == head[j].RNTI && head[i].CRCFLAG == head[j].CRCFLAG) {
                unionOperation(&uf, i, j);
            }
        }
    }

    int disjointPairs = 0;
    for (int i = 0; i < N; i++) {
        if (find(&uf, i) == i) {
            disjointPairs++;
        }
    }

    free(uf.parent);
    free(uf.rank);

    return disjointPairs;
}

int main() {
    int N;
    printf("Enter the number of structures: ");
    scanf("%d", &N);

    clock_t start = clock();
    NFAPI_CRC_INDICATION_PDU_T* head = createLinkedList(N, MAX_MEMORY_LIMIT);
    if (head != NULL) {
        int disjointPairs = countDisjointPairs(head, N);
        printf("Number of disjoint pairs: %d\n", disjointPairs);
        free(head);
    }
    clock_t end = clock();
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", time_taken);

    return 0;
}
