#include <stdbool.h>

#define MAX_MEMORY_LIMIT 1048576 // Example maximum memory limit in bytes

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int calculate_required_memory(size_t N, size_t struct_size) {
    if (N == 0 || struct_size == 0) {
        return 0;
    }
    size_t required_memory = N * struct_size;
    if (required_memory / N != struct_size || required_memory > MAX_MEMORY_LIMIT) {
        // Handle integer overflow or memory limit exceeded
        return -1;
    }
    return required_memory;
}

void add_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* data, size_t N, Node** head) {
    int required_memory = calculate_required_memory(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (required_memory == -1) {
        // Handle memory allocation failure or limit exceeded
        return;
    }
    for (size_t i = 0; i < N; ++i) {
        insert_node(head, data[i]);
    }
}
