#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Function to safely calculate the total memory required for payload allocation
size_t safe_size_add(size_t a, size_t b) {
    if (b > SIZE_MAX - a) {
        fprintf(stderr, "Memory allocation would exceed maximum limit\n");
        return 0; // Handle overflow error gracefully
    }
    return a + b;
}

// Function to process incoming network packets and allocate memory
void process_packets(int packet_count, size_t *payload_sizes) {
    size_t total_memory = 0;

    // Calculate total memory required for all payloads
    for (int i = 0; i < packet_count; ++i) {
        total_memory = safe_size_add(total_memory, payload_sizes[i]);
        if (total_memory == 0) {
            // Memory allocation failed due to overflow
            fprintf(stderr, "Failed to allocate memory\n");
            return;
        }
    }

    // Allocate memory in a single block
    void *memory_block = malloc(total_memory);
    if (memory_block == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Populate each payload slot with packet data
    char *current_position = (char *)memory_block;
    for (int i = 0; i < packet_count; ++i) {
        memcpy(current_position, &payload_sizes[i], payload_sizes[i]);
        current_position += payload_sizes[i];
    }

    // Free the allocated memory after processing
    free(memory_block);
}

// Example usage
int main() {
    int packet_count = 3;
    size_t payload_sizes[] = {1024, 2048, 512};

    process_packets(packet_count, payload_sizes);

    return 0;
}
```

