// Define the memory pool manager structure
typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
    size_t free_index;
} MemoryPool;

// Function to initialize the memory pool
void init_memory_pool(MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(num_blocks * block_size);
    if (pool->blocks == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memset(pool->blocks, 0, num_blocks * block_size);
    pool->free_index = 0;
}

// Function to allocate memory from the pool
void* mem_pool_alloc(MemoryPool* pool) {
    if (pool->free_index == pool->num_blocks) {
        fprintf(stderr, "No free blocks available\n");
        return NULL;
    }
    void* block = (char*)pool->blocks + pool->free_index * pool->block_size;
    pool->free_index++;
    return block;
}

// Function to deallocate memory back to the pool
void mem_pool_free(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->blocks) / pool->block_size;
    if (index >= pool->num_blocks || index < 0) {
        fprintf(stderr, "Invalid block pointer\n");
        return;
    }
    memset(block, 0, pool->block_size);
    pool->free_index = index + 1;
}

// Function to dynamically manage the collection of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* manage_structures(MemoryPool* pool, size_t max_structures) {
    static NFAPI_CRC_INDICATION_PDU_T** structures = NULL;
    static size_t current_count = 0;

    if (structures == NULL) {
        structures = malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (structures == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        memset(structures, 0, max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    if (max_structures < current_count) {
        fprintf(stderr, "Exceeds current limit of structures\n");
        return NULL;
    }

    while (current_count < max_structures) {
        NFAPI_CRC_INDICATION_PDU_T* new_structure = mem_pool_alloc(pool);
        if (new_structure == NULL) {
            break;
        }
        // Initialize the structure with random values
        new_structure->RX_UE_INFORMATION_TAG = rand();
        new_structure->RNTI = rand() % 65536; // Random RNTI within valid range
        new_structure->CRC_INDICATION_REL8_TAG = rand() % 256; // Random tag
        new_structure->CRCFLAG = rand() % 2; // Random CRC flag

        structures[current_count++] = new_structure;
    }

    return structures;
}

// Example usage
int main() {
    MemoryPool pool;
    init_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), 100);

    size_t max_structures = 50;
    NFAPI_CRC_INDICATION_PDU_T** structures = manage_structures(&pool, max_structures);

    if (structures != NULL) {
        for (size_t i = 0; i < max_structures; i++) {
            printf("Structure %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u, CRCFLAG=%d\n",
                   i, structures[i]->RX_UE_INFORMATION_TAG, structures[i]->RNTI, structures[i]->CRC_INDICATION_REL8_TAG, structures[i]->CRCFLAG);
        }
    }

    // Free all allocated memory
    for (size_t i = 0; i < current_count; i++) {
        mem_pool_free(&pool, structures[i]);
    }
    free(structures);

    return 0;
}
