pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *head = NULL;

void* add_node(void* arg) {
    int N = *(int*)arg;
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < N; i++) {
        if (head == NULL) {
            head = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!head) {
                perror("Memory allocation failed");
                pthread_mutex_unlock(&list_lock);
                return NULL;
            }
            head->next = NULL;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!current->next) {
                perror("Memory allocation failed");
                pthread_mutex_unlock(&list_lock);
                return NULL;
            }
            current->next->next = NULL;
        }
        head->RX_UE_INFORMATION_TAG = rand() % 1000;
        head->RNTI = rand() % 5000;
        head->CRCFLAG = rand() % 2;
        time(&head->timestamp);
    }
    pthread_mutex_unlock(&list_lock);
    return NULL;
}

void print_list() {
    pthread_mutex_lock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d, Timestamp: %ld\n",
               current->RX_UE_INFORMATION_TAG,
               current->RNTI,
               current->CRCFLAG,
               current->timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

