    int N = 10; // Example value for number of elements
    if (N > MAX_ELEMENTS) {
        printf("N exceeds the maximum allowed value.\n");
        return 1;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, add_node, &N);
    pthread_join(thread_id, NULL);

    print_list();

    // Cleanup code to free allocated memory
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

