    for (uint32_t i = 0; i < maxTasks; ++i) {
        taskArray[i] = (ImageProcessingTask*)malloc(sizeof(ImageProcessingTask));
        if (!taskArray[i]) {
            // Clean up previously allocated memory on error
            for (uint32_t j = 0; j < i; ++j) free(taskArray[j]);
            free(taskArray);
            return NULL;
        }
        taskArray[i]->imageData = (ProcessedImageData*)malloc(sizeof(ProcessedImageData));
        if (!taskArray[i]->imageData) {
            // Clean up previously allocated memory on error
            for (uint32_t j = 0; j <= i; ++j) {
                free(taskArray[j]->imageData);
                free(taskArray[j]);
            }
            free(taskArray);
            return NULL;
        }
    }
    return taskArray;
}

