    if (dimensions->width == 0 || dimensions->height == 0) return -1; // Zero dimensions are invalid
    uint64_t requiredMemory = dimensions->width * dimensions->height * sizeof(uint8_t); // Example: assume 8-bit image
    if (requiredMemory > UINT32_MAX) return -1; // Check for integer overflow

    taskArray[taskId]->status = 1;
    taskArray[taskId]->imageData->buffer = malloc(requiredMemory);
    if (!taskArray[taskId]->imageData->buffer) {
        taskArray[taskId]->status = -1;
        return -1;
    }

    // Simulate image processing
    memset(taskArray[taskId]->imageData->buffer, 0xFF, requiredMemory);

    taskArray[taskId]->status = 2;
    return 0;
}
