#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000
#define VALID_RNTI_MIN 1
#define VALID_RNTI_MAX 65535
#define MEMORY_LIMIT (MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t allocated;
    pthread_mutex_t mutex;
} NfaApiCrcArray;

int nfa_api_crc_init(NfaApiCrcArray *arr) {
    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr) != 0) {
        return -1;
    }
    if (pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE) != 0) {
        pthread_mutexattr_destroy(&attr);
        return -1;
    }
    if (pthread_mutex_init(&arr->mutex, &attr) != 0) {
        pthread_mutexattr_destroy(&attr);
        return -1;
    }
    arr->array = NULL;
    arr->count = 0;
    arr->allocated = 0;
    pthread_mutexattr_destroy(&attr);
    return 0;
}

int nfa_api_crc_add(NfaApiCrcArray *arr) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->allocated == MAX_STRUCTURES) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    size_t new_size = arr->allocated + 1;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        pthread_mutex_unlock(&arr->mutex);
        return -ENOMEM;
    }

    arr->array = new_array;
    arr->allocated = new_size;

    NFAPI_CRC_INDICATION_PDU_T *new_struct = &arr->array[arr->count];
    new_struct->RX_UE_INFORMATION_TAG.value = 0; // Example initialization
    new_struct->RNTI = (rand() % (VALID_RNTI_MAX - VALID_RNTI_MIN + 1)) + VALID_RNTI_MIN;
    new_struct->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    arr->count++;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void nfa_api_crc_free(NfaApiCrcArray *arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->count = 0;
    arr->allocated = 0;
    pthread_mutex_unlock(&arr->mutex);
}
```

### DNS Resolution Function

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

#define DNS_QUERY_LIMIT 1000
#define DNS_QUERY_INTERVAL_US 500000 // 0.5 seconds

typedef struct {
    char *hostname;
    u_char ip_address[4];
    pthread_mutex_t mutex;
} DnsEntry;

int dns_query(const char *hostname, u_char *ip_address) {
    static size_t query_count = 0;
    static struct timeval last_query_time;

    pthread_mutex_lock(&last_query_time_mutex);
    if (query_count >= DNS_QUERY_LIMIT) {
        pthread_mutex_unlock(&last_query_time_mutex);
        return -ETOOMANYREFS;
    }

    gettimeofday(&last_query_time, NULL);
    query_count++;
    pthread_mutex_unlock(&last_query_time_mutex);

    // Simulate DNS resolution
    ip_address[0] = 192;
    ip_address[1] = 168;
    ip_address[2] = 1;
    ip_address[3] = 1;
    return 0;
}

int dns_entry_init(DnsEntry *entry, const char *hostname) {
    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr) != 0) {
        return -1;
    }
    if (pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE) != 0) {
        pthread_mutexattr_destroy(&attr);
        return -1;
    }
    if (pthread_mutex_init(&entry->mutex, &attr) != 0) {
        pthread_mutexattr_destroy(&attr);
        return -1;
    }
    entry->hostname = strdup(hostname);
    memset(entry->ip_address, 0, sizeof(entry->ip_address));
    pthread_mutexattr_destroy(&attr);
    return 0;
}

int dns_entry_query(DnsEntry *entry) {
    int result = dns_query(entry->hostname, entry->ip_address);
    if (result != 0) {
        return result;
    }
    return 0;
}
