typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t max_count;
    pthread_mutex_t mutex;
} CRC_INDICATION_LIST;

int create_crc_indication_list(CRC_INDICATION_LIST *list, size_t num_structures) {
    if (num_structures > MAX_STRUCTURES) {
        log_error("Error: Requested number of structures exceeds maximum limit.");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    size_t required_size = list->count + num_structures;
    if (required_size < list->count || required_size > list->max_count) {
        log_error("Error: Integer overflow detected during memory allocation.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, required_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        log_error("Error: Failed to allocate memory for CRC indication list.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    for (size_t i = 0; i < num_structures; i++) {
        new_list[list->count + i].ue_info = generate_random_ue_info();
        new_list[list->count + i].rnti = generate_random_rnti();
        new_list[list->count + i].crc_indication.crcflag = generate_random_crcflag();
    }

    list->list = new_list;
    list->count += num_structures;
    pthread_mutex_unlock(&list->mutex);
    log_info("Successfully created %zu CRC indication structures.", num_structures);

    return 0;
}
