void processAndModifyNFALIST(int N, std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& nfalist, const std::string& targetRnti, const std::string& newString) {
    if (N <= 0 || N >= 1000) {
        std::cerr << "Invalid value for N. Must be between 1 and 999." << std::endl;
        return;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1); // Randomly set CRCFLAG to 0 or 1

    for (int i = 0; i < N && !nfalist.empty(); ++i) {
        nfalist.front().RX_UE_INFORMATION_TAG.tag = RX_UE_INFORMATION_TAG;
        nfalist.front().RNTI = targetRnti;
        nfalist.front().CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);
    }

    auto it = std::find_if(nfalist.begin(), nfalist.end(), [&targetRnti](const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Assuming RNTI is a string for simplicity
        return pdu.RNTI == targetRnti;
    });

    if (it != nfalist.end()) {
        it = nfalist.insert_after(it, {});
        (*it).RX_UE_INFORMATION_TAG.tag = RX_UE_INFORMATION_TAG;
        (*it).RNTI = newString;
        (*it).CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // Assuming CRCFLAG is not applicable for new elements
    } else {
        nfalist.push_front({});
        nfalist.front().RX_UE_INFORMATION_TAG.tag = RX_UE_INFORMATION_TAG;
        nfalist.front().RNTI = newString;
        nfalist.front().CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // Assuming CRCFLAG is not applicable for new elements
    }
}
