#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    size_t allocated_count;
    pthread_mutex_t mutex;
} DynamicArray;

int init_dynamic_array(DynamicArray* da, size_t initial_size) {
    if (initial_size == 0) {
        return -1; // Invalid size
    }

    da->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        return -2; // Memory allocation failed
    }

    da->count = 0;
    da->allocated_count = initial_size;
    pthread_mutex_init(&da->mutex, NULL);

    return 0;
}

int resize_dynamic_array(DynamicArray* da, size_t new_size) {
    if (new_size <= da->allocated_count) {
        return -1; // No need to resize
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        return -2; // Memory allocation failed
    }

    da->array = new_array;
    da->allocated_count = new_size;

    return 0;
}

int add_to_dynamic_array(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&da->mutex);
    if (da->count >= da->allocated_count) {
        int result = resize_dynamic_array(da, da->allocated_count * 2);
        if (result != 0) {
            pthread_mutex_unlock(&da->mutex);
            return result;
        }
    }

    da->array[da->count++] = *item;
    pthread_mutex_unlock(&da->mutex);

    return 0;
}

void free_dynamic_array(DynamicArray* da) {
    if (da->array) {
        free(da->array);
        da->array = NULL;
    }
    pthread_mutex_destroy(&da->mutex);
}
```

