    size_t total_payload_size = 0;
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].payload != NULL && packets[i].timestamp != 0) {
            total_payload_size += strlen(packets[i].payload) + MAX_TIMESTAMP_SIZE;
        }
    }

    if (total_payload_size > max_buffer_size) {
        printf("Error: Total payload size exceeds maximum buffer limit.\n");
        return NULL;
    }

    Packet* processed_packets = malloc(packet_count * sizeof(Packet));
    if (processed_packets == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < packet_count; i++) {
        size_t payload_length = strlen(packets[i].payload);
        processed_packets[i].payload = malloc(payload_length + MAX_TIMESTAMP_SIZE);
        if (processed_packets[i].payload == NULL) {
            printf("Error: Memory allocation failed.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(processed_packets[j].payload);
            }
            free(processed_packets);
            return NULL;
        }

        strcpy(processed_packets[i].payload, packets[i].payload);
        processed_packets[i].timestamp = packets[i].timestamp;
    }

