#define MAX_MEMORY 1024 * 1024 // Example maximum memory limit of 1MB

typedef struct {
    uint32_t packet_id;
    uint32_t payload_size;
    char* payload;
} NetworkPacket;

NetworkPacket** process_packets(uint32_t N, uint32_t* packet_sizes) {
    if (N == 0 || !packet_sizes || packet_sizes[0] > MAX_MEMORY) {
        return NULL; // Handle edge cases or invalid input
    }

    NetworkPacket** packets = (NetworkPacket**)malloc(N * sizeof(NetworkPacket*));
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    uint64_t total_memory_needed = 0;
    for (uint32_t i = 0; i < N; ++i) {
        if (packet_sizes[i] > MAX_MEMORY / N) {
            free(packets); // Handle potential overflow or excessively large packet
            return NULL;
        }
        total_memory_needed += sizeof(NetworkPacket) + packet_sizes[i];
    }

    if (total_memory_needed > MAX_MEMORY) {
        free(packets);
        return NULL; // Total memory exceeds maximum limit
    }

    char* memory_block = (char*)malloc(total_memory_needed);
    if (!memory_block) {
        free(packets);
        return NULL; // Memory allocation failed
    }

    for (uint32_t i = 0, offset = 0; i < N; ++i) {
        packets[i] = (NetworkPacket*)(memory_block + offset);
        packets[i]->packet_id = i;
        packets[i]->payload_size = packet_sizes[i];
        packets[i]->payload = (char*)memory_block + offset + sizeof(NetworkPacket);
        memory_block += offset + sizeof(NetworkPacket) + packet_sizes[i];
    }

    return packets; // Return array of pointers to NetworkPacket structures
}
