void initializePackets(NFAPI_CRC_INDICATION_PDU_T* packets, int numPackets) {
    srand(time(0));
    for (int i = 0; i < numPackets; i++) {
        packets[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        packets[i].rnti = RNTI;
        packets[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
        packets[i].crcflag = rand() % 2; // Randomly set CRCFLAG
    }
}

int addPacketsToBuffer(NFAPI_CRC_INDICATION_PDU_T* buffer, NFAPI_CRC_INDICATION_PDU_T* newPackets, int numNewPackets, int* currentSize) {
    int packetsToAdd = (BUFFER_SIZE - (*currentSize)) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (numNewPackets > packetsToAdd) {
        printf("Buffer overflow detected. Truncating %d packets.\n", numNewPackets - packetsToAdd);
        numNewPackets = packetsToAdd;
    }
    memcpy(buffer + (*currentSize / sizeof(NFAPI_CRC_INDICATION_PDU_T)), newPackets, numNewPackets * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *currentSize += numNewPackets * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return numNewPackets;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T newPackets[MAX_PACKETS];
    initializePackets(newPackets, MAX_PACKETS);

    int currentSize = 0;
    int packetsAdded = addPacketsToBuffer(buffer, newPackets, MAX_PACKETS, &currentSize);
    printf("Number of packets added: %d\n", packetsAdded);

    free(buffer);
    return 0;
}
