#include <stdlib.h>
#include <stdio.h>

#define MAX_PACKET_SIZE 1024

typedef struct {
    void* data;
    size_t size;
    size_t capacity;
} PayloadArray;

void initPayloadArray(PayloadArray* array, size_t initialCapacity) {
    array->data = malloc(initialCapacity * sizeof(void*));
    if (array->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initialCapacity;
}

void resizePayloadArray(PayloadArray* array, size_t newCapacity) {
    void** newData = realloc(array->data, newCapacity * sizeof(void*));
    if (newData == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->data = newData;
    array->capacity = newCapacity;
}

void addPayload(PayloadArray* array, void* payload, size_t payloadSize) {
    if (array->size + 1 >= array->capacity) {
        resizePayloadArray(array, array->capacity * 2);
    }
    array->data[array->size++] = payload;
}

void processPackets(PayloadArray* array, const char* packetData, size_t packetCount) {
    for (size_t i = 0; i < packetCount; ++i) {
        size_t payloadSize = *(const size_t*)packetData; // Assuming the first 8 bytes are the payload size
        if (payloadSize > MAX_PACKET_SIZE) {
            fprintf(stderr, "Payload too large: %zu\n", payloadSize);
            continue;
        }
        void* payload = malloc(payloadSize);
        if (payload == NULL) {
            fprintf(stderr, "Memory allocation failed for packet payload\n");
            continue;
        }
        memcpy(payload, packetData + 8, payloadSize); // Assuming the first 8 bytes are the size
        addPayload(array, payload, payloadSize);
        packetData += 8 + payloadSize; // Move to the next packet
    }
}

void cleanupPayloadArray(PayloadArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
}
