int load_resource_bundle(ResourceBundle *bundle) {
    FILE *file = fopen(BUNDLE_FILE, "r");
    if (!file) {
        perror("Failed to open resource bundle file");
        return -1;
    }

    // Estimate the number of items based on average line length
    int estimate_item_count = 0;
    while (fgets(NULL, MAX_PACKET_SIZE, file)) {
        estimate_item_count++;
    }
    rewind(file);

    bundle->item_count = 0;
    bundle->items = malloc(estimate_item_count * sizeof(char *));
    if (!bundle->items) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return -1;
    }

    char line[MAX_PACKET_SIZE];
    while (fgets(line, MAX_PACKET_SIZE, file)) {
        line[strcspn(line, "\n")] = '\0'; // Remove newline character
        bundle->items[bundle->item_count] = strdup(line);
        if (!bundle->items[bundle->item_count]) {
            perror("Failed to allocate memory for resource item");
            fclose(file);
            return -1;
        }
        bundle->item_count++;
    }

    fclose(file);
    return 0;
}

