    if (load_resource_bundle(&bundle)) {
        fprintf(stderr, "Failed to load resource bundle\n");
        for (int i = 0; i < bundle.item_count; i++) {
            free(bundle.items[i]);
        }
        free(bundle.items);
        return -1;
    }

    // Process packets using the bundle items
    // ...

    // Clean up resource bundle
    for (int i = 0; i < bundle.item_count; i++) {
        free(bundle.items[i]);
