NFAPI_CRC_INDICATION_PDU_T* initialize_structures(int argc, ...) {
    va_list args;
    va_start(args, argc);

    if (argc > MAX_STRUCTS) {
        va_end(args);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(argc * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        va_end(args);
        return NULL;
    }

    uint32_t total_rnti_sum = 0;
    for (int i = 0; i < argc; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* current_struct = va_arg(args, NFAPI_CRC_INDICATION_PDU_T*);

        if (current_struct->RNTI > UINT32_MAX - total_rnti_sum) {
            free(array);
            va_end(args);
            return NULL;
        }
        total_rnti_sum += current_struct->RNTI;

        if (total_rnti_sum > MAX_RNTI_SUM) {
            free(array);
            va_end(args);
            return NULL;
        }

        array[i] = *current_struct;
    }

    va_end(args);

    return array;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T structs[MAX_STRUCTS];
    // Initialize structs with valid values
