        structs[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    NFAPI_CRC_INDICATION_PDU_T* initialized_array = initialize_structures(MAX_STRUCTS, structs);
    if (initialized_array) {
        // Use initialized_array as needed
        free(initialized_array);
    } else {
        printf("Failed to allocate or validate structures.\n");
    }

    return 0;
}
