int process_packets(int max_packets, size_t memory_limit) {
    srand(time(NULL));
    void **packets = (void **)malloc(max_packets * sizeof(void *));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return -1;
    }

    size_t total_memory_used = 0;

    for (int i = 0; i < max_packets; ++i) {
        int payload_size = PAYLOAD_RANGE_MIN + rand() % (PAYLOAD_RANGE_MAX - PAYLOAD_RANGE_MIN);
        if ((total_memory_used + sizeof(void *) + payload_size) > memory_limit) {
            fprintf(stderr, "Memory limit exceeded\n");
            break;
        }

        void *packet_header = malloc(sizeof(void *));
        if (!packet_header) {
            perror("Failed to allocate memory for packet header");
            free(packets);
            return -1;
        }

        void *payload = malloc(payload_size);
        if (!payload) {
            perror("Failed to allocate memory for payload");
            free(packet_header);
            free(packets);
            return -1;
        }

        // Simulate copying data into the packet
        memcpy(packet_header, &i, sizeof(int));
        memcpy(payload, &i, payload_size);

        packets[i] = payload;

        if (validate_packet(payload) != 0) {
            fprintf(stderr, "Packet validation failed\n");
            free(payload);
            free(packet_header);
            continue;
        }

        total_memory_used += sizeof(void *) + payload_size;
    }

    // Process packets...
    // ...

    for (int i = 0; i < max_packets; ++i) {
        if (packets[i]) {
            free(packets[i]);
        }
    }

    free(packets);
    return 0;
}
