#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

void initialize_list(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Handle memory allocation failure
    }
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    LinkedList list;
    initialize_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data = {1, 2, 3};
    add_to_list(&list, data);

    free_list(&list);
    return 0;
}
