#define MAX_ITEMS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int loadResourceBundle(const char* filePath, NFAPI_CRC_INDICATION_PDU_T** bundle) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    int itemCount = 0;
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > MAX_ITEMS * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "File size exceeds maximum allowed items\n");
        fclose(file);
        return -1;
    }

    itemCount = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *bundle = (NFAPI_CRC_INDICATION_PDU_T*)malloc(itemCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*bundle) {
        perror("Failed to allocate memory");
        fclose(file);
        return -1;
    }

    size_t bytesRead = fread(*bundle, sizeof(NFAPI_CRC_INDICATION_PDU_T), itemCount, file);
    if (bytesRead != (size_t)itemCount) {
        fprintf(stderr, "Failed to read all data from file\n");
        free(*bundle);
        *bundle = NULL;
        fclose(file);
        return -1;
    }

    for (int i = 0; i < itemCount; i++) {
        (*bundle)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    fclose(file);
    return itemCount;
}
