#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for a single packet
typedef struct Packet {
    int priority;
    char *payload;
    size_t payload_size;
    struct Packet *next;
} Packet;

// Define a structure for the memory management module
typedef struct MemoryManagementModule {
    void *(*allocate)(size_t);
    void (*deallocate)(void *);
} MemoryManagementModule;

// Function to allocate memory using the provided module
static inline void* safe_allocate(MemoryManagementModule *module, size_t size) {
    return module->allocate(size);
}

// Function to deallocate memory using the provided module
static inline void safe_deallocate(MemoryManagementModule *module, void *ptr) {
    module->deallocate(ptr);
}

// Function to create a new packet
Packet* create_packet(int priority, const char *payload, size_t payload_size, MemoryManagementModule *mm_module) {
    Packet *new_packet = (Packet *)safe_allocate(mm_module, sizeof(Packet));
    if (!new_packet) {
        return NULL;
    }
    new_packet->priority = priority;
    new_packet->payload = (char *)safe_allocate(mm_module, payload_size);
    if (!new_packet->payload) {
        safe_deallocate(mm_module, new_packet);
        return NULL;
    }
    memcpy(new_packet->payload, payload, payload_size);
    new_packet->payload_size = payload_size;
    new_packet->next = NULL;
    return new_packet;
}

// Function to insert a packet into the linked list based on priority
void insert_packet(Packet **head, Packet *packet) {
    if (!*head || (*head)->priority < packet->priority) {
        packet->next = *head;
        *head = packet;
    } else {
        Packet *current = *head;
        while (current->next && current->next->priority >= packet->priority) {
            current = current->next;
        }
        packet->next = current->next;
        current->next = packet;
    }
}

// Function to process a variable number of packets
Packet* process_packets(int packet_count, MemoryManagementModule *mm_module) {
    if (packet_count <= 0 || packet_count > 1000) {
        return NULL; // Handle invalid packet count
    }

    Packet *head = NULL;
    for (int i = 0; i < packet_count; ++i) {
        char payload[256];
        int priority;
        printf("Enter packet %d details:\n", i + 1);
        scanf("%d%s", &priority, payload);

        Packet *new_packet = create_packet(priority, payload, strlen(payload) + 1, mm_module);
        if (new_packet) {
            insert_packet(&head, new_packet);
        }
    }

    return head;
}

int main() {
    MemoryManagementModule mm_module = {
        .allocate = malloc,
        .deallocate = free
    };

    Packet *packet_list = process_packets(3, &mm_module);

    // Print the processed packet list
    while (packet_list) {
        printf("Priority: %d, Payload: %s\n", packet_list->priority, packet_list->payload);
        Packet *temp = packet_list;
        packet_list = packet_list->next;
        safe_deallocate(&mm_module, temp->payload);
        safe_deallocate(&mm_module, temp);
    }

    return 0;
}
