typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->mutex);
}

void freeLinkedList(LinkedList* list) {
