MemoryPool_T memory_pool = {NULL, 0, 0};

void init_memory_pool(size_t initial_size) {
    if (initial_size > MAX_POOL_SIZE) return;
    memory_pool.pool = malloc(initial_size);
    memory_pool.size = initial_size;
    memory_pool.used = 0;
}

void* allocate_from_pool(size_t size) {
    if (memory_pool.used + size > memory_pool.size) return NULL;
    void* ptr = (char*)memory_pool.pool + memory_pool.used;
    memory_pool.used += size;
    return ptr;
}

void free_memory_pool() {
    free(memory_pool.pool);
    memory_pool.pool = NULL;
    memory_pool.size = 0;
    memory_pool.used = 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t tag, uint16_t rnti, bool crc_indication) {
    if (memory_pool.pool == NULL) return NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T));
