ImageMetadata* loadAndProcessMetadata(const char* filePath, size_t maxRecords) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open metadata file");
        return NULL;
    }

    ImageMetadata* head = NULL;
    ImageMetadata** current = &head;

    size_t recordCount = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file) && recordCount < maxRecords) {
        ImageMetadata* newRecord = (ImageMetadata*)malloc(sizeof(ImageMetadata));
        if (!newRecord) {
            perror("Memory allocation failed");
            fclose(file);
            freeList(head);
            return NULL;
        }

        // Parse the metadata from the buffer
        sscanf(buffer, "%255s %d %d %31s", newRecord->filename, &newRecord->width, &newRecord->height, newRecord->format);

        // Add the record to the linked list
        *current = newRecord;
        current = &(*current)->next;

        recordCount++;
    }

    fclose(file);
    *current = NULL;  // Null-terminate the linked list

    return head;
}

// Helper function to free the memory allocated for the linked list
void freeList(ImageMetadata* head) {
    ImageMetadata* current = head;
    while (current) {
        ImageMetadata* next = current->next;
        free(current);
        current = next;
    }
}

