#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTS 100000
#define MAX_MEMORY_LIMIT 256 * 1024 * 1024 // 256MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

MemoryPoolNode *memory_pool = NULL;

NFAPI_CRC_INDICATION_PDU_T* allocate_structs(int N) {
    if (N > MAX_STRUCTS || N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_LIMIT) {
        return NULL; // Exceeds limits
    }

    for (int i = 0; i < N; ++i) {
        MemoryPoolNode *node = (MemoryPoolNode *)malloc(sizeof(MemoryPoolNode));
        if (!node) {
            return NULL; // Failed to allocate memory
        }
        node->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node->data) {
            free(node);
            return NULL; // Failed to allocate memory for data
        }

        memset(node->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        node->data->RX_UE_INFORMATION_TAG = rand() % 1000;
        node->data->RNTI = rand() % 256;
        node->data->CRC_INDICATION_REL8_TAG = rand() % 2;

        node->next = memory_pool;
        memory_pool = node;
    }

    return (NFAPI_CRC_INDICATION_PDU_T *)memory_pool->data;
}

void free_structs(NFAPI_CRC_INDICATION_PDU_T *list) {
    while (list) {
        MemoryPoolNode *node = (MemoryPoolNode *)list;
        list = list->next;
        free(node);
    }
}
