        return;
    }

    if (!isset($_SESSION['session_id'])) {
        $_SESSION['session_id'] = uniqid();
    }

    $session_id = $_SESSION['session_id'];

    // Log session ID for monitoring
    log_event("Session ID: $session_id", 'INFO');

    try {
        if (isset($_GET['code'])) {
            $token = $provider->getAccessToken('authorization_code', [
                'code' => $_GET['code']
            ]);

            $_SESSION['access_token'] = $token;
            echo "Authentication successful. Access Token: " . htmlspecialchars($token->getToken());

            // Log successful authentication
            log_event("User authenticated with session ID: $session_id", 'INFO');
        } else {
            $authUrl = $provider->getAuthorizationUrl([
                'scope' => 'openid email',
                'state' => $_SESSION['session_id']
            ]);

            $_SESSION['oauth2state'] = $provider->getState();

            header('Location: ' . $authUrl);
            exit;
        }
    } catch (\Exception $e) {
        echo "Error: " . htmlspecialchars($e->getMessage());

        // Log error
        log_event("Authentication failed with session ID: $session_id - Error: " . $e->getMessage(), 'ERROR');
    }
}

