typedef struct {
    int width;
    int height;
    size_t file_offset;
} ImageSegment;

#define MAX_SEGMENTS_PER_FILE 1000

int process_image_files(const char* filenames[], int num_files, ImageSegment** segments, size_t* total_segments) {
    // Calculate available system resources
    long long total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    long long max_memory_to_use = (long long)(total_memory * 0.8);

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
            perror("Failed to open file");
            return -1;
        }

        fseek(file, 0, SEEK_END);
        long long file_size = ftell(file);
        rewind(file);

        int num_segments = file_size / sizeof(ImageSegment); // Simplified calculation
        if (num_segments > MAX_SEGMENTS_PER_FILE) {
            fprintf(stderr, "Too many segments in file %s\n", filenames[i]);
            fclose(file);
            return -1;
        }

        // Check for integer overflow before allocation
        size_t required_memory = num_segments * sizeof(ImageSegment);
        if ((required_memory / sizeof(ImageSegment)) != num_segments) {
            fprintf(stderr, "Memory calculation overflow for file %s\n", filenames[i]);
            fclose(file);
            return -1;
        }

        // Allocate memory safely
        ImageSegment* new_segments = realloc(*segments, (*total_segments + num_segments) * sizeof(ImageSegment));
        if (!new_segments) {
            perror("Failed to allocate memory");
            fclose(file);
            return -2;
        }
        *segments = new_segments;

        // Populate segments with metadata (simplified for example)
        for (int j = 0; j < num_segments; j++) {
            (*segments)[*total_segments + j].width = rand() % 1000;
            (*segments)[*total_segments + j].height = rand() % 1000;
            (*segments)[*total_segments + j].file_offset = ftell(file);
        }

        *total_segments += num_segments;
        fclose(file);

        // Check if memory usage exceeds limit
        if (required_memory > max_memory_to_use) {
            fprintf(stderr, "Memory limit exceeded for file %s\n", filenames[i]);
            return -3;
        }
    }

    return 0;
}
