typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_config_file(const char *filename, int *N) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    if (fscanf(file, "%d", N) != 1 || *N <= 0) {
        fprintf(stderr, "Invalid or out-of-range value in configuration file\n");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int generate_RNTI(int *allocated_RNTIs, int max_size, unsigned short *RNTI) {
    static unsigned short last_RNTI = 0;
    while (last_RNTI <= 65535) {
        if (!is_allocated(allocated_RNTIs, max_size, last_RNTI)) {
            *RNTI = last_RNTI;
            allocated_RNTIs[*RNTI] = 1;
            return 0;
        }
        last_RNTI++;
    }
    fprintf(stderr, "Failed to allocate a unique RNTI\n");
    return -1;
}

int is_allocated(int *allocated_RNTIs, int max_size, unsigned short RNTI) {
    if (RNTI < 0 || RNTI >= max_size) {
        return 1;
    }
    return allocated_RNTIs[RNTI];
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(const char *filename, int *count) {
    int N;
    if (read_config_file(filename, &N) != 0) {
        *count = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for array: %s\n", strerror(errno));
        *count = -1;
        return NULL;
    }

    int allocated_RNTIs[65536] = {0};
    srand(time(NULL));

    *count = 0;
    for (int i = 0; i < N; i++) {
        unsigned short RNTI;
        if (generate_RNTI(allocated_RNTIs, 65536, &RNTI) != 0) {
            continue;
        }

        array[*count].RX_UE_INFORMATION_TAG = i + 1;
        array[*count].RNTI = RNTI;
        array[*count].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 'C' : '!';

        (*count)++;
    }

    if (*count < N) {
        fprintf(stderr, "Only %d structures were successfully allocated\n", *count);
    }

    return array;
}

int main() {
    const char *config_file = "path/to/config/file";
    int count;
    NFAPI_CRC_INDICATION_PDU_T *array = create_and_populate_array(config_file, &count);

    if (count != -1) {
        // Process the array
        free(array);
    }

    return 0;
}
