#define MAX_PACKET_SIZE 1024
#define MEMORY_POOL_SIZE 512

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_packets(int num_packets, size_t max_memory) {
    static NFAPI_CRC_INDICATION_PDU_T memory_pool[MEMORY_POOL_SIZE];
    static int pool_index = 0;
    static size_t current_usage = 0;

    if (current_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_packets > max_memory) {
        return NULL; // Exceeds maximum memory limit
    }

    NFAPI_CRC_INDICATION_PDU_T* packets = NULL;

    if (num_packets <= MEMORY_POOL_SIZE - pool_index) {
        packets = &memory_pool[pool_index];
        pool_index += num_packets;
    } else {
        packets = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_packets);
        if (!packets) {
            return NULL; // Memory allocation failed
        }
    }

    current_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_packets;

    for (int i = 0; i < num_packets; i++) {
