typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
} DoublyLinkedList;

void initialize_doubly_linked_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

void insert_at_end(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
}

void free_doubly_linked_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    initialize_doubly_linked_list(list);
}
