// Function to process multiple image files
void process_images(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return;
    }

    for (int i = 1; i < argc; ++i) {
