        fread(&width, sizeof(int), 1, file);
        fread(&height, sizeof(int), 1, file);

        if (width <= 0 || height <= 0) {
            fprintf(stderr, "Invalid image dimensions in file: %s\n", argv[i]);
            fclose(file);
            continue;
        }

        // Calculate memory required for the image
        size_t memory_required = calculate_image_memory(&img);

        // Allocate memory safely
        if (memory_required > SIZE_MAX / sizeof(unsigned char)) {
            fprintf(stderr, "Memory allocation too large for file: %s\n", argv[i]);
            fclose(file);
            continue;
        }

        unsigned char* data = malloc(memory_required);
