EVP_CIPHER* manage_NFAPI_CRC_list(int N, yaml_parser_t *parser) {
    if (N <= 0) {
        return NULL; // Invalid size
    }

    NFAPI_CRC_INDICATION_PDU_T** list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        // Randomly set CRCFLAG and initialize other fields
        if (!RAND_bytes((unsigned char*)&list[i]->crc_ind_tag.CRCFLAG, sizeof(list[i]->crc_ind_tag.CRCFLAG))) {
            for (int j = 0; j <= i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        // Parse YAML parameters
        if (!yaml_parser_parse(parser)) {
            for (int j = 0; j <= i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        // Initialize other fields based on YAML data
    }

    // Choose cipher mode based on configuration
    EVP_CIPHER* cipher;
    const char* mode_str = yaml_parser_get_tag(parser); // Get mode from YAML
    if (strcmp(mode_str, "ECB") == 0) {
        cipher = EVP_aes_128_ecb();
    } else if (strcmp(mode_str, "EDE") == 0) {
        cipher = EVP_aes_192_cbc(); // Simulating EDE with CBC for demonstration
    } else if (strcmp(mode_str, "EDE3") == 0) {
        cipher = EVP_aes_256_ecb(); // Simulating EDE3 with ECB for demonstration
    } else if (strcmp(mode_str, "CFB") == 0) {
        cipher = EVP_aes_128_cfb128();
    } else {
        for (int i = 0; i < N; i++) {
            free(list[i]);
        }
        free(list);
        return NULL; // Invalid mode
    }

    // Return the chosen cipher mode
    return cipher;
}
