#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 10000
#define RESIZE_THRESHOLD 0.8

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_array(size_t initial_capacity) {
    if (initial_capacity > MAX_CAPACITY) {
        fprintf(stderr, "Initial capacity exceeds maximum allowed.\n");
        return NULL;
    }
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void resize_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    if (new_capacity > MAX_CAPACITY) {
        fprintf(stderr, "Resizing would exceed maximum allowed capacity.\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
        return;
    }
    array->array = new_array;
    array->capacity = new_capacity;
}

int add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity * RESIZE_THRESHOLD) {
        resize_array(array);
    }
    if (array->size >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Error: Not enough space
    }
    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void free_array(DynamicArray *array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->mutex);
        free(array->array);
        free(array);
    }
}
