            fprintf(stderr, "Error: Not enough buffer space for image segment\n");
            fclose(file);
            continue;
        }

        // Allocate memory for the current segment
        ImageSegment* newSegment = realloc(segments, totalSize + segmentSize);
        if (!newSegment) {
            perror("Memory allocation failed");
            fclose(file);
            free(segments);
            return NULL;
        }
        segments = newSegment;

        // Initialize and populate the segment structure
