        strcpy(segments[totalSize / sizeof(ImageSegment)].format, format);
        strcpy(segments[totalSize / sizeof(ImageSegment)].compressionType, "Baseline");  // Example compression type

        totalSize += segmentSize;
        fclose(file);
    }

