#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_METADATA_SIZE 150

typedef struct ImageMetadata {
    char fileName[256];
    int resolution;
    size_t fileSize;
    char metadata[MAX_METADATA_SIZE];
    struct ImageMetadata *next;
} ImageMetadata;

ImageMetadata* processImageFiles(int numFiles, ...) {
    va_list args;
    va_start(args, numFiles);

    ImageMetadata *head = NULL;
    ImageMetadata **current = &head;

    for (int i = 0; i < numFiles; ++i) {
        const char *fileName = va_arg(args, const char *);
        int resolution = va_arg(args, int);
        size_t fileSize = va_arg(args, size_t);
        const char *metadata = va_arg(args, const char *);

        // Calculate required memory for the node
        size_t totalSize = sizeof(ImageMetadata) + strlen(metadata) - 1;
        if (totalSize > MAX_METADATA_SIZE) {
            printf("Error: Metadata exceeds maximum allowed size.\n");
            return NULL;
        }

        *current = (ImageMetadata *)malloc(totalSize);
        if (*current == NULL) {
            printf("Memory allocation failed.\n");
            va_end(args);
            while (head != NULL) {
                ImageMetadata *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        strncpy((*current)->fileName, fileName, 255);
        (*current)->fileName[255] = '\0';
        (*current)->resolution = resolution;
        (*current)->fileSize = fileSize;
        strncpy((*current)->metadata, metadata, MAX_METADATA_SIZE - 1);
        (*current)->metadata[MAX_METADATA_SIZE - 1] = '\0';

        (*current)->next = NULL;
        current = &(*current)->next;
    }

    va_end(args);
    return head;
}

// Example usage
int main() {
    ImageMetadata *images = processImageFiles(2, 
                                              "image1.jpg", 1920, 500000, "EXIF data",
                                              "image2.png", 1080, 300000, "PNG metadata");

    if (images != NULL) {
        // Process the linked list
        ImageMetadata *current = images;
        while (current != NULL) {
            printf("File: %s, Resolution: %d, Size: %zu bytes, Metadata: %s\n",
                   current->fileName, current->resolution, current->fileSize, current->metadata);
            ImageMetadata *temp = current;
            current = current->next;
            free(temp);
        }
    } else {
        printf("Failed to process image files.\n");
    }

    return 0;
}
