#define MAX_PAYLOAD_SIZE 1024

typedef struct PacketData {
    char header[32];
    size_t payload_length;
    char *payload_data;
} PacketData;

typedef struct PacketNode {
    PacketData packet;
    struct PacketNode *next;
} PacketNode;

PacketNode* process_packets(const char *packet_stream, size_t total_payload_limit) {
    PacketNode *head = NULL;
    PacketNode *current = NULL;
    size_t current_payload_size = 0;

    // Simulate reading packets from a stream
    const char *packet_start = packet_stream;
    while (*packet_start != '\0') {
        // Assuming each packet starts with its header and payload length
        if (strlen(packet_start) < 32 + sizeof(size_t)) {
            fprintf(stderr, "Malformed packet format\n");
            break;
        }

        strcpy(current->packet.header, packet_start);
        size_t payload_len = *(size_t *)(packet_start + 32);
        current->packet.payload_length = payload_len;

        // Check for integer overflow
        if (payload_len > SIZE_MAX - current_payload_size) {
            fprintf(stderr, "Integer overflow error\n");
            break;
        }

        if ((current_payload_size += payload_len) > total_payload_limit) {
            fprintf(stderr, "Payload limit exceeded\n");
            break;
        }

        // Allocate memory for the payload
        current->packet.payload_data = (char *)malloc(payload_len);
        if (!current->packet.payload_data) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        memcpy(current->packet.payload_data, packet_start + 32 + sizeof(size_t), payload_len);

        // Move to the next packet in the stream
        packet_start += 32 + sizeof(size_t) + payload_len;

        if (!head) {
            head = current;
        }
    }

    return head;
}

void free_packet_list(PacketNode *node) {
    PacketNode *temp;
    while (node) {
        temp = node;
        node = node->next;
        free(temp->packet.payload_data);
        free(temp);
    }
}
