#define MAX_PACKETS 20000
#define DEFAULT_MEMORY_LIMIT (1 * 1024 * 1024 * 1024) // 1 GB in bytes

typedef struct PacketData {
    int priority;
    size_t payload_length;
    char* payload_data;
    struct PacketData* next;
} PacketData;

typedef struct MemoryPool {
    char* pool_start;
    char* pool_end;
    char* current_alloc;
    size_t total_size;
    size_t used_memory;
} MemoryPool;

MemoryPool* create_memory_pool(size_t memory_limit) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->pool_start = (char*)malloc(memory_limit);
    if (!pool->pool_start) {
        free(pool);
        return NULL;
    }

    pool->pool_end = pool->pool_start + memory_limit;
    pool->current_alloc = pool->pool_start;
    pool->total_size = memory_limit;
    pool->used_memory = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool_start);
    free(pool);
}

char* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->current_alloc + size > pool->pool_end) {
        return NULL; // Not enough space in the pool
    }

    char* allocated = pool->current_alloc;
    pool->current_alloc += size;
    pool->used_memory += size;

    return allocated;
}

PacketData* create_packet(int priority, const char* payload_data, size_t payload_length) {
    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    if (!packet) return NULL;

    packet->priority = priority;
    packet->payload_length = payload_length;

    packet->payload_data = allocate_from_pool(&memory_pool, payload_length);
    if (!packet->payload_data) {
        free(packet);
        return NULL;
    }

    memcpy(packet->payload_data, payload_data, payload_length);

    packet->next = NULL;

    return packet;
}

void destroy_packet(PacketData* packet) {
    free(packet->payload_data);
    free(packet);
}

