#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct PacketData {
    int header;
    size_t payload_length;
    char* payload;
    struct PacketData* prev;
    struct PacketData* next;
} PacketData;

typedef struct ThreadSafeList {
    pthread_mutex_t lock;
    PacketData* head;
    PacketData* tail;
    size_t total_payload_size;
    size_t max_memory_usage;
} ThreadSafeList;

void init_thread_safe_list(ThreadSafeList* list, size_t max_memory_usage) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->total_payload_size = 0;
    list->max_memory_usage = max_memory_usage;
}

void destroy_thread_safe_list(ThreadSafeList* list) {
    PacketData* current = list->head;
    while (current != NULL) {
        PacketData* next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int process_packet(ThreadSafeList* list, int header, const char* payload, size_t payload_length) {
    if (payload_length > MAX_PACKET_SIZE) {
        fprintf(stderr, "Error: Payload too large\n");
        return -1;
    }

    // Check for integer overflow
    size_t new_payload_size = list->total_payload_size + payload_length;
    if (new_payload_size < list->total_payload_size || new_payload_size > list->max_memory_usage) {
        fprintf(stderr, "Error: Memory allocation limit exceeded\n");
        return -1;
    }

    // Allocate memory for the new packet
    PacketData* new_packet = (PacketData*)malloc(sizeof(PacketData));
    if (!new_packet) {
        perror("Failed to allocate memory");
        return -1;
    }

    new_packet->header = header;
    new_packet->payload_length = payload_length;
    new_packet->payload = (char*)malloc(payload_length);
    if (!new_packet->payload) {
        free(new_packet);
        perror("Failed to allocate memory for payload");
        return -1;
    }
    memcpy(new_packet->payload, payload, payload_length);

    // Add the new packet to the list
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_packet;
        list->tail = new_packet;
    } else {
        list->tail->next = new_packet;
        new_packet->prev = list->tail;
        list->tail = new_packet;
    }
    list->total_payload_size += payload_length;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Example usage
int main() {
    ThreadSafeList packet_list;
    init_thread_safe_list(&packet_list, 10 * 1024 * 1024); // 10 MB limit

    const char* payload = "Hello, world!";
    process_packet(&packet_list, 0x1234, payload, strlen(payload));

    destroy_thread_safe_list(&packet_list);
    return 0;
}
