        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    OUT_OF_MEMORY,
    BAD_INPUT
} Result;

Result allocate_and_populate_list(NFAPI_CRC_INDICATION_PDU_T **head, int N, size_t max_memory_limit) {
    if (N <= 0 || max_memory_limit <= 0) {
        return BAD_INPUT;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = NULL;
    NFAPI_CRC_INDICATION_PDU_T *new_node = NULL;

    for (int i = 0; i < N; ++i) {
        size_t node_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (node_size > max_memory_limit || (current && current->next && (current->next + 1)->RNTI > UINT16_MAX)) {
            return OUT_OF_MEMORY;
        }

        new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(node_size);
        if (!new_node) {
            return OUT_OF_MEMORY;
        }

        new_node->RX_UE_INFORMATION_TAG = i + 1;
        new_node->RNTI = (uint16_t)(rand() % UINT16_MAX);
        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (!current) {
            *head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }

        if (i > max_memory_limit / 2) {
            // Log allocation exceeding 50% of the specified limit
            printf("Warning: Allocation exceeds 50%% of memory limit\n");
        }
    }

    return SUCCESS;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int N = 1000; // Number of nodes
    size_t max_memory_limit = 1024 * 1024 * 1024; // 1GB

    Result result = allocate_and_populate_list(&head, N, max_memory_limit);
    if (result != SUCCESS) {
        printf("Failed to allocate and populate list: %d\n", result);
    } else {
        free_list(head);
    }

    return 0;
}
