#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 10000
#define MAX_MEMORY_USAGE_LIMIT 1024 * 1024 // 1MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
    size_t memory_usage;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initialize_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void insert_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_LIST_SIZE) {
        printf("List size limit exceeded\n");
        pthread_mutex_unlock(&list->lock);
        free(node);
        return;
    }
    if (list->memory_usage + sizeof(Node) > MAX_MEMORY_USAGE_LIMIT * 0.5) {
        printf("Memory usage nearing limit, consider optimizing allocation strategy\n");
    }
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->count++;
    list->memory_usage += sizeof(Node);
    pthread_mutex_unlock(&list->lock);
}

void remove_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (node == NULL) {
        printf("Node to remove is null\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    free(node);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

void process_list(DoublyLinkedList* list, bool retain_crcflag_set) {
    Node* current = list->head;
    while (current != NULL) {
        if (!retain_crcflag_set && !current->data.CRCFLAG) {
            remove_node(list, current);
            current = current->next; // Skip the removed node
        } else {
            current = current->next;
        }
    }
}

void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->memory_usage = 0;
}

int main() {
    DoublyLinkedList list;
    initialize_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = 123;
    data.RNTI = 456;
    data.CRCFLAG = true;

    Node* node = create_node(data);
    insert_node(&list, node);

    process_list(&list, false);

    free_list(&list);
    pthread_mutex_destroy(&list.lock);

    return 0;
}
```

This code provides a basic implementation of a doubly-linked list with thread-safe operations and memory management features as per the given requirements. It includes functions for initializing, inserting, removing, processing, and freeing the list. The `process_list` function demonstrates how to selectively retain nodes based on the `CRCFLAG`. Note that external logging and performance optimization strategies are not implemented in this code snippet and should be integrated separately based on specific logging library and performance measurement tools.']

