} JPEG_IMAGE_T;

JPEG_IMAGE_T** create_image_collection(int max_images, size_t max_total_memory) {
    if (max_images <= 0 || max_total_memory == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    size_t total_pixel_data_size = max_images * MAX_IMAGE_SIZE;
    if (total_pixel_data_size > max_total_memory) {
        fprintf(stderr, "Total pixel data size exceeds maximum memory limit.\n");
        return NULL;
    }

    JPEG_IMAGE_T** collection = (JPEG_IMAGE_T**)malloc(max_images * sizeof(JPEG_IMAGE_T*));
    if (!collection) {
        perror("Failed to allocate memory for image collection.");
        return NULL;
    }

    for (int i = 0; i < max_images; ++i) {
        collection[i] = (JPEG_IMAGE_T*)malloc(sizeof(JPEG_IMAGE_T));
        if (!collection[i]) {
            fprintf(stderr, "Failed to allocate memory for JPEG_IMAGE_T structure.\n");
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(collection[j]);
            }
            free(collection);
            return NULL;
        }

        collection[i]->pixel_data_size = MAX_IMAGE_SIZE;
        collection[i]->pixel_data = (unsigned char*)malloc(MAX_IMAGE_SIZE * sizeof(unsigned char));
        if (!collection[i]->pixel_data) {
            fprintf(stderr, "Failed to allocate memory for pixel data.\n");
            // Free previously allocated structures and pixel data
            free(collection[i]);
            for (int j = 0; j < i; ++j) {
                free(collection[j]->pixel_data);
                free(collection[j]);
            }
            free(collection);
            return NULL;
        }

        collection[i]->width = 1024; // Example width
        collection[i]->height = 768; // Example height
    }

    return collection;
}

void destroy_image_collection(JPEG_IMAGE_T** collection, int max_images) {
    if (!collection || max_images <= 0) {
        return;
    }

    for (int i = 0; i < max_images; ++i) {
        if (collection[i]) {
            free(collection[i]->pixel_data);
            free(collection[i]);
        }
    }

    free(collection);
}

// Example usage
int main() {
    size_t max_total_memory = 1024 * 1024 * 1024; // 1GB
    int max_images = 10;

    JPEG_IMAGE_T** collection = create_image_collection(max_images, max_total_memory);
    if (collection) {
        printf("Image collection created successfully.\n");
        destroy_image_collection(collection, max_images);
    }

    return 0;
}
