int allocate_pdu(int n, int total_mem_size_kb) {
    pthread_mutex_lock(&pdu_list_mutex);

    if (n > MAX_PDU_COUNT || ((current_pdu_count + n) > MAX_PDU_COUNT)) {
        pthread_mutex_unlock(&pdu_list_mutex);
        return -1; // Error: Exceeds maximum number of PDUs
    }

    size_t required_memory = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
