        pthread_mutex_unlock(&pdu_list_mutex);
        return -2; // Error: Exceeds maximum memory size
    }

    for (int i = 0; i < n; i++) {
        pdu_list[current_pdu_count + i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
