#define MAX_IMAGE_SIZE 1024 * 1024 // 1MB

typedef struct {
    int width;
    int height;
    unsigned char* pixels;
} img_t;

img_t* processImages(int maxMemory, int numPaths, const char** paths) {
    if (numPaths < 1 || !paths || maxMemory <= 0) {
        fprintf(stderr, "Invalid input: Number of images must be greater than 0 and maxMemory must be positive.\n");
        return NULL;
    }

    img_t* images = malloc(numPaths * sizeof(img_t));
    if (!images) {
        fprintf(stderr, "Failed to allocate memory for image structures.\n");
        return NULL;
    }

    size_t totalMemoryRequired = 0;

    for (int i = 0; i < numPaths; ++i) {
        FILE* file = fopen(paths[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open image file: %s\n", paths[i]);
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(images[j].pixels);
            }
            free(images);
            return NULL;
        }

        fseek(file, 0, SEEK_END);
        size_t fileSize = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (fileSize > MAX_IMAGE_SIZE) {
            fprintf(stderr, "Image file too large: %s\n", paths[i]);
            fclose(file);
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(images[j].pixels);
            }
            free(images);
            return NULL;
        }

        if (fileSize > (maxMemory - totalMemoryRequired)) {
            fprintf(stderr, "Insufficient memory to load image: %s\n", paths[i]);
            fclose(file);
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(images[j].pixels);
            }
            free(images);
            return NULL;
        }

        images[i].width = 1024; // Dummy value, actual width should be read from file
        images[i].height = 768; // Dummy value, actual height should be read from file
        images[i].pixels = malloc(fileSize);
        if (!images[i].pixels) {
            fprintf(stderr, "Failed to allocate memory for image pixels: %s\n", paths[i]);
            fclose(file);
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(images[j].pixels);
            }
            free(images);
            return NULL;
        }

        size_t bytesRead = fread(images[i].pixels, 1, fileSize, file);
        if (bytesRead != fileSize) {
            fprintf(stderr, "Failed to read image file: %s\n", paths[i]);
            fclose(file);
            // Free previously allocated structures
            for (int j = 0; j < i; ++j) {
                free(images[j].pixels);
            }
            free(images);
            return NULL;
        }

        fclose(file);
        totalMemoryRequired += fileSize;
    }

    return images;
}
