typedef struct PacketHeader {
    time_t timestamp;
    size_t length;
    char* payload;
} PacketHeader;

PacketHeader* process_packets(char** packet_data, size_t num_packets, size_t max_payload_size, size_t max_memory, void (*log_error)(const char*), void (*log_metric)(const char*, int)) {
    PacketHeader* headers = NULL;
    size_t total_length = 0;

    for (size_t i = 0; i < num_packets && total_length <= max_memory; ++i) {
        size_t packet_size = strlen(packet_data[i]) + 1;
        if (packet_size > max_payload_size || packet_size > max_memory - total_length) {
            log_error("Packet exceeds maximum allowed payload or memory limit.");
            break;
        }

        headers = realloc(headers, (i + 1) * sizeof(PacketHeader));
        if (!headers) {
            log_error("Memory allocation failed.");
            return NULL;
        }

        headers[i].timestamp = time(NULL);
        headers[i].length = packet_size;
        headers[i].payload = malloc(packet_size);
        if (!headers[i].payload) {
            log_error("Failed to allocate memory for packet payload.");
            free(headers);
            return NULL;
        }
        strcpy(headers[i].payload, packet_data[i]);
        total_length += headers[i].length;

        // Log performance metric
        log_metric("Processed packet", i + 1);
    }

    if (total_length > max_memory) {
        log_error("Total allocated memory exceeds maximum limit.");
        for (size_t i = 0; i < num_packets; ++i) {
            free(headers[i].payload);
        }
        free(headers);
        return NULL;
    }

    return headers;
}
