} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    bool paused;
} NFAPICRCIndicationQueue;

NFAPICRCIndicationQueue* create_queue() {
    NFAPICRCIndicationQueue* queue = (NFAPICRCIndicationQueue*)malloc(sizeof(NFAPICRCIndicationQueue));
    if (!queue) return NULL;

    pthread_mutex_init(&queue->mutex, NULL);
    queue->data = NULL;
    queue->count = 0;
    queue->capacity = 0;
    queue->paused = false;

    return queue;
}

void free_queue(NFAPICRCIndicationQueue* queue) {
    if (queue->data) {
        free(queue->data);
    }
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

bool enqueue(NFAPICRCIndicationQueue* queue, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->paused) {
        // Wait until unpaused
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }

    if (queue->count >= queue->capacity && !queue->paused) {
        size_t new_capacity = queue->capacity == 0 ? 1 : queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(queue->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&queue->mutex);
            return false;
        }
        queue->data = new_data;
        queue->capacity = new_capacity;
    }

    queue->data[queue->count++] = item;

    pthread_mutex_unlock(&queue->mutex);
    return true;
}

bool dequeue(NFAPICRCIndicationQueue* queue, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->count == 0 && !queue->paused) {
        // Wait until data is available
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }

    if (queue->count > 0) {
        *item = queue->data[--queue->count];
        memmove(queue->data + queue->count, queue->data + queue->count + 1, (queue->capacity - queue->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        pthread_mutex_unlock(&queue->mutex);
        return false;
    }

    pthread_mutex_unlock(&queue->mutex);
    return true;
}

void* nfa_pi_crc_indication(void* arg) {
    NFAPICRCIndicationQueue* queue = (NFAPICRCIndicationQueue*)arg;
    NFAPI_CRC_INDICATION_PDU_T item;

    while (!queue->paused) {
