        // Log successful completion
        printf("Enqueued item: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%d\n", 
               item.RX_UE_INFORMATION_TAG, item.RNTI, item.CRC_INDICATION_REL8_TAG);
    }

    return NULL;
}
