int safe_add(size_t a, size_t b, size_t* result) {
    if (b > SIZE_MAX - a) {
        *result = 0;
        return -1; // Overflow
    }
    *result = a + b;
    return 0;
}

void packet_list_init(PacketList* list, size_t initial_capacity) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&list->mutex, &attr);

    list->packets = (PacketHeader**)malloc(initial_capacity * sizeof(PacketHeader*));
    if (!list->packets) {
        log_error("Failed to allocate initial packet buffer");
        return;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    list->total_memory_used = 0;
}

void packet_list_add(PacketList* list, const NetworkPacket* packet) {
    pthread_mutex_lock(&list->mutex);

    if (safe_add(list->size, 1, &list->size) != 0) {
        log_error("Size overflow during packet addition");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (list->size > list->capacity) {
        size_t new_capacity = list->capacity * 2;
        PacketHeader** new_packets = realloc(list->packets, new_capacity * sizeof(PacketHeader*));
        if (!new_packets) {
            log_error("Failed to reallocate packet buffer");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->packets = new_packets;
        list->capacity = new_capacity;
    }

    PacketHeader* header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (!header) {
        log_error("Failed to allocate packet header");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    header->timestamp = time(NULL);
    header->length = packet->length;

    size_t payload_size;
    if (safe_add(packet->length, sizeof(time_t), &payload_size) != 0) {
        log_error("Payload size overflow");
        free(header);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    void* payload = malloc(payload_size);
    if (!payload) {
        log_error("Failed to allocate packet payload");
        free(header);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memcpy(payload, &header->timestamp, sizeof(time_t));
    memcpy((char*)payload + sizeof(time_t), packet->data, packet->length);

    if (calculate_checksum(payload, payload_size) != CHECKSUM_OK) {
        log_error("Packet checksum error");
        free(header);
        free(payload);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    header->payload = payload;
    list->packets[list->size - 1] = header;

    pthread_mutex_unlock(&list->mutex);
}

void packet_list_free(PacketList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->mutex);
}
