#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define MAX_MEMORY 1073741824 // 1GB

typedef struct PacketHeader {
    time_t timestamp;
    size_t length;
    char *payload;
    int processed;
} PacketHeader;

typedef struct Node {
    PacketHeader *packet;
    struct Node *next;
} Node;

typedef struct Queue {
    Node *front;
    Node *rear;
    size_t current_size;
    size_t total_memory_used;
    pthread_mutex_t lock;
} Queue;

Queue* create_queue() {
    Queue *q = (Queue*)malloc(sizeof(Queue));
    q->front = q->rear = NULL;
    q->current_size = 0;
    q->total_memory_used = 0;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(Queue *q, PacketHeader *packet) {
    pthread_mutex_lock(&q->lock);
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->packet = packet;
    new_node->next = NULL;

    if (q->rear == NULL) {
        q->front = q->rear = new_node;
    } else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    q->current_size++;
    q->total_memory_used += sizeof(PacketHeader) + packet->length;

    if (q->total_memory_used > MAX_MEMORY) {
        // Handle memory overflow
    }

    pthread_mutex_unlock(&q->lock);
}

PacketHeader* dequeue(Queue *q) {
    pthread_mutex_lock(&q->lock);
    if (q->front == NULL) {
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    Node *temp = q->front;
    PacketHeader *packet = temp->packet;

    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    q->current_size--;
    q->total_memory_used -= sizeof(PacketHeader) + packet->length;

    pthread_mutex_unlock(&q->lock);
    return packet;
}

void destroy_queue(Queue *q) {
    pthread_mutex_lock(&q->lock);
    Node *temp = q->front;
    while (temp != NULL) {
        Node *next = temp->next;
        free(temp->packet->payload);
        free(temp->packet);
        free(temp);
        temp = next;
    }
    pthread_mutex_unlock(&q->lock);
    pthread_mutex_destroy(&q->lock);
    free(q);
}
