struct PacketSummary {
    int protocolVersion;
    size_t payloadLength;
    uint64_t uniqueId;
};

class PacketProcessor {
public:
    void processPacket(int protocolVersion, const std::vector<char>& payload) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (processingRate_ >= maxProcessingRate_) {
            cv_.wait(lock);
        }
        if (payload.size() > MAX_PAYLOAD_SIZE || protocolVersion < 0) {
            throw std::invalid_argument("Invalid packet data");
        }
        PacketSummary summary = {protocolVersion, payload.size(), generateUniqueId()};
        summaries_.push_back(summary);
        ++packetCount_;
        processingRate_++;
    }

    size_t getPacketCount() const {
        return packetCount_;
    }

    void adjustProcessingRate(size_t targetRate) {
        maxProcessingRate_ = targetRate;
    }

private:
    std::vector<PacketSummary> summaries_;
    size_t packetCount_ = 0;
    size_t processingRate_ = 0;
    const size_t maxProcessingRate_ = 5;
    const size_t MAX_PAYLOAD_SIZE = 1024 * 1024; // 1MB
    std::mutex mutex_;
    std::condition_variable cv_;

    uint64_t generateUniqueId() {
        return std::chrono::duration_cast<std::chrono::nanoseconds>(
                   std::chrono::system_clock::now().time_since_epoch()).count();
    }
};

int main() {
    PacketProcessor processor;
    // Simulate packet processing
    for (size_t i = 0; i < 1000; ++i) {
        try {
            processor.processPacket(static_cast<int>(i % 6), std::vector<char>(i % MAX_PAYLOAD_SIZE));
        } catch (const std::exception& e) {
            std::cerr << "Exception: " << e.what() << std::endl;
