    if (num_entries > MAX_ENTRIES || num_entries * sizeof(NFAPI_CRC_INDICATION_PDU) > MAX_MEMORY_LIMIT) {
        return -1; // Exceeds maximum limit
    }
    size_t new_size = current_size + num_entries;
    if (new_size < current_size) { // Check for integer overflow
        return -2; // Integer overflow
    }
    NFAPI_CRC_INDICATION_PDU* new_array = realloc(pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (new_array == NULL) {
        return -3; // Memory allocation failure
    }
    pdu_array = new_array;
    current_size = new_size;
    return 0;
}

int compute_sha256_hash(const char* filename, unsigned char hash[SHA256_DIGEST_LENGTH]) {
    FILE* file = fopen(filename, "rb");
