        if (bytes_read == 0 && ferror(file)) {
            fclose(file);
            return -2; // Read error
        }
        SHA256_Update(&sha256, buffer, bytes_read);
    }
    fclose(file);
    SHA256_Final(hash, &sha256);
    return 0;
}

