#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_PACKETS 10000
#define MAX_RETRIES 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* packets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

void initializePacketList(PacketList* list) {
    list->packets = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int addPacketToQueue(PacketList* list, NFAPI_CRC_INDICATION_PDU_T packet) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_PACKETS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Queue overflow
    }

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_packets = realloc(list->packets, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_packets == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }
        list->packets = new_packets;
        list->capacity = new_capacity;
    }

    list->packets[list->size++] = packet;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void destroyPacketList(PacketList* list) {
    pthread_mutex_lock(&list->lock);

    free(list->packets);
    list->packets = NULL;
    list->size = 0;
    list->capacity = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

This code snippet provides a basic structure for managing a queue of network packets using a lock-based approach. It includes functions to initialize, add packets to the queue, and destroy the packet list. The implementation ensures thread safety by locking around critical sections, preventing data corruption in concurrent environments. The code also handles memory allocation and reallocation with error checking for both success and failure scenarios. This example is intended as a starting point for a more comprehensive solution that addresses all the specified requirements.']

