    RX_UE_INFORMATION_T rx_ue_info;
    CRC_INDICATION_REL8_T crc_ind_rel8;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_dynamic_list(int N) {
    if (N <= 0) return NULL;

    // Seed for random number generation
    srand(time(0));

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node == NULL) {
            // Handle memory allocation failure
            while (head != NULL) {
                current = head;
                head = head->next;
                free(current);
            }
            return NULL;
        }

        new_node->rx_ue_info.RX_UE_INFORMATION_TAG = i; // Example initialization
        new_node->rx_ue_info.RNTI = rand() % 1024; // Random RNTI between 0 and 1023
        new_node->crc_ind_rel8.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

// Example usage
int main() {
    int N = 5;
    NFAPI_CRC_INDICATION_PDU_T *list = create_dynamic_list(N);
    // Use the list...
    while (list != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               list->rx_ue_info.RX_UE_INFORMATION_TAG,
               list->rx_ue_info.RNTI,
               list->crc_ind_rel8.CRCFLAG);
        NFAPI_CRC_INDICATION_PDU_T *temp = list;
        list = list->next;
        free(temp);
    }
    return 0;
}
