#define MAX_LAYERS_PER_IMAGE 10000
#define MAX_SIZE_PER_LAYER (1 * 1024 * 1024 * 1024) // 1 GB in bytes
#define MAX_TOTAL_MEMORY (10 * 1024 * 1024 * 1024 * 1024) // 10 TB in bytes

typedef struct {
    int width;
    int height;
    unsigned char* data;
} image_layer_t;

typedef struct {
    int layer_count;
    image_layer_t** layers;
} image_file_t;

int allocate_image_layers(image_file_t* image, const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open image file");
        return -1;
    }

    fscanf(file, "%d", &image->layer_count);
    if (image->layer_count > MAX_LAYERS_PER_IMAGE) {
        fprintf(stderr, "Error: Image contains too many layers\n");
        fclose(file);
        return -2;
    }

    image->layers = (image_layer_t**)malloc(image->layer_count * sizeof(image_layer_t*));
    if (!image->layers) {
        perror("Failed to allocate memory for layer pointers");
        fclose(file);
        return -3;
    }

    uint64_t total_memory = 0;
    for (int i = 0; i < image->layer_count; ++i) {
        image->layers[i] = (image_layer_t*)malloc(sizeof(image_layer_t));
        if (!image->layers[i]) {
            perror("Failed to allocate memory for layer");
            for (int j = 0; j < i; ++j) {
                free(image->layers[j]);
            }
            free(image->layers);
            fclose(file);
            return -4;
        }

        fscanf(file, "%d %d", &image->layers[i]->width, &image->layers[i]->height);
        size_t layer_size = image->layers[i]->width * image->layers[i]->height * sizeof(unsigned char);
        if (layer_size > MAX_SIZE_PER_LAYER) {
            fprintf(stderr, "Error: Layer exceeds maximum size\n");
            for (int j = 0; j <= i; ++j) {
                free(image->layers[j]);
            }
            free(image->layers);
            fclose(file);
            return -5;
        }

        total_memory += layer_size;
        if (total_memory > MAX_TOTAL_MEMORY) {
            fprintf(stderr, "Error: Total memory exceeds maximum limit\n");
            for (int j = 0; j <= i; ++j) {
                free(image->layers[j]);
            }
            free(image->layers);
            fclose(file);
            return -6;
        }

        image->layers[i]->data = (unsigned char*)malloc(layer_size);
        if (!image->layers[i]->data) {
            perror("Failed to allocate memory for layer data");
            for (int j = 0; j <= i; ++j) {
                free(image->layers[j]);
            }
            free(image->layers);
            fclose(file);
            return -7;
        }

        // Simulate reading pixel data from file
        fread(image->layers[i]->data, layer_size, 1, file);
    }

    fclose(file);
    return 0;
}

