typedef struct {
    char* metadata;
    size_t length;
} NetworkPacket;

int processNetworkPackets(NetworkPacket** packets, size_t maxPackets, size_t packetLength, size_t headerSize) {
    if (maxPackets == 0 || packetLength == 0 || headerSize == 0) {
        return -1; // Invalid input
    }

    NetworkPacket* tempPackets = (NetworkPacket*)malloc(maxPackets * sizeof(NetworkPacket));
    if (!tempPackets) {
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < maxPackets; ++i) {
        if (headerSize > packetLength) {
            free(tempPackets);
            return -3; // Invalid header size
        }

        tempPackets[i].metadata = (char*)malloc(headerSize);
        if (!tempPackets[i].metadata) {
            for (size_t j = 0; j < i; ++j) {
                free(tempPackets[j].metadata);
            }
            free(tempPackets);
            return -2; // Memory allocation failed
        }

        tempPackets[i].length = packetLength;
    }

    *packets = tempPackets;
    return maxPackets;
}

int main() {
    NetworkPacket* packets = NULL;
    size_t maxPackets = 100;
    size_t packetLength = 1500;
    size_t headerSize = 20;

    int result = processNetworkPackets(&packets, maxPackets, packetLength, headerSize);
    if (result < 0) {
        printf("Error processing network packets: %d\n", result);
        return 1;
    }

    for (size_t i = 0; i < result; ++i) {
        free(packets[i].metadata);
    }
    free(packets);

    return 0;
}
