int processDirectory(const char* directoryPath, size_t maxMemoryLimit, ImageFile** imageFiles) {
    DIR* dir;
    struct dirent* ent;
    struct stat fileStat;
    size_t totalSize = 0;
    int count = 0;

    if ((dir = opendir(directoryPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char filePath[MAX_FILENAME_LENGTH];
            snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, ent->d_name);

            if (lstat(filePath, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
                ImageFile* newImage = malloc(sizeof(ImageFile));
                if (!newImage) return -1; // Memory allocation failed

                newImage->pixelData = malloc(fileStat.st_size);
                if (!newImage->pixelData) {
                    free(newImage);
                    return -2; // Memory allocation failed for pixel data
                }

