                (*imageFiles)[count++] = *newImage;

                totalSize += fileStat.st_size;
                if (totalSize > maxMemoryLimit) {
                    free(newImage->pixelData);
                    free(newImage);
                    return -3; // Exceeds maximum memory limit
                }
            }
        }
        closedir(dir);
    } else {
        return -4; // Failed to open directory
    }

    *imageFiles = realloc(*imageFiles, count * sizeof(ImageFile));
    if (!*imageFiles) return -5; // Realloc failed

    return count;
}

