void* packet_processor(void* arg) {
    // Simulate packet processing
    for (int i = 0; i < MAX_PACKETS; ++i) {
        pthread_mutex_lock(&mutex);
        if (allocated_packets >= MAX_PACKETS) {
            printf("Memory limit reached!\n");
            pthread_mutex_unlock(&mutex);
            break;
        }

        Packet* new_packet = &packet_list[allocated_packets++];
        // Simulate packet creation and data fetching
        new_packet->identifier = i;
        new_packet->payload_length = rand() % MAX_PACKET_SIZE;
        // Initialize payload with dummy data
        for (size_t j = 0; j < new_packet->payload_length; ++j) {
            new_packet->payload[j] = 'A' + (i % 26);
        }
