        (*pduList)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pduList)[i].RNTI = rand() % 65536;
        (*pduList)[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }
    return N; // Return the number of structures generated
}

// Function to execute an external command asynchronously
void executeCommandAsync(const char* command, const char* outputFilePath) {
    FILE* outputFile = fopen(outputFilePath, "w");
    if (outputFile == NULL) {
        perror("Failed to open output file");
        return;
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        fclose(outputFile);
        return;
    } else if (pid == 0) {
        // Child process
        execlp("sh", "sh", "-c", command, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0); // Wait for the child process to finish
        fclose(outputFile);
    }
}

// Function to delete a file if it exists
void deleteFile(const char* filePath) {
    if (remove(filePath) != 0) {
        perror("Failed to delete file");
    }
}

int main() {
    int N = 1000; // Example number of structures
    NFAPI_CRC_INDICATION_PDU_T* pduList;
    int result = generateNFAPICRCIndicationPduList(N, &pduList);
    if (result < 0) {
        printf("Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    const char* command = "your_command_here"; // Replace with actual command
    const char* outputFilePath = "/path/to/output/file";
    deleteFile(outputFilePath); // Delete existing file if it exists
    executeCommandAsync(command, outputFilePath);

    free(pduList); // Free allocated memory
    return EXIT_SUCCESS;
}
