#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_ALLOCATIONS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int log_total_structures = 0;
int log_errors = 0;
FILE* log_file = NULL;

void initialize_logging() {
    log_file = fopen("allocation_log.txt", "w");
}

void finalize_logging() {
    if (log_file) {
        fclose(log_file);
    }
}

void log_allocation(int successful, int total_allocated) {
    if (log_file) {
        fprintf(log_file, "%s %d\n", successful ? "Success" : "Error", total_allocated);
        fflush(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(int N) {
    if (N > MAX_ALLOCATIONS || N <= 0) {
        log_allocation(0, N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_allocation(0, N);
        log_errors++;
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    log_allocation(1, N);
    log_total_structures += N;

    return pdus;
}

int main() {
    initialize_logging();

    int num_allocations[] = {500, 600, 700};
    for (size_t i = 0; i < sizeof(num_allocations) / sizeof(num_allocations[0]); i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_and_populate_pdus(num_allocations[i]);
        if (pdus) {
            // Use the allocated and populated PDUs
            free(pdus);
        }
    }

    finalize_logging();
    printf("Total structures created: %d\n", log_total_structures);
    printf("Total errors encountered: %d\n", log_errors);

    return 0;
}
