#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_PAYLOAD_SIZE 1024
#define SYSTEM_MEMORY_LIMIT 0.1

typedef struct PacketHeader {
    time_t timestamp;
    int protocol_type;
    char* payload;
    size_t payload_size;
    struct PacketHeader* next;
} PacketHeader;

PacketHeader* create_packet_header(time_t timestamp, int protocol_type, const char* payload, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Payload size exceeds maximum allowed.\n");
        return NULL;
    }

    PacketHeader* header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (!header) {
        perror("Failed to allocate memory for packet header.");
        return NULL;
    }

    header->timestamp = timestamp;
    header->protocol_type = protocol_type;
    header->payload_size = payload_size;

    header->payload = (char*)malloc(payload_size);
    if (!header->payload) {
        perror("Failed to allocate memory for payload.");
        free(header);
        return NULL;
    }

    memcpy(header->payload, payload, payload_size);

    header->next = NULL;

    // Check system memory usage
    struct sysinfo si;
    if (sysinfo(&si) != 0) {
        fprintf(stderr, "Failed to get system information.\n");
        free(header->payload);
        free(header);
        return NULL;
    }

    size_t total_memory_usage = si.totalram - si.freeram + header->payload_size * sizeof(PacketHeader);
    if (total_memory_usage > si.totalram * SYSTEM_MEMORY_LIMIT) {
        fprintf(stderr, "Memory usage exceeds system limit.\n");
        free(header->payload);
        free(header);
        return NULL;
    }

    return header;
}

void process_packet_batch(const PacketHeader* packet_batch, size_t batch_size) {
    PacketHeader* head = NULL;
    PacketHeader** tail = &head;

    for (size_t i = 0; i < batch_size; ++i) {
        PacketHeader* new_header = create_packet_header(packet_batch[i].timestamp,
                                                       packet_batch[i].protocol_type,
                                                       packet_batch[i].payload,
                                                       packet_batch[i].payload_size);
        if (!new_header) {
            fprintf(stderr, "Failed to process packet at index %zu.\n", i);
            // Clean up previously allocated headers
            while (head) {
                PacketHeader* temp = head;
                head = head->next;
                free(temp->payload);
                free(temp);
            }
            return;
        }

        *tail = new_header;
        tail = &new_header->next;
    }

    // Process the linked list of packet headers
    while (head) {
        PacketHeader* temp = head;
        head = head->next;
        printf("Processing packet with timestamp: %ld, protocol type: %d\n", temp->timestamp, temp->protocol_type);
        free(temp->payload);
        free(temp);
    }
}

// Example usage
int main() {
    // Simulate packet batch processing
    PacketHeader packets[10000];
    for (size_t i = 0; i < 10000; ++i) {
        packets[i].timestamp = time(NULL);
        packets[i].protocol_type = rand() % 256;
        // Simulate payload content
        snprintf(packets[i].payload, MAX_PAYLOAD_SIZE, "Packet %zu", i);
        packets[i].payload_size = strlen(packets[i].payload);
    }

    process_packet_batch(packets, 10000);

    return 0;
}
```

This code snippet demonstrates the creation of a `create_packet_header` function to allocate and initialize a new `PacketHeader` structure. The `process_packet_batch` function processes an array of packet headers, ensuring that each packet is validated against the maximum payload size and that total memory usage does not exceed 10% of available system memory. Error handling is implemented for scenarios where payload size exceeds the configured maximum or memory allocation fails. Memory allocations are properly managed, including cleanup when the function completes or encounters an error. The code also includes a main function to simulate packet batch processing.']

