#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 1000
#define MIN_MEMORY_THRESHOLD 1024 * 1024 // 1MB
#define MAX_MEMORY_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct {
    int length;
    char* data;
} Packet;

typedef struct {
    int rnti;
    int crcFlag;
    // Other metadata fields
} RX_UE_INFORMATION_TAG;

typedef struct {
    int rnti;
    // Other metadata fields
} RNTI;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    RNTI rnti;
    // Other metadata fields
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* manageConnections(Packet packets[], int packetCount, int* memoryThreshold) {
    static NFAPI_CRC_INDICATION_PDU_T connections[MAX_CONNECTIONS];
    static int currentIndex = 0;
    int totalMemoryUsed = 0;

    for (int i = 0; i < packetCount; i++) {
        if (totalMemoryUsed + packets[i].length > *memoryThreshold) {
            printf("Memory threshold exceeded. Adjusting threshold...\n");
            *memoryThreshold *= 2;
            if (*memoryThreshold > MAX_MEMORY_THRESHOLD) {
                *memoryThreshold = MAX_MEMORY_THRESHOLD;
                break;
            }
        }

        connections[currentIndex].rxUeInfoTag.rnti = rand() % 1000;
        connections[currentIndex].rnti.rnti = rand() % 1000;
        connections[currentIndex].rxUeInfoTag.crcFlag = rand() % 2;

        memcpy(connections[currentIndex].rxUeInfoTag.data, packets[i].data, packets[i].length);
        memcpy(connections[currentIndex].rnti.data, packets[i].data + packets[i].length, sizeof(RNTI));

        totalMemoryUsed += packets[i].length;
        currentIndex = (currentIndex + 1) % MAX_CONNECTIONS;
    }

    return connections;
}

int main() {
    srand(time(NULL));

    Packet packets[MAX_PACKETS];
    int packetCount = 500; // Example number of packets

    for (int i = 0; i < packetCount; i++) {
        packets[i].length = rand() % 1024 + 1;
        packets[i].data = (char*)malloc(packets[i].length);
        // Populate packet data
    }

    int memoryThreshold = MIN_MEMORY_THRESHOLD;

    NFAPI_CRC_INDICATION_PDU_T* connectionList = manageConnections(packets, packetCount, &memoryThreshold);

    for (int i = 0; i < MAX_CONNECTIONS && connectionList[i].rxUeInfoTag.rnti != -1; i++) {
        printf("Connection %d: RNTI=%d, CRCFlag=%d\n", i, connectionList[i].rnti, connectionList[i].rxUeInfoTag.crcFlag);
    }

    for (int i = 0; i < packetCount; i++) {
        free(packets[i].data);
    }

    return 0;
}
