from subprocess import run, CalledProcessError

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def read_config(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

def generate_crc_indication_pdu():
    pdu = {
        "RX_UE_INFORMATION_TAG": random.randint(0, 2**32 - 1),
        "RNTI": random.randint(0, 2**16 - 1),
        "CRC_INDICATION_REL8_TAG": {"CRCFLAG": random.choice([True, False])}
    }
    return pdu

def update_network_config(config):
    interfaces = config['network_interfaces']
    for interface in interfaces:
        if os.path.exists(interface['config_file']):
            logging.info(f"Updating {interface['config_file']}")
            with open(interface['config_file'], 'w') as file:
                file.write(json.dumps(generate_crc_indication_pdu(), indent=4))
        else:
            logging.warning(f"{interface['config_file']} does not exist, skipping")

def execute_shell_command(command):
    try:
        result = run(command, check=True, capture_output=True, text=True)
        return result.stdout
    except CalledProcessError as e:
        logging.error(f"Command failed: {e}, output: {e.stderr}")
        return None

def main():
    config_file_path = 'network_config.json'
    config = read_config(config_file_path)
    update_network_config(config)
    # Example command execution
    execute_shell_command(['ifconfig', 'eth0', 'up'])

if __name__ == "__main__":
    main()
