typedef struct NetworkPacket {
    char* data;
    size_t length;
    time_t timestamp;
    struct NetworkPacket* next;
} NetworkPacket;

void process_packets(NetworkPacket** head, size_t* total_memory_used) {
    if (*head == NULL || *total_memory_used >= MEMORY_THRESHOLD) return;

    // Simulate reading a packet from the network
    NetworkPacket* new_packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (new_packet == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    new_packet->length = rand() % MAX_PACKET_SIZE + 1; // Random length between 1 and MAX_PACKET_SIZE
    new_packet->data = (char*)malloc(new_packet->length * sizeof(char));
    if (new_packet->data == NULL) {
        printf("Memory allocation failed for packet data.\n");
        free(new_packet);
        exit(1);
    }
    // Simulate filling the packet with data
    for (size_t i = 0; i < new_packet->length; ++i) {
        new_packet->data[i] = rand() % 256;
    }

    time(&new_packet->timestamp);

    new_packet->next = *head;
    *head = new_packet;

    *total_memory_used += new_packet->length;

    // Simulate processing the packet
    printf("Processing packet of size: %zu\n", new_packet->length);
}

int main() {
    NetworkPacket* head = NULL;
    size_t total_memory_used = 0;

    srand(time(NULL)); // Seed for random number generation

    while (1) {
        process_packets(&head, &total_memory_used);

        // Simulate processing metrics logging
        printf("Total memory used: %zu\n", total_memory_used);

        // Check if the memory usage exceeds the threshold
        if (total_memory_used >= MEMORY_THRESHOLD) {
            break;
        }

        // Simulate network activity
        sleep(1);
    }

    // Free allocated memory
    NetworkPacket* current = head;
    while (current != NULL) {
        NetworkPacket* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }

    return 0;
}
