typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    size_t capacity;
    size_t max_memory;
    pthread_mutex_t lock;
} NFAPICRCList;

bool nfapi_crc_list_init(NFAPICRCList *list, size_t initial_capacity, size_t max_memory) {
    if (initial_capacity < MINIMUM_NFAPIS || initial_capacity > MAX_NFAPIS ||
        max_memory == 0) {
        return false;
    }

    list->items = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        return false;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    list->max_memory = max_memory;
    pthread_mutex_init(&list->lock, NULL);
    return true;
}

bool nfapi_crc_list_add(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        if (nfapi_crc_list_resize(list, list->capacity * 2)) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    size_t required_memory = (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > list->max_memory) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->items[list->count++] = item;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool nfapi_crc_list_resize(NFAPICRCList *list, size_t new_capacity) {
    if (new_capacity < MINIMUM_NFAPIS || new_capacity > MAX_NFAPIS ||
        new_capacity <= list->capacity) {
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_items) {
        return false;
    }

    list->items = new_items;
    list->capacity = new_capacity;
    return true;
}

NFAPI_CRC_INDICATION_PDU_T nfapi_crc_list_get(const NFAPICRCList *list, size_t index) {
    if (index >= list->count) {
        NFAPI_CRC_INDICATION_PDU_T zeroed_item = {0};
        return zeroed_item;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T item = list->items[index];
    pthread_mutex_unlock(&list->lock);
    return item;
}

void nfapi_crc_list_free(NFAPICRCList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->items);
}
