['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct Packet {
    uint32_t length;
    char* payload;
} Packet;

typedef struct BufferNode {
    Packet packet;
    struct BufferNode* next;
} BufferNode;

typedef struct BufferPool {
    BufferNode* head;
    BufferNode* tail;
    size_t poolSize;
    size_t allocatedSize;
    pthread_mutex_t lock;
    pthread_cond_t full;
    pthread_cond_t notFull;
} BufferPool;

BufferPool* createBufferPool(size_t initialSize) {
    BufferPool* pool = (BufferPool*)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pool->head = pool->tail = NULL;
    pool->poolSize = 0;
    pool->allocatedSize = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->full, NULL);
    pthread_cond_init(&pool->notFull, NULL);

    for (size_t i = 0; i < initialSize; ++i) {
        BufferNode* node = (BufferNode*)malloc(sizeof(BufferNode));
        if (!node) {
            destroyBufferPool(pool);
            return NULL;
        }
        node->packet.length = 0;
        node->packet.payload = NULL;
        node->next = NULL;
        pool->tail = pool->tail ? pool->tail->next : pool->head = node;
    }

    pool->poolSize = initialSize;
    return pool;
}

void destroyBufferPool(BufferPool* pool) {
    BufferNode* current = pool->head;
    while (current) {
        BufferNode* next = current->next;
        free(current->packet.payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->full);
    pthread_cond_destroy(&pool->notFull);
    free(pool);
}

int addPacketToPool(BufferPool* pool, Packet packet) {
    pthread_mutex_lock(&pool->lock);
    while (pool->allocatedSize == pool->poolSize) {
        pthread_cond_wait(&pool->notFull, &pool->lock);
    }

    BufferNode* node = pool->tail;
    if (!node) {
        node = (BufferNode*)malloc(sizeof(BufferNode));
        if (!node) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Allocation failed
        }
        node->next = NULL;
        pool->head = pool->tail = node;
    } else {
        pool->tail = node->next = (BufferNode*)malloc(sizeof(BufferNode));
        if (!pool->tail) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Allocation failed
        }
        pool->tail->next = NULL;
    }

    node->packet = packet;
    pool->allocatedSize++;
    pthread_cond_signal(&pool->full);
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

Packet* getPacketFromPool(BufferPool* pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->allocatedSize == 0) {
        pthread_cond_wait(&pool->notFull, &pool->lock);
    }

    BufferNode* node = pool->head;
    Packet* packet = &node->packet;
    pool->head = node->next;
    if (!pool->head) {
        pool->tail = NULL;
    }
    free(node);
    pool->allocatedSize--;
    pthread_cond_signal(&pool->notFull);
    pthread_mutex_unlock(&pool->lock);
    return packet;
}
