    // Check if reallocation is needed
    if (processor->count >= processor->capacity) {
        size_t newCapacity = processor->capacity > 0 ? processor->capacity * 2 : 16;
        ImageMetadata* newMetadata = realloc(processor->metadata, newCapacity * sizeof(ImageMetadata));

        if (!newMetadata) {
            log_error("Failed to reallocate memory for image metadata.");
            pthread_mutex_unlock(&processor->lock);
            return -1;
        }

        processor->metadata = newMetadata;
        processor->capacity = newCapacity;
    }

    // Add the new entry
    processor->metadata[processor->count].filePath = strdup(filePath);
    processor->metadata[processor->count].sizeKB = sizeKB;
    processor->count++;

    pthread_mutex_unlock(&processor->lock);
