typedef struct {
    uint8_t *ip_address;
} DNS_RESULT_T;

DNS_RESULT_T* resolve_dns(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    DNS_RESULT_T *result = (DNS_RESULT_T *)malloc(sizeof(DNS_RESULT_T));
    if (!result) {
        perror("Failed to allocate memory for DNS result");
        return NULL;
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        free(result);
        return NULL;
    }

    result->ip_address = (uint8_t *)malloc(INET6_ADDRSTRLEN);
    if (!result->ip_address) {
        perror("Failed to allocate memory for IP address");
        freeaddrinfo(res);
        free(result);
        return NULL;
    }

    p = res;
    void *addr;
    char *ipver;

    // get the pointer to the address itself,
    // different fields in IPv4 and IPv6:
    if (p->ai_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        addr = &(ipv4->sin_addr);
        ipver = "IPv4";
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
        addr = &(ipv6->sin6_addr);
        ipver = "IPv6";
    }

    // convert the IP to a string and print it:
    inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
    printf("%s: %s\n", ipver, ipstr);

    freeaddrinfo(res); // all done with this structure
    return result;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int N) {
    if (N <= 0 || N > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Invalid number of structures\n");
        return NULL;
    }

    pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory for NFAPI CRC Indication PDUs");
        return NULL;
    }

    // Initialize each structure with random values
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand();
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return pdu_list;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T *pdu_list, DNS_RESULT_T *dns_result) {
    if (pdu_list) {
        free(pdu_list);
    }
    if (dns_result && dns_result->ip_address) {
