#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define TOTAL_MEMORY_LIMIT (10 * 1024 * 1024) // 10 MB

typedef struct ImageMetadata {
    char file_path[256];
    int width;
    int height;
    int bit_depth;
    time_t creation_time;
    time_t last_modified_time;
} ImageMetadata;

ImageMetadata* metadata_collection[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_metadata(const char* file_path, int width, int height, int bit_depth) {
    pthread_mutex_lock(&mutex);
    if (entry_count >= MAX_ENTRIES) {
        fprintf(stderr, "Error: Maximum number of entries reached.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    ImageMetadata* new_entry = malloc(sizeof(ImageMetadata));
    if (!new_entry) {
        perror("Failed to allocate memory for metadata entry.");
        pthread_mutex_unlock(&mutex);
        return;
    }
    strcpy(new_entry->file_path, file_path);
    new_entry->width = width;
    new_entry->height = height;
    new_entry->bit_depth = bit_depth;
    time_t current_time = time(NULL);
    new_entry->creation_time = current_time;
    new_entry->last_modified_time = current_time;
    metadata_collection[entry_count++] = new_entry;
    pthread_mutex_unlock(&mutex);
}

void remove_metadata(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= entry_count) {
        fprintf(stderr, "Error: Invalid index for metadata removal.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    free(metadata_collection[index]);
    for (int i = index; i < entry_count - 1; i++) {
        metadata_collection[i] = metadata_collection[i + 1];
    }
    entry_count--;
    pthread_mutex_unlock(&mutex);
}

void print_metadata() {
    pthread_mutex_lock(&mutex);
    if (entry_count == 0) {
        printf("No metadata entries to display.\n");
    } else {
        for (int i = 0; i < entry_count; i++) {
            ImageMetadata* entry = metadata_collection[i];
            printf("File Path: %s\n", entry->file_path);
            printf("Width: %d\n", entry->width);
            printf("Height: %d\n", entry->height);
            printf("Bit Depth: %d\n", entry->bit_depth);
            printf("Creation Time: %s", ctime(&entry->creation_time));
            printf("Last Modified Time: %s", ctime(&entry->last_modified_time));
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* process_metadata(void* arg) {
    int index = *(int*)arg;
    // Simulate metadata processing
    sleep(1);
    remove_metadata(index);
    return NULL;
}

int main() {
    add_metadata("image1.jpg", 800, 600, 24);
    add_metadata("image2.jpg", 1920, 1080, 32);

    pthread_t threads[entry_count];
    for (int i = 0; i < entry_count; i++) {
        int* index = malloc(sizeof(int));
        *index = i;
        if (pthread_create(&threads[i], NULL, process_metadata, index) != 0) {
            perror("Failed to create thread.");
            free(index);
        }
    }

    for (int i = 0; i < entry_count; i++) {
        pthread_join(threads[i], NULL);
    }

    print_metadata();

    return 0;
}
