    if (numPackets <= 0) {
        *status = -1; // Invalid number of packets
        return NULL;
    }

    // Calculate total memory required
    size_t totalSize = numPackets * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((totalSize / sizeof(NFAPI_CRC_INDICATION_PDU_T)) != (uint64_t)numPackets) {
        *status = -2; // Integer overflow detected
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** linkedList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numPackets * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!linkedList) {
        *status = -3; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < numPackets; ++i) {
        linkedList[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!linkedList[i]) {
            *status = -3; // Memory allocation failed for individual element
            for (int j = 0; j < i; ++j) {
                free(linkedList[j]);
            }
            free(linkedList);
            return NULL;
        }
        linkedList[i]->RX_UE_INFORMATION_TAG = rand() % 256;
        linkedList[i]->RNTI = rand() % 65536;
        linkedList[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRCFLAG
    }

    *status = 0; // Success
    return linkedList;
}

