#include <stdlib.h>
#include <pthread.h>

#define MAX_NFAPIS 1000

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_NFAPIS];
    int pool_size;
    int used_count;
} NFAPI_POOL_T;

void nfa_pi_pool_init(NFAPI_POOL_T *pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->pool_size = 0;
    pool->used_count = 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_get(NFAPI_POOL_T *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->used_count < pool->pool_size) {
        pdu = pool->pool[pool->used_count];
        pool->used_count++;
    }
    pthread_mutex_unlock(&pool->lock);

    return pdu;
}

void nfa_pi_put(NFAPI_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count > 0) {
        pool->used_count--;
        pool->pool[pool->used_count] = pdu;
    }
    pthread_mutex_unlock(&pool->lock);
}

void nfa_pi_free_all(NFAPI_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->used_count; i++) {
        free(pool->pool[i]);
    }
    pool->used_count = 0;
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_POOL_T *create_nfa_pi_pool(int size) {
    NFAPI_POOL_T *pool = malloc(sizeof(NFAPI_POOL_T));
    nfa_pi_pool_init(pool);

    for (int i = 0; i < size && pool->used_count < MAX_NFAPIS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu) {
            nfa_pi_put(pool, pdu);
        }
    }

    return pool;
}

void destroy_nfa_pi_pool(NFAPI_POOL_T *pool) {
    nfa_pi_free_all(pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
