#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MIN_TASKS 10
#define MAX_TASKS 500

typedef struct ImageTask {
    int image_id;
    int width;
    int height;
} ImageTask;

typedef struct TaskList {
    ImageTask *tasks;
    int size;
    int capacity;
} TaskList;

void init_task_list(TaskList *list) {
    list->size = 0;
    list->capacity = MIN_TASKS;
    list->tasks = (ImageTask *)malloc(list->capacity * sizeof(ImageTask));
}

void free_task_list(TaskList *list) {
    free(list->tasks);
    list->tasks = NULL;
    list->size = 0;
    list->capacity = 0;
}

void add_task(TaskList *list, int image_id, int width, int height) {
    if (list->size >= list->capacity) {
        list->capacity = (list->capacity == 0) ? MIN_TASKS : list->capacity * 2;
        list->tasks = (ImageTask *)realloc(list->tasks, list->capacity * sizeof(ImageTask));
    }
    list->tasks[list->size].image_id = image_id;
    list->tasks[list->size].width = width;
    list->tasks[list->size].height = height;
    list->size++;
}

void remove_task(TaskList *list, int index) {
    if (index < 0 || index >= list->size) return;
    for (int i = index; i < list->size - 1; i++) {
        list->tasks[i] = list->tasks[i + 1];
    }
    list->size--;
}

void print_task_list(TaskList *list) {
    printf("Task List:\n");
    for (int i = 0; i < list->size; i++) {
        printf("Image ID: %d, Width: %d, Height: %d\n", list->tasks[i].image_id, list->tasks[i].width, list->tasks[i].height);
    }
}

int main() {
    TaskList task_list;
    init_task_list(&task_list);

    // Example usage
    add_task(&task_list, 1, 800, 600);
    add_task(&task_list, 2, 1920, 1080);
    print_task_list(&task_list);

    remove_task(&task_list, 0);
    print_task_list(&task_list);

    free_task_list(&task_list);
    return 0;
}
