typedef struct {
    // Define your NFAPI_CRC_INDICATION_PDU_T structure members here
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[MAX_ELEMENTS];
int pool_index = -1;

pthread_mutex_t lock;

void init_pool() {
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool[i]) {
            perror("Failed to allocate memory in pool");
            exit(EXIT_FAILURE);
        }
    }
}

void* get_from_pool() {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *element = NULL;
    if (pool_index >= 0) {
        element = pool[pool_index--];
    }
    pthread_mutex_unlock(&lock);
    return element;
}

void free_to_pool(void *element) {
    pthread_mutex_lock(&lock);
    if (pool_index < MAX_ELEMENTS - 1) {
        pool[++pool_index] = element;
    } else {
        free(element);
    }
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int N, int *created_count, int *error_count) {
    if (N > MAX_ELEMENTS || N < 0) {
        (*error_count)++;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        (*error_count)++;
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Populate each structure with random valid data
        result[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        result[i].RNTI = rand() % 65536;
        if (i >= N / 2) {
            free_to_pool(result + i);
            (*created_count)++;
        }
    }

    *created_count += N;
    return result;
}

void log_info(int created_count, int error_count) {
    // Integrate with an external logging system
    printf("Total structures created: %d\n", created_count);
    printf("Errors encountered: %d\n", error_count);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    srand(time(NULL));
    init_pool();

    int N = 500;
    int created_count = 0;
    int error_count = 0;

    NFAPI_CRC_INDICATION_PDU_T *data = allocate_and_populate(N, &created_count, &error_count);
    if (!data) {
        printf("Failed to allocate and populate data\n");
        return EXIT_FAILURE;
    }

    log_info(created_count, error_count);

    free(data);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
