        nfaapi_pdu_list[i].RNTI = rand() % 65536;
        nfaapi_pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        nfaapi_pdu_list[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return NULL;
}

void* run_task(void* arg) {
    parse_config_file("config.txt");

    pthread_t vendor_lib_thread;
    if (pthread_create(&vendor_lib_thread, NULL, load_vendor_library, NULL) != 0) {
        fprintf(stderr, "Error creating thread for loading vendor library\n");
        return NULL;
    }

    pthread_join(vendor_lib_thread, NULL);

    pthread_t generate_pdu_list_thread;
    if (pthread_create(&generate_pdu_list_thread, NULL, generate_nfaapi_pdu_list, NULL) != 0) {
        fprintf(stderr, "Error creating thread for generating PDU list\n");
        return NULL;
    }

    pthread_join(generate_pdu_list_thread, NULL);

    free(nfaapi_pdu_list);
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t task_thread;
    if (pthread_create(&task_thread, NULL, run_task, NULL) != 0) {
        fprintf(stderr, "Error creating thread for running task\n");
        return EXIT_FAILURE;
    }

    pthread_join(task_thread, NULL);

    printf("Task completed successfully\n");
    return EXIT_SUCCESS;
}
