typedef struct {
    ImageMetadata metadata;
    // Add additional image data members here
} ImageData;

ImageData *image_array[MAX_IMAGES];
int current_images = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_image(ImageMetadata *metadata) {
    // Initialize the image with valid metadata
}

void add_image(ImageMetadata *metadata) {
    pthread_mutex_lock(&mutex);
    while (current_images >= MAX_IMAGES) {
        pthread_mutex_unlock(&mutex);
        printf("Memory allocation failed. Retrying...\n");
        sleep(1); // Exponential backoff strategy
        pthread_mutex_lock(&mutex);
    }
    image_array[current_images] = malloc(sizeof(ImageData));
    if (image_array[current_images]) {
        initialize_image(&image_array[current_images]->metadata, metadata);
        current_images++;
    } else {
        printf("Failed to allocate memory for image. Exiting.\n");
        exit(1);
    }
    pthread_mutex_unlock(&mutex);
}

void free_images() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < current_images; i++) {
        free(image_array[i]);
    }
    current_images = 0;
    pthread_mutex_unlock(&mutex);
}
