#include <string.h>
#include <limits.h>

typedef struct Packet {
    int size;
    char *data;
} Packet;

void process_packets(int max_total_memory, va_list args) {
    size_t total_allocated = 0;
    int packet_count = 0;

    while (1) {
        int packet_size = va_arg(args, int);
        if (packet_size == -1) break; // End of arguments marker

        if (packet_size < 0 || packet_size > INT_MAX) {
            fprintf(stderr, "Invalid packet size: %d\n", packet_size);
            continue;
        }

        size_t required_memory = sizeof(Packet) + packet_size;
        if (required_memory <= SIZE_MAX - total_allocated) {
            Packet *new_packet = (Packet *)malloc(required_memory);
            if (new_packet == NULL) {
                fprintf(stderr, "Memory allocation failed for packet %d\n", packet_count);
                continue;
            }

            new_packet->size = packet_size;
            new_packet->data = (char *)(new_packet + 1);

            // Simulate processing of packet data
            memset(new_packet->data, 'A', packet_size);
            printf("Processed packet %d with size: %d\n", packet_count, packet_size);

            total_allocated += required_memory;
            packet_count++;
        } else {
            fprintf(stderr, "Memory limit exceeded for packet %d\n", packet_count);
            break;
        }
    }

    va_end(args);
}

int main() {
    // Example usage with variable arguments
    process_packets(1024 * 1024, 100, -1); // First packet of size 100 bytes
    process_packets(1024 * 1024, 200, -1); // Second packet of size 200 bytes
    process_packets(1024 * 1024, 500, -1); // Third packet that would exceed limit

    return 0;
}
