typedef struct {
    unsigned char r;
    unsigned char g;
    unsigned char b;
} PixelData;

PixelData** createImageData(int width, int height, int colorDepth) {
    if (width <= 0 || height <= 0 || colorDepth <= 0) {
        fprintf(stderr, "Invalid image dimensions or color depth\n");
        return NULL;
    }

    // Calculate the total number of pixels
    unsigned long long totalPixels = (unsigned long long)width * height;
    if ((totalPixels > UINT_MAX / sizeof(PixelData *)) || 
        (totalPixels > UINT_MAX / colorDepth)) {
        fprintf(stderr, "Memory allocation would exceed system limits\n");
        return NULL;
    }

    // Allocate memory for the array of pointers
    PixelData** image = (PixelData**)malloc(totalPixels * sizeof(PixelData *));
    if (!image) {
        perror("Failed to allocate memory for pixel data pointers");
        return NULL;
    }

    // Calculate total memory needed for the pixel data
    unsigned long long totalMemory = totalPixels * colorDepth * sizeof(unsigned char);
    PixelData* allPixels = (PixelData*)malloc(totalMemory);
    if (!allPixels) {
        perror("Failed to allocate memory for pixel data");
        free(image); // Free previously allocated pointers
        return NULL;
    }

    // Initialize the image array with pointers to pixel data
    for (int i = 0; i < totalPixels; ++i) {
        image[i] = &allPixels[i * colorDepth];
    }

    return image;
}

void freeImageData(PixelData** image, int width, int height, int colorDepth) {
    if (image) {
        // No need to manually free each pixel data entry since it's part of the allPixels array
        free(image);
    }
}
