#define MAX_STRUCTURES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

extern void log_message(int level, const char* message);

void* generate_crc_indication_pdu_list(int num_rntis, ...) {
    if (num_rntis > MAX_STRUCTURES) {
        log_message(LOG_ERROR, "Too many RNTI values requested");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** pdu_list = malloc(num_rntis * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        log_message(LOG_ERROR, "Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    va_list args;
    va_start(args, num_rntis);

    int* rnti_set = malloc(num_rntis * sizeof(int));
    if (!rnti_set) {
        log_message(LOG_ERROR, "Memory allocation failed");
        free(pdu_list);
        return NULL;
    }

    for (int i = 0; i < num_rntis; i++) {
        int rnti = va_arg(args, int);
        if (i > 0 && rnti == rnti_set[i - 1]) {
            log_message(LOG_WARNING, "Duplicate RNTI value detected");
            free(rnti_set);
            free(pdu_list);
            return NULL;
        }
        rnti_set[i] = rnti;

        pdu_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list[i]) {
            log_message(LOG_ERROR, "Memory allocation failed");
            for (int j = 0; j < i; j++) {
                free(pdu_list[j]);
            }
            free(rnti_set);
            free(pdu_list);
            return NULL;
        }

        pthread_mutex_lock(&mutex);
        pdu_list[i]->RX_UE_INFORMATION_TAG = rand() % 1000; // Example assignment
        pdu_list[i]->RNTI = rnti;
        pdu_list[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
        log_message(LOG_DEBUG, "Created NFAPI_CRC_INDICATION_PDU_T with RNTI: %d", rnti);
        pthread_mutex_unlock(&mutex);
    }

    va_end(args);
    free(rnti_set);

    return pdu_list;
}
