typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CrcIndicationList;

CrcIndicationList* create_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    CrcIndicationList *list = malloc(sizeof(CrcIndicationList));
    if (!list) return NULL;

    list->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_list(CrcIndicationList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    free(list->elements);
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_element(CrcIndicationList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? 2 * list->capacity : 4;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->elements[list->size].RNTI = RNTI;
    list->elements[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->elements[list->size].CRCFLAG = CRCFLAG;
    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

size_t get_list_size(CrcIndicationList *list) {
    if (!list) return 0;

    pthread_mutex_lock(&list->mutex);
    size_t size = list->size;
    pthread_mutex_unlock(&list->mutex);

    return size;
}
