void destroy_list(ResizableList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(ResizableList *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Initialize new structure fields here

    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void remove_from_list(ResizableList *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size > 0) {
        // Clean up and reuse memory here
        list->size--;
    }

    pthread_mutex_unlock(&list->mutex);
