NFAPI_CRC_INDICATION_PDU_T* traverseAndCollect(TreeNode* root, const char* selector, size_t* count) {
    if (root == NULL || selector == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    *count = 0;

    if (isMatch(root, selector)) {
        // Allocate memory for the new structure
        result = realloc(result, (*count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (result == NULL) return NULL; // Handle memory allocation failure

        result[*count].rxUeInfoTag = getRX_UE_INFORMATION_TAG();
        result[*count].rnti = getRNTI();
        result[*count].crcFlag = getRandomCRCFLAG();
        (*count)++;
    }

    for (int i = 0; i < root->childCount; i++) {
        size_t childCount;
        NFAPI_CRC_INDICATION_PDU_T* childResult = traverseAndCollect(root->children[i], selector, &childCount);
        if (childResult != NULL) {
            // Reallocate memory for the combined result
            result = realloc(result, (*count + childCount) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (result == NULL) return NULL; // Handle memory allocation failure

            memcpy(result + *count, childResult, childCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *count += childCount;
        }
    }

    return result;
}
