typedef struct FileProcessingContext {
    int file_count;
    pthread_mutex_t mutex;
} FileProcessingContext;

int process_image_files(FileProcessingContext* context, const char* file_paths[], int num_files) {
    // Initialize the mutex
    pthread_mutex_init(&context->mutex, NULL);

    // Calculate the total number of layers across all files
    size_t total_layers = 0;
    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            perror("Failed to open file");
            return -1;
        }

        // Assume a simple format where the first 4 bytes are the number of layers
        size_t layers_in_file;
        fread(&layers_in_file, sizeof(size_t), 1, file);
        fclose(file);

        if (layers_in_file > SIZE_MAX - total_layers) {
            fprintf(stderr, "Potential integer overflow detected\n");
            return -1;
        }

        total_layers += layers_in_file;
    }

    // Dynamically allocate memory for the ImageLayer structures
    ImageLayer* layers = malloc(total_layers * sizeof(ImageLayer));
    if (!layers) {
        perror("Failed to allocate memory for ImageLayer structures");
        return -1;
    }

    // Process each file and populate the ImageLayer structures
    size_t layer_index = 0;
    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            perror("Failed to open file");
            free(layers);
            return -1;
        }

        // Assume the format described above
        size_t layers_in_file;
        fread(&layers_in_file, sizeof(size_t), 1, file);

        for (size_t j = 0; j < layers_in_file; ++j) {
            ImageLayer* layer = &layers[layer_index++];
            layer->id = j + 1;
            layer->data_size = read_layer_data_size(file);
            size_t name_length = read_name_length(file);
            if (name_length > INT_MAX) {
                fprintf(stderr, "File name too long\n");
                free(layers);
                fclose(file);
                return -1;
            }
            layer->origin_file_name = malloc((name_length + 1) * sizeof(char));
            if (!layer->origin_file_name) {
                perror("Failed to allocate memory for file name");
                free(layers);
                fclose(file);
                return -1;
            }
            fread(layer->origin_file_name, sizeof(char), name_length, file);
            layer->origin_file_name[name_length] = '\0';
        }

        fclose(file);
    }

    // Assign the layers to the context (safely)
    pthread_mutex_lock(&context->mutex);
    context->layers = layers;
    context->layer_count = total_layers;
    pthread_mutex_unlock(&context->mutex);

    return 0;
}

