#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_STRUCTURES 1024

typedef struct {
    // Define the fields of NFAPI_CRC_INDICATION_PDU_T here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    size_t allocated_count;
    size_t used_count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_POOL_T;

void nfapi_crc_indication_pool_init(NFAPI_CRC_INDICATION_POOL_T *pool) {
    pool->structures = NULL;
    pool->allocated_count = 0;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

int nfapi_crc_indication_pool_allocate(NFAPI_CRC_INDICATION_POOL_T *pool, size_t requested_count) {
    pthread_mutex_lock(&pool->lock);

    if (requested_count > MAX_STRUCTURES - pool->used_count) {
        fprintf(stderr, "Error: Requested more structures than available capacity.\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    size_t new_allocated_count = pool->allocated_count + requested_count;
    if (new_allocated_count < pool->allocated_count || // Check for integer overflow
        new_allocated_count > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Integer overflow in allocation.\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(pool->structures, new_allocated_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_structures == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->structures = new_structures;
    pool->allocated_count = new_allocated_count;
    pool->used_count += requested_count;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void nfapi_crc_indication_pool_free(NFAPI_CRC_INDICATION_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->structures);
    pool->structures = NULL;
    pool->allocated_count = 0;
    pool->used_count = 0;
    pthread_mutex_unlock(&pool->lock);
}
