    if (max_frame_length > 0 && padding_factor > 0.0f) {
        size_t padded_frame_length = max_frame_length * padding_factor;
        if (padded_frame_length < max_frame_length) {
            fprintf(stderr, "Error: Padding factor results in zero or negative frame length.\n");
            return NULL;
        }
        total_buffer_size = num_frames * padded_frame_length;
    } else {
        fprintf(stderr, "Error: Invalid maximum frame length or padding factor.\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    frames = (NFAPI_RX_FRAME_T*)malloc(num_frames * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        perror("Failed to allocate memory for frames.");
        return NULL;
    }

    // Allocate buffer memory for each frame
    for (int i = 0; i < num_frames; ++i) {
        frames[i].frame_buffer = (unsigned char*)malloc(total_buffer_size);
        if (!frames[i].frame_buffer) {
            perror("Failed to allocate memory for frame buffer.");
            free_frames(frames, i); // Free previously allocated buffers
            return NULL;
        }
    }

    return frames;
}

void free_frames(NFAPI_RX_FRAME_T* frames, int num_allocated_frames) {
    if (frames) {
        for (int i = 0; i < num_allocated_frames; ++i) {
            free(frames[i].frame_buffer);
        }
        free(frames);
    }
}

// Example usage
int main() {
    int num_frames = 10;
    int max_frame_length = 1500;
    float padding_factor = 1.2f;
    int expected_throughput = 1000;

    NFAPI_RX_FRAME_T* frames = allocate_frames(num_frames, max_frame_length, padding_factor, expected_throughput);
    if (frames) {
        // Process the frames
        free_frames(frames, num_frames); // Free allocated memory when done
    }

    return 0;
}
```

This code snippet defines a function `allocate_frames` that dynamically allocates memory for an array of `NFAPI_RX_FRAME_T` structures based on the number of received frames and the maximum frame length. It includes error handling for potential discrepancies between expected and actual throughput, as well as system dependencies such as latency in accessing external data sources for frame headers. The function also provides a mechanism to free allocated memory when it is no longer needed.']

