typedef struct ImageFrame {
    int width;
    int height;
    int bitsPerPixel;
    unsigned char* data;
} ImageFrame;

typedef struct FrameMetadata {
    char filename[256];
    int frameCount;
} FrameMetadata;

void* processFrame(void* arg) {
    // Process individual frame logic here
    return NULL;
}

int calculateTotalSize(FrameMetadata* metadata, int numFiles) {
    long long totalSize = 0;
    for (int i = 0; i < numFiles; ++i) {
        totalSize += metadata[i].frameCount * sizeof(ImageFrame);
        if (totalSize > INT_MAX) {
            fprintf(stderr, "Integer overflow detected in total size calculation.\n");
            return -1;
        }
    }
    return (int)totalSize;
}

void* processImageFiles(void* arg) {
    FrameMetadata* metadata = (FrameMetadata*)arg;
    int numFiles = metadata[0].frameCount;

    if (numFiles <= 0) {
        fprintf(stderr, "No files to process.\n");
        return NULL;
    }

    int totalSize = calculateTotalSize(metadata + 1, numFiles);
    if (totalSize < 0) {
        return NULL;
    }

    ImageFrame* frames = (ImageFrame*)malloc(totalSize * sizeof(ImageFrame));
    if (frames == NULL) {
        perror("Failed to allocate memory for image frames");
        return NULL;
    }

    pthread_t threads[numFiles];
    int threadID = 0;

    for (int i = 1; i <= numFiles; ++i) {
        FrameMetadata currentFile = metadata[i];
        for (int j = 0; j < currentFile.frameCount; ++j) {
            // Simulate frame processing
            frames[threadID].width = currentFile.width;
            frames[threadID].height = currentFile.height;
            frames[threadID].bitsPerPixel = currentFile.bitsPerPixel;
            frames[threadID].data = (unsigned char*)malloc(currentFile.width * currentFile.height * currentFile.bitsPerPixel / 8);
            if (frames[threadID].data == NULL) {
                perror("Failed to allocate memory for frame data");
                free(frames);
                return NULL;
            }
            // Initialize frame data
            memset(frames[threadID].data, 0, currentFile.width * currentFile.height * currentFile.bitsPerPixel / 8);

            if (pthread_create(&threads[threadID], NULL, processFrame, &frames[threadID]) != 0) {
                perror("Failed to create thread");
                free(frames);
                return NULL;
            }

            threadID++;
        }
    }

    for (int i = 0; i < threadID; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory for frames and their data
    for (int i = 0; i < threadID; ++i) {
        free(frames[i].data);
    }
    free(frames);

    return NULL;
}

int main() {
    FrameMetadata metadata[] = {
        { "file1.dat", 5 },
        { "frame1.png", 320, 240, 24 },
        { "frame2.png", 640, 480, 32 },
        // Add more file metadata as needed
    };

    int numFiles = sizeof(metadata) / sizeof(metadata[0]) - 1;

    processImageFiles(metadata);

    return 0;
}
