NFAPI_CRC_INDICATION_PDU_T* create_node(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (RX_UE_INFORMATION_TAG > UINT32_MAX || RNTI > UINT16_MAX) {
        fprintf(stderr, "Error: Tag sizes exceed maximum limits.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    new_node->next = NULL;
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 256; // Randomly set CRCFLAG

    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T **head, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI);
    if (new_node == NULL) {
        return;
    }

    new_node->next = *head;
    *head = new_node;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **head) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;

    // Example usage
    for (int i = 0; i < 5; i++) {
        add_to_list(&head, i * 1000, i * 10);
    }

    free_list(&head);

    return 0;
}
