    while (1) {
        long long frame_size;
        if (fread(&frame_size, sizeof(long long), 1, file) != 1) {
            break; // End of file or error
        }

        if (frame_size < MIN_FRAME_SIZE || frame_size > MAX_FRAME_SIZE) {
            fprintf(stderr, "Invalid frame size in file %d\n", file_index);
            fclose(file);
            return NULL;
        }

        meta.frame_count++;
        meta.total_size += frame_size;
    }

    pthread_mutex_lock(&metadata_lock);
    if (meta.total_size > available_memory) {
        fprintf(stderr, "Not enough memory to store frames in file %d\n", file_index);
