#define MAX_PDUS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateRxtxIndications(NFAPI_CRC_INDICATION_PDU_T *pduPool, int maxPduCount) {
    static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
    static int poolSize = 0;
    static int allocated = 0;

    if (maxPduCount > MAX_PDUS || maxPduCount <= 0) {
        printf("Invalid maxPduCount: %d\n", maxPduCount);
        return;
    }

    for (int i = 0; i < maxPduCount; ++i) {
        if (allocated == poolSize) {
            int newSize = (poolSize == 0) ? 1 : poolSize * 2;
            if (newSize > MAX_PDUS) {
                printf("Max pool size reached\n");
                break;
            }
            NFAPI_CRC_INDICATION_PDU_T *newPool = realloc(pool, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newPool) {
                printf("Memory allocation failed\n");
                return;
            }
            pool = newPool;
            poolSize = newSize;
        }

        int index = allocated++;
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[index];
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = (rand() % 2) ? 1 : 0;

        printf("Created/Reused structure at index: %d\n", index);
    }
}
```

