#include <string.h>
#include <limits.h>

#define MAX_PACKET_SIZE 1500
#define SYSTEM_MEMORY_LIMIT (1024 * 1024 * 1024) // 1GB

typedef struct {
    uint16_t header_size;
    uint32_t payload_size;
    char data[0];
} PacketHeader;

int validate_packet_header(PacketHeader* packet, size_t max_payload_size) {
    if (packet->header_size < sizeof(PacketHeader) || packet->header_size > MAX_PACKET_SIZE ||
        packet->payload_size > max_payload_size || packet->payload_size == 0) {
        return -1; // Invalid packet header
    }
    return 0;
}

void* allocate_payload_memory(size_t payload_size, size_t* allocated_size, size_t system_memory_limit) {
    if (payload_size > system_memory_limit) {
        printf("Error: Payload size exceeds system memory limit.\n");
        return NULL;
    }

    // Allocate memory with a small padding to handle minor variations
    *allocated_size = payload_size + 1024; // Assuming 1KB padding
    void* memory = malloc(*allocated_size);
    if (memory == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }
    return memory;
}

void process_packets(PacketHeader* packets, size_t num_packets, size_t max_payload_size, size_t system_memory_limit) {
    for (size_t i = 0; i < num_packets; ++i) {
        if (validate_packet_header(&packets[i], max_payload_size) != 0) {
            printf("Invalid packet header at index %zu.\n", i);
            continue;
        }

        size_t allocated_size;
        void* payload_memory = allocate_payload_memory(packets[i].payload_size, &allocated_size, system_memory_limit);
        if (payload_memory == NULL) {
            // Handle allocation failure gracefully
            printf("Failed to allocate memory for packet %zu.\n", i);
            continue;
        }

        // Process the payload data here
        memcpy(payload_memory, packets[i].data, packets[i].payload_size);

        // Free allocated memory after use
        free(payload_memory);
    }
}

int main() {
    // Example usage
    PacketHeader packets[] = {
        {sizeof(PacketHeader) + 1000, 1000},
        {sizeof(PacketHeader) + 2000, 2000}
    };
    size_t num_packets = sizeof(packets) / sizeof(packets[0]);
    size_t max_payload_size = 5000;
    size_t system_memory_limit = SYSTEM_MEMORY_LIMIT;

    process_packets(packets, num_packets, max_payload_size, system_memory_limit);

    return 0;
}
