#define MAX_IMAGE_SIZE (1024 * 1024 * 10) // 10 MB

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    uint32_t width;
    uint32_t height;
    uint8_t* pixel_data;
} image_data;

image_data** process_image_directory(const char* directory_path, int* num_images) {
    DIR *dir;
    struct dirent *entry;
    image_data **images = NULL;
    int count = 0;

    if ((dir = opendir(directory_path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strlen(entry->d_name) < MAX_FILENAME_LENGTH) {
                images = realloc(images, (count + 1) * sizeof(image_data*));
                if (!images) {
                    fprintf(stderr, "Memory allocation failed.\n");
                    closedir(dir);
                    return NULL;
                }

                images[count] = malloc(sizeof(image_data));
                if (!images[count]) {
                    fprintf(stderr, "Memory allocation failed for image %s.\n", entry->d_name);
                    count--;
                    continue;
                }

                strcpy(images[count]->filename, entry->d_name);

                // Simulate reading metadata
                uint32_t width = rand() % 10000 + 1; // Example: random width between 1 and 10000
                uint32_t height = rand() % 10000 + 1; // Example: random height between 1 and 10000

                if (width > UINT32_MAX / height || width * height > MAX_IMAGE_SIZE) {
                    fprintf(stderr, "Invalid image dimensions for %s.\n", entry->d_name);
                    free(images[count]);
                    count--;
                    continue;
                }

                size_t pixel_data_size = width * height;
                images[count]->pixel_data = malloc(pixel_data_size);
                if (!images[count]->pixel_data) {
                    fprintf(stderr, "Memory allocation failed for pixel data of %s.\n", entry->d_name);
                    free(images[count]);
                    count--;
                    continue;
                }

                images[count]->width = width;
                images[count]->height = height;

                // Simulate reading pixel data
                memset(images[count]->pixel_data, 0, pixel_data_size);

                count++;
            }
        }
        closedir(dir);
    } else {
        perror("Failed to open directory");
        return NULL;
    }

    *num_images = count;
    return images;
}
