int dns_resolution(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        memcpy(ip_address, ipstr, INET6_ADDRSTRLEN);

        freeaddrinfo(res); // Free the linked list
        return 0; // Success
    }

    freeaddrinfo(res); // Free the linked list if no addresses were found
    return -1; // No valid addresses
}

void free_indication_pdu_list(NFAPI_DATA_INDICATION_LIST_T *indication_list) {
    for (size_t i = 0; i < indication_list->indication_pdu_count; ++i) {
        free(indication_list->indication_pdu_list[i]->crc_indication_rel8_tag);
        free(indication_list->indication_pdu_list[i]);
    }
    free(indication_list->indication_pdu_list);
    free(indication_list);
}
