    uint32_t src_ip;
    uint32_t dst_ip;
} PacketHeader;

typedef struct {
    PacketHeader *headers;
    size_t allocated_size;
    size_t used_count;
} BufferPool;

BufferPool *buffer_pool_init(size_t initial_size) {
    BufferPool *pool = (BufferPool *)malloc(sizeof(BufferPool));
    pool->headers = (PacketHeader *)calloc(initial_size, sizeof(PacketHeader));
    pool->allocated_size = initial_size;
    pool->used_count = 0;
    return pool;
}

void buffer_pool_free(BufferPool *pool) {
    free(pool->headers);
    free(pool);
}

PacketHeader *buffer_pool_get_header(BufferPool *pool) {
    if (pool->used_count == pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        PacketHeader *new_headers = (PacketHeader *)realloc(pool->headers, new_size * sizeof(PacketHeader));
        if (!new_headers) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        pool->headers = new_headers;
        pool->allocated_size = new_size;
    }
    return &pool->headers[pool->used_count++];
}

void process_packets(const uint8_t *raw_data, size_t data_length) {
    BufferPool *pool = buffer_pool_init(MIN_BUFFER_POOL_SIZE);
    if (!pool) {
        fprintf(stderr, "Failed to initialize buffer pool\n");
        return;
    }

    for (size_t i = 0; i < data_length; i += MAX_PACKET_SIZE) {
        PacketHeader *header = buffer_pool_get_header(pool);
        if (!header) {
            continue;
        }

        // Parse packet data and populate header
        // Example: header->length = parse_packet_length(raw_data + i);
        // Example: header->protocol_type = parse_protocol_type(raw_data + i);
        // Example: header->src_ip = parse_source_ip(raw_data + i);
        // Example: header->dst_ip = parse_destination_ip(raw_data + i);

        if (header->length > MAX_PACKET_SIZE) {
            fprintf(stderr, "Packet length exceeds maximum allowed size\n");
            continue;
        }
    }

    buffer_pool_free(pool);
}

int main() {
    // Simulate receiving raw packet data
    uint8_t raw_data[] = { /* ... */ };
    process_packets(raw_data, sizeof(raw_data));
    return 0;
}
