int process_image_metadata(ImageMetadata **metadata_array, int max_memory, const ImageMetadata *entry) {
    static size_t current_memory = 0;
    size_t new_memory = calculate_entry_size(entry->width, entry->height, entry->format);

    if (current_memory + new_memory > max_memory) {
        log_error("Memory limit exceeded");
        return -1;
    }

    ImageMetadata *new_entry = realloc(*metadata_array, current_memory + new_memory);
    if (!new_entry) {
        log_error("Failed to allocate memory");
        return -1;
    }

    *metadata_array = new_entry;
    memcpy(&(*metadata_array)[current_memory / sizeof(ImageMetadata)], entry, new_memory);
    current_memory += new_memory;

    printf("Processed metadata for file: %s\n", entry->location);

    return 0;
}

int main() {
    ImageMetadata metadata[MAX_ENTRIES];
    int max_memory = 1024 * 1024; // 1MB
