typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_size) {
    if (initial_size == 0) {
        fprintf(stderr, "Initial size must be greater than zero.\n");
        return NULL;
    }

    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) {
        perror("Failed to allocate memory for DynamicArray.");
        return NULL;
    }

    da->array = realloc(NULL, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        perror("Failed to allocate memory for array.");
        return NULL;
    }

    da->capacity = initial_size;
    da->size = 0;

    return da;
}

int resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    if (new_capacity < da->size) {
        fprintf(stderr, "New capacity must be greater than or equal to current size.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to allocate memory for resized array.");
        return -1;
    }

    da->array = new_array;
    da->capacity = new_capacity;

    return 0;
}

int add_element_to_dynamic_array(DynamicArray *da, int RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRC_INDICATION_REL8_TAG) {
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * GROWTH_FACTOR;
        if (resize_dynamic_array(da, new_capacity) != 0) {
