#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t N_max;
    uint64_t M_bytes;
    uint32_t min_mem_per_struct;
    float max_overhead_pct;
} ConfigManagerSettings;

typedef struct {
    void* pool_start;
    size_t pool_size;
    size_t used_memory;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0};

void* allocate_from_pool(size_t size) {
    if (memory_pool.pool_start == NULL) {
        // Initialize the memory pool
        memory_pool.pool_size = size * 2; // Allocate twice the requested size for buffer
        memory_pool.pool_start = malloc(memory_pool.pool_size);
        if (memory_pool.pool_start == NULL) {
            return NULL;
        }
    }

    if ((memory_pool.used_memory + size) > memory_pool.pool_size) {
        return NULL; // Not enough space in the pool
    }

    void* allocated_memory = (char*)memory_pool.pool_start + memory_pool.used_memory;
    memory_pool.used_memory += size;
    return allocated_memory;
}

void free_to_pool(void* ptr, size_t size) {
    if (ptr == NULL || size == 0) {
        return;
    }

    // Simple linear search to find the block in the pool
    char* start = (char*)memory_pool.pool_start;
    char* end = (char*)memory_pool.pool_start + memory_pool.used_memory;

    while (start < end && (char*)ptr != start) {
        start += size; // Move to the next block
    }

    if ((char*)ptr == start) {
        memory_pool.used_memory -= size;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_structs(ConfigManagerSettings settings, uint32_t N_requested) {
    if (settings.N_max < N_requested || settings.M_bytes < 1 || settings.min_mem_per_struct < 1 || settings.max_overhead_pct < 0.0f || settings.max_overhead_pct > 1.0f) {
        // Invalid input values
        return NULL;
    }

    uint64_t total_size = (uint64_t)N_requested * settings.min_mem_per_struct;
    float overhead = total_size * settings.max_overhead_pct / 100.0f;

    if ((total_size + overhead) > settings.M_bytes) {
        // Not enough memory
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(N_requested * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structs == NULL) {
        return NULL; // Memory allocation failed
    }

    memset(structs, 0, N_requested * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Initialize structures

    // Log memory usage and allocation details
    printf("Allocated %zu bytes for %u structures\n", N_requested * sizeof(NFAPI_CRC_INDICATION_PDU_T), N_requested);

    return structs;
}

void free_nfaapi_structs(NFAPI_CRC_INDICATION_PDU_T* structs, uint32_t N) {
    if (structs == NULL || N == 0) {
        return;
    }

    free_to_pool(structs, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Log memory deallocation details
    printf("Deallocated %zu bytes for %u structures\n", N * sizeof(NFAPI_CRC_INDICATION_PDU_T), N);
}
```

