#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IMAGES 1000
#define MEMORY_THRESHOLD 512 * 1024 * 1024 // 512MB

typedef struct {
    char* file_path;
    size_t expected_size;
    int id;
} IMAGE_METADATA;

typedef struct {
    IMAGE_METADATA** images;
    size_t count;
    size_t allocated_count;
    pthread_mutex_t mutex;
} IMAGE_BUFFER;

int allocate_image_buffer(IMAGE_BUFFER* buffer, size_t initial_capacity) {
    if (initial_capacity > MAX_IMAGES) {
        return -1; // Insufficient resource allocation
    }

    buffer->images = (IMAGE_METADATA**)malloc(initial_capacity * sizeof(IMAGE_METADATA*));
    if (!buffer->images) {
        return -2; // Memory allocation failed
    }

    buffer->count = 0;
    buffer->allocated_count = initial_capacity;
    pthread_mutex_init(&buffer->mutex, NULL);
    return 0;
}

void free_image_buffer(IMAGE_BUFFER* buffer) {
    for (size_t i = 0; i < buffer->count; ++i) {
        free(buffer->images[i]->file_path);
        free(buffer->images[i]);
    }
    free(buffer->images);
    pthread_mutex_destroy(&buffer->mutex);
}

int add_image_to_buffer(IMAGE_BUFFER* buffer, IMAGE_METADATA* metadata) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->count == buffer->allocated_count) {
        size_t new_capacity = buffer->allocated_count * 2;
        IMAGE_METADATA** new_images = realloc(buffer->images, new_capacity * sizeof(IMAGE_METADATA*));
        if (!new_images) {
            pthread_mutex_unlock(&buffer->mutex);
            return -2; // Memory allocation failed
        }
        buffer->images = new_images;
        buffer->allocated_count = new_capacity;
    }

    buffer->images[buffer->count] = metadata;
    ++buffer->count;

    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int load_image_data(IMAGE_BUFFER* buffer, IMAGE_METADATA** metadata_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        IMAGE_METADATA* metadata = metadata_array[i];
        FILE* file = fopen(metadata->file_path, "rb");
        if (!file) {
            continue; // Ignore files that cannot be opened
        }

        fseek(file, 0, SEEK_END);
        size_t file_size = ftell(file);
        fclose(file);

        if (file_size > MEMORY_THRESHOLD) {
            printf("Image %d exceeds memory threshold. Truncating data.\n", metadata->id);
            file_size = MEMORY_THRESHOLD;
        }

        IMAGE_METADATA* new_metadata = (IMAGE_METADATA*)malloc(sizeof(IMAGE_METADATA));
        if (!new_metadata) {
            continue; // Ignore images that cannot be allocated
        }
        new_metadata->file_path = strdup(metadata->file_path);
        new_metadata->expected_size = file_size;
        new_metadata->id = metadata->id;

        int result = load_image_data_from_file(new_metadata, file_size);
        if (result != 0) {
            free(new_metadata->file_path);
            free(new_metadata);
            continue; // Ignore images that cannot be loaded
        }

        add_image_to_buffer(buffer, new_metadata);
    }
    return 0;
}

int load_image_data_from_file(IMAGE_METADATA* metadata, size_t size) {
    FILE* file = fopen(metadata->file_path, "rb");
    if (!file) {
        return -1; // File cannot be opened
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    if (file_size != size) {
        fclose(file);
        return -2; // Incorrect file size
    }

    void* buffer = malloc(size);
    if (!buffer) {
        fclose(file);
        return -3; // Memory allocation failed
    }

    size_t bytes_read = fread(buffer, 1, size, file);
    fclose(file);

    if (bytes_read != size) {
        free(buffer);
        return -4; // File read error
    }

    metadata->data = buffer;
    metadata->actual_size = bytes_read;
    return 0;
}
