#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure fields here
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initializeList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void validateCRC(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        // Add CRC validation logic here
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freeList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList myList;
    initializeList(&myList);

    NFAPI_CRC_INDICATION_PDU_T newData = {1, 2};
    insertNode(&myList, newData);

    validateCRC(&myList);

    freeList(&myList);

    return 0;
}
