#define MAX_MEMORY_SIZE 1024 * 1024 * 1024 // 1GB
#define DEFAULT_N 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t allocated_size;
} CustomAllocator;

CustomAllocator allocator = {NULL, 0};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_allocator() {
    pthread_mutex_lock(&mutex);
    if (allocator.data == NULL) {
        allocator.allocated_size = MAX_MEMORY_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        allocator.data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(allocator.allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (allocator.data == NULL) {
            printf("Failed to initialize custom allocator.\n");
        }
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_array(int N) {
    if (N <= 0) {
        return NULL;
    }

    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_size > allocator.allocated_size) {
        printf("Memory allocation request exceeds the allocated memory pool.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* array = &allocator.data[allocator.allocated_size - required_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    allocator.allocated_size -= required_size;

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
    }

    pthread_mutex_unlock(&mutex);
    return array;
}

void* memory_monitor(void* arg) {
    while (1) {
        size_t used_memory = MAX_MEMORY_SIZE - allocator.allocated_size;
        double usage_rate = (double)used_memory / MAX_MEMORY_SIZE * 100;

