typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} DoublyLinkedList;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = CRCFLAG;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

int populate_list(DoublyLinkedList* list, int N) {
    for (int i = 0; i < N; i++) {
        if ((i % 1024 == 0 && i != 0)) {
            // Reduce fragmentation and improve cache performance
            pthread_mutex_lock(&list->mutex);
            NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
            while (temp) {
                NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
                free(temp);
                temp = next;
            }
            list->head = list->tail = NULL;
            pthread_mutex_unlock(&list->mutex);
        }
        int RX_UE_INFORMATION_TAG = rand() % 1000;
        int RNTI = rand() % 65536;
        int CRCFLAG = (rand() % 2) == 0 ? 0 : 1; // Randomly set CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T* node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
        if (node == NULL) {
            return -1;
        }
        insert_node(list, node);
    }
    return 0;
}

void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
    while (temp) {
        NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
        free(temp);
        temp = next;
    }
    list->head = list->tail = NULL;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    DoublyLinkedList list;
    pthread_mutex_init(&list.mutex, NULL);
    int N = 10000; // Example value
    if (populate_list(&list, N) == 0) {
        printf("List populated successfully.\n");
    } else {
        printf("Failed to populate list.\n");
    }
    free_list(&list);
    pthread_mutex_destroy(&list.mutex);
    return 0;
}
