    *out_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!result) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < max_indications; ++i) {
        int retries = 0;
        bool success = false;

        while (!success && retries < MAX_RETRIES) {
            // Simulate fetching UE info and RNTI from external API with random values
            result[*out_count].RX_UE_INFORMATION_TAG = rand() % 1000; // Example logic to fetch tag
            result[*out_count].RNTI = rand() % 65536; // Example logic to fetch RNTI

            // Simulate fetching CRC flag with retry logic for network failures
            int crcFlag;
            while (true) {
                // Simulate API call and potential failure
                if (rand() % 2 == 0) {
                    crcFlag = rand() % 3; // Valid CRC flags: 0, 1, or 2
                    success = true;
                    break;
                } else {
                    retries++;
                    if (retries >= MAX_RETRIES) {
                        printf("Failed to fetch CRC flag after %d retries.\n", retries);
                        goto cleanup;
                    }
                }

                // Backoff with exponential increase in delay
                sleep(BACKOFF_BASE * (1 << retries));
            }

            result[*out_count].CRC_INDICATION_REL8_TAG = crcFlag;
            (*out_count)++;
        }
    }

cleanup:
    if (!success) {
        free(result);
        return NULL; // Return NULL on failure
    }

    // Resize array to exact size used
    NFAPI_CRC_INDICATION_PDU_T* new_result = (NFAPI_CRC_INDICATION_PDU_T*)realloc(result, (*out_count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_result) {
        free(result);
        return NULL; // Memory reallocation failed
    }

    return new_result;
}
