int validateMetadata(const ImageMetaData *metaData) {
    if (metaData->width <= 0 || metaData->height <= 0 || metaData->filesize < 0) {
        return 0;
    }
    return 1;
}

long long calculateMemoryUsage(int count, const ImageMetaData *metaDataList) {
    long long totalSize = 0;
    for (int i = 0; i < count; i++) {
        if (!validateMetadata(&metaDataList[i])) {
            fprintf(stderr, "Warning: Invalid metadata at index %d\n", i);
            continue;
        }
        totalSize += sizeof(ImageMetaData);
    }
    return totalSize;
}

int processImageMetaData(const ImageMetaData *metaDataList, int count) {
    long long memoryUsage = calculateMemoryUsage(count, metaDataList);
    if (memoryUsage < 0) {
        fprintf(stderr, "Error: Integer overflow detected\n");
        return 1;
    }
    printf("Total memory required: %lld bytes\n", memoryUsage);

    // Simulate memory allocation
    void *buffer = malloc(memoryUsage);
    if (!buffer) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return 1;
    }

    free(buffer);
    return 0;
}

