        {"image2.jpg", -1, 600, 300000}
    };
    int count = sizeof(metadata) / sizeof(metadata[0]);

    if (processImageMetaData(metadata, count)) {
        fprintf(stderr, "Error: Processing metadata failed\n");
        return 1;
    }

    printf("Metadata processing successful\n");
