typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

ListNode* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void appendNode(ListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = createNode(data);
    if (newNode == NULL) {
        return; // Handle allocation failure gracefully
    }
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    ListNode* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

void freeList(ListNode** head) {
    ListNode* current = *head;
    ListNode* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
