typedef struct {
    uint32_t width;
    uint32_t height;
    uint64_t size;
} ImageMetadata;

typedef struct {
    ImageMetadata *metadata;
    size_t count;
    size_t capacity;
    size_t memory_limit;
} MetadataCache;

int metadata_cache_init(MetadataCache *cache, size_t initial_capacity, size_t memory_limit) {
    cache->metadata = malloc(initial_capacity * sizeof(ImageMetadata));
    if (cache->metadata == NULL) {
        return -1; // Allocation failed
    }
    cache->count = 0;
    cache->capacity = initial_capacity;
    cache->memory_limit = memory_limit;
    return 0;
}

void metadata_cache_free(MetadataCache *cache) {
    free(cache->metadata);
    cache->metadata = NULL;
    cache->count = 0;
    cache->capacity = 0;
    cache->memory_limit = 0;
}

int metadata_cache_add(MetadataCache *cache, uint32_t width, uint32_t height, uint64_t size) {
    if (cache->count >= cache->capacity) {
        size_t new_capacity = cache->capacity ? cache->capacity * 2 : 16;
        ImageMetadata *new_metadata = realloc(cache->metadata, new_capacity * sizeof(ImageMetadata));
        if (new_metadata == NULL) {
            return -1; // Allocation failed
        }
        cache->metadata = new_metadata;
        cache->capacity = new_capacity;
    }

    size_t new_size = cache->count * sizeof(ImageMetadata);
    if (new_size > cache->memory_limit) {
        return -2; // Memory limit exceeded
    }

    ImageMetadata *entry = &cache->metadata[cache->count];
    entry->width = width;
    entry->height = height;
    entry->size = size;
    cache->count++;

    return 0;
}

int main() {
    MetadataCache cache;
    if (metadata_cache_init(&cache, 16, 1024 * 1024 * 1024) != 0) {
        fprintf(stderr, "Failed to initialize metadata cache\n");
        return 1;
    }

    // Example usage
    uint32_t width = 800;
    uint32_t height = 600;
    uint64_t size = 5 * 1024 * 1024; // 5MB

    if (metadata_cache_add(&cache, width, height, size) != 0) {
        fprintf(stderr, "Failed to add metadata entry\n");
        metadata_cache_free(&cache);
        return 1;
    }

    printf("Metadata cache contains %zu entries\n", cache.count);

    metadata_cache_free(&cache);
    return 0;
}
