#define MAX_PACKET_SIZE 1024
#define MIN_PACKET_SIZE 1

typedef struct Packet {
    int size;
    char *payload;
} Packet;

int calculate_buffer_size(int packet_count, double average_payload_size) {
    if (average_payload_size > MAX_PACKET_SIZE || average_payload_size < MIN_PACKET_SIZE) {
        return -1; // Invalid average payload size
    }

    long long total_size = (long long)packet_count * average_payload_size;
    if (total_size > INT_MAX) {
        return -2; // Potential integer overflow
    }

    return (int)total_size;
}

char* process_packets(int packet_count, Packet packets[], int max_payload_size) {
    if (packet_count < 10 || packet_count > 10000) {
        return NULL; // Invalid packet count
    }

    double total_payload_size = 0;
    for (int i = 0; i < packet_count; ++i) {
        if (packets[i].size < MIN_PACKET_SIZE || packets[i].size > max_payload_size) {
            return NULL; // Invalid payload size
        }
        total_payload_size += packets[i].size;
    }

    int buffer_size = calculate_buffer_size(packet_count, total_payload_size / packet_count);
    if (buffer_size == -1) {
        return NULL; // Invalid average payload size
    } else if (buffer_size == -2) {
        return NULL; // Potential integer overflow
    }

    char *buffer = (char *)malloc(buffer_size);
    if (!buffer) {
        return NULL; // Insufficient memory available
    }

    int offset = 0;
    for (int i = 0; i < packet_count; ++i) {
        memcpy(&buffer[offset], packets[i].payload, packets[i].size);
        offset += packets[i].size;
    }

    return buffer;
}

void free_buffer(char *buffer) {
    free(buffer);
}
