typedef struct PacketInfo {
    int id;
    time_t timestamp;
    char data[MAX_PACKET_SIZE];
} PacketInfo;

typedef struct Node {
    PacketInfo packet;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t totalSize;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->totalSize = 0;
}

void appendPacket(LinkedList* list, PacketInfo packet) {
    if (list->totalSize + strlen(packet.data) > BUFFER_LIMIT) {
        // Handle buffer overflow
        // Implement your strategy here (e.g., drop packets, overwrite)
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->packet = packet;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }

    list->totalSize += strlen(packet.data);
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->totalSize = 0;
}

