PacketList* packet_list_init() {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->total_size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void packet_list_destroy(PacketList* list) {
    pthread_mutex_lock(&list->lock);
    PacketInfo* current = list->head;
    while (current != NULL) {
        PacketInfo* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int packet_list_insert(PacketList* list, int id, long timestamp, const char* data, size_t data_size) {
    if (data_size > BUFFER_LIMIT - list->total_size) return -1; // Check buffer limit

    PacketInfo* new_packet = (PacketInfo*)malloc(sizeof(PacketInfo));
    if (!new_packet) return -1;

    new_packet->id = id;
    new_packet->timestamp = timestamp;
    new_packet->data = (char*)malloc(data_size);
    if (!new_packet->data) {
        free(new_packet);
        return -1;
    }
    memcpy(new_packet->data, data, data_size);
    new_packet->data_size = data_size;
    new_packet->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = list->tail = new_packet;
    } else {
        new_packet->prev = list->tail;
        list->tail->next = new_packet;
        list->tail = new_packet;
    }
    list->total_size += data_size;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void packet_list_remove(PacketList* list, int id) {
    pthread_mutex_lock(&list->lock);
    PacketInfo* current = list->head;
    while (current != NULL) {
        if (current->id == id) {
            if (current->prev != NULL) current->prev->next = current->next;
            if (current->next != NULL) current->next->prev = current->prev;
            if (list->head == current) list->head = current->next;
            if (list->tail == current) list->tail = current->prev;

            free(current->data);
            free(current);
            list->total_size -= current->data_size;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Add more functions as needed for iterating, etc.
```

