#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define BUFFER_LIMIT 1024 * 1024 // 1 MB

typedef struct PacketInfo {
    unsigned int id;
    time_t timestamp;
    char* data;
    size_t data_size;
} PacketInfo;

typedef struct Node {
    PacketInfo packet;
    struct Node* next;
} Node;

typedef struct SharedResource {
    Node* head;
    Node* tail;
    size_t total_data_size;
    pthread_mutex_t lock;
} SharedResource;

SharedResource shared_resource;

void init_shared_resource() {
    shared_resource.head = NULL;
    shared_resource.tail = NULL;
    shared_resource.total_data_size = 0;
    pthread_mutex_init(&shared_resource.lock, NULL);
}

Node* create_node(unsigned int id, time_t timestamp, const char* data, size_t data_size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->packet.id = id;
    node->packet.timestamp = timestamp;
    node->packet.data = (char*)malloc(data_size);
    if (node->packet.data == NULL) {
        perror("Failed to allocate memory for data payload");
        free(node);
        return NULL;
    }
    memcpy(node->packet.data, data, data_size);
    node->packet.data_size = data_size;
    node->next = NULL;
    return node;
}

void add_packet_to_list(unsigned int id, time_t timestamp, const char* data, size_t data_size) {
    pthread_mutex_lock(&shared_resource.lock);

    if (shared_resource.total_data_size + data_size > BUFFER_LIMIT) {
        // Handle buffer limit reached
        printf("Buffer limit reached. Dropping packet.\n");
        pthread_mutex_unlock(&shared_resource.lock);
        return;
    }

    Node* new_node = create_node(id, timestamp, data, data_size);
    if (new_node == NULL) {
        pthread_mutex_unlock(&shared_resource.lock);
        return;
    }

    if (shared_resource.head == NULL) {
        shared_resource.head = new_node;
        shared_resource.tail = new_node;
    } else {
        shared_resource.tail->next = new_node;
        shared_resource.tail = new_node;
    }
    shared_resource.total_data_size += data_size;

    pthread_mutex_unlock(&shared_resource.lock);
}

void free_shared_resource() {
    Node* current = shared_resource.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->packet.data);
        free(current);
        current = next;
    }
    shared_resource.head = NULL;
    shared_resource.tail = NULL;
    pthread_mutex_destroy(&shared_resource.lock);
}

int main() {
    init_shared_resource();

    // Simulate adding packets
    add_packet_to_list(1, time(NULL), "Data 1", strlen("Data 1") + 1);
    add_packet_to_list(2, time(NULL) + 1, "Data 2", strlen("Data 2") + 1);

    free_shared_resource();
    return 0;
}
```

This code provides a basic structure for managing a linked list of `PacketInfo` structures within a shared resource pool. It includes functions to initialize the shared resource, add packets to the list while respecting the buffer limit, and clean up resources. The use of mutex locks ensures thread safety during concurrent access.']

