#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 1000

typedef struct {
    unsigned long long timestamp;
    unsigned int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTS];
    size_t count;
    pthread_mutex_t mutex;
    size_t successful_allocations;
} DynamicList;

int is_prime(unsigned int num) {
    // Function to check if a number is prime
}

void initialize_list(DynamicList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->successful_allocations = 0;
}

int allocate_memory(DynamicList* list, size_t N) {
    if (N > MAX_STRUCTS || N == 0) {
        printf("Warning: Invalid input size.\n");
        return -1;
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&list->mutex);
        list->structures[list->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->structures[list->count]) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = list->structures[list->count];
        pdu->timestamp = time(NULL); // Set timestamp
        pdu->RNTI = rand(); // Set RNTI
        pdu->CRCFLAG = is_prime(pdu->RNTI) ? 1 : 0; // Set CRCFLAG based on prime check
        list->count++;
        list->successful_allocations++;
        pthread_mutex_unlock(&list->mutex);
    }

    printf("Allocated %zu structures successfully.\n", N);
    return 0;
}

void free_memory(DynamicList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_lock(&list->mutex);
        free(list->structures[i]);
        list->structures[i] = NULL;
        list->count--;
        pthread_mutex_unlock(&list->mutex);
    }
    pthread_mutex_destroy(&list->mutex);
}

void update_crc_flags(DynamicList* list, unsigned int prime_rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_lock(&list->mutex);
        NFAPI_CRC_INDICATION_PDU_T* pdu = list->structures[i];
        if (pdu->RNTI == prime_rnti) {
            pdu->CRCFLAG = 1;
        }
        pthread_mutex_unlock(&list->mutex);
    }
}
