int create_and_populate_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t N) {
    if (N > MAX_LIST_SIZE) return -1; // Input validation and bounds checking

    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return -2; // Memory allocation failure

    for (size_t i = 0; i < N; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand();
        (*list)[i].RNTI = (uint16_t)(rand() % 65536);
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return 0; // Success
}

int resolve_dns(const char* hostname, u_char** ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -3; // DNS resolution failure
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* h = (struct sockaddr_in*)p->ai_addr;
        *ip_address = malloc(sizeof(u_char) * 4);
        if (*ip_address == NULL) {
            freeaddrinfo(res); // Free the linked list of addrinfo structures
            return -2; // Memory allocation failure
        }
        memcpy(*ip_address, &(h->sin_addr.s_addr), 4);
    }

    freeaddrinfo(res); // Free the linked list of addrinfo structures

    return 0; // Success
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* list;
    u_char* ip_address;

    if (create_and_populate_list(&list, 5) != 0) {
        printf("Failed to create and populate list\n");
        return 1;
    }

    if (resolve_dns("example.com", &ip_address) != 0) {
        printf("Failed to resolve DNS\n");
        free(list); // Clean up allocated memory
        return 1;
    }

    printf("IP Address: %u.%u.%u.%u\n",
           ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    free(list); // Clean up allocated memory
    free(ip_address);

    return 0;
}
