#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024 * 1024 // Maximum packet size in bytes

// Structure to represent a network packet
typedef struct {
    unsigned int length; // Length of the payload
    void* payload;       // Pointer to the payload data
} NetworkPacket;

// Function to process incoming network packets
void processNetworkPackets(NetworkPacket* packets, int num_packets, size_t max_memory) {
    size_t total_allocated = 0;

    for (int i = 0; i < num_packets; ++i) {
        if (packets[i].length > MAX_PACKET_SIZE) {
            fprintf(stderr, "Warning: Packet length %u exceeds maximum expected size.\n", packets[i].length);
            continue;
        }

        if ((total_allocated + packets[i].length) > max_memory) {
            fprintf(stderr, "Error: Memory allocation would exceed max_memory. Dropping packet.\n");
            continue;
        }

        // Allocate memory for the payload
        packets[i].payload = malloc(packets[i].length);
        if (!packets[i].payload) {
            fprintf(stderr, "Error: Failed to allocate memory for packet payload.\n");
            continue;
        }

        total_allocated += packets[i].length;

        // Simulate processing the payload (e.g., copying data)
        // For demonstration purposes, we'll just zero out the payload
        memset(packets[i].payload, 0, packets[i].length);

        // Free the allocated memory after processing
        free(packets[i].payload);
    }

    // Log total memory used for payloads
    printf("Total memory used for payloads: %zu bytes\n", total_allocated);
}

// Example usage
int main() {
    NetworkPacket packets[] = {
        {1024, NULL},
        {2048, NULL},
        {512, NULL}
    };
    int num_packets = sizeof(packets) / sizeof(packets[0]);
    size_t max_memory = 3 * MAX_PACKET_SIZE;

    processNetworkPackets(packets, num_packets, max_memory);

    return 0;
}
