#define MAX_DOCUMENT_SIZE 1024 * 1024 // 1MB
#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    int document_size;
    char* content;
} Document;

typedef struct {
    int total_memory_used;
    pthread_mutex_t memory_lock;
} MemoryManager;

MemoryManager memory_manager = {0, PTHREAD_MUTEX_INITIALIZER};

void* process_document(void* arg) {
    Document* doc = (Document*)arg;
    // Process the document
    printf("Processing document with size: %d\n", doc->document_size);

    free(doc->content); // Free allocated memory for content
    pthread_mutex_lock(&memory_manager.memory_lock);
    memory_manager.total_memory_used -= doc->document_size + sizeof(Document);
    pthread_mutex_unlock(&memory_manager.memory_lock);

    return NULL;
}

void ingest_documents(int max_memory, int num_threads) {
    Document* documents[MAX_THREADS];
    pthread_t threads[MAX_THREADS];

    int document_count = 0;

    while (memory_manager.total_memory_used < max_memory) {
        // Simulate reading a document from the stream
        if (document_count >= MAX_THREADS) break; // Limit number of documents for simplicity

        Document* doc = (Document*)malloc(sizeof(Document));
        if (!doc) {
            printf("Memory allocation failed\n");
            return;
        }

        int header_size = 4; // Size of the document size field
        int content_size = rand() % MAX_DOCUMENT_SIZE; // Simulate random content size

        if ((memory_manager.total_memory_used + sizeof(Document) + content_size) > max_memory) {
            free(doc);
            break;
        }

        pthread_mutex_lock(&memory_manager.memory_lock);
        doc->document_size = content_size;
        memory_manager.total_memory_used += sizeof(Document) + content_size;
        pthread_mutex_unlock(&memory_manager.memory_lock);

        doc->content = (char*)malloc(content_size);
        if (!doc->content) {
            free(doc);
            printf("Memory allocation failed\n");
            return;
        }

        // Simulate filling the document content
        memset(doc->content, 'A', content_size);

        documents[document_count++] = doc;

        if (document_count % num_threads == 0 && document_count > 0) {
            for (int i = 0; i < document_count; i++) {
                pthread_create(&threads[i], NULL, process_document, documents[i]);
            }
            for (int i = 0; i < document_count; i++) {
                pthread_join(threads[i], NULL);
            }
            document_count = 0;
        }
    }

    // Process remaining documents
    if (document_count > 0) {
        for (int i = 0; i < document_count; i++) {
            pthread_create(&threads[i], NULL, process_document, documents[i]);
        }
        for (int i = 0; i < document_count; i++) {
            pthread_join(threads[i], NULL);
        }
    }

    printf("Total memory used: %d\n", memory_manager.total_memory_used);
}
