#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1024
#define INITIAL_CAPACITY 64
#define GROWTH_FACTOR 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_UE_CONTEXTS];
    size_t capacity[MAX_UE_CONTEXTS];
    size_t count[MAX_UE_CONTEXTS];
} CRC_LIST_MANAGER_T;

int crc_list_manager_init(CRC_LIST_MANAGER_T *manager) {
    for (size_t i = 0; i < MAX_UE_CONTEXTS; ++i) {
        pthread_mutex_init(&manager->mutex[i], NULL);
        manager->pdus[i] = NULL;
        manager->capacity[i] = INITIAL_CAPACITY;
        manager->count[i] = 0;
    }
    return 0;
}

int crc_list_manager_add_pdu(CRC_LIST_MANAGER_T *manager, size_t ue_context_id) {
    if (ue_context_id >= MAX_UE_CONTEXTS) return -1; // Error: Invalid UE context ID

    pthread_mutex_lock(&manager->mutex[ue_context_id]);

    if (manager->count[ue_context_id] == manager->capacity[ue_context_id]) {
        size_t new_capacity = manager->capacity[ue_context_id] * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(manager->pdus[ue_context_id], new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&manager->mutex[ue_context_id]);
            return -2; // Error: Memory allocation failed
        }
        manager->pdus[ue_context_id] = new_pdus;
        manager->capacity[ue_context_id] = new_capacity;
    }

    // Populate the new PDU with random data
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &manager->pdus[ue_context_id][manager->count[ue_context_id]];
    new_pdu->RX_UE_INFORMATION_TAG = rand();
    new_pdu->RNTI = (uint16_t)rand();
    new_pdu->crc_indication.CRCFLAG = (rand() % 2 == 0);

    manager->count[ue_context_id]++;
    pthread_mutex_unlock(&manager->mutex[ue_context_id]);

    return manager->count[ue_context_id];
}

size_t crc_list_manager_get_count(CRC_LIST_MANAGER_T *manager, size_t ue_context_id) {
    if (ue_context_id >= MAX_UE_CONTEXTS) return 0; // Error: Invalid UE context ID
    return manager->count[ue_context_id];
}
