#define MIN_RESIZE_THRESHOLD 5
#define LOGGING_LEVEL 2

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
int pool_size = 0;
pthread_mutex_t pool_lock;
int global_counter = 0;
int resize_threshold = MIN_RESIZE_THRESHOLD;

void log_memory_allocation(int thread_id, int num_structs) {
    if (LOGGING_LEVEL > 1) {
        time_t now = time(NULL);
        printf("Thread %d: Allocated %d structures at %s\n", thread_id, num_structs, ctime(&now));
    }
}

int allocate_structures(int num_structs) {
    pthread_mutex_lock(&pool_lock);
    if (global_counter + num_structs > MAX_STRUCTS) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }
    if (pool_size < global_counter + num_structs) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool, (global_counter + num_structs) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool_lock);
            return -2;
        }
        pool = new_pool;
        pool_size = global_counter + num_structs;
    }
    for (int i = 0; i < num_structs; i++) {
        // Initialize structure members here
        pool[global_counter + i].ue_info = generate_ue_info();
        pool[global_counter + i].rnti = generate_rnti();
        pool[global_counter + i].crc_indication.crcflag = rand() % 2;
    }
    global_counter += num_structs;
    log_memory_allocation(pthread_self(), num_structs);
    pthread_mutex_unlock(&pool_lock);
    return 0;
}

void initialize_pool() {
    pthread_mutex_init(&pool_lock, NULL);
    pool = malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool_size = MAX_STRUCTS;
}

void cleanup_pool() {
    pthread_mutex_destroy(&pool_lock);
    free(pool);
}
