#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 100
#define INITIAL_CAPACITY 500

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UE_CONTEXT {
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t capacity;
    size_t count;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
} UE_CONTEXT;

UE_CONTEXT* create_ue_context() {
    UE_CONTEXT* context = (UE_CONTEXT*)malloc(sizeof(UE_CONTEXT));
    if (!context) {
        return NULL; // Memory allocation failure
    }
    context->buffer = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!context->buffer) {
        free(context);
        return NULL; // Memory allocation failure
    }
    context->capacity = INITIAL_CAPACITY;
    context->count = 0;
    context->head = 0;
    context->tail = 0;
    pthread_mutex_init(&context->mutex, NULL);
    return context;
}

void destroy_ue_context(UE_CONTEXT* context) {
    pthread_mutex_lock(&context->mutex);
    free(context->buffer);
    pthread_mutex_unlock(&context->mutex);
    free(context);
}

int add_pdu_to_context(UE_CONTEXT* context, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&context->mutex);
    if (context->count == context->capacity) {
        size_t new_capacity = context->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = (NFAPI_CRC_INDICATION_PDU_T*)realloc(context->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            pthread_mutex_unlock(&context->mutex);
            return -1; // Memory allocation failure
        }
        context->buffer = new_buffer;
        context->capacity = new_capacity;
    }
    size_t next_tail = (context->tail + 1) % context->capacity;
    if (next_tail == context->head) {
        pthread_mutex_unlock(&context->mutex);
        return -2; // List is full, cannot add
    }
    context->buffer[context->tail] = pdu;
    context->tail = next_tail;
    context->count++;
    pthread_mutex_unlock(&context->mutex);
    return 0; // Success
}

size_t get_count(UE_CONTEXT* context) {
    size_t count;
    pthread_mutex_lock(&context->mutex);
    count = context->count;
    pthread_mutex_unlock(&context->mutex);
    return count;
}
```

This code provides a basic implementation of the required functionality. It includes functions to create and destroy UE contexts, add PDUs to a context, and get the current count of PDUs in a context. The use of mutexes ensures thread safety, and the ring buffer approach helps manage memory more efficiently by minimizing fragmentation. Error handling is included for memory allocation failures and list full conditions.']

