#include <stdbool.h>
#include <string.h>
#include <stdio.h>

#define NFAPI_CRC_INDICATION_PDU_T_SIZE 1024
#define MAX_MEMORY 1048576
#define REASONABLE_THRESHOLD 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
    size_t capacity;
} ListOfPdus;

int allocateListOfPdus(ListOfPdus *list, size_t N, size_t M) {
    if (N > REASONABLE_THRESHOLD) {
        printf("Warning: Number of structures exceeds reasonable threshold.\n");
    }

    size_t requiredMemory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (requiredMemory + list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY) {
        printf("Error: Insufficient system resources for memory allocation.\n");
        return -1;
    }

    size_t newCapacity = N + list->capacity;
    void *newList = realloc(list->list, newCapacity * NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (newList == NULL) {
        printf("Error: Failed to allocate memory for PDU list.\n");
        return -2;
    }

    list->list = (NFAPI_CRC_INDICATION_PDU_T *)newList;
    list->capacity = newCapacity;

    for (size_t i = list->size; i < N + list->size; ++i) {
        list->list[i].RX_UE_INFORMATION_TAG = generateRandomTag();
        list->list[i].RNTI = generateRandomRnti();
        list->list[i].CRCFLAG = rand() % 2 == 0;
    }

    list->size += N;
    return 0;
}

// Helper functions for generating random values
uint32_t generateRandomTag() {
    // Generate a random RX_UE_INFORMATION_TAG value
    return (rand() >> 16) & 0xFFFFF; // Assuming 20-bit tag
}

uint16_t generateRandomRnti() {
    // Generate a random RNTI value
    return rand() & 0x3FFF; // Assuming 14-bit RNTI
}

// Example usage and synchronization
#include <pthread.h>

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

void *createListOfPdusThread(void *arg) {
    ListOfPdus list = { .list = NULL, .size = 0, .capacity = 0 };
    size_t N = *(size_t *)arg;
    size_t M = 1024; // Example payload size

    pthread_mutex_lock(&listMutex);
    int result = allocateListOfPdus(&list, N, M);
    if (result != 0) {
        printf("Failed to allocate list of PDUs.\n");
    } else {
        printf("Successfully allocated list of %zu PDUs.\n", N);
    }
    pthread_mutex_unlock(&listMutex);

    free(list.list);
    return NULL;
}

int main() {
    size_t N = 500; // Example number of structures
    pthread_t thread;

    if (pthread_create(&thread, NULL, createListOfPdusThread, &N) != 0) {
        printf("Failed to create thread.\n");
        return -1;
    }

    pthread_join(thread, NULL);
    return 0;
}
