#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t size;
    size_t capacity;
    size_t max_entries;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* nfapi_crc_list_create(size_t max_entries) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->max_entries = max_entries;

    srand(time(NULL)); // Initialize random seed for CRCFLAG generation

    return list;
}

void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T* list) {
    free(list->entries);
    free(list);
}

bool nfapi_crc_list_resize(NFAPI_CRC_LIST_T* list, size_t new_capacity) {
    if (new_capacity < list->size) return false;

    NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) return false;

    list->entries = new_entries;
    list->capacity = new_capacity;

    return true;
}

bool nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (list->size >= list->max_entries) return false;

    if (list->size == list->capacity && !nfapi_crc_list_resize(list, list->capacity * GROWTH_FACTOR)) return false;

    NFAPI_CRC_INDICATION_PDU_T* new_entry = &list->entries[list->size++];
    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = (rand() % 2) == 0; // Randomly set CRCFLAG

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_list_get(NFAPI_CRC_LIST_T* list, size_t index) {
    if (index >= list->size) return NULL;

    return &list->entries[index];
}
