    if (limit == 0) limit = DEFAULT_LIMIT;

    ImageInfo* info_array = (ImageInfo*)malloc(count * sizeof(ImageInfo));
    if (!info_array) return NULL;

    for (int i = 0; i < count; ++i) {
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
