        fread(&info_array[i].width, sizeof(int), 1, file);
        fread(&info_array[i].height, sizeof(int), 1, file);
        fclose(file);

        // Validate dimensions
        if (info_array[i].width > MAX_DIMENSION || info_array[i].height > MAX_DIMENSION) {
            fprintf(stderr, "Image %s has invalid dimensions\n", filenames[i]);
            free(info_array);
            return NULL;
        }

        // Check memory limit
        if ((i + 1) * sizeof(ImageInfo) > limit) {
            fprintf(stderr, "Memory limit exceeded\n");
            free(info_array);
            return NULL;
        }

        // Copy filename
        strncpy(info_array[i].filename, filenames[i], sizeof(info_array[i].filename) - 1);
    }

    return info_array;
}

