void initialize_packet_pool() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        packet_pool[i] = NULL;
    }
}

PacketMetadata* create_packet(int id, time_t timestamp, const char* payload, size_t payload_size) {
    if (pool_index >= MAX_PACKETS || pool_index < 0) {
        return NULL;
    }

    PacketMetadata* packet = packet_pool[pool_index];
    if (!packet) {
        packet = (PacketMetadata*)malloc(sizeof(PacketMetadata));
        if (!packet) {
            return NULL;
        }
    } else {
        pool_index++;
    }

    packet->id = id;
    packet->timestamp = timestamp;
    packet->payload = (char*)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    memcpy(packet->payload, payload, payload_size);

    return packet;
}

void destroy_packet(PacketMetadata* packet) {
    if (!packet) {
        return;
    }

    if (packet->payload) {
        free(packet->payload);
    }

    int index = -1;
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packet_pool[i] == packet) {
            index = i;
            break;
        }
    }

    if (index != -1 && index < pool_index) {
        free(packet);
        packet_pool[index] = NULL;
        for (int i = index; i < pool_index - 1; i++) {
            packet_pool[i] = packet_pool[i + 1];
        }
        pool_index--;
    } else {
        free(packet);
    }
}

