#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Linked_List {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} Linked_List;

void initialize_list(Linked_List *list, int initial_capacity) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

int allocate_memory_for_node(NFAPI_CRC_INDICATION_PDU_T **node, size_t memory_limit) {
    size_t node_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (memory_limit < node_size) {
        return -1; // Memory limit exceeded
    }
    *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(node_size);
    if (*node == NULL) {
        return -2; // Memory allocation failed
    }
    return 0;
}

void populate_node(NFAPI_CRC_INDICATION_PDU_T *node, int RX_UE_INFORMATION_TAG, int RNTI) {
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    node->timestamp = time(NULL);
}

void insert_at_end(Linked_List *list, int RX_UE_INFORMATION_TAG, int RNTI, size_t memory_limit) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2; // Double the capacity for resizing
    }
    NFAPI_CRC_INDICATION_PDU_T *new_node;
    int result = allocate_memory_for_node(&new_node, memory_limit);
    if (result != 0) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Memory allocation failed or limit exceeded\n");
        return;
    }
    populate_node(new_node, RX_UE_INFORMATION_TAG, RNTI);
    new_node->next = NULL;
    if (list->tail == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void free_list(Linked_List *list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void *create_and_populate_list(void *arg) {
    int N = *(int *)arg;
    Linked_List *list = (Linked_List *)malloc(sizeof(Linked_List));
    initialize_list(list, N);

    for (int i = 0; i < N; i++) {
        insert_at_end(list, rand(), rand());
    }

    // Simulate some processing
    sleep(1);

    free_list(list);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t thread;
    int N = 1000;
    size_t memory_limit = 10 * 1024 * 1024; // 10 MB limit

    if (pthread_create(&thread, NULL, create_and_populate_list, &N) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);
    return 0;
