#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE 1024 * 1024 // 1 MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t block_size;
    size_t pool_size;
    void *pool_start;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool;

void init_memory_pool(size_t block_size, size_t pool_size) {
    memory_pool.block_size = block_size;
    memory_pool.pool_size = pool_size;
    memory_pool.pool_start = malloc(block_size * pool_size);
    if (memory_pool.pool_start == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void* allocate_block() {
    void *block = NULL;
    pthread_mutex_lock(&memory_pool.lock);
    block = memory_pool.pool_start;
    if (block != NULL) {
        memory_pool.pool_start += memory_pool.block_size;
        if ((char *)memory_pool.pool_start - (char *)memory_pool.pool_start > memory_pool.pool_size * memory_pool.block_size) {
            memory_pool.pool_start = NULL; // Reset pool on full allocation
        }
    }
    pthread_mutex_unlock(&memory_pool.lock);
    return block;
}

void free_block(void *block) {
    // Not needed in this simple allocator, but could be implemented for advanced features
}

int create_nfaapi_crc_pdu_array(size_t N, size_t M) {
    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > M) {
        return -1; // Not enough memory
    }

    NFAPI_CRC_INDICATION_PDU_T *array = allocate_block();
    if (array == NULL) {
        fprintf(stderr, "Failed to allocate memory for NFAPI CRC PDU array\n");
        return -2;
    }

    for (size_t i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        array[i].RNTI = rand() % UINT32_MAX;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Use the array for your purposes
    free_block(array); // Free block when done

    return 0;
}

void *resource_monitor(void *arg) {
    while (1) {
        pthread_mutex_lock(&memory_pool.lock);
        size_t current_memory_usage = memory_pool.pool_size - ((char *)memory_pool.pool_start - (char *)memory_pool.pool_start);
        if (current_memory_usage > MAX_MEMORY_SIZE / 2) {
            printf("Warning: Memory usage approaching threshold\n");
            // Suggest actions to free up memory
        }
        pthread_mutex_unlock(&memory_pool.lock);
        sleep(1); // Check every second
    }
}

int main() {
    init_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1000);

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, resource_monitor, NULL) != 0) {
        fprintf(stderr, "Failed to create resource monitor thread\n");
        exit(1);
    }

    int result = create_nfaapi_crc_pdu_array(500, MAX_MEMORY_SIZE);
    if (result != 0) {
        printf("Error: %d\n", result);
    }

    pthread_join(monitor_thread, NULL);

    return 0;
}
