    if (stat(path, &file_stat) == 0) {
        return file_stat.st_size;
    }
    return -1;
}

image_t* load_images_from_directory(const char* directory_path, size_t max_memory) {
    DIR* dir = opendir(directory_path);
    if (!dir) return NULL;

    image_t** images = malloc(sizeof(image_t*) * 256); // Initial capacity
    if (!images) return NULL;
    int count = 0;

    char path[1024];
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);
        if (is_image_file(entry->d_name)) {
            size_t file_size = get_image_size(path);
            if (file_size == -1 || count * sizeof(image_t*) + file_size > max_memory) break;

            images[count] = malloc(sizeof(image_t));
            if (!images[count]) {
                closedir(dir);
                for (int i = 0; i < count; i++) free(images[i]);
                free(images);
                return NULL;
            }
            images[count]->path = strdup(path);
            // Simulate loading image dimensions
            images[count]->width = rand() % 1920 + 320;
            images[count]->height = rand() % 1080 + 240;

            count++;
        } else if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            image_t* sub_images = load_images_from_directory(path, max_memory - count * sizeof(image_t*) + file_size);
            if (!sub_images) {
                closedir(dir);
                for (int i = 0; i < count; i++) free(images[i]);
                free(images);
                return NULL;
            }
            images[count++] = sub_images;
        }
    }

    // Resize the array to fit exactly
    image_t** resized_images = realloc(images, count * sizeof(image_t*));
    if (!resized_images) {
        for (int i = 0; i < count; i++) free(images[i]);
        free(images);
        return NULL;
    }
    images = resized_images;

    closedir(dir);
    return images;
}

