    free(image);
}

void free_image_array(image_t** images, int count) {
    for (int i = 0; i < count; i++) {
        if (images[i]->width > 1920 || images[i]->height > 1080) {
            // Simulate freeing resources for large images
        }
        free_image_data(images[i]);
    }
    free(images);
}

