#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint64_t timestamp;
    int severity_level;
    char *message;
} log_entry_t;

typedef struct {
    size_t max_entries;
    size_t total_size_limit;
    size_t current_size;
    log_entry_t **entries;
} log_manager_t;

log_manager_t* create_log_manager(size_t initial_capacity, size_t total_size_limit) {
    log_manager_t *manager = (log_manager_t*)malloc(sizeof(log_manager_t));
    if (!manager) return NULL;

    manager->max_entries = initial_capacity;
    manager->total_size_limit = total_size_limit;
    manager->current_size = 0;
    manager->entries = (log_entry_t**)malloc(initial_capacity * sizeof(log_entry_t*));

    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->entries[i] = NULL;
    }

    return manager;
}

void destroy_log_manager(log_manager_t *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->current_size; ++i) {
        free(manager->entries[i]->message);
        free(manager->entries[i]);
    }

    free(manager->entries);
    free(manager);
}

int add_log_entry(log_manager_t *manager, log_entry_t *entry) {
    if (!manager || !entry) return -1;

    size_t new_total_size = manager->current_size + sizeof(log_entry_t*) + entry->message ? strlen(entry->message) : 0;

    // Check for integer overflow
    if (new_total_size < manager->current_size || new_total_size > manager->total_size_limit) {
        return -1;
    }

    if (manager->current_size == manager->max_entries) {
        size_t new_capacity = manager->max_entries * 2;
        log_entry_t **new_entries = realloc(manager->entries, new_capacity * sizeof(log_entry_t*));
        if (!new_entries) return -1;

        manager->entries = new_entries;
        manager->max_entries = new_capacity;
    }

    manager->entries[manager->current_size++] = entry;

    return 0;
}

log_entry_t* create_log_entry(uint64_t timestamp, int severity_level, const char *message) {
    log_entry_t *entry = (log_entry_t*)malloc(sizeof(log_entry_t));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    entry->severity_level = severity_level;
    entry->message = strdup(message);

    if (!entry->message) {
        free(entry);
        return NULL;
    }

    return entry;
}

void destroy_log_entry(log_entry_t *entry) {
    if (!entry) return;

    free(entry->message);
    free(entry);
}
```

