#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t currentSize;
    size_t maxSize;
    pthread_mutex_t mutex;
} LinkedList;

int initLinkedList(LinkedList* list, size_t maxSize) {
    list->head = NULL;
    list->tail = NULL;
    list->currentSize = 0;
    list->maxSize = maxSize;
    pthread_mutex_init(&list->mutex, NULL);
    return 0;
}

int insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->currentSize >= list->maxSize) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory limit reached
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Allocation failed
    }

    newNode->data = data;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }

    list->currentSize++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    LinkedList myList;
    initLinkedList(&myList, 100); // Initialize with a max size of 100 structures

    NFAPI_CRC_INDICATION_PDU_T newData; // Populate newData as needed
    insertNode(&myList, newData);

    freeLinkedList(&myList);
    return 0;
}
