LinkedList list;

void init_list() {
    list.head = NULL;
    list.tail = NULL;
    list.current_size = 0;
    list.max_size = MAX_LIST_SIZE;
    pthread_mutex_init(&list.lock, NULL);
}

int insert_to_list(NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&list.lock);
    if (list.current_size >= list.max_size) {
        pthread_mutex_unlock(&list.lock);
        return -1; // List is full
    }
    if (list.head == NULL) {
        list.head = list.tail = new_node;
    } else {
        list.tail->next = new_node;
        list.tail = new_node;
    }
    list.current_size++;
    pthread_mutex_unlock(&list.lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_new_node() {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
