    }
    node->RX_UE_INFORMATION_TAG = rand() % 1000;
    node->RNTI = rand() % 500;
    node->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0;
    time(&node->timestamp);
    node->next = NULL;
    return node;
}

int create_and_manage_list(int N, size_t M) {
    if (N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > M) {
        return -2; // Memory requirement exceeds limit
    }
    init_list();
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_new_node();
        if (new_node == NULL) {
            return -1; // Failed to allocate memory for node
        }
        if (insert_to_list(new_node) != 0) {
            free(new_node);
            return -1; // List is full
        }
    }
    return 0;
}

