class NFAPICRCList {
public:
    void Add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mutex_);
        list_.push_back(pdu);
        cond_var_.notify_one();
    }

    bool Pop(NFAPI_CRC_INDICATION_PDU_T& pdu, std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!cond_var_.wait_for(lock, timeout, [this]{ return !list_.empty(); })) {
            return false;
