#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

void initList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int insertFront(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    newNode->data = data;
    newNode->next = list->head;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->tail = newNode;
    }
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int insertBack(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->tail == NULL) {
        list->head = newNode;
    } else {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_destroy(&list->mutex);
}

int main() {
    LinkedList list;
    initList(&list);

    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 2, 3, time(NULL)};
    NFAPI_CRC_INDICATION_PDU_T data2 = {4, 5, 6, time(NULL)};

    insertFront(&list, data1);
    insertBack(&list, data2);

    // Process the list...

    freeList(&list);
    return 0;
}
```

