ImageMetadata* process_image_file_paths(char** file_paths, int num_paths, int* total_images) {
    if (num_paths <= 0 || !file_paths) {
        *total_images = 0;
        return NULL;
    }

    // Estimate the number of images by assuming all files have one image
    size_t estimated_total_images = 1ULL * num_paths; // Use 1ULL to ensure unsigned long long for estimation
    if (estimated_total_images > INT_MAX) {
        fprintf(stderr, "Error: Estimated total images exceed the maximum value for int.\n");
        *total_images = 0;
        return NULL;
    }

    ImageMetadata* metadata_array = (ImageMetadata*)malloc(estimated_total_images * sizeof(ImageMetadata));
    if (!metadata_array) {
        perror("Failed to allocate memory for image metadata array.");
        *total_images = 0;
        return NULL;
    }

    int actual_images = 0;
    for (int i = 0; i < num_paths; ++i) {
        DIR* dir = opendir(file_paths[i]);
        if (!dir) {
            perror("Failed to open directory");
            continue;
        }

        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            // Check if the file is an image (example for JPEG and PNG)
            if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg") ||
                strstr(entry->d_name, ".png")) {
                snprintf(metadata_array[actual_images].filename, sizeof(metadata_array[actual_images].filename),
                         "%s/%s", file_paths[i], entry->d_name);
                // Simulate metadata retrieval (e.g., using a library like libexif)
                metadata_array[actual_images].width = 800; // Example width
                metadata_array[actual_images].height = 600; // Example height
                ++actual_images;
            }
        }

        closedir(dir);
    }

    *total_images = actual_images;
    return metadata_array;
}

int main() {
    char* file_paths[] = {"/path/to/images1", "/path/to/images2"};
    int num_paths = sizeof(file_paths) / sizeof(file_paths[0]);
    int total_images;

    ImageMetadata* metadata = process_image_file_paths(file_paths, num_paths, &total_images);
    if (metadata) {
        printf("Total images: %d\n", total_images);
        for (int i = 0; i < total_images; ++i) {
            printf("Image: %s, Width: %d, Height: %d\n",
                   metadata[i].filename, metadata[i].width, metadata[i].height);
        }
        free(metadata);
    } else {
        printf("Failed to process image file paths.\n");
    }

    return 0;
}
