unsigned int calculate_md5_hash(const char* input, unsigned char* output) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, input, strlen(input));
    MD5_Final(output, &md5);
    return 16; // Return the hash size
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_indications(int num_elements, const char* input_string, char* buffer, int max_allocation_size, unsigned int* actual_size) {
    if (num_elements <= 0 || max_allocation_size <= 0) {
        *actual_size = 0;
        return NULL;
    }

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_required_size = num_elements * structure_size + calculate_md5_hash(input_string, NULL);

    if (total_required_size > max_allocation_size) {
        *actual_size = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)buffer;

    for (int i = 0; i < num_elements; ++i) {
        result[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
