#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    char* content;
    int length;
} TextLine;

size_t safe_add(size_t a, size_t b) {
    if (b > SIZE_MAX - a) {
        fprintf(stderr, "Integer overflow detected\n");
        exit(EXIT_FAILURE);
    }
    return a + b;
}

size_t count_lines_in_file(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    size_t line_count = 0;
    int ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }

    fclose(file);
    return line_count;
}

TextLine* read_files(const char* paths[], size_t num_paths, size_t* total_lines) {
    *total_lines = 0;

    for (size_t i = 0; i < num_paths; i++) {
        *total_lines += count_lines_in_file(paths[i]);
    }

    TextLine* lines = malloc((*total_lines) * sizeof(TextLine));
    if (!lines) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t index = 0;
    for (size_t i = 0; i < num_paths; i++) {
        FILE* file = fopen(paths[i], "r");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        int ch;
        while ((ch = fgetc(file)) != EOF) {
            if (ch == '\n') {
                lines[index].length = 0;
                lines[index].content = realloc(lines[index].content, lines[index].length + 1);
                if (!lines[index].content) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    exit(EXIT_FAILURE);
                }
                lines[index].content[lines[index].length] = '\0';
                index++;
            } else {
                lines[index].length = safe_add(lines[index].length, 1);
                lines[index].content = realloc(lines[index].content, lines[index].length + 1);
                if (!lines[index].content) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    exit(EXIT_FAILURE);
                }
                lines[index].content[lines[index].length - 1] = ch;
            }
        }

        fclose(file);
    }

    return lines;
}

int main() {
    const char* paths[] = {"file1.txt", "file2.txt", "file3.txt"};
    size_t total_lines;
    TextLine* lines = read_files(paths, sizeof(paths) / sizeof(paths[0]), &total_lines);

    for (size_t i = 0; i < total_lines; i++) {
        printf("Line %zu: %s\n", i + 1, lines[i].content);
        free(lines[i].content);
    }

    free(lines);
    return 0;
}
