#define MAX_ALLOCATION_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t current_allocation_size;
} AllocationManager;

AllocationManager allocation_manager = {PTHREAD_MUTEX_INITIALIZER, 0};

void* allocate_memory(size_t num_structures) {
    pthread_mutex_lock(&allocation_manager.mutex);
    if (num_structures > MAX_ALLOCATION_SIZE - allocation_manager.current_allocation_size) {
        pthread_mutex_unlock(&allocation_manager.mutex);
        return NULL; // Allocation would exceed max allowed
    }
    size_t total_size = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* memory = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (memory == NULL) {
        pthread_mutex_unlock(&allocation_manager.mutex);
        return NULL; // Memory allocation failed
    }
    for (size_t i = 0; i < num_structures; i++) {
        memory[i].RX_UE_INFORMATION_TAG = rand();
        memory[i].RNTI = rand() % 1024;
        memory[i].CRC_INDICATION_REL8_TAG = rand() % 1024;
        memory[i].CRCFLAG = rand() & 1; // Randomly set to 0 or 1
    }
    allocation_manager.current_allocation_size += num_structures;
    pthread_mutex_unlock(&allocation_manager.mutex);
    return memory;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T* memory, size_t num_structures) {
    pthread_mutex_lock(&allocation_manager.mutex);
    free(memory);
    allocation_manager.current_allocation_size -= num_structures;
    pthread_mutex_unlock(&allocation_manager.mutex);
}

int main() {
    size_t num_structures = 512; // Example input
    NFAPI_CRC_INDICATION_PDU_T* memory = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(num_structures);
    if (memory == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }
    // Use the allocated memory...
    free_memory(memory, num_structures);
    return 0;
}
