typedef struct PacketHeader {
    int header_length;
    int payload_length;
    char* payload;
} PacketHeader;

PacketHeader* process_packet_headers(int* header_lengths, int* payload_sizes, int count) {
    PacketHeader* packet_array = (PacketHeader*)malloc(count * sizeof(PacketHeader));
    if (!packet_array) {
        perror("Failed to allocate memory for packet headers");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        if (payload_sizes[i] > MAX_PACKET_SIZE) {
            fprintf(stderr, "Payload size too large for packet %d\n", i);
            free(packet_array);
            return NULL;
        }

        packet_array[i].header_length = sizeof(PacketHeader);
        packet_array[i].payload_length = payload_sizes[i];
        packet_array[i].payload = (char*)malloc(payload_sizes[i]);
        if (!packet_array[i].payload) {
            perror("Failed to allocate memory for payload");
            // Free previously allocated headers and payloads
            for (int j = 0; j < i; j++) {
                free(packet_array[j].payload);
            }
            free(packet_array);
            return NULL;
        }
    }

    return packet_array;
}

void free_packet_headers(PacketHeader* packet_array, int count) {
    for (int i = 0; i < count; i++) {
        free(packet_array[i].payload);
    }
    free(packet_array);
}
