    PacketBatch* batch = (PacketBatch*)arg;

    for (int i = 0; i < batch->num_packets; i++) {
        if (batch->packets[i]->size > MAX_PAYLOAD_SIZE) {
            printf("Warning: Payload size exceeds maximum limit. Processing may be limited.\n");
