    pthread_t threads[num_batches];
    PacketBatch batches[num_batches];

    for (int i = 0; i < num_batches; i++) {
        batches[i].num_packets = rand() % 10 + 1; // Random number of packets between 1 and 10
        batches[i].packets = malloc(batches[i].num_packets * sizeof(Packet*));

