// Define PacketHeader structure
typedef struct {
    int header_length;
    int payload_length;
    char *payload_data;
} PacketHeader;

// Function to create a new PacketHeader with allocated memory for the payload
PacketHeader* CreatePacketHeader(int header_len, int payload_len) {
    PacketHeader *packet = (PacketHeader*)malloc(sizeof(PacketHeader));
    packet->header_length = header_len;
    packet->payload_length = payload_len;
    packet->payload_data = (char*)malloc(payload_len);
    return packet;
}

// Function to free the memory allocated for a PacketHeader
void FreePacketHeader(PacketHeader *packet) {
    if (packet != NULL) {
        free(packet->payload_data);
        free(packet);
    }
}

// Function to generate random float and integer values within a specified range
float GenerateRandomFloat(float min, float max) {
    return ((max - min) * ((float)rand() / RAND_MAX)) + min;
}

int GenerateRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Class to manage the range and provide random value generation
typedef struct {
    float min_value;
    float max_value;
} RangeManager;

void SetRange(RangeManager *manager, float min_val, float max_val) {
    manager->min_value = min_val;
    manager->max_value = max_val;
}

float GenerateRandomFloatInRange(RangeManager *manager) {
    return GenerateRandomFloat(manager->min_value, manager->max_value);
}

int GenerateRandomIntInRange(RangeManager *manager) {
    return GenerateRandomInt((int)manager->min_value, (int)manager->max_value);
}

// Override ToString method to display the range of values
void ToString(RangeManager *manager) {
    printf("Range: %.2f to %.2f\n", manager->min_value, manager->max_value);
}

// Function to process network packets asynchronously
void ProcessNetworkPackets() {
    // Example usage
    PacketHeader *packet = CreatePacketHeader(10, 1024);
    RangeManager range_manager;
    SetRange(&range_manager, 0.0f, 100.0f);

    float random_float = GenerateRandomFloatInRange(&range_manager);
    int random_int = GenerateRandomIntInRange(&range_manager);

    printf("Random Float: %.2f\n", random_float);
    printf("Random Int: %d\n", random_int);

    ToString(&range_manager);

    FreePacketHeader(packet);
}
