unsigned char *buffer = NULL;
size_t buffer_size = 0;

void* process_packets(void* arg) {
    int connection_id = *(int*)arg;
    // Simulate packet processing
    pthread_mutex_lock(&buffer_lock);
    if (connection_count < MAX_CONNECTIONS) {
        connections[connection_count++] = (NetworkConnection){.connection_id = connection_id};
        buffer_size += 1024; // Example size increment for each connection
        buffer = realloc(buffer, buffer_size);
    } else {
        fprintf(stderr, "Maximum connections reached\n");
    }
    pthread_mutex_unlock(&buffer_lock);

    // Perform checksum verification and other operations

    return NULL;
}

int main() {
