    int ids[MAX_CONNECTIONS];

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        ids[i] = i;
        pthread_create(&threads[i], NULL, process_packets, &ids[i]);
    }

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(buffer);

    return 0;
}
