#define MAX_STRUCTURES 1000000
#define MEM_THRESHOLD (MAX_STRUCTURES * NFAPI_CRC_INDICATION_PDU_T_SIZE)

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint8_t crcflag;
