pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES] = {NULL};
int structure_count = 0;

int allocate_structures(int N) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&memory_lock);
    int required_memory = N * NFAPI_CRC_INDICATION_PDU_T_SIZE;
    if (required_memory + structure_count * NFAPI_CRC_INDICATION_PDU_T_SIZE > MEM_THRESHOLD || required_memory < 0) {
        pthread_mutex_unlock(&memory_lock);
        return -2; // Memory limit exceeded or integer overflow
    }

    for (int i = 0; i < N; i++) {
        structures[structure_count] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE);
        if (!structures[structure_count]) {
            pthread_mutex_unlock(&memory_lock);
            return -3; // Memory allocation failed
        }
        structure_count++;
    }

    pthread_mutex_unlock(&memory_lock);
    return 0;
}

void free_structures() {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < structure_count; i++) {
        free(structures[i]);
    }
    memset(structures, 0, sizeof(structures));
    structure_count = 0;
    pthread_mutex_unlock(&memory_lock);
}

void log_structure_creation(int index) {
    if (index >= 0 && index < structure_count) {
        // Log creation of structure
        printf("Structure created at index %d\n", index);
    }
}
