#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

ListNode* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int safe_allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        return -1;
    }
    return 0;
}

void safe_free_memory(void* ptr) {
    free(ptr);
}

ListNode* create_new_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* new_node = (ListNode*)safe_allocate_memory(sizeof(ListNode));
    if (!new_node) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    ListNode* new_node = create_new_node(data);
    if (new_node) {
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&mutex);
}

void free_linked_list() {
    ListNode* current = head;
    while (current) {
        pthread_mutex_lock(&mutex);
        ListNode* temp = current;
        current = current->next;
        safe_free_memory(temp);
        pthread_mutex_unlock(&mutex);
    }
    head = NULL;
}

int generate_random_crc_flag() {
