#include <stdio.h>
#include <stdlib.h>

// Define the structure for a header
typedef struct Header {
    int id;
    // Add other header fields here
    struct Header *next;
} Header;

// Define the structure for a packet
typedef struct Packet {
    int packet_id;
    Header *headers;
    struct Packet *next;
} Packet;

// Function to create a new header
Header* create_header(int id) {
    Header* header = (Header*)malloc(sizeof(Header));
    if (!header) {
        fprintf(stderr, "Memory allocation failed for header\n");
        exit(EXIT_FAILURE);
    }
    header->id = id;
    header->next = NULL;
    return header;
}

// Function to add a header to a packet
void add_header_to_packet(Packet* packet, int id) {
    Header* new_header = create_header(id);
    if (!packet->headers) {
        packet->headers = new_header;
    } else {
        Header* current = packet->headers;
        while (current->next) {
            current = current->next;
        }
        current->next = new_header;
    }
}

// Function to create a new packet
Packet* create_packet(int packet_id) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed for packet\n");
        exit(EXIT_FAILURE);
    }
    packet->packet_id = packet_id;
    packet->headers = NULL;
    packet->next = NULL;
    return packet;
}

// Function to add a packet to the linked list
void add_packet_to_list(Packet** head, Packet* new_packet) {
    if (*head == NULL) {
        *head = new_packet;
    } else {
        Packet* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_packet;
    }
}

// Function to process a packet stream
void process_packet_stream(int max_headers_per_packet, int max_total_headers) {
    // Initialize variables for packet and header counting
    Packet* head = NULL;
    int total_headers = 0;

    // Simulate receiving packets (this would be replaced by actual data source)
    for (int i = 1; i <= 1000; i++) {
        Packet* new_packet = create_packet(i);
        // Add headers to the packet (this could also be done asynchronously)
        for (int j = 1; j <= max_headers_per_packet && total_headers < max_total_headers; j++) {
            add_header_to_packet(new_packet, j);
            total_headers++;
        }
        add_packet_to_list(&head, new_packet);

        // Check if adding more headers would exceed the limit
        if (total_headers >= max_total_headers) {
            fprintf(stderr, "Maximum number of headers reached\n");
            break;
        }
    }

    // Process the linked list of packets (this could be done in parallel)
    Packet* current = head;
    while (current) {
        // Process packet
        printf("Processing packet %d with headers: ", current->packet_id);
        Header* header = current->headers;
        while (header) {
            printf("%d ", header->id);
            header = header->next;
        }
        printf("\n");

        Packet* next_packet = current->next;
        // Free the packet's headers
        Header* current_header = current->headers;
        while (current_header) {
            Header* temp = current_header;
            current_header = current_header->next;
            free(temp);
        }
        free(current);
        current = next_packet;
    }
}

int main() {
    const int MAX_HEADERS_PER_PACKET = 10;
    const int MAX_TOTAL_HEADERS = 5000;

    process_packet_stream(MAX_HEADERS_PER_PACKET, MAX_TOTAL_HEADERS);

    return 0;
}
