typedef struct PacketHeader {
    int payloadSize;
} PacketHeader;

int processNetworkPackets(PacketHeader* headers, int numHeaders, size_t maxMemory) {
    if (headers == NULL || numHeaders <= 0 || maxMemory == 0) {
        return -1; // Invalid input
    }

    size_t totalAllocated = 0;
    for (int i = 0; i < numHeaders; i++) {
        // Robust check for integer overflow during allocation
        if (headers[i].payloadSize > SIZE_MAX / sizeof(char *)) {
            return -2; // Potential integer overflow
        }
        size_t requiredMemory = headers[i].payloadSize * sizeof(char *);

        // Check for under-allocation risk
        char* payload = malloc(requiredMemory);
        if (payload == NULL) {
            return -3; // Memory allocation failed
        }

        totalAllocated += requiredMemory;

        // Simulate processing the packet header and payload
        free(payload); // Free memory after use
    }

    // Check for excessive allocation
    if (totalAllocated > maxMemory) {
        return -4; // Exceeded maximum allowed memory
    }

    return 0; // Success
}

int main() {
    PacketHeader headers[] = {{10}, {20}, {30}};
    int result = processNetworkPackets(headers, 3, 1000);
    printf("Result: %d\n", result);

    return 0;
}
