#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define MAX_BUFFER_SIZE (1024 * 1024)

typedef struct Packet {
    char payload[MAX_PACKET_SIZE];
    time_t timestamp;
} Packet;

typedef struct PacketBuffer {
    Packet* packets;
    size_t count;
    size_t capacity;
    size_t total_size;
} PacketBuffer;

int initialize_buffer(PacketBuffer* buffer) {
    buffer->packets = (Packet*)malloc(MAX_BUFFER_SIZE);
    if (!buffer->packets) {
        return -1; // Memory allocation failed
    }
    buffer->count = 0;
    buffer->capacity = MAX_BUFFER_SIZE / sizeof(Packet);
    buffer->total_size = 0;
    return 0;
}

int add_packet(PacketBuffer* buffer, const Packet* packet) {
    if (buffer->total_size + sizeof(Packet) > buffer->capacity) {
        return -1; // Buffer overflow
    }
    memcpy(&buffer->packets[buffer->count], packet, sizeof(Packet));
    buffer->count++;
    buffer->total_size += sizeof(Packet);
    return 0;
}

void free_buffer(PacketBuffer* buffer) {
    free(buffer->packets);
    buffer->packets = NULL;
    buffer->count = 0;
    buffer->capacity = 0;
    buffer->total_size = 0;
}
