#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_CAPACITY 10

typedef struct Packet {
    size_t payload_size;
    char *payload;
} Packet;

typedef struct PacketBuffer {
    size_t capacity;
    size_t count;
    Packet **packets;
    void (*parse_header)(char *, Packet *);
} PacketBuffer;

void init_packet_buffer(PacketBuffer *buffer, void (*parse_header_func)(char *, Packet *)) {
    buffer->capacity = INITIAL_CAPACITY;
    buffer->count = 0;
    buffer->packets = (Packet **)malloc(buffer->capacity * sizeof(Packet *));
    buffer->parse_header = parse_header_func;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    for (size_t i = 0; i < buffer->count; i++) {
        free(buffer->packets[i]->payload);
        free(buffer->packets[i]);
    }
    free(buffer->packets);
}

int add_packet(PacketBuffer *buffer, char *packet_data, size_t max_payload_size) {
    if (buffer->count >= buffer->capacity) {
        buffer->capacity *= 2;
        Packet **new_packets = (Packet **)realloc(buffer->packets, buffer->capacity * sizeof(Packet *));
        if (!new_packets) return -1;
        buffer->packets = new_packets;
    }

    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) return -1;

    packet->payload_size = strlen(packet_data);
    if (packet->payload_size > max_payload_size) {
        free(packet);
        return -2;
    }

    packet->payload = (char *)malloc((packet->payload_size + 1) * sizeof(char));
    if (!packet->payload) {
        free(packet);
        return -3;
    }

    strcpy(packet->payload, packet_data);

    buffer->packets[buffer->count++] = packet;

    buffer->parse_header(packet_data, packet);

    return 0;
}

void process_packets(PacketBuffer *buffer, void (*process_payload)(Packet *)) {
    for (size_t i = 0; i < buffer->count; i++) {
        process_payload(buffer->packets[i]);
    }
}
