NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, int IV_len, int Key_len, const char* password) {
    if (N <= 0 || IV_len <= 0 || Key_len <= 0 || password == NULL) {
        return NULL;
    }

    size_t total_size = (size_t)N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((total_size / N) != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Handle integer overflow
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (array == NULL) {
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(array);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, (unsigned char*)array)) {
        EVP_CIPHER_CTX_free(ctx);
        free(array);
        return NULL;
    }

    // Initialize IV
    unsigned char iv[IV_len];
    if (!RAND_bytes(iv, IV_len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(array);
        return NULL;
    }

    // Set IV in the context (assuming IV is of the correct length)
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, password, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        free(array);
        return NULL;
    }

    // Disable cipher when done
    EVP_CIPHER_CTX_free(ctx);

    return array;
}
