} ImageInfo;

int process_image_files(const char *env_var, size_t memory_limit) {
    const char *img_paths = getenv(env_var);
    if (!img_paths || !*img_paths) {
        fprintf(stderr, "Environment variable %s is not set or empty.\n", env_var);
        return -1;
    }

    ImageInfo *image_info = NULL;
    size_t num_files = 0;
    size_t total_size = 0;

    DIR *dir = opendir(".");
    if (!dir) {
        perror("opendir");
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", img_paths, entry->d_name);

        struct stat st;
        if (stat(path, &st) != 0) {
            perror("stat");
            continue;
        }

        if (S_ISREG(st.st_mode)) {
            ImageInfo *new_image_info = realloc(image_info, (num_files + 1) * sizeof(ImageInfo));
            if (!new_image_info) {
                fprintf(stderr, "Memory allocation failed.\n");
                free(image_info);
                closedir(dir);
                return -1;
            }
            image_info = new_image_info;

            // Simulate reading image data and metadata
            image_info[num_files].path = strdup(path);
            image_info[num_files].width = rand() % 2048 + 1; // Random width between 1 and 2048
            image_info[num_files].height = rand() % 2048 + 1; // Random height between 1 and 2048

            total_size += sizeof(ImageInfo) + strlen(path);

            if (total_size > memory_limit) {
                fprintf(stderr, "Memory limit exceeded.\n");
                for (size_t i = 0; i <= num_files; ++i)
                    free(image_info[i].path);
                free(image_info);
                closedir(dir);
                return -1;
            }

            num_files++;
        }
    }

    closedir(dir);

    // Simulate image processing using an external library
    for (size_t i = 0; i < num_files; ++i) {
        printf("Processing image: %s\n", image_info[i].path);
        // Add code to use the external library here

        free(image_info[i].path);
    }

    free(image_info);

    return 0;
}

int main() {
    size_t memory_limit = 1024 * 1024; // 1 MB
    return process_image_files("IMG_PATHS", memory_limit);
}
