    int protocol_type;
} PacketMetadata;

PacketMetadata* initialize_packet_metadata(size_t num_packets, const unsigned char *secret_key, size_t key_len) {
    // Error handling for invalid inputs
    if (num_packets == 0 || secret_key == NULL || key_len == 0) {
        return NULL;
    }

    // Custom allocator to mitigate integer overflow risk
    size_t total_size = num_packets * sizeof(PacketMetadata);
    if ((total_size / num_packets) != sizeof(PacketMetadata)) {
        return NULL; // Integer overflow detected
    }

    PacketMetadata* packet_array = (PacketMetadata*)malloc(total_size);
    if (packet_array == NULL) {
        return NULL; // Memory allocation failed
    }

    HMAC_CTX *ctx = HMAC_CTX_new();
    if (ctx == NULL) {
        free(packet_array); // Clean up on failure
        return NULL;
    }

    if (!HMAC_Init_ex(ctx, secret_key, key_len, EVP_sha256(), NULL)) {
        HMAC_CTX_free(ctx);
        free(packet_array); // Clean up on failure
        return NULL;
    }

    // Initialize packet array and HMAC context
    for (size_t i = 0; i < num_packets; ++i) {
        memset(&packet_array[i], 0, sizeof(PacketMetadata));
    }

    // Disable the HMAC context after use
    HMAC_Final(NULL, NULL, ctx);
    HMAC_CTX_free(ctx);

    return packet_array;
}
