#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned char* payload;
    size_t size;
} NetworkPacket;

typedef struct {
    NetworkPacket** packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PacketList;

void init_packet_list(PacketList* list, size_t initial_capacity) {
    list->packets = (NetworkPacket**)malloc(initial_capacity * sizeof(NetworkPacket*));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_packet_list(PacketList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->mutex);
}

void add_packet_to_list(PacketList* list, unsigned char* payload, size_t size) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->packets = realloc(list->packets, new_capacity * sizeof(NetworkPacket*));
        pthread_mutex_lock(&list->mutex);
        list->capacity = new_capacity;
        pthread_mutex_unlock(&list->mutex);
    }

    NetworkPacket* packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    packet->payload = (unsigned char*)realloc(packet->payload, size);
    memcpy(packet->payload, payload, size);
    packet->size = size;

    pthread_mutex_lock(&list->mutex);
    list->packets[list->count++] = packet;
    pthread_mutex_unlock(&list->mutex);
}

// Example usage
int main() {
    PacketList list;
    init_packet_list(&list, 10);

    unsigned char payload1[] = "Packet 1";
    add_packet_to_list(&list, payload1, sizeof(payload1));

    unsigned char payload2[] = "Packet 2";
    add_packet_to_list(&list, payload2, sizeof(payload2));

    // ...

    free_packet_list(&list);
    return 0;
}
```

This code provides a basic implementation of the required functionality. It includes a `NetworkPacket` structure to hold packet data and a `PacketList` structure to manage a list of packets. The `init_packet_list` function initializes the packet list with a given capacity, while the `free_packet_list` function frees all allocated memory for the packet list and its contents.

The `add_packet_to_list` function adds a new packet to the list, reallocating memory as necessary if the list is full. It also handles memory allocation for the packet payload and copies the data into the newly allocated memory.

The code uses mutex locks to ensure thread safety when accessing shared resources. The example usage in the `main` function demonstrates how to initialize the packet list, add packets, and free the list when done.

Note that this implementation provides a basic starting point and may need further enhancements to fully meet the requirements of the task.']

