        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T** manage_crc_indication_list(int N) {
    static NFAPI_CRC_INDICATION_PDU_T* pool[MAX_N] = { NULL };
    static int pool_size = 0;

    if (N > MAX_N || N <= 0) {
        fprintf(stderr, "Invalid number of elements\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        if (pool[i] == NULL) {
            pool[i] = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pool_size++;
        }
        pool[i]->rx_ue_tag = generate_rx_ue_tag(); // Assume this function is defined
        pool[i]->rnti = generate_rnti(); // Assume this function is defined
        pool[i]->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

