#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_FRAME_COUNT 100000
#define MAX_PAYLOAD_SIZE 1024 * 1024

typedef struct FRAME_DATA {
    int id;
    time_t timestamp;
    size_t payload_size;
    int* dependencies;
    int dependency_count;
} FRAME_DATA;

typedef struct LIST_NODE {
    FRAME_DATA data;
    struct LIST_NODE* next;
} LIST_NODE;

LIST_NODE* create_list_node(FRAME_DATA data) {
    LIST_NODE* new_node = (LIST_NODE*)malloc(sizeof(LIST_NODE));
    if (new_node == NULL) {
        perror("Failed to allocate memory for list node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_frame_into_list(LIST_NODE** head, FRAME_DATA data) {
    LIST_NODE* new_node = create_list_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        LIST_NODE* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void free_frame_data(FRAME_DATA data) {
    free(data.dependencies);
}

void free_list(LIST_NODE** head) {
    LIST_NODE* current = *head;
    while (current != NULL) {
        LIST_NODE* next = current->next;
        free_frame_data(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}

int process_frames(int frame_count, FRAME_DATA frames[]) {
    if (frame_count > MAX_FRAME_COUNT || frames[0].payload_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Frame count or payload size exceeds safe limits\n");
        return -1;
    }

    LIST_NODE* head = NULL;

    for (int i = 0; i < frame_count; i++) {
        insert_frame_into_list(&head, frames[i]);
    }

    // Implement your processing logic here

    free_list(&head);

    return 0;
}

int main() {
    srand(time(NULL));

    FRAME_DATA frames[10];
    for (int i = 0; i < 10; i++) {
        frames[i].id = i + 1;
        frames[i].timestamp = time(NULL);
        frames[i].payload_size = rand() % MAX_PAYLOAD_SIZE;
        frames[i].dependencies = NULL;
        frames[i].dependency_count = rand() % 5;
    }

    process_frames(10, frames);

    return 0;
}
