#include <pthread.h>

#define MAX_IMAGES 10000

typedef struct {
    int resolution;
    int color_depth;
    size_t file_size;
} JPEGImage;

JPEGImage *image_pool[MAX_IMAGES];
int pool_index = 0;

void log_event(const char *operation, int num_elements) {
    time_t now = time(NULL);
    printf("[%s] %s: %d elements\n", ctime(&now), operation, num_elements);
}

void *allocate_image() {
    if (pool_index >= MAX_IMAGES) {
        return NULL;
    }
    JPEGImage *image = malloc(sizeof(JPEGImage));
    if (image == NULL) {
        log_event("Memory allocation failed", 1);
        return NULL;
    }
    image_pool[pool_index++] = image;
    log_event("Image allocated", pool_index);
    return image;
}

void free_image(void *ptr) {
    int index = -1;
    for (int i = 0; i < pool_index; i++) {
        if (image_pool[i] == ptr) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        free(ptr);
        for (int i = index; i < pool_index - 1; i++) {
            image_pool[i] = image_pool[i + 1];
        }
        pool_index--;
        log_event("Image freed", pool_index);
    } else {
        log_event("Invalid image pointer", 0);
    }
}

void *allocate_images(int N) {
    if (N <= 0 || N > MAX_IMAGES) {
        log_event("Invalid number of images", N);
        return NULL;
    }

    void **image_array = malloc(N * sizeof(void *));
    if (image_array == NULL) {
        log_event("Memory allocation failed for image array", N);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        image_array[i] = allocate_image();
        if (image_array[i] == NULL) {
            // Free previously allocated images
            for (int j = 0; j < i; j++) {
                free_image(image_array[j]);
            }
            free(image_array);
            log_event("Failed to allocate all images", N);
            return NULL;
        }
    }

    log_event("Images allocated", N);
    return image_array;
}

void free_images(void **image_array, int N) {
    if (N <= 0 || N > MAX_IMAGES) {
        log_event("Invalid number of images", N);
        return;
    }

    for (int i = 0; i < N; i++) {
        free_image(image_array[i]);
    }
    free(image_array);
    log_event("Images freed", N);
}

// Thread-safe version using mutex
pthread_mutex_t mutex;

void *allocate_images_threadsafe(int N) {
    pthread_mutex_lock(&mutex);
    void *result = allocate_images(N);
    pthread_mutex_unlock(&mutex);
    return result;
}

void free_images_threadsafe(void **image_array, int N) {
    pthread_mutex_lock(&mutex);
    free_images(image_array, N);
    pthread_mutex_unlock(&mutex);
}
