#define MAX_IP_ADDRESSES 10

typedef struct u_char_node {
    u_char data;
    struct u_char_node *next;
} u_char_node;

u_char_node* create_u_char_node(u_char data) {
    u_char_node *new_node = (u_char_node*)malloc(sizeof(u_char_node));
    if (new_node == NULL) {
        syslog(LOG_ERR, "Memory allocation failed for u_char_node");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_u_char_list(u_char_node *head) {
    while (head != NULL) {
        u_char_node *temp = head;
        head = head->next;
        free(temp);
    }
}

u_char_node* resolve_hostname(const char *hostname) {
    struct hostent *host_entry = gethostbyname(hostname);
    if (host_entry == NULL) {
        syslog(LOG_ERR, "DNS resolution failed for %s", hostname);
        return NULL;
    }

    u_char_node *head = NULL;
    int i = 0;
    while (i < MAX_IP_ADDRESSES && host_entry->h_addr_list[i] != NULL) {
        struct in_addr *ip_addr = (struct in_addr*)host_entry->h_addr_list[i];
        for (int j = 0; j < sizeof(struct in_addr); j++) {
            u_char_node *new_node = create_u_char_node(((u_char*)ip_addr)[j]);
            if (new_node == NULL) {
                free_u_char_list(head);
                return NULL;
            }
            new_node->next = head;
            head = new_node;
        }
        i++;
    }

    return head;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int max_limit, int rx_ue_info_tag, int rnti) {
    if (max_limit <= 0 || rx_ue_info_tag < 0 || rnti < 0) {
        syslog(LOG_ERR, "Invalid input values for creating CRC indication PDU");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        syslog(LOG_ERR, "Memory allocation failed for CRC indication PDU array");
        return NULL;
    }

    int count = 0;
    while (count < max_limit && pdus[count].rx_UE_information_tag != rx_ue_info_tag) {
        pdus[count].rx_UE_information_tag = rx_ue_info_tag;
        pdus[count].rnti = rnti;
        pdus[count].crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
        count++;
    }

    return pdus;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, int max_limit) {
    if (pdus != NULL) {
        free(pdus);
    }
}
