        image_list[i] = (JPEG_IMAGE_T*)malloc(sizeof(JPEG_IMAGE_T));
        if (image_list[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for image %d.\n", i);
            // Free previously allocated images
            for (int j = 0; j < i; j++) {
                free(image_list[j]);
            }
            free(image_list);
            return NULL;
        }

        // Populate IMAGE_HEADER and IMAGE_METADATA with valid data
        image_list[i]->header.width = rand() % 1920 + 1;
        image_list[i]->header.height = rand() % 1080 + 1;
        snprintf(image_list[i]->metadata.description, sizeof(image_list[i]->metadata.description), "Image %d", i);
        image_list[i]->metadata.timestamp = time(NULL);

        // Calculate and store the checksum
        image_list[i]->checksum = (unsigned int)((image_list[i]->header.width * image_list[i]->header.height) ^ (time(NULL)));
    }

    return image_list;
}

void free_jpeg_images(JPEG_IMAGE_T** image_list, int max_limit) {
