    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    int npdu_count;
    if (fscanf(file, "%d", &npdu_count) != 1 || npdu_count <= 0) {
        fprintf(stderr, "Invalid NPDU count in configuration file\n");
        fclose(file);
        return NULL;
    }

    if (npdu_count > MAX_NPDU) {
        fprintf(stderr, "Requested NPDU count exceeds maximum allowed: %d\n", MAX_NPDU);
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** pdus = malloc(npdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
        perror("Failed to allocate memory for NPDU array");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < npdu_count; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus[i]) {
            perror("Failed to allocate memory for NPDU structure");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(pdus[j]);
            }
            free(pdus);
            fclose(file);
            return NULL;
        }
    }

    printf("Successfully allocated %d NPDU structures\n", npdu_count);

    fclose(file);
    return pdus;
}

