    char path[MAX_PATH_LENGTH];
    off_t size;
} file_size_info_t;

int process_file_paths(const char *path_array[], int num_paths, file_size_info_t **file_infos, size_t max_memory) {
    if (num_paths <= 0 || !path_array || !file_infos || max_memory == 0) {
        return -1; // Invalid input
    }

    *file_infos = NULL;
    off_t total_size = 0;

    for (int i = 0; i < num_paths; ++i) {
        struct stat file_stat;
        if (stat(path_array[i], &file_stat) != 0 || !S_ISREG(file_stat.st_mode)) {
            printf("Invalid or non-regular file: %s\n", path_array[i]);
            continue;
        }

        if (total_size + file_stat.st_size > max_memory) {
            printf("Memory allocation limit exceeded for file: %s\n", path_array[i]);
            break;
        }

        (*file_infos) = realloc(*file_infos, (i + 1) * FILE_INFO_SIZE);
        if (!*file_infos) {
            printf("Failed to allocate memory for file info.\n");
            free(*file_infos);
            *file_infos = NULL;
            return -1;
        }

        strcpy((*file_infos)[i].path, path_array[i]);
        (*file_infos)[i].size = file_stat.st_size;
        total_size += file_stat.st_size;
    }

    if (total_size == 0) {
        free(*file_infos);
        *file_infos = NULL;
        return -1; // No valid files found
    }

    return i; // Number of successfully processed files
}
