NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_memory(size_t N) {
    if (N > MAX_N) {
        return NULL; // Prevent potential integer overflow
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random tag
        array[i].RNTI = rand() % 1024; // Random RNTI
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return array;
}
