#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILE_PATH_LENGTH 256
#define MIN_WIDTH 10
#define MIN_HEIGHT 10
#define MAX_WIDTH 10000
#define MAX_HEIGHT 10000

typedef struct {
    char file_path[MAX_FILE_PATH_LENGTH];
    int width;
    int height;
} image_metadata_t;

int validate_dimensions(int width, int height) {
    if (width < MIN_WIDTH || width > MAX_WIDTH ||
        height < MIN_HEIGHT || height > MAX_HEIGHT) {
        return 0; // Invalid dimensions
    }
    return 1; // Valid dimensions
}

int process_image_metadata(const char* file_paths[], int widths[], int heights[], int num_entries, image_metadata_t** metadata) {
    if (num_entries <= 0) {
        return -1; // No entries provided
    }

    *metadata = (image_metadata_t*)malloc(num_entries * sizeof(image_metadata_t));
    if (*metadata == NULL) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < num_entries; i++) {
        if (!validate_dimensions(widths[i], heights[i])) {
            free(*metadata);
            return -3; // Invalid dimensions found
        }
        strncpy((*metadata)[i].file_path, file_paths[i], MAX_FILE_PATH_LENGTH);
        (*metadata)[i].width = widths[i];
        (*metadata)[i].height = heights[i];
    }

    return num_entries; // Success
}

int main() {
    const char* file_paths[] = {"image1.jpg", "image2.png"};
    int widths[] = {800, 1920};
    int heights[] = {600, 1080};
    int num_entries = sizeof(file_paths) / sizeof(file_paths[0]);
    image_metadata_t* metadata;

    int result = process_image_metadata(file_paths, widths, heights, num_entries, &metadata);
    if (result < 0) {
        printf("Error: %d\n", result);
        return 1;
    }

    for (int i = 0; i < result; i++) {
        printf("File Path: %s, Width: %d, Height: %d\n", metadata[i].file_path, metadata[i].width, metadata[i].height);
    }

    free(metadata);

    return 0;
}
