typedef struct {
    char filename[256];
    size_t metadata_size;
} image_metadata_t;

int calculate_total_memory(image_metadata_t **metadata, char *directory, size_t max_memory) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    size_t total_memory = 0;
    int count = 0;

    dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);

        if (stat(path, &file_stat) == 0) {
            if (S_ISREG(file_stat.st_mode)) {
                // Estimate metadata size based on file size
                size_t estimated_metadata_size = file_stat.st_size / 1024; // Simplified estimation

                if ((total_memory + estimated_metadata_size) <= max_memory) {
                    (*metadata)[count].metadata_size = estimated_metadata_size;
                    strncpy((*metadata)[count].filename, entry->d_name, sizeof((*metadata)[count].filename) - 1);
                    (*metadata)[count].filename[sizeof((*metadata)[count].filename) - 1] = '\0';
                    total_memory += estimated_metadata_size;
                    count++;
                } else {
                    break; // Reached maximum memory limit
                }
            }
        } else {
            perror("Failed to get file stats");
            closedir(dir);
            return -1;
        }
    }

    closedir(dir);
    *metadata = realloc(*metadata, count * sizeof(image_metadata_t));
    if (!*metadata) {
        perror("Failed to reallocate memory");
        return -1;
    }

    return count;
}
