    ALLOC_FAILURE,
    ALLOC_RETRY
} AllocationStatus;

AllocationStatus allocateNFAPICRCIndicationPDUs(uint32_t N, uint32_t MAX_N, size_t MAX_SIZE) {
    if (N == 0 || N > MAX_N) {
        fprintf(stderr, "Invalid number of structures: %u\n", N);
        return ALLOC_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(*pdus));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for %u structures\n", N);
        return ALLOC_RETRY;
    }

    srand(time(NULL)); // Seed the random number generator
    for (uint32_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() & 0xFFFF;
        pdus[i].RNTI = rand() & 0xFFFF;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Use the allocated memory for further processing...

    free(pdus);
    return ALLOC_SUCCESS;
}

int main() {
    uint32_t N = 10; // Example number of structures
    uint32_t MAX_N = 1000; // Maximum allowed number of structures
    size_t MAX_SIZE = sizeof(NFAPI_CRC_INDICATION_PDU_T); // Size of each structure

    AllocationStatus status = allocateNFAPICRCIndicationPDUs(N, MAX_N, MAX_SIZE);
    if (status == ALLOC_FAILURE) {
        fprintf(stderr, "Failed to allocate memory after retries\n");
        return 1;
    }

    if (status == ALLOC_RETRY) {
        fprintf(stderr, "Retrying allocation...\n");
        while ((status = allocateNFAPICRCIndicationPDUs(N, MAX_N, MAX_SIZE)) == ALLOC_RETRY) {
            // Handle retry logic here
        }
    }

    return status == ALLOC_SUCCESS ? 0 : 1;
