    IMAGE_FORMAT_JPEG,
    IMAGE_FORMAT_PNG,
    IMAGE_FORMAT_BMP,
    // Add more formats as needed
} IMAGE_FORMAT_T;

typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t depth;
    IMAGE_FORMAT_T format;
    float compression_ratio;
    void *raw_data;
    void *format_header;
} IMAGE_DATA_T;

pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

IMAGE_DATA_T** allocate_image_array(size_t N, size_t max_resolution, uint8_t max_depth, size_t *allocated_size) {
    pthread_mutex_lock(&allocation_mutex);

    // Validate input parameters
    if (N == 0 || max_resolution == 0 || max_depth == 0) {
        perror("Invalid input parameters");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Calculate total size needed
    size_t total_size = N * sizeof(IMAGE_DATA_T*);
    for (size_t i = 0; i < N; ++i) {
        total_size += sizeof(IMAGE_DATA_T);
        total_size += max_resolution * max_resolution * max_depth / 8; // Approximate raw data size
        total_size += 128; // Estimated format header size
    }

    // Check for integer overflow
    if (total_size < N || total_size > SIZE_MAX) {
        perror("Integer overflow during memory allocation");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Allocate memory
    IMAGE_DATA_T **image_array = (IMAGE_DATA_T**)malloc(total_size);
    if (!image_array) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    *allocated_size = total_size;

    for (size_t i = 0; i < N; ++i) {
        image_array[i] = (IMAGE_DATA_T*)(image_array + N + i);
        memset(image_array[i], 0, sizeof(IMAGE_DATA_T));
        image_array[i]->width = max_resolution;
        image_array[i]->height = max_resolution;
        image_array[i]->depth = max_depth;
        // Initialize other fields as needed
    }

    pthread_mutex_unlock(&allocation_mutex);
    return image_array;
}

// Example usage
int main() {
    size_t N = 10;
    size_t max_resolution = 2048;
    uint8_t max_depth = 24;

    size_t allocated_size;
    IMAGE_DATA_T **image_array = allocate_image_array(N, max_resolution, max_depth, &allocated_size);

    if (image_array) {
        printf("Successfully allocated memory for %zu images\n", N);
        // Use the image_array as needed
        free(image_array);
    }

    return 0;
}
