#define MAX_PACKETS 1024
#define MAX_PAYLOAD_SIZE 65536 // Example: Max packet payload size
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int size;
    unsigned char* payload;
} Packet;

typedef struct {
    Packet* packets[MAX_PACKETS];
    int count;
    size_t total_memory_usage;
} PacketBuffer;

int allocate_packet(Packet* packet, int size) {
    if (size > MAX_PAYLOAD_SIZE) return -1; // Prevent oversized payloads
    packet->payload = (unsigned char*)malloc(size);
    if (!packet->payload) return -1; // Handle allocation failure
    packet->size = size;
    return 0;
}

void free_packet(Packet* packet) {
    if (packet->payload) {
        free(packet->payload);
        packet->payload = NULL;
        packet->size = 0;
    }
}

int add_packet_to_buffer(PacketBuffer* buffer, Packet* packet) {
    if (buffer->count >= MAX_PACKETS) return -1; // Buffer overflow protection
    if (buffer->total_memory_usage + packet->size > MEMORY_LIMIT) return -1; // Memory limit check

    buffer->packets[buffer->count++] = packet;
    buffer->total_memory_usage += packet->size;

    return 0;
}

void process_packets(PacketBuffer* buffer) {
    for (int i = 0; i < buffer->count; ++i) {
        // Process each packet here
        printf("Processing packet with size: %d\n", buffer->packets[i]->size);
        free_packet(buffer->packets[i]); // Free the packet after processing
    }
    buffer->count = 0;
    buffer->total_memory_usage = 0;
}

int main() {
    PacketBuffer buffer = { .count = 0, .total_memory_usage = 0 };
    Packet packets[MAX_PACKETS];

    for (int i = 1; i <= MAX_PACKETS; ++i) {
        if (allocate_packet(&packets[i - 1], i * 1024) == 0) {
            if (add_packet_to_buffer(&buffer, &packets[i - 1]) != 0) {
                free_packet(&packets[i - 1]);
            }
        } else {
            // Handle allocation failure
            break;
        }

        if (buffer.total_memory_usage >= MEMORY_LIMIT) {
            process_packets(&buffer);
        }
    }

    process_packets(&buffer); // Process any remaining packets

    return 0;
}
