['```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_PACKET_COUNT 10

typedef struct Packet {
    int size;
    char data[MAX_PACKET_SIZE];
} Packet;

typedef struct PacketQueue {
    Packet *packets;
    int front, rear, count;
    int capacity;
} PacketQueue;

PacketQueue* create_packet_queue(int initial_capacity) {
    PacketQueue *queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->capacity = initial_capacity > 0 ? initial_capacity : INITIAL_PACKET_COUNT;
    queue->packets = (Packet*)calloc(queue->capacity, sizeof(Packet));
    if (!queue->packets) {
        free(queue);
        return NULL;
    }

    queue->front = queue->rear = -1;
    queue->count = 0;

    return queue;
}

int is_full(PacketQueue *queue) {
    return (queue->count == queue->capacity);
}

int is_empty(PacketQueue *queue) {
    return (queue->count == 0);
}

int enqueue(PacketQueue *queue, Packet packet) {
    if (is_full(queue)) {
        // Handle memory overflow by dynamically resizing the queue
        int new_capacity = queue->capacity * 2;
        Packet *new_packets = (Packet*)realloc(queue->packets, new_capacity * sizeof(Packet));
        if (!new_packets) return -1; // Memory allocation failed

        queue->packets = new_packets;
        queue->capacity = new_capacity;
    }

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->packets[queue->rear] = packet;
    if (is_empty(queue)) {
        queue->front = queue->rear;
    }
    queue->count++;

    return 0; // Success
}

Packet dequeue(PacketQueue *queue) {
    Packet packet = {0};
    if (!is_empty(queue)) {
        packet = queue->packets[queue->front];
        queue->front = (queue->front + 1) % queue->capacity;
        queue->count--;
    }

    return packet;
}

void destroy_packet_queue(PacketQueue *queue) {
    free(queue->packets);
    free(queue);
}
```

This code provides a basic implementation of a `PacketQueue` structure to manage incoming network packets. The `create_packet_queue` function initializes the queue with an initial capacity, and the `enqueue` function adds a packet to the queue while handling memory overflow by dynamically resizing the queue when it reaches full capacity. The `dequeue` function removes a packet from the front of the queue. Finally, the `destroy_packet_queue` function cleans up the allocated resources.

Remember that this is a simplified example and may need further optimization and error checking depending on the specific requirements and constraints of your application.']

