#define MAX_PACKET_SIZE 1024

typedef struct {
    size_t header_length;
    char* data;
} PacketHeader;

PacketHeader* process_packets(const char* packet_stream, size_t stream_size, size_t initial_buffer_size, size_t* final_buffer_size) {
    size_t packet_count = 0, packet_start = 0;
    PacketHeader* headers = NULL;

    // Initial allocation
    headers = (PacketHeader*)malloc(initial_buffer_size * sizeof(PacketHeader));
    if (!headers) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    while (packet_start < stream_size) {
        size_t packet_length = 0;

        // Extract header length from packet_stream
        memcpy(&packet_length, &packet_stream[packet_start], sizeof(size_t));
        packet_start += sizeof(size_t);

        if (packet_start + packet_length > stream_size) {
            fprintf(stderr, "Invalid packet size detected\n");
            free(headers);
            return NULL;
        }

        // Check for integer overflow
        if ((packet_count + 1) * sizeof(PacketHeader) < (packet_count + 2) * sizeof(PacketHeader)) {
            size_t new_buffer_size = initial_buffer_size * 2;
            PacketHeader* temp_headers = (PacketHeader*)realloc(headers, new_buffer_size * sizeof(PacketHeader));
            if (!temp_headers) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(headers);
                return NULL;
            }
            headers = temp_headers;
        }

        // Populate packet header
        headers[packet_count].header_length = packet_length;
        headers[packet_count].data = (char*)malloc(packet_length);
        if (!headers[packet_count].data) {
            fprintf(stderr, "Memory allocation for packet data failed\n");
            free(headers);
            return NULL;
        }
        memcpy(headers[packet_count].data, &packet_stream[packet_start], packet_length);

        packet_start += packet_length;
        packet_count++;
    }

    *final_buffer_size = packet_count * sizeof(PacketHeader);
    return headers;
}

// Example usage
int main() {
    const char* packet_stream = "..."; // Simulated stream of network packets
    size_t stream_size = strlen(packet_stream);
    size_t initial_buffer_size = 100;
    size_t final_buffer_size;

    PacketHeader* headers = process_packets(packet_stream, stream_size, initial_buffer_size, &final_buffer_size);

    if (headers) {
        // Process packet headers and data
        free(headers);
    }

    return 0;
}
