#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_MEMORY_ALLOCATION_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryBlock {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock *memory_pool = NULL;
sem_t memory_semaphore;
int memory_allocated = 0;

void init_memory_pool(size_t initial_size) {
    if (initial_size > MAX_MEMORY_ALLOCATION_LIMIT) {
        fprintf(stderr, "Initial size exceeds maximum allowed memory allocation limit.\n");
        exit(EXIT_FAILURE);
    }

    sem_init(&memory_semaphore, 0, 1);
    MemoryBlock *block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    block->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    block->size = initial_size;
    block->next = NULL;

    memory_pool = block;
    memory_allocated += initial_size;
}

void destroy_memory_pool() {
    MemoryBlock *current = memory_pool;
    while (current) {
        MemoryBlock *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    sem_destroy(&memory_semaphore);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(size_t num_elements) {
    if ((size_t)memory_allocated + num_elements > MAX_MEMORY_ALLOCATION_LIMIT) {
        fprintf(stderr, "Memory allocation limit exceeded.\n");
        return NULL;
    }

    sem_wait(&memory_semaphore);

    MemoryBlock *current = memory_pool;
    while (current && current->size < num_elements) {
        current = current->next;
    }

    if (!current) {
        // Allocate new block if no suitable block found
        MemoryBlock *new_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
        size_t new_size = MAX_MEMORY_ALLOCATION_LIMIT - memory_allocated;
        new_block->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_block->size = new_size;
        new_block->next = NULL;

        current = new_block;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = current->data + (current->size - num_elements);
    current->size -= num_elements;
    memory_allocated += num_elements;

    sem_post(&memory_semaphore);

    return pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t num_elements) {
    sem_wait(&memory_semaphore);

    MemoryBlock *current = memory_pool;
    while (current && current->data + current->size != pdu) {
        current = current->next;
    }

    if (!current) {
        fprintf(stderr, "Invalid PDU pointer provided.\n");
        sem_post(&memory_semaphore);
        return;
    }

    current->size += num_elements;
    memory_allocated -= num_elements;

    sem_post(&memory_semaphore);
}

void* manage_pdus(void *arg) {
    size_t *num_elements = (size_t *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(*num_elements);

    if (!pdu) {
        fprintf(stderr, "Failed to allocate PDU.\n");
        return NULL;
    }

    // Populate PDU with data
    for (size_t i = 0; i < *num_elements; i++) {
        pdu[i].rx_ue_info_tag = /* initialize RX_UE_INFORMATION_TAG */;
        pdu[i].rnti = /* generate random RNTI */;
        pdu[i].crc_indication_tag.crcflag = /* set random CRCFLAG */;
    }

    // Process PDU
    // ...

    deallocate_pdu(pdu, *num_elements);

    return NULL;
}

int main() {
    size_t initial_pool_size = 1024; // Initial memory pool size in elements

    init_memory_pool(initial_pool_size);

    pthread_t threads[10];
    size_t num_elements = 50;

    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, manage_pdus, &num_elements) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            destroy_memory_pool();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool();

    return EXIT_SUCCESS;
}
