MemoryPool* create_memory_pool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->structures = NULL;
    pool->count = 0;
    pool->allocated_count = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < pool->allocated_count; i++) {
        free(pool->structures[i]);
    }
    free(pool->structures);
    free(pool);
}

int allocate_structures(MemoryPool* pool, int requested_count) {
    if ((pool->count + requested_count) > GLOBAL_MEMORY_LIMIT) {
        printf("Memory overflow warning: Exceeding global memory limit\n");
        requested_count = GLOBAL_MEMORY_LIMIT - pool->count;
    }

    NFAPI_CRC_INDICATION_PDU_T** new_structures = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pool->structures, (pool->allocated_count + requested_count) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!new_structures) {
        return -1; // Memory allocation failed
    }

    pool->structures = new_structures;

    for (int i = 0; i < requested_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structure) {
