        new_structure->RNTI = rand(); // Random value for demonstration
        new_structure->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        pool->structures[pool->allocated_count + i] = new_structure;
    }

    pool->count += requested_count;
    pool->allocated_count += requested_count;

    return requested_count;
}

void free_structures(MemoryPool* pool, int count) {
    if (count > pool->count) {
        printf("Error: Attempting to free more structures than allocated\n");
        return;
    }

    for (int i = 0; i < count; i++) {
        free(pool->structures[pool->allocated_count - 1]);
        pool->allocated_count--;
        pool->count--;
    }
}
