    ImageMetadata* metadata = malloc(*count * sizeof(ImageMetadata));
    if (!metadata) {
        fprintf(stderr, "Error: Unable to allocate memory for image metadata\n");
        fclose(file);
        return NULL;
    }

    // Read the image metadata
