compressed_image_t** allocate_compressed_images(int N) {
    if (N <= 0) {
        return NULL; // Handle invalid input
    }

    compressed_image_t** images = (compressed_image_t**)malloc(N * sizeof(compressed_image_t*));
    if (!images) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; ++i) {
        images[i] = (compressed_image_t*)malloc(sizeof(compressed_image_t));
        if (!images[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(images[j]);
            }
            free(images);
            return NULL;
        }

        images[i]->image_width = rand() % 1920 + 640; // Random width between 640 and 1920
        images[i]->image_height = rand() % 1080 + 480; // Random height between 480 and 1080

        size_t buffer_size = (size_t)images[i]->image_width * images[i]->image_height / 16;
        if (buffer_size > MAX_IMAGE_SIZE) {
            buffer_size = MAX_IMAGE_SIZE;
        }

        images[i]->compressed_data = (unsigned char*)malloc(buffer_size);
        if (!images[i]->compressed_data) {
            // Free previously allocated memory on failure
            free(images[i]);
            for (int j = 0; j < i; ++j) {
                free(images[j]);
            }
            free(images);
            return NULL;
        }

        // Initialize compressed data with random values
        for (size_t k = 0; k < buffer_size; ++k) {
            images[i]->compressed_data[k] = rand() % 256;
        }
    }

    return images;
}

void free_compressed_images(compressed_image_t** images, int N) {
    if (images) {
        for (int i = 0; i < N; ++i) {
            if (images[i]) {
                free(images[i]->compressed_data);
                free(images[i]);
            }
        }
        free(images);
    }
}

// Example usage
