    int N;
    printf("Enter the number of images: ");
    scanf("%d", &N);

    compressed_image_t** images = allocate_compressed_images(N);
    if (images) {
        // Use the images array
        free_compressed_images(images, N);
    } else {
        printf("Failed to allocate memory for images.\n");
    }

    return 0;
}
