#include <stdlib.h>
#include <string.h>

typedef struct {
    char file_path[256];
    int resolution_x;
    int resolution_y;
    unsigned char flags;
} TaskMetadata;

typedef struct MemoryNode {
    struct MemoryNode* next;
    void* data;
    size_t size;
} MemoryNode;

MemoryNode* memory_pool_head = NULL;

void* allocate_memory(size_t size) {
    if (size == 0) return NULL;
    MemoryNode* new_node = (MemoryNode*)malloc(sizeof(MemoryNode));
    if (!new_node) return NULL;
    new_node->data = malloc(size);
    if (!new_node->data) {
        free(new_node);
        return NULL;
    }
    new_node->size = size;
    new_node->next = memory_pool_head;
    memory_pool_head = new_node;
    return new_node->data;
}

void deallocate_memory(void* ptr) {
    MemoryNode** current = &memory_pool_head;
    while (*current) {
        if ((*current)->data == ptr) {
            MemoryNode* temp = *current;
            *current = temp->next;
            free(temp->data);
            free(temp);
            return;
        }
        current = &(*current)->next;
    }
}

TaskMetadata** create_task_list(int N, int max_tasks) {
    if (N > max_tasks) {
        printf("Exceeds maximum tasks. Reducing to %d.\n", max_tasks);
        N = max_tasks;
    }
    TaskMetadata** task_list = (TaskMetadata**)allocate_memory(N * sizeof(TaskMetadata*));
    if (!task_list) {
        printf("Failed to allocate memory for task list.\n");
        return NULL;
    }
    for (int i = 0; i < N; i++) {
        task_list[i] = (TaskMetadata*)allocate_memory(sizeof(TaskMetadata));
        if (!task_list[i]) {
            printf("Failed to allocate memory for task %d.\n", i);
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) deallocate_memory(task_list[j]);
            deallocate_memory(task_list);
            return NULL;
        }
    }
    return task_list;
}

void free_task_list(TaskMetadata** task_list, int N) {
    for (int i = 0; i < N; i++) {
        if (task_list[i]) deallocate_memory(task_list[i]);
    }
    deallocate_memory(task_list);
}

// Example usage
int main() {
    int N = 15000;
    TaskMetadata** tasks = create_task_list(N, 10000);
    if (tasks) {
        // Perform operations on tasks...
        free_task_list(tasks, N);
    }
    return 0;
}
```

