typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t memory_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* memory_pool[MAX_N] = {NULL};
int pool_index = 0;

void initialize_memory_pool() {
    for (int i = 0; i < MAX_N; i++) {
        memory_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to allocate memory for pool index %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_new_pdu() {
    pthread_mutex_lock(&memory_pool_mutex);
    if (pool_index >= MAX_N) {
        pthread_mutex_unlock(&memory_pool_mutex);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = memory_pool[pool_index++];
    pthread_mutex_unlock(&memory_pool_mutex);
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (int i = 0; i < MAX_N; i++) {
        if (memory_pool[i] == pdu) {
            pthread_mutex_lock(&memory_pool_mutex);
            memory_pool[i] = NULL;
            pool_index--;
            pthread_mutex_unlock(&memory_pool_mutex);
            return;
        }
    }
    fprintf(stderr, "Attempted to free a non-pool member\n");
}

int main() {
