            *error_code = -3; // Error: Individual memory allocation failed
            // Free previously allocated structures
            for (int j = 0; j < i; j++) {
                free(image_list[j]);
            }
            free(image_list);
            return NULL;
        }
    }

    *error_code = 0; // Success
    return image_list;
}

void populate_image_list(IMAGE_DATA_T** image_list, int N) {
    for (int i = 0; i < N; i++) {
        image_list[i]->width = rand() % 1024 + 1;
        image_list[i]->height = rand() % 768 + 1;
        snprintf(image_list[i]->format, sizeof(image_list[i]->format), "RGB%d", rand() % 3 + 1);
