    srand(time(NULL));

    int populated_count = 0;
    while (populated_count < N / 2) {
        JPEG_IMAGE_DATA_T* current_struct = &structs[populated_count];
        current_struct->IMAGE_WIDTH = rand() % 1920 + 1; // Random width between 1 and 1920
        current_struct->IMAGE_HEIGHT = rand() % 1080 + 1; // Random height between 1 and 1080
        current_struct->BITDEPTH = rand() % 33 + 1; // Random bitdepth between 1 and 32

        populated_count++;
    }

    pthread_mutex_unlock(mutex);

    return structs;
}

int main() {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int N = 500; // Example value for N
    JPEG_IMAGE_DATA_T* structs = allocate_and_populate_structs(N, &mutex);
    if (structs) {
        printf("Successfully allocated and populated %d structures\n", N);
        free(structs);
    }

