#define MAX_FILES 1000
#define MAX_FILE_SIZE 1024 * 1024 * 1024 // 1 GB

typedef struct {
    int sample_rate;
    int duration;
    int bitrate;
    int channels;
} AudioMetadata;

AudioMetadata* parse_audio_metadata(const char* input_file, int max_files) {
    FILE* file = fopen(input_file, "r");
    if (!file) {
        perror("Failed to open input file");
        return NULL;
    }

    int num_files;
    if (fscanf(file, "%d", &num_files) != 1 || num_files > max_files) {
        fprintf(stderr, "Invalid number of files or exceeds maximum limit\n");
        fclose(file);
        return NULL;
    }

    AudioMetadata* metadata = malloc(num_files * sizeof(AudioMetadata));
    if (!metadata) {
        perror("Failed to allocate memory for metadata");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < num_files; ++i) {
        if (fscanf(file, "%d %d %d %d", &metadata[i].sample_rate,
                      &metadata[i].duration, &metadata[i].bitrate,
                      &metadata[i].channels) != 4) {
            fprintf(stderr, "Failed to read metadata for file %d\n", i + 1);
            free(metadata);
            fclose(file);
            return NULL;
        }

        if (metadata[i].sample_rate <= 0 || metadata[i].duration <= 0 ||
            metadata[i].bitrate <= 0 || metadata[i].channels <= 0) {
            fprintf(stderr, "Invalid metadata for file %d\n", i + 1);
            free(metadata);
            fclose(file);
            return NULL;
        }

        if (metadata[i].sample_rate > MAX_FILE_SIZE || metadata[i].duration > MAX_FILE_SIZE ||
            metadata[i].bitrate > MAX_FILE_SIZE) {
            fprintf(stderr, "File size exceeds maximum allowable limit\n");
            free(metadata);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return metadata;
}

int main() {
    AudioMetadata* metadata = parse_audio_metadata("audio_files.txt", MAX_FILES);
    if (metadata) {
        // Process the parsed audio metadata
        printf("Processed %d audio files successfully\n", num_files);
        free(metadata);
    } else {
        fprintf(stderr, "Failed to process audio files\n");
    }

    return 0;
}
