typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    int allow_duplicates;
} LinkedList;

int initLinkedList(LinkedList* list, size_t max_size, int allow_duplicates) {
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    list->allow_duplicates = allow_duplicates;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

int insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory limit exceeded
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int checkDuplicate(LinkedList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti && !list->allow_duplicates) {
            return 1; // Duplicate RNTI found
        }
        current = current->next;
    }
    return 0;
}

int populateLinkedList(LinkedList* list, size_t N, int memory_limit, int allow_duplicates) {
    srand(time(NULL));
    for (size_t i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 1024; // Assuming RNTI is a small integer
        pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

        if (checkDuplicate(list, pdu.RNTI)) {
            printf("Error: Duplicate RNTI found\n");
            return -3;
        }

        int result = insertNode(list, pdu);
        if (result != 0) {
            printf("Error: Failed to insert node\n");
            return result;
        }
    }

    return 0;
}

int main() {
    LinkedList list;
    size_t max_size = MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    initLinkedList(&list, max_size, 1); // Allow duplicates for demonstration

    int result = populateLinkedList(&list, 1000, MAX_MEMORY_LIMIT, 1);
    if (result != 0) {
        printf("Failed to populate linked list\n");
        return result;
    }

    // Cleanup code here
    return 0;
}
```

This code provides a basic implementation of a thread-safe linked list with dynamic memory allocation and concurrency control. It includes functions for initializing the list, inserting nodes, checking for duplicates, and populating the list with random data. The example demonstrates how to handle memory limits, logging errors, and ensuring thread safety.']

