    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    CRCFLAG_NOT_SET = 0,
    CRCFLAG_SET
} CRC_FLAG_T;

typedef struct NFAPI_CRC_INDICATION_REL8_TAG {
    CRC_FLAG_T CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(size_t N) {
    if (N > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: Requested list size exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Error: Memory allocation failed. Error code: %d\n", errno);
            free_linked_list(head);
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = i; // Example value
        new_node->RNTI = i * 2; // Example value
        NFAPI_CRC_INDICATION_REL8_TAG *crc_tag = (NFAPI_CRC_INDICATION_REL8_TAG*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_REL8_TAG));
        if (!crc_tag) {
            fprintf(stderr, "Error: Memory allocation failed. Error code: %d\n", errno);
            free_linked_list(head);
            aligned_free(new_node);
            return NULL;
        }

        new_node->next = crc_tag;
        crc_tag->CRCFLAG = (i % 2 == 0) ? CRCFLAG_SET : CRCFLAG_NOT_SET;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        if (next && next != current->next) {
            aligned_free(next);
        }
        aligned_free(current);
        current = next;
    }
}

