#include <string.h>

typedef struct PacketSegment {
    int segment_length;
    int checksum;
    char *data;
    struct PacketSegment *next;
    struct PacketSegment *prev;
} PacketSegment;

PacketSegment* process_packet(int header_segment_length, int header_checksum) {
    if (header_segment_length <= 0 || header_checksum < 0) {
        return NULL; // Invalid header values
    }

    PacketSegment *segment = (PacketSegment *)malloc(sizeof(PacketSegment));
    if (!segment) {
        return NULL; // Memory allocation failed
    }

    segment->segment_length = header_segment_length;
    segment->checksum = header_checksum;

    segment->data = (char *)malloc(segment->segment_length);
    if (!segment->data) {
        free(segment);
        return NULL; // Memory allocation failed for data
    }

    memset(segment->data, 0, segment->segment_length); // Initialize data to zero

    segment->next = NULL;
    segment->prev = NULL;

    return segment;
}

void free_segments(PacketSegment *head) {
    while (head) {
        PacketSegment *temp = head;
        head = head->next;
        free(temp->data);
        free(temp);
    }
}
