    pthread_mutex_lock(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        fprintf(stderr, "Dynamic list is full\n");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_remove(DynamicList *list, RX_UE_INFORMATION_TAG ue_info_tag) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i].ue_info_tag == ue_info_tag) {
            for (int j = i; j < list->count - 1; j++) {
                list->elements[j] = list->elements[j + 1];
