typedef struct {
    time_t timestamp;
    size_t length;
    void* payload;
} PacketHeader;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
