void process_packets(const char* file_path, size_t max_memory) {
    if (max_memory < MIN_MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit too low. Minimum required: %zu bytes\n", MIN_MEMORY_LIMIT);
        return;
    }

    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    size_t total_images;
    if (fscanf(file, "%zu", &total_images) != 1 || total_images > MAX_IMAGES) {
        fprintf(stderr, "Invalid file format or corrupted data\n");
        fclose(file);
        return;
    }

    PacketHeader* headers = malloc(total_images * sizeof(PacketHeader));
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(total_images * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!headers || !crc_indications) {
        fprintf(stderr, "Memory allocation failed\n");
        free(headers);
        free(crc_indications);
        fclose(file);
        return;
    }

    size_t allocated_memory = 0;

    for (size_t i = 0; i < total_images; ++i) {
        size_t payload_length;
        if (fscanf(file, "%zu", &payload_length) != 1) {
            fprintf(stderr, "Invalid file format or corrupted data\n");
            free(headers);
            free(crc_indications);
            fclose(file);
            return;
        }

        if (allocated_memory + sizeof(PacketHeader) + payload_length > max_memory) {
            fprintf(stderr, "Memory allocation limit exceeded\n");
            free(headers);
            free(crc_indications);
            fclose(file);
            return;
        }

        headers[i].timestamp = time(NULL);
        headers[i].length = sizeof(PacketHeader) + payload_length;
        headers[i].payload = malloc(payload_length);

        if (!headers[i].payload) {
            fprintf(stderr, "Memory allocation failed\n");
            for (size_t j = 0; j < i; ++j) {
                free(headers[j].payload);
            }
            free(headers);
            free(crc_indications);
            fclose(file);
            return;
        }

        // Simulate reading payload
        for (size_t j = 0; j < payload_length; ++j) {
            ((uint8_t*)headers[i].payload)[j] = rand() % 256;
        }

        crc_indications[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indications[i].RNTI = (i * 100) % 65535; // RNTI should be in the range [0, 65534]
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    fclose(file);

    // Simulate processing
    for (size_t i = 0; i < total_images; ++i) {
        free(headers[i].payload);
    }

    free(headers);
    free(crc_indications);
}
