// Define a structure to represent a network packet
typedef struct Packet {
    uint16_t payload_size; // Variable-length payload size in header
    void* payload;         // Pointer to dynamically allocated payload
    struct Packet* next;   // Pointer to the next packet in the queue
} Packet;

// Function to create a new packet with given payload size
Packet* create_packet(uint16_t payload_size) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed for packet header\n");
        return NULL;
    }
    packet->payload_size = payload_size;

    // Dynamically allocate memory for the payload
    packet->payload = malloc(payload_size);
    if (packet->payload == NULL) {
        fprintf(stderr, "Memory allocation failed for payload of size %u\n", payload_size);
        free(packet); // Clean up the header before returning
        return NULL;
    }

    memset(packet->payload, 0, payload_size); // Initialize payload to zero

    packet->next = NULL; // Set next pointer to NULL for now

    return packet;
}

// Function to process a packet stream and log the number of bytes processed
void process_packets(Packet** head) {
    Packet* current = *head;
    while (current != NULL) {
        uint16_t total_bytes_processed = 0;

        // Process the packet payload here
        // Example: Increment the first byte by 1
        if (current->payload_size > 0) {
            ((uint8_t*)current->payload)[0] += 1;
            total_bytes_processed = current->payload_size;
        }

        // Log the number of bytes processed for this packet
        printf("Processed %u bytes\n", total_bytes_processed);

        // Move to the next packet in the queue
        Packet* temp = current;
        current = current->next;

        // Free the memory allocated for the current packet and its payload
        free(temp->payload);
        free(temp);
    }

    // Set head pointer to NULL after processing all packets
    *head = NULL;
}

// Function to demonstrate usage of create_packet and process_packets
int main() {
    Packet* packet_queue_head = NULL;

    // Example: Create a few packets with varying payload sizes
    uint16_t payload_sizes[] = {1024, 2048, 512};
    for (size_t i = 0; i < sizeof(payload_sizes) / sizeof(payload_sizes[0]); ++i) {
        Packet* packet = create_packet(payload_sizes[i]);
        if (packet != NULL) {
            if (packet_queue_head == NULL) {
                packet_queue_head = packet;
            } else {
                // Assuming a single-threaded environment for simplicity
                packet_queue_head->next = packet;
                packet_queue_head = packet->next;
            }
        }
    }

    // Process the packet queue and log bytes processed
    process_packets(&packet_queue_head);

    return 0;
}
```

