#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    char header[16]; // Assuming a fixed header size for simplicity
    char *payload;
} PacketData;

PacketData* process_packets(int num_packets, int max_payload_size, int max_total_memory) {
    if (num_packets <= 0 || max_payload_size <= 0 || max_total_memory <= 0) {
        return NULL; // Invalid input
    }

    // Calculate required memory for payloads
    size_t total_payload_size = (size_t)num_packets * max_payload_size;
    if (total_payload_size > SIZE_MAX / sizeof(PacketData)) {
        return NULL; // Potential overflow
    }

    size_t total_memory_needed = total_payload_size + num_packets * sizeof(PacketData);

    if (total_memory_needed > (size_t)max_total_memory) {
        return NULL; // Exceeds maximum memory limit
    }

    PacketData* packets = malloc(total_memory_needed);
    if (!packets) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_packets; ++i) {
        size_t payload_offset = sizeof(PacketData) * i;
        packets[i].payload = (char*)((char*)packets + payload_offset);
        memset(packets[i].header, 0, sizeof(packets[i].header));
    }

    return packets;
}

void free_packets(PacketData* packets, int num_packets) {
    if (packets) {
        for (int i = 0; i < num_packets; ++i) {
            // Assuming payload is dynamically allocated and needs to be freed
            free(packets[i].payload);
        }
        free(packets);
    }
}
