typedef struct MemoryManager {
    size_t total_memory_limit;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} MemoryManager;

void initializeMemoryManager(MemoryManager *manager, size_t limit) {
    manager->total_memory_limit = limit;
    manager->current_memory_usage = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int allocateLayerMetadata(MemoryManager *manager, LayerMetadata **metadata, int num_layers, int layer_size) {
    size_t required_memory = num_layers * sizeof(LayerMetadata);

    if (required_memory > manager->total_memory_limit - manager->current_memory_usage) {
        return -1; // Memory allocation exceeds limit
    }

    pthread_mutex_lock(&manager->lock);
    if (required_memory > manager->total_memory_limit - manager->current_memory_usage) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation still exceeds limit after locking
    }

    *metadata = malloc(required_memory);
    if (*metadata == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Failed to allocate memory
    }

    manager->current_memory_usage += required_memory;
    pthread_mutex_unlock(&manager->lock);

    for (int i = 0; i < num_layers; ++i) {
        (*metadata)[i].layer_id = i + 1;
        (*metadata)[i].size = layer_size;
        // Initialize other layer metadata fields
    }

    return 0;
}

void freeLayerMetadata(LayerMetadata *metadata, int num_layers) {
    if (metadata != NULL) {
        free(metadata);
    }
}

int processImageFiles(const char *file_list[], int file_count, MemoryManager *manager) {
    for (int i = 0; i < file_count; ++i) {
        // Simulate reading metadata from the file
        ImageFile image_file;
        strcpy(image_file.filename, file_list[i]);
        int num_layers = rand() % 10 + 1; // Random number of layers between 1 and 10

        if (allocateLayerMetadata(manager, &image_file.layers, num_layers, 4096) != 0) {
            printf("Failed to allocate memory for image file: %s\n", image_file.filename);
            continue;
        }

        // Process the image layers
        // ...

        freeLayerMetadata(image_file.layers, num_layers);
    }

    return 0;
}

int main() {
    MemoryManager manager;
    initializeMemoryManager(&manager, 1024 * 1024); // 1 MB memory limit

    const char *file_list[] = {"image1.jpg", "image2.png", "image3.bmp"};
    int file_count = sizeof(file_list) / sizeof(file_list[0]);

    processImageFiles(file_list, file_count, &manager);

    return 0;
}
