#define MAX_NODES 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for DoublyLinkedList\n");
        return NULL;
    }
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for Node\n");
        return NULL;
    }
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

void insertNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_NODES) {
        fprintf(stderr, "Memory limit reached for the linked list\n");
        return;
    }
    Node* newNode = createNode(data);
    if (!newNode) {
        return;
    }
    if (list->head == NULL) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
}

void freeList(DoublyLinkedList* list) {
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    free(list);
}
