Packet* create_packet_queue(size_t num_packets, size_t max_payload_size, size_t *total_memory) {
    if (num_packets == 0 || max_payload_size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Invalid input sizes.\n");
        return NULL;
    }

    // Calculate total memory required
    size_t required_memory = num_packets * (sizeof(Packet) + max_payload_size);

    // Check for integer overflow
    if ((num_packets > SIZE_MAX / (sizeof(Packet) + max_payload_size)) || (required_memory < num_packets * sizeof(Packet))) {
        fprintf(stderr, "Memory allocation would exceed system limits.\n");
        return NULL;
    }

    Packet *packet_queue = (Packet *)malloc(required_memory);
    if (!packet_queue) {
        fprintf(stderr, "Failed to allocate memory for packet queue.\n");
        return NULL;
    }

    *total_memory = required_memory;

    // Initialize payload pointers and sizes
    size_t current_payload_offset = num_packets * sizeof(Packet);
    for (size_t i = 0; i < num_packets; ++i) {
        packet_queue[i].payload = (char *)(packet_queue + num_packets) + current_payload_offset;
        packet_queue[i].payload_size = max_payload_size;
        current_payload_offset += max_payload_size;
    }

    return packet_queue;
}

