SampleManager* create_sample_manager(size_t initial_capacity, size_t max_sample_size) {
    SampleManager *manager = malloc(sizeof(SampleManager));
    if (!manager) return NULL;

    manager->max_sample_size = max_sample_size;
    manager->sample_count = 0;
    manager->samples = calloc(initial_capacity, sizeof(AudioSample));
    if (!manager->samples) {
        free(manager);
        return NULL;
    }

    // Initialize memory pool
    manager->memory_pool = malloc(max_sample_size * initial_capacity);
    if (!manager->memory_pool) {
        free(manager->samples);
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_sample_manager(SampleManager *manager) {
    for (size_t i = 0; i < manager->sample_count; ++i) {
        free(manager->samples[i].audio_stream);
    }
    free(manager->samples);
    free(manager->memory_pool);
    free(manager);
}

int add_audio_sample(SampleManager *manager, int metadata, const char *stream, size_t stream_size) {
    if (manager->sample_count >= manager->max_sample_size - 1) return -1; // Avoid overflow

    AudioSample *sample = &manager->samples[manager->sample_count];
    sample->metadata = metadata;
    sample->audio_stream = malloc(stream_size);
    if (!sample->audio_stream) return -1;

    memcpy(sample->audio_stream, stream, stream_size);
    sample->stream_size = stream_size;

    manager->sample_count++;
    return 0;
}

