typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Packet {
    void* payload;
    size_t payload_size;
    NFAPI_CRC_INDICATION_PDU_T** structures;
    int num_structures;
} Packet;

int allocate_memory_for_packets(int max_payload_size, int num_packets, int num_structures) {
    size_t total_memory = 0;

    // Calculate the total memory required for all structures
    total_memory += num_packets * sizeof(Packet);
    total_memory += num_packets * num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*);

    for (int i = 0; i < num_packets; i++) {
        total_memory += max_payload_size;
    }

    // Check for potential integer overflows
    if ((total_memory / sizeof(Packet)) != num_packets || 
        (total_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T*)) != num_packets ||
        (total_memory / max_payload_size) != num_packets) {
        return -1; // Integer overflow detected
    }

    // Allocate memory for all structures
    void* memory = malloc(total_memory);
    if (!memory) {
        return -2; // Memory allocation failed
    }

    return 0;
}

Packet* create_packets(int max_payload_size, int num_packets, int num_structures) {
    Packet* packets = (Packet*)malloc(num_packets * sizeof(Packet));
    if (!packets) {
        return NULL;
    }

    for (int i = 0; i < num_packets; i++) {
        packets[i].payload = malloc(max_payload_size);
        if (!packets[i].payload) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }

        packets[i].payload_size = max_payload_size;
        packets[i].structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!packets[i].structures) {
            // Handle memory allocation failure
            free(packets[i].payload);
            for (int j = 0; j < i; j++) {
                free(packets[j].payload);
                free(packets[j].structures);
            }
            free(packets);
            return NULL;
        }

        packets[i].num_structures = num_structures;
    }

    return packets;
}

void free_packets(Packet* packets, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        free(packets[i].payload);
        free(packets[i].structures);
    }
    free(packets);
}

int main() {
    int max_payload_size = MAX_PAYLOAD_SIZE;
    int num_packets = 5;
    int num_structures = 10;

    if (allocate_memory_for_packets(max_payload_size, num_packets, num_structures) == -1) {
        printf("Integer overflow detected during memory allocation\n");
        return 1;
    }

    Packet* packets = create_packets(max_payload_size, num_packets, num_structures);
    if (!packets) {
        printf("Failed to allocate memory for packets\n");
        return 1;
    }

    // Use the packets...

    free_packets(packets, num_packets);

    return 0;
}
