        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }

    *num_layers_ptr = num_layers;
    return layers;
}

int main() {
    const char* dir_path = "/path/to/image/directory";
    int num_layers;

    ImageMetadataLayer** layers = read_directory(dir_path, &num_layers);

    // Process each layer concurrently
    pthread_t threads[num_layers];
    for (int i = 0; i < num_layers; i++) {
        if (pthread_create(&threads[i], NULL, process_image_metadata, layers[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_layers; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    for (int i = 0; i < num_layers; i++) {
        free(layers[i]->metadata_content);
        free(layers[i]);
    }
    free(layers);

    return 0;
}
