int init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->count = 0;
    da->capacity = initial_capacity > 1 ? initial_capacity : 1;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) return -1; // Allocation failed
    pthread_mutex_init(&da->lock, NULL);
    return 0;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->array = NULL;
    da->count = da->capacity = 0;
    pthread_mutex_unlock(&da->lock);
}

int add_to_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity + (da->capacity / 2) : 1;
