#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT (1024 * 1024 * 1024) // 1GB

typedef struct {
    uint32_t data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t total_allocated;
    size_t peak_usage;
    size_t min_usage;
    pthread_mutex_t lock;
} MemoryUsageStats;

MemoryUsageStats mem_stats = {0};

void update_memory_stats(size_t allocated) {
    pthread_mutex_lock(&mem_stats.lock);
    mem_stats.total_allocated += allocated;
    if (allocated > mem_stats.peak_usage) {
        mem_stats.peak_usage = allocated;
    }
    if (allocated < mem_stats.min_usage || mem_stats.min_usage == 0) {
        mem_stats.min_usage = allocated;
    }
    pthread_mutex_unlock(&mem_stats.lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfapi_crc_indication_pdu(size_t num_structs, size_t start_index, uint32_t seed) {
    if (num_structs == 0 || start_index > UINT32_MAX - num_structs) {
        errno = EINVAL;
        return NULL;
    }

    size_t total_size = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > MAX_MEMORY_LIMIT) {
        errno = ENOMEM;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (!array) {
        update_memory_stats(0);
        return NULL;
    }

    // Populate the array with random values using the provided seed
    srand(seed + start_index);
    for (size_t i = 0; i < num_structs; ++i) {
        array[i].data = rand();
    }

    update_memory_stats(total_size);

    return array;
}

void deallocate_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array, size_t num_structs) {
    if (array) {
        free(array);
        pthread_mutex_lock(&mem_stats.lock);
        mem_stats.total_allocated -= num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pthread_mutex_unlock(&mem_stats.lock);
    }
}

// Example usage
int main() {
    size_t num_structs = 1000;
    size_t start_index = 0;
    uint32_t seed = 42;

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_nfaapi_crc_indication_pdu(num_structs, start_index, seed);
    if (!array) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    // Use the allocated array...

    deallocate_nfaapi_crc_indication_pdu(array, num_structs);

    printf("Total allocated: %zu bytes\n", mem_stats.total_allocated);
    printf("Peak usage: %zu bytes\n", mem_stats.peak_usage);
    printf("Min usage: %zu bytes\n", mem_stats.min_usage);

    return EXIT_SUCCESS;
}
