        size_t new_capacity = list->capacity * 2;
        // Reallocate memory for the fixed-size array or linked list
        // ...
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    new_node->data = item;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    list->total_memory_used += sizeof(ListNode);

    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(DynamicList* list, size_t index) {
    if (!list || index >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);

    ListNode* current = list->head;
    while (index--) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* item = &current->data;
    pthread_mutex_unlock(&list->mutex);
    return item;
}

