#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERFACE_NAME_LENGTH 64
#define MAX_IP_ADDRESS_LENGTH 16
#define MAX_SUBNET_MASK_LENGTH 16
#define MAX_GATEWAY_LENGTH 16

typedef struct {
    char interface_name[MAX_INTERFACE_NAME_LENGTH];
    char ip_address[MAX_IP_ADDRESS_LENGTH];
    char subnet_mask[MAX_SUBNET_MASK_LENGTH];
    char gateway[MAX_GATEWAY_LENGTH];
} NetworkInterface;

NetworkInterface* create_network_interface_list(int initial_size) {
    if (initial_size <= 0) {
        fprintf(stderr, "Initial size must be greater than zero.\n");
        return NULL;
    }

    NetworkInterface* interface_list = (NetworkInterface*)malloc(initial_size * sizeof(NetworkInterface));
    if (interface_list == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the list with empty strings
    for (int i = 0; i < initial_size; i++) {
        memset(&interface_list[i], 0, sizeof(NetworkInterface));
    }

    return interface_list;
}

void free_network_interface_list(NetworkInterface* interface_list) {
    if (interface_list != NULL) {
        free(interface_list);
    }
}

int add_network_interface(NetworkInterface* interface_list, int size, const char* name, const char* ip, const char* subnet_mask, const char* gateway) {
    if (size <= 0 || interface_list == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    // Check for buffer overflows
    if (strlen(name) >= MAX_INTERFACE_NAME_LENGTH ||
        strlen(ip) >= MAX_IP_ADDRESS_LENGTH ||
        strlen(subnet_mask) >= MAX_SUBNET_MASK_LENGTH ||
        strlen(gateway) >= MAX_GATEWAY_LENGTH) {
        fprintf(stderr, "Input strings exceed maximum length.\n");
        return -1;
    }

    // Find an empty slot to add the new interface
    for (int i = 0; i < size; i++) {
        if (strlen(interface_list[i].interface_name) == 0) {
            strcpy(interface_list[i].interface_name, name);
            strcpy(interface_list[i].ip_address, ip);
            strcpy(interface_list[i].subnet_mask, subnet_mask);
            strcpy(interface_list[i].gateway, gateway);
            return i;
        }
    }

    fprintf(stderr, "No available slots to add the interface.\n");
    return -1;
}

void print_network_interface_list(NetworkInterface* interface_list, int size) {
    if (size <= 0 || interface_list == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        if (strlen(interface_list[i].interface_name) > 0) {
            printf("Interface %d: Name=%s, IP=%s, Subnet Mask=%s, Gateway=%s\n",
                   i, interface_list[i].interface_name,
                   interface_list[i].ip_address,
                   interface_list[i].subnet_mask,
                   interface_list[i].gateway);
        }
    }
}

int main() {
    int initial_size = 10;
    NetworkInterface* interfaces = create_network_interface_list(initial_size);

    if (interfaces != NULL) {
        add_network_interface(interfaces, initial_size, "eth0", "192.168.1.1", "255.255.255.0", "192.168.1.254");
        add_network_interface(interfaces, initial_size, "eth1", "192.168.1.2", "255.255.255.0", "192.168.1.254");

        print_network_interface_list(interfaces, initial_size);

        free_network_interface_list(interfaces);
    }

    return 0;
}
