#include <stdlib.h>
#include <time.h>

typedef struct {
    int tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned short value;
} RNTI;

typedef struct {
    int flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_unique_rnti(RNTI *existing_rntis, int num_existing) {
    srand(time(NULL));
    unsigned short new_rnti;
    do {
        new_rnti = rand() % 65536; // Random RNTI between 0 and 65535
    } while (num_existing > 0 && (new_rnti == existing_rntis[--num_existing].value));
    return new_rnti;
}

int allocate_nfapi_crc_indication_pdus(int n, int max_memory_kb, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (n <= 0 || max_memory_kb <= 0) {
        return -1; // Invalid input
    }

    size_t total_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > ((size_t)max_memory_kb * 1024)) {
        return -1; // Exceeds maximum memory limit
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(total_size);
    if (*pdus == NULL) {
        return -1; // Memory allocation failed
    }

    RNTI *existing_rntis = NULL;
    int num_existing = 0;

    for (int i = 0; i < n; ++i) {
        (*pdus)[i].ue_info_tag.tag = i + 1;
        (*pdus)[i].rnti.value = generate_unique_rnti(existing_rntis, num_existing);
        existing_rntis = realloc(existing_rntis, (num_existing + 1) * sizeof(RNTI));
        existing_rntis[num_existing++] = (*pdus)[i].rnti;

        (*pdus)[i].crc_indication_rel8_tag.flag = rand() % 2; // Random CRC flag
    }

    free(existing_rntis);
    return 0;
}

void free_nfapi_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
}
