ImageTag** process_image_files(const char* file_paths[], int num_files, int* total_tags) {
    ImageTag** tags = NULL;
    *total_tags = 0;

    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_paths[i], "r");
        if (!file) {
            fprintf(stderr, "Error opening file %s\n", file_paths[i]);
            continue;
        }

        int num_tags_in_file;
        fscanf(file, "%d", &num_tags_in_file);
        *total_tags += num_tags_in_file;

        tags = realloc(tags, (*total_tags) * sizeof(ImageTag*));
        if (!tags) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            continue;
        }

        for (int j = 0; j < num_tags_in_file; ++j) {
            ImageTag* tag = malloc(sizeof(ImageTag));
            if (!tag) {
                fprintf(stderr, "Memory allocation failed for tag\n");
                free(tags);
                tags = NULL;
                fclose(file);
                continue;
            }

            fscanf(file, "%d %s", &tag->id, tag->metadata);
            tags[*total_tags - 1] = tag;
        }

        fclose(file);
    }

    return tags;
}
