    }

    size_t alloc_size = INITIAL_ALLOC_SIZE;
    size_t current_tags = 0;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char file_path[MAX_FILE_PATH];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        if (stat(file_path, &file_stat) != 0) {
            perror("stat");
            free(tags);
            closedir(dir);
            return NULL;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            ImageTag* sub_tags = process_image_files(file_path, total_tags);
            if (!sub_tags) {
                free(tags);
                closedir(dir);
                return NULL;
            }
            size_t num_sub_tags = *total_tags;

            tags = realloc(tags, (current_tags + num_sub_tags) * sizeof(ImageTag));
            if (!tags) {
                perror("realloc");
                free(sub_tags);
                closedir(dir);
                return NULL;
            }

            memcpy(&tags[current_tags], sub_tags, num_sub_tags * sizeof(ImageTag));
            current_tags += num_sub_tags;
            free(sub_tags);
        } else {
            FILE* file = fopen(file_path, "r");
            if (!file) {
                perror("fopen");
                continue;
            }

            int num_tags;
            fscanf(file, "%d", &num_tags);

            for (int i = 0; i < num_tags; ++i) {
                if (current_tags == alloc_size) {
                    tags = realloc(tags, alloc_size * 2 * sizeof(ImageTag));
                    if (!tags) {
                        perror("realloc");
                        fclose(file);
                        closedir(dir);
                        return NULL;
                    }
                    alloc_size *= 2;
                }

                ImageTag tag;
                fscanf(file, "%d %s", &tag.id, tag.metadata);
                tags[current_tags++] = tag;
            }

            fclose(file);
        }
    }

    *total_tags = current_tags;
    closedir(dir);
    return tags;
}
```

This code block demonstrates a C function that processes image files in a given directory and its subdirectories, reading the number of tags from each file and storing them in an dynamically allocated array of `ImageTag` structures. The function handles various system dependencies such as directory traversal and external data sources with network I/O operations. It also includes performance optimizations and error handling mechanisms to ensure efficient resource utilization and avoid unnecessary allocations.']

