    char* payload;
} network_packet_t;

int process_packets(network_packet_t** packets, int packet_count) {
    static size_t total_memory_allocated = 0;
    static size_t next_id = 0;

    if (packet_count > MAX_PACKETS_PER_SECOND) {
        fprintf(stderr, "Error: Exceeds maximum packets per second limit.\n");
        return -1;
    }

    for (int i = 0; i < packet_count; ++i) {
        size_t payload_size = strlen(packets[i]->payload);

        if (total_memory_allocated + payload_size > MAX_MEMORY_LIMIT) {
            fprintf(stderr, "Error: Exceeds maximum memory limit.\n");
            return -1;
        }

        packets[i]->id = next_id++;
        total_memory_allocated += payload_size;
    }

    return 0;
}

int main() {
    // Example usage
    network_packet_t* packets[MAX_PACKETS_PER_SECOND];

    for (int i = 0; i < MAX_PACKETS_PER_SECOND; ++i) {
        packets[i] = malloc(sizeof(network_packet_t));
        if (!packets[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for packet.\n");
            return -1;
        }

        // Simulate payload data
        snprintf(packets[i]->payload, 1024, "Payload %d", i);
    }

