    if (result == 0) {
        printf("All packets processed successfully.\n");
    } else {
        printf("Packet processing failed with error code: %d\n", result);
    }

    // Free allocated memory
    for (int i = 0; i < MAX_PACKETS_PER_SECOND; ++i) {
        free(packets[i]);
    }

    return 0;
}
