    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t current_size;
    size_t max_size;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list, size_t max_size) {
    list->max_size = max_size;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int create_and_populate_nfaapi_crc_linked_list(CRC_LIST_T *list, size_t num_pdus) {
    if (num_pdus > list->max_size - list->current_size) {
        return -EVAL_RESOURCE_EXHAUSTED;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(*new_pdu));
        if (!new_pdu) {
            cleanup_crc_list(list);
            return -EVAL_MEMORY_FAILURE;
        }

        // Initialize fields with random values or other logic
        new_pdu->ue_info_tag = generate_random_UE_INFO_TAG();
        new_pdu->RNTI = generate_random_RNTI();
        new_pdu->crc_indication.CRCFLAG = generate_random_CRCFLAG();

        pthread_mutex_lock(&list->lock);
        if (!list->head) {
            list->head = list->tail = new_pdu;
            new_pdu->next = new_pdu->prev = NULL;
        } else {
            list->tail->next = new_pdu;
            new_pdu->prev = list->tail;
            new_pdu->next = NULL;
            list->tail = new_pdu;
        }
        ++list->current_size;
        pthread_mutex_unlock(&list->lock);
    }

    return 0; // Success
}

void cleanup_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->current_size = 0;
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    CRC_LIST_T crc_list;
    init_crc_list(&crc_list, 1000);

    int result = create_and_populate_nfaapi_crc_linked_list(&crc_list, 500);
    if (result != 0) {
        handle_error(result); // Handle error appropriately
    }

    cleanup_crc_list(&crc_list);
    return 0;
}
