#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define INITIAL_CAPACITY 16

typedef struct {
    uint32_t id;
    time_t timestamp;
    size_t payload_length;
    char payload[MAX_PACKET_SIZE];
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t size;
    size_t capacity;
    size_t total_memory_used;
    size_t max_size_limit;
} PacketBuffer;

void initialize_packet_buffer(PacketBuffer *buffer, size_t max_size_limit) {
    buffer->packets = (NetworkPacket *)malloc(INITIAL_CAPACITY * sizeof(NetworkPacket));
    if (!buffer->packets) {
        fprintf(stderr, "Failed to allocate memory for packet buffer\n");
        exit(EXIT_FAILURE);
    }
    buffer->size = 0;
    buffer->capacity = INITIAL_CAPACITY;
    buffer->total_memory_used = 0;
    buffer->max_size_limit = max_size_limit;
}

void add_packet(PacketBuffer *buffer, NetworkPacket *packet) {
    if (buffer->size >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        NetworkPacket *new_packets = (NetworkPacket *)realloc(buffer->packets, new_capacity * sizeof(NetworkPacket));
        if (!new_packets) {
            fprintf(stderr, "Failed to reallocate memory for packet buffer\n");
            exit(EXIT_FAILURE);
        }
        buffer->packets = new_packets;
        buffer->capacity = new_capacity;
    }

    size_t packet_size = sizeof(NetworkPacket) + packet->payload_length;
    if (buffer->total_memory_used + packet_size > buffer->max_size_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }

    memcpy(&buffer->packets[buffer->size], packet, packet_size);
    buffer->size++;
    buffer->total_memory_used += packet_size;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    free(buffer->packets);
    buffer->packets = NULL;
    buffer->size = 0;
    buffer->capacity = 0;
    buffer->total_memory_used = 0;
}
