void destroyDynamicPduList(DynamicPduList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    list->pdus = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

int resizeDynamicPduList(DynamicPduList *list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return 0; // No need to resize

    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdus == NULL) {
        return -1; // Out of memory
    }
    list->pdus = new_pdus;
    list->capacity = new_capacity;
    return 0;
}

int updateDynamicPduList(DynamicPduList *list, size_t new_count) {
    pthread_mutex_lock(&list->mutex);
    if (new_count > list->capacity) {
        if (resizeDynamicPduList(list, new_count * 2) != 0) {
            pthread_mutex_unlock(&list->mutex);
