#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct LogCollection {
    LogEntry *head;
    size_t count;
    size_t max_memory_limit;
    size_t current_memory_usage;
} LogCollection;

LogCollection* log_collection_create(size_t max_memory_limit) {
    LogCollection *collection = (LogCollection*)malloc(sizeof(LogCollection));
    collection->head = NULL;
    collection->count = 0;
    collection->max_memory_limit = max_memory_limit;
    collection->current_memory_usage = 0;
    return collection;
}

void log_collection_destroy(LogCollection *collection) {
    LogEntry *entry = collection->head;
    while (entry != NULL) {
        LogEntry *next = entry->next;
        free(entry->message);
        free(entry);
        entry = next;
    }
    free(collection);
}

int log_entry_add(LogCollection *collection, LogLevel level, const char *message) {
    size_t message_len = strlen(message) + 1;
    if (message_len > SIZE_MAX - sizeof(LogEntry)) {
        return -1; // Overflow check for memory allocation
    }

    LogEntry *new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    new_entry->timestamp = time(NULL);
    new_entry->level = level;
    new_entry->message = (char*)malloc(message_len);
    strcpy(new_entry->message, message);
    new_entry->next = NULL;

    if ((collection->current_memory_usage + sizeof(LogEntry) + message_len) > collection->max_memory_limit) {
        free(new_entry->message);
        free(new_entry);
        return -2; // Memory limit exceeded
    }

    new_entry->next = collection->head;
    collection->head = new_entry;
    collection->count++;
    collection->current_memory_usage += sizeof(LogEntry) + message_len;

    return 0;
}

void log_collection_print(LogCollection *collection) {
    LogEntry *entry = collection->head;
    while (entry != NULL) {
        printf("[%s] %s: %s\n", ctime(&entry->timestamp), LogLevelToString(entry->level), entry->message);
        entry = entry->next;
    }
}

const char* LogLevelToString(LogLevel level) {
    switch(level) {
        case INFO:
            return "INFO";
        case WARNING:
            return "WARNING";
        case ERROR:
            return "ERROR";
        default:
            return "UNKNOWN";
    }
}
```

