    PacketProcessor(size_t maxMemory) : maxMemory(maxMemory), currentMemory(0) {}

    void processPacket(const Packet& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        if (currentMemory + sizeof(Packet) + packet.payloadSize <= maxMemory) {
            // Process the packet
            currentMemory += sizeof(Packet) + packet.payloadSize;
            std::cout << "Processing packet of type " << packet.type << " with payload size " << packet.payloadSize << std::endl;
        } else {
            // Handle memory allocation failure gracefully
            std::cerr << "Failed to process packet due to insufficient memory" << std::endl;
        }
    }

private:
    size_t maxMemory;
    size_t currentMemory;
    std::mutex mutex;
};

int main() {
    const size_t MAX_MEMORY = 1024 * 1024; // 1MB
    PacketProcessor processor(MAX_MEMORY);

    std::vector<std::thread> threads(10);
    for (size_t i = 0; i < threads.size(); ++i) {
        threads[i] = std::thread([&processor]() {
            for (int j = 0; j < 1000; ++j) {
                Packet packet;
                packet.type = rand() % 5; // Random packet type
                packet.payloadSize = rand() % 1024 + 1; // Random payload size
                packet.payload = new char[packet.payloadSize];
                processor.processPacket(packet);
                delete[] packet.payload;
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
