['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t mutex;
} CRCList;

int init_crc_list(CRCList** list, size_t max_size) {
    *list = (CRCList*)malloc(sizeof(CRCList));
    if (*list == NULL) return -1; // Memory allocation failed

    (*list)->head = (*list)->tail = NULL;
    (*list)->current_size = 0;
    (*list)->max_size = max_size;
    pthread_mutex_init(&(*list)->mutex, NULL);

    return 0;
}

void destroy_crc_list(CRCList** list) {
    Node* current = (*list)->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&(*list)->mutex);
    free(*list);
    *list = NULL;
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Insufficient resources
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->current_size++;

    pthread_mutex_unlock(&list->mutex);

    printf("Added to CRC List at address %p with CRCFLAG %d\n", (void*)new_node, data.CRCFLAG);
    return 0;
}

int create_and_populate_crc_list(int N, size_t MAX_MEMORY, CRCList** list) {
    if (N <= 0 || MAX_MEMORY <= 0) return -1; // Invalid input parameters

    if (init_crc_list(list, MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) return -2;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = {
            rand() % 1000, // RX_UE_INFORMATION_TAG
            rand() % 1000, // RNTI
            rand() % 1000, // CRC_INDICATION_REL8_TAG
            rand() % 2    // Random CRCFLAG
        };

        if (add_to_crc_list(*list, data) != 0) {
            destroy_crc_list(list);
            return -3; // Failed to add to list
        }
    }

    return 0;
}
