    if (required_size > MAX_SIZE || required_size / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -2; // Potential overflow or invalid calculation
    }

    *array = malloc(required_size);
    if (*array == NULL) {
        return -3; // Memory allocation failed
    }

