typedef struct {
    int width;
    int height;
    size_t fileSize;
} ImageMetadata;

int allocateImageMetadata(ImageMetadata **metadataArray, size_t numEntries) {
    if (numEntries > MAX_ENTRIES) {
        fprintf(stderr, "Error: Number of entries exceeds the maximum limit.\n");
        return -1;
    }

    size_t totalSize = numEntries * sizeof(ImageMetadata);
    if ((totalSize / numEntries != sizeof(ImageMetadata)) || (totalSize > MAX_MEMORY_LIMIT)) {
        fprintf(stderr, "Error: Requested memory exceeds the maximum limit or causes overflow.\n");
        return -1;
    }

    *metadataArray = malloc(totalSize);
    if (*metadataArray == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for image metadata.\n");
        return -1;
    }

    // Initialize the array with default values
    for (size_t i = 0; i < numEntries; ++i) {
        (*metadataArray)[i].width = 0;
        (*metadataArray)[i].height = 0;
        (*metadataArray)[i].fileSize = 0;
    }

    return 0;
}

