#define MAX_LIMIT 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int current_limit = MAX_LIMIT;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_and_initialize_pdu_list(int num_elements) {
    if (num_elements <= 0 || num_elements > current_limit) {
        fprintf(stderr, "Error: Invalid number of elements or exceeding maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        fprintf(stderr, "Error: Out of memory.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_elements; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand();
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&mutex);

    return pdu_list;
}

void* thread_function(void* arg) {
    int num_elements = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = generate_and_initialize_pdu_list(num_elements);
    if (pdu_list != NULL) {
        // Process the PDU list
        free(pdu_list);
    }
    return NULL;
}

void set_max_limit(int new_limit) {
    pthread_mutex_lock(&mutex);
    if (new_limit > 0 && new_limit <= MAX_LIMIT) {
        current_limit = new_limit;
    } else {
        fprintf(stderr, "Error: Invalid new limit.\n");
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));

    // Example usage
    int num_elements = 500;
    pthread_t threads[10];
    int thread_args[10];

    for (int i = 0; i < 10; i++) {
        thread_args[i] = num_elements;
        pthread_create(&threads[i], NULL, thread_function, &thread_args[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Dynamically set new limit
    set_max_limit(2000);

    return 0;
}
