NetworkPacketInfo** process_packets(size_t packet_count, uint64_t* timestamps, size_t* lengths, const char* payloads) {
    NetworkPacketInfo** packet_infos = (NetworkPacketInfo**)malloc(packet_count * sizeof(NetworkPacketInfo*));
    if (!packet_infos) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < packet_count; ++i) {
        size_t payload_length = lengths[i];
        NetworkPacketInfo* packet_info = (NetworkPacketInfo*)malloc(sizeof(NetworkPacketInfo));
        if (!packet_info) {
            free(packet_infos); // Free previously allocated memory
            return NULL; // Memory allocation failed
        }

        packet_info->timestamp = timestamps[i];
        packet_info->length = payload_length;
        packet_info->payload = malloc(payload_length);
        if (!packet_info->payload) {
            free(packet_info); // Free the partial structure
            free(packet_infos); // Free previously allocated memory
            return NULL; // Memory allocation failed
        }

        memcpy(packet_info->payload, payloads + i * payload_length, payload_length);

        packet_infos[i] = packet_info;
    }

    return packet_infos;
}
