#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NetworkPacketInfo {
    time_t timestamp;
    size_t length;
    char* payload;
    int identifier;
    struct NetworkPacketInfo* next;
} NetworkPacketInfo;

NetworkPacketInfo* process_packets(char** packets, size_t packet_count, size_t max_payload_size) {
    if (packets == NULL || packet_count == 0) {
        return NULL;
    }

    NetworkPacketInfo dummy_head = {0};
    NetworkPacketInfo* tail = &dummy_head;

    for (size_t i = 0; i < packet_count; ++i) {
        size_t timestamp_size = sizeof(time_t);
        if ((sizeof(NetworkPacketInfo) + timestamp_size + max_payload_size + 1) > SIZE_MAX) {
            // Handle integer overflow
            return NULL;
        }

        NetworkPacketInfo* new_packet = (NetworkPacketInfo*)malloc(sizeof(NetworkPacketInfo) + timestamp_size + max_payload_size + 1);
        if (new_packet == NULL) {
            // Memory allocation failed, clean up existing list
            while (dummy_head.next != NULL) {
                NetworkPacketInfo* temp = dummy_head.next;
                dummy_head.next = temp->next;
                free(temp);
            }
            return NULL;
        }

        new_packet->timestamp = *((time_t*)packets[i]);
        new_packet->length = strlen(packets[i + 1]) < max_payload_size ? strlen(packets[i + 1]) : max_payload_size - 1;
        new_packet->payload = (char*)(new_packet + 1);
        memcpy(new_packet->payload, packets[i + 1], new_packet->length);
        new_packet->identifier = i;
        new_packet->next = NULL;

        tail->next = new_packet;
        tail = new_packet;
    }

    return dummy_head.next;
}
