int allocate_and_populate_pdus(NFAPI_CRC_INDICATION_PDU_T** pdus, int N, uint16_t min_rnti, uint16_t max_rnti, uint32_t max_memory, uint32_t seed) {
    if (N <= 0 || min_rnti >= max_rnti) {
        printf("Invalid input parameters.\n");
        return -1;
    }

    uint32_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    uint32_t total_memory_required = N * pdu_size;

    if (total_memory_required > max_memory) {
        printf("Memory limit exceeded.\n");
        return -1;
    }

    *pdus = malloc(total_memory_required);
    if (*pdus == NULL) {
        printf("Failed to allocate memory.\n");
        return -1;
    }

    srand(seed);

    uint32_t allocated_count = 0;
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*pdus)[i];
        do {
            pdu->RNTI = rand() % (max_rnti - min_rnti + 1) + min_rnti;
        } while (check_rnti_collision(pdus, i));

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();

        allocated_count++;
    }

    printf("Successfully allocated %d PDUs.\n", allocated_count);
    return allocated_count;
}

int check_rnti_collision(NFAPI_CRC_INDICATION_PDU_T** pdus, int index) {
    NFAPI_CRC_INDICATION_PDU_T* current_pdu = &(*pdus)[index];
    for (int i = 0; i < index; ++i) {
        if ((*pdus)[i].RNTI == current_pdu->RNTI) {
            return 1;
        }
    }
    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    int N = 100;
    uint16_t min_rnti = 1;
    uint16_t max_rnti = 1000;
    uint32_t max_memory = 10 * 1024 * 1024; // 10MB
    uint32_t seed = time(NULL);

    int allocated_count = allocate_and_populate_pdus(&pdus, N, min_rnti, max_rnti, max_memory, seed);
    if (allocated_count != -1) {
        free(pdus);
    }

    return 0;
}
