typedef struct ImageNode {
    void* image; // Pointer to the image data
    int width;
    int height;
    char* filePath;
    struct ImageNode* next;
} ImageNode;

ImageNode* createImageNode(void* image, int width, int height, const char* filePath) {
    ImageNode* newNode = (ImageNode*)malloc(sizeof(ImageNode));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }

    newNode->image = malloc(width * height); // Allocate memory for the image data
    if (newNode->image == NULL) {
        free(newNode);
        return NULL; // Handle memory allocation failure for image data
    }

    newNode->width = width;
    newNode->height = height;

    newNode->filePath = (char*)malloc(strlen(filePath) + 1); // Allocate memory for the file path
    if (newNode->filePath == NULL) {
        free(newNode->image);
        free(newNode);
        return NULL; // Handle memory allocation failure for file path
    }
    strcpy(newNode->filePath, filePath);

    newNode->next = NULL;

    return newNode;
}

void destroyImageNode(ImageNode* node) {
    if (node == NULL) {
        return;
    }

    free(node->image); // Free the image data
    free(node->filePath); // Free the file path
    free(node); // Free the node itself
}

ImageNode* addImageToCollection(ImageNode** head, void* image, int width, int height, const char* filePath) {
    ImageNode* newNode = createImageNode(image, width, height, filePath);
    if (newNode == NULL) {
        return *head; // Return the current head on failure
    }

    newNode->next = *head;
    *head = newNode;

    return *head;
}

void removeImageFromCollection(ImageNode** head, const char* filePath) {
    ImageNode* current = *head;
    ImageNode* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->filePath, filePath) == 0) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }

            destroyImageNode(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void clearImageCollection(ImageNode** head) {
    while (*head != NULL) {
        ImageNode* temp = *head;
        *head = (*head)->next;
        destroyImageNode(temp);
    }
}
