}

typedef enum {
    SUCCESS,
    INVALID_INPUT,
    MEMORY_ALLOCATION_FAILED,
    THREAD_CREATION_FAILED
} Status;

Status create_and_populate_array(int N, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (N <= 0) {
        return INVALID_INPUT;
    }

    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }

    for (int i = 0; i < N; i++) {
        // Populate the array with random values
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*array)[i].RNTI = rand() % 1000;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*array)[i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    return SUCCESS;
}

void* process_array_element(void *arg) {
    int index = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *element = &elements[index];

    // Process the element here
    printf("Processing element %d\n", index);

    pthread_exit(NULL);
}

Status process_data_pipeline(int N, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (N <= 0 || array == NULL) {
        return INVALID_INPUT;
    }

    pthread_t *threads = malloc(N * sizeof(pthread_t));
    int *indices = malloc(N * sizeof(int));

    if (threads == NULL || indices == NULL) {
        free(threads);
        free(indices);
        return MEMORY_ALLOCATION_FAILED;
    }

    for (int i = 0; i < N; i++) {
        indices[i] = i;

        if (pthread_create(&threads[i], NULL, process_array_element, &indices[i]) != 0) {
            for (int j = 0; j < i; j++) {
                pthread_join(threads[j], NULL);
            }
            free(threads);
            free(indices);
            return THREAD_CREATION_FAILED;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(indices);

    return SUCCESS;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int N = atoi(argv[1]);
    NFAPI_CRC_INDICATION_PDU_T *array;

    Status status = create_and_populate_array(N, &array);
    if (status != SUCCESS) {
        fprintf(stderr, "Failed to create and populate array: %d\n", status);
        return EXIT_FAILURE;
    }

    status = process_data_pipeline(N, &array);
    if (status != SUCCESS) {
        fprintf(stderr, "Failed to process data pipeline: %d\n", status);
        free(array);
        return EXIT_FAILURE;
    }

    free(array);

    return EXIT_SUCCESS;
}
