#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic memory pool
#define POOL_SIZE 1024

NFAPI_CRC_INDICATION_PDU_T* pool[POOL_SIZE];
uint32_t pool_index = 0;
pthread_mutex_t pool_lock;

// Function to allocate memory from the pool
NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool() {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* ptr = pool[pool_index++];
        memset(ptr, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&pool_lock);
        return ptr;
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Pool is full
}

// Function to free memory back to the pool
void free_to_pool(NFAPI_CRC_INDICATION_PDU_T* ptr) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index > 0 && ptr == pool[pool_index - 1]) {
        pool_index--;
        pthread_mutex_unlock(&pool_lock);
        return;
    }
    pthread_mutex_unlock(&pool_lock);
    // Free memory if it's not the last element
    free(ptr);
}

// Function to generate a hash for RNTI values
uint32_t rnti_hash(uint16_t rnti, uint32_t seed) {
    return ((rnti * 17) + seed) % POOL_SIZE;
}

// Main function to create and populate the array
uint32_t create_and_populate_array(uint32_t N, uint16_t min_rnti, uint16_t max_rnti, uint8_t crc_seed, uint64_t max_memory) {
    pthread_mutex_init(&pool_lock, NULL);

    // Validate input parameters
    if (N == 0 || min_rnti >= max_rnti) {
        return 0; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_destroy(&pool_lock);
        return 0; // Memory allocation failed
    }

    uint32_t allocated_count = 0;
    for (uint32_t i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool();
        if (!pdu) {
            free(array);
            pthread_mutex_destroy(&pool_lock);
            return allocated_count; // Pool exhausted
        }

        uint16_t rnti;
        do {
            rnti = (uint16_t)(rand_r(&crc_seed)) % (max_rnti - min_rnti + 1) + min_rnti;
        } while (rnti == array[i].RNTI); // Ensure uniqueness

        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand_r(&crc_seed) % 2; // Randomly set CRCFLAG
        memcpy(&array[i], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free_to_pool(pdu);

        allocated_count++;
    }

    pthread_mutex_destroy(&pool_lock);
    return allocated_count;
}
