#include <stdlib.h>

typedef struct Header {
    int headerType;
    // other fields as needed for different protocols
} Header;

typedef struct PacketMetadata {
    unsigned long packetID;
    size_t totalHeaderSize;
    // other metadata fields as needed
} PacketMetadata;

typedef struct NetworkPacket {
    Header* headers;
    PacketMetadata metadata;
    struct NetworkPacket* next;
} NetworkPacket;

NetworkPacket* processBatch(NetworkPacket** packets, size_t batchCount) {
    NetworkPacket* head = NULL;
    NetworkPacket* current = NULL;

    for (size_t i = 0; i < batchCount; ++i) {
        NetworkPacket* packet = packets[i];
        if (!packet) continue;

        // Calculate total header size
        size_t totalHeaderSize = 0;
        Header* currentHeader = packet->headers;
        while (currentHeader) {
            totalHeaderSize += sizeof(Header);
            currentHeader = currentHeader->next;
        }

        // Check for integer overflow before allocation
        if ((totalHeaderSize / sizeof(Header)) != (size_t)(totalHeaderSize / sizeof(Header))) {
            continue; // Handle error: integer overflow detected
        }

        NetworkPacket* newPacket = (NetworkPacket*)malloc(sizeof(NetworkPacket));
        if (!newPacket) continue;

        newPacket->headers = packet->headers;
        newPacket->metadata.packetID = i + 1; // Example ID assignment
        newPacket->metadata.totalHeaderSize = totalHeaderSize;
        newPacket->next = NULL;

        if (head == NULL) {
            head = newPacket;
        } else {
            current->next = newPacket;
        }
        current = newPacket;
    }

    return head;
}
