#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define MAX_MEMORY_THRESHOLD 512 * 1024 // 512 KB

typedef struct Packet {
    int metadata;
    char payload[MAX_PACKET_SIZE];
    struct Packet* next;
} Packet;

Packet* head = NULL;
size_t total_memory_usage = 0;

int add_packet(int metadata, const char* payload) {
    if (strlen(payload) >= MAX_PACKET_SIZE) {
        fprintf(stderr, "Error: Payload size exceeds maximum limit.\n");
        return -1;
    }

    if (total_memory_usage + strlen(payload) > MAX_MEMORY_THRESHOLD) {
        // Discard the least recently added packet
        Packet* temp = head;
        head = head->next;
        total_memory_usage -= strlen(temp->payload);
        free(temp);
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    if (!new_packet) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    new_packet->metadata = metadata;
    strcpy(new_packet->payload, payload);
    new_packet->next = head;
    head = new_packet;

    total_memory_usage += strlen(payload);

    return 0;
}

void print_packets() {
    Packet* current = head;
    while (current != NULL) {
        printf("Metadata: %d, Payload: %s\n", current->metadata, current->payload);
        current = current->next;
    }
}

int main() {
    add_packet(1, "Packet 1");
    add_packet(2, "Packet 2");
    add_packet(3, "Packet 3 that exceeds limit");

    print_packets();

    return 0;
