#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define CONFIG_FILE "config.txt"
#define DEFAULT_BUFFER_SIZE 1024
#define MAX_ALIGNMENT 64

typedef struct {
    size_t buffer_size;
    size_t alignment;
} Config;

Config load_config(const char* config_path) {
    FILE* file = fopen(config_path, "r");
    if (file == NULL) {
        return (Config){DEFAULT_BUFFER_SIZE, MAX_ALIGNMENT};
    }

    Config config = {0};
    fscanf(file, "%zu %zu", &config.buffer_size, &config.alignment);
    fclose(file);
    return config;
}

size_t calculate_buffer_size(size_t file_count, size_t max_file_size, const Config* config) {
    if (file_count * max_file_size > SIZE_MAX / sizeof(char)) {
        fprintf(stderr, "Error: Integer overflow in buffer size calculation\n");
        exit(EXIT_FAILURE);
    }

    return file_count * max_file_size + config->buffer_size;
}

void* allocate_buffer(size_t size, const Config* config) {
    if (size % config->alignment != 0) {
        size = ((size / config->alignment) + 1) * config->alignment;
    }

    void* buffer = aligned_alloc(config->alignment, size);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return buffer;
}

void process_files(const char** file_paths, int file_count, const Config* config) {
    size_t total_size = calculate_buffer_size(file_count, 1024 * 1024, config); // Assuming max file size
    void* buffer = allocate_buffer(total_size, config);

    for (int i = 0; i < file_count; ++i) {
        FILE* file = fopen(file_paths[i], "rb");
        if (file == NULL) {
            fprintf(stderr, "Error: Failed to open file %s\n", file_paths[i]);
            continue;
        }

        fseek(file, 0, SEEK_END);
        size_t file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        char* buffer_ptr = (char*)buffer + i * config->buffer_size;
        if (fread(buffer_ptr, 1, file_size, file) != file_size) {
            fprintf(stderr, "Error: Failed to read file %s\n", file_paths[i]);
            fclose(file);
            continue;
        }

        // Process the file data here

        fclose(file);
    }

    free(buffer);
}

int main() {
    Config config = load_config(CONFIG_FILE);
    const char* files[] = {"image1.jpg", "image2.jpg"};
    int file_count = sizeof(files) / sizeof(files[0]);

    process_files(files, file_count, &config);

    return 0;
}
