#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Packet {
    int payload_size;
    bool is_critical;
    struct Packet *next;
} Packet;

typedef struct Queue {
    Packet *front, *rear;
    int count;
    size_t total_buffer_size;
} Queue;

Queue* createQueue(size_t max_payload_size) {
    Queue *queue = (Queue*)malloc(sizeof(Queue));
    queue->front = queue->rear = NULL;
    queue->count = 0;
    queue->total_buffer_size = 0;
    return queue;
}

bool isFull(Queue *queue, size_t packet_size, size_t alignment) {
    size_t aligned_payload_size = ((packet_size + alignment - 1) / alignment) * alignment;
    return (queue->total_buffer_size + aligned_payload_size > 50 * 1024 * 1024); // 50% of total memory
}

void enqueue(Queue *queue, int payload_size, bool is_critical) {
    if (isFull(queue, payload_size, sizeof(Packet))) {
        printf("Buffer full or resource limit reached.\n");
        return;
    }

    Packet *newPacket = (Packet*)malloc(sizeof(Packet));
    newPacket->payload_size = payload_size;
    newPacket->is_critical = is_critical;
    newPacket->next = NULL;

    size_t aligned_payload_size = ((payload_size + sizeof(Packet) - 1) / sizeof(Packet)) * sizeof(Packet);
    queue->total_buffer_size += aligned_payload_size;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newPacket;
    } else {
        queue->rear->next = newPacket;
        queue->rear = newPacket;
    }
    queue->count++;
}

Packet* dequeue(Queue *queue) {
    if (queue->front == NULL) {
        printf("Queue is empty.\n");
        return NULL;
    }

    Packet *temp = queue->front;
    queue->front = queue->front->next;

    if (queue->front == NULL)
        queue->rear = NULL;

    size_t aligned_payload_size = ((temp->payload_size + sizeof(Packet) - 1) / sizeof(Packet)) * sizeof(Packet);
    queue->total_buffer_size -= aligned_payload_size;
    queue->count--;

    return temp;
}

void processPackets(Queue *queue) {
    Packet *current = queue->front;
    while (current != NULL) {
        if (current->is_critical) {
            printf("Processing critical packet with payload size: %d\n", current->payload_size);
            free(current);
            current = NULL;
        } else {
            // Simulate processing of non-critical packets
            printf("Buffering non-critical packet with payload size: %d\n", current->payload_size);
        }
        queue->front = current->next;
        if (current != NULL) {
            free(current);
        }
        current = queue->front;
    }
}

int main() {
    Queue *queue = createQueue(1024);

    enqueue(queue, 512, true);
    enqueue(queue, 2048, false);
    enqueue(queue, 768, true);

    processPackets(queue);

    return 0;
}
