void allocate_memory_for_nfaip_crc_indications(uint32_t additional_needed) {
    uint32_t new_limit = current_usage + additional_needed;
    if (new_limit > MAX_NFAP_CRC_INDICATIONS) {
        printf("Memory allocation failed: Exceeds maximum limit.\n");
        return;
    }

    for (uint32_t i = 0; i < additional_needed; ++i) {
        nfapi_crc_indication_pool[current_usage + i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapi_crc_indication_pool[current_usage + i]) {
            printf("Memory allocation failed: Out of memory.\n");
            new_limit = current_usage;
            break;
        }
    }

    current_usage = new_limit;
}

void initialize_nfaip_crc_indications() {
    allocate_memory_for_nfaip_crc_indications(10);
}

void release_memory_for_nfaip_crc_indications(uint32_t to_release) {
    for (uint32_t i = 0; i < to_release; ++i) {
        if (nfapi_crc_indication_pool[current_usage - i]) {
            free(nfapi_crc_indication_pool[current_usage - i]);
            nfapi_crc_indication_pool[current_usage - i] = NULL;
        }
    }
    current_usage -= to_release;
}

