#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Packet {
    int protocol_type;
    size_t length;
    time_t timestamp;
} Packet;

typedef struct PacketBuffer {
    Packet *packets;
    size_t size;
    size_t count;
    size_t max_heap_size;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_size, size_t max_heap_size) {
    if (initial_size == 0 || max_heap_size == 0) return NULL;
    PacketBuffer *buffer = malloc(sizeof(PacketBuffer));
    if (!buffer) return NULL;

    buffer->packets = malloc(initial_size * sizeof(Packet));
    if (!buffer->packets) {
        free(buffer);
        return NULL;
    }

    buffer->size = initial_size;
    buffer->count = 0;
    buffer->max_heap_size = max_heap_size;

    return buffer;
}

int add_packet(PacketBuffer *buffer, int protocol_type, size_t length, time_t timestamp) {
    if (length > buffer->max_heap_size - sizeof(time_t)) return -1; // Check for potential overflow
    if (buffer->count >= buffer->size) {
        size_t new_size = buffer->size * 2;
        if (new_size * sizeof(Packet) > buffer->max_heap_size) return -1; // Ensure within max heap size
        Packet *new_packets = realloc(buffer->packets, new_size * sizeof(Packet));
        if (!new_packets) return -1;

        buffer->packets = new_packets;
        buffer->size = new_size;
    }

    buffer->packets[buffer->count].protocol_type = protocol_type;
    buffer->packets[buffer->count].length = length;
    buffer->packets[buffer->count].timestamp = timestamp;
    buffer->count++;

    return 0;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    free(buffer->packets);
    free(buffer);
}

// Example usage
int main() {
    PacketBuffer *buffer = create_packet_buffer(10, 1024); // Initial size of 10 and max heap size of 1024 bytes
    if (!buffer) return -1;

    add_packet(buffer, 6, 50, time(NULL));
    add_packet(buffer, 17, 100, time(NULL));

    for (size_t i = 0; i < buffer->count; i++) {
        printf("Protocol: %d, Length: %zu, Timestamp: %ld\n", 
               buffer->packets[i].protocol_type,
               buffer->packets[i].length,
               buffer->packets[i].timestamp);
    }

    destroy_packet_buffer(buffer);
    return 0;
}
