// Function to dynamically generate image thumbnails
int createThumbnails(int N, int MAX_MEM, Thumbnail** thumbnails) {
    // Validate input
    if (N <= 0) {
        fprintf(stderr, "Invalid number of thumbnails: %d\n", N);
        return -1;
    }

    // Calculate the size of a single thumbnail
    size_t thumbnail_size = sizeof(Thumbnail);

    // Adjust N to fit within memory limit
    int actual_N = N;
    while (actual_N > 0 && actual_N * thumbnail_size > MAX_MEM) {
        actual_N--;
    }
    if (actual_N == 0) {
        fprintf(stderr, "Not enough memory for even one thumbnail\n");
        return -1;
    }

    // Allocate memory for the thumbnails
    *thumbnails = malloc(actual_N * thumbnail_size);
    if (*thumbnails == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return -1;
    }

    // Populate the thumbnails with metadata (example implementation)
    for (int i = 0; i < actual_N; i++) {
        (*thumbnails)[i].width = rand() % 800 + 100;
        (*thumbnails)[i].height = rand() % 600 + 100;
        (*thumbnails)[i].id = i;
    }

    return actual_N;
}

