#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 10000
#define MEMORY_LIMIT (1 * 1024 * 1024 * 1024) // 1 GB

typedef struct Task {
    void* imageData;
    size_t imageSize;
    time_t lastAccessTime;
} Task;

Task* taskQueue[MAX_TASKS];
size_t queueSize = 0;
size_t totalMemoryUsage = 0;

void evictLeastRecentlyUsed() {
    if (queueSize == 0) return;

    int lruIndex = 0;
    for (int i = 1; i < queueSize; ++i) {
        if (taskQueue[i]->lastAccessTime < taskQueue[lruIndex]->lastAccessTime) {
            lruIndex = i;
        }
    }

    totalMemoryUsage -= taskQueue[lruIndex]->imageSize;
    free(taskQueue[lruIndex]->imageData);
    free(taskQueue[lruIndex]);
    for (int i = lruIndex; i < queueSize - 1; ++i) {
        taskQueue[i] = taskQueue[i + 1];
    }
    --queueSize;
}

Task* createTask(void* imageData, size_t imageSize) {
    if (imageData == NULL || imageSize == 0) return NULL;

    Task* newTask = (Task*)malloc(sizeof(Task));
    if (newTask == NULL) return NULL;

    newTask->imageData = malloc(imageSize);
    if (newTask->imageData == NULL) {
        free(newTask);
        return NULL;
    }

    memcpy(newTask->imageData, imageData, imageSize);
    newTask->imageSize = imageSize;
    newTask->lastAccessTime = time(NULL);

    return newTask;
}

void enqueueTask(Task* task) {
    if (task == NULL) return;

    while (totalMemoryUsage + task->imageSize > MEMORY_LIMIT && queueSize > 0) {
        evictLeastRecentlyUsed();
    }

    taskQueue[queueSize++] = task;
    totalMemoryUsage += task->imageSize;
}

Task* dequeueTask() {
    if (queueSize == 0) return NULL;

    Task* task = taskQueue[--queueSize];
    task->lastAccessTime = time(NULL);
    totalMemoryUsage -= task->imageSize;
    return task;
}

void updateTaskLastAccess(Task* task) {
    if (task != NULL) {
        task->lastAccessTime = time(NULL);
    }
}

// Example usage
int main() {
    // Simulate adding tasks to the queue
    for (int i = 0; i < MAX_TASKS; ++i) {
        void* imageData = malloc(1024 * 1024); // 1 MB image data
        Task* task = createTask(imageData, 1024 * 1024);
        if (task != NULL) {
            enqueueTask(task);
        }
    }

    // Simulate processing tasks from the queue
    while (queueSize > 0) {
        Task* task = dequeueTask();
        if (task != NULL) {
            free(task->imageData);
            free(task);
        }
    }

    return 0;
}
