#include <stdio.h>
#include <stdlib.h>

#define MAX_THUMBNAILS 100
#define MAX-thumbnail_SIZE 4096

typedef struct {
    int width;
    int height;
    unsigned char *data;
} Thumbnail;

typedef struct {
    Thumbnail thumbnails[MAX_THUMBNAILS];
    int count;
    int eviction_index;
    size_t total_memory_usage;
    size_t max_memory_limit;
} ThumbnailCache;

ThumbnailCache cache = {0};

void initialize_cache(size_t max_memory) {
    cache.max_memory_limit = max_memory;
}

int add_thumbnail(int width, int height, unsigned char *data) {
    if (cache.count >= MAX_THUMBNAILS) {
        // Evict the least recently added thumbnail
        free(cache.thumbnails[cache.eviction_index].data);
        cache.eviction_index = (cache.eviction_index + 1) % MAX_THUMBNAILS;
    }

    int index = cache.count++;
    Thumbnail *thumbnail = &cache.thumbnails[index];
    thumbnail->width = width;
    thumbnail->height = height;

    // Allocate memory for the thumbnail data
    size_t new_memory_usage = cache.total_memory_usage + (size_t)width * (size_t)height;
    if (new_memory_usage > cache.max_memory_limit) {
        printf("Memory limit exceeded, eviction triggered.\n");
        free(thumbnail->data);
        cache.count--;
        return -1; // Memory allocation failed
    }

    thumbnail->data = (unsigned char *)malloc((size_t)width * (size_t)height);
    if (!thumbnail->data) {
        printf("Memory allocation failed.\n");
        cache.count--;
        return -1;
    }

    // Copy the data into the allocated memory
    memcpy(thumbnail->data, data, (size_t)width * (size_t)height);

    cache.total_memory_usage = new_memory_usage;

    return index; // Return the index of the added thumbnail
}

void free_cache() {
    for (int i = 0; i < cache.count; i++) {
        free(cache.thumbnails[i].data);
    }
    cache.count = 0;
    cache.eviction_index = 0;
    cache.total_memory_usage = 0;
}
