FrameMetadata* allocate_and_initialize_frames(size_t num_frames, const size_t* frame_sizes) {
    if (num_frames == 0 || frame_sizes == NULL) {
        fprintf(stderr, "Invalid input: num_frames must be greater than 0 and frame_sizes cannot be NULL.\n");
        return NULL;
    }

    FrameMetadata* frames = (FrameMetadata*)malloc(num_frames * sizeof(FrameMetadata));
    if (frames == NULL) {
        fprintf(stderr, "Memory allocation failed for frames.\n");
        return NULL;
    }

    size_t total_payload_size = 0;
    for (size_t i = 0; i < num_frames; ++i) {
        if (frame_sizes[i] == 0) {
            fprintf(stderr, "Invalid input: frame_sizes cannot contain zero values.\n");
            free(frames);
            return NULL;
        }

        // Check for potential integer overflow
        size_t new_total = total_payload_size + frame_sizes[i];
        if (new_total < total_payload_size) {
            fprintf(stderr, "Integer overflow detected in payload size calculation.\n");
            free(frames);
            return NULL;
        }

        total_payload_size = new_total;
    }

    frames->payload = (char*)malloc(total_payload_size * sizeof(char));
    if (frames->payload == NULL) {
        fprintf(stderr, "Memory allocation failed for payload.\n");
        free(frames);
        return NULL;
    }

    // Initialize frames with payloads and metadata
    char* current_position = frames->payload;
    for (size_t i = 0; i < num_frames; ++i) {
        frames[i].payload = current_position;
        frames[i].length = frame_sizes[i];
        frames[i].timestamp = get_current_timestamp(); // Assume this function is defined elsewhere

        memcpy(current_position, get_payload_data(i), frame_sizes[i]); // Assume these functions are defined elsewhere
        current_position += frame_sizes[i];
    }

    return frames;
}

// Example usage:
