#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t *protocol_type;
    size_t *packet_length;
    time_t *timestamp;
} PacketInfo;

PacketInfo* process_packets(size_t max_packets, size_t initial_capacity) {
    PacketInfo *packets = (PacketInfo *)malloc(initial_capacity * sizeof(PacketInfo));
    if (!packets) return NULL;

    packets->protocol_type = (uint8_t *)malloc(initial_capacity * sizeof(uint8_t));
    if (!packets->protocol_type) {
        free(packets);
        return NULL;
    }

    packets->packet_length = (size_t *)malloc(initial_capacity * sizeof(size_t));
    if (!packets->packet_length) {
        free(packets->protocol_type);
        free(packets);
        return NULL;
    }

    packets->timestamp = (time_t *)malloc(initial_capacity * sizeof(time_t));
    if (!packets->timestamp) {
        free(packets->protocol_type);
        free(packets->packet_length);
        free(packets);
        return NULL;
    }

    size_t current_size = 0;
    for (size_t i = 0; i < max_packets; ++i) {
        // Simulate packet processing
        if (current_size >= initial_capacity) {
            size_t new_capacity = initial_capacity + (initial_capacity / 2);
            uint8_t *new_protocol_type = (uint8_t *)realloc(packets->protocol_type, new_capacity * sizeof(uint8_t));
            if (!new_protocol_type) break;
            packets->protocol_type = new_protocol_type;

            size_t *new_packet_length = (size_t *)realloc(packets->packet_length, new_capacity * sizeof(size_t));
            if (!new_packet_length) break;
            packets->packet_length = new_packet_length;

            time_t *new_timestamp = (time_t *)realloc(packets->timestamp, new_capacity * sizeof(time_t));
            if (!new_timestamp) break;
            packets->timestamp = new_timestamp;

            initial_capacity = new_capacity;
        }

        // Example: Simulate packet data
        uint8_t protocol = 6; // TCP
        size_t length = 1024; // Packet length in bytes
        time_t current_time = time(NULL);

        if (length > UINT_MAX) {
            // Handle potential integer overflow
            continue;
        }

        packets->protocol_type[current_size] = protocol;
        packets->packet_length[current_size] = length;
        packets->timestamp[current_size] = current_time;

        ++current_size;
    }

    if (current_size < initial_capacity) {
        // Shrink memory allocations to fit the actual data size
        uint8_t *new_protocol_type = (uint8_t *)realloc(packets->protocol_type, current_size * sizeof(uint8_t));
        packets->protocol_type = new_protocol_type;

        size_t *new_packet_length = (size_t *)realloc(packets->packet_length, current_size * sizeof(size_t));
        packets->packet_length = new_packet_length;

        time_t *new_timestamp = (time_t *)realloc(packets->timestamp, current_size * sizeof(time_t));
        packets->timestamp = new_timestamp;
    }

    return packets;
}
