#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500
#define INITIAL_HEAP_SIZE 1024
#define GROWTH_FACTOR 2

typedef struct Packet {
    uint8_t protocol_type;
    uint16_t packet_length;
    time_t timestamp;
    uint32_t sequence_number;
    uint8_t data[MAX_PACKET_SIZE];
} Packet;

typedef struct Node {
    Packet *packet;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    size_t count;
    size_t max_heap_size;
} PacketQueue;

PacketQueue* create_packet_queue(size_t max_heap_size) {
    PacketQueue *queue = (PacketQueue *)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->head = queue->tail = NULL;
    queue->count = 0;
    queue->max_heap_size = max_heap_size;

    return queue;
}

void enqueue_packet(PacketQueue *queue, Packet *packet) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return;

    node->packet = packet;
    node->next = NULL;

    if (queue->tail) {
        queue->tail->next = node;
    } else {
        queue->head = node;
    }
    queue->tail = node;
    queue->count++;

    // Grow the heap if necessary
    if ((queue->max_heap_size - queue->count) < INITIAL_HEAP_SIZE) {
        size_t new_size = queue->max_heap_size * GROWTH_FACTOR;
        // Allocate more memory for the queue
        // ...
    }
}

Packet* dequeue_packet(PacketQueue *queue) {
    if (!queue->head) return NULL;

    Node *node = queue->head;
    Packet *packet = node->packet;

    queue->head = node->next;
    if (!queue->head) queue->tail = NULL;
    queue->count--;

    free(node);

    // Shrink the heap if necessary
    if (queue->count < queue->max_heap_size / GROWTH_FACTOR) {
        size_t new_size = queue->max_heap_size / GROWTH_FACTOR;
        // Deallocate memory from the queue
        // ...
    }

    return packet;
}

void destroy_packet_queue(PacketQueue *queue) {
    while (queue->head) {
        Node *node = queue->head;
        free(node->packet);
        free(node);
        queue->head = node->next;
    }
    free(queue);
}
