function renderFooterScripts(scripts) {
    let scriptTags = '';
    scripts.forEach(script => {
        if (script && typeof script.key === 'string' && typeof script.code === 'string') {
            try {
                scriptTags += `<script key="${script.key}">${escapeHtml(script.code)}</script>`;
            } catch (e) {
                console.error('Invalid script object:', script);
            }
        }
    });
    return scriptTags;
}

function escapeHtml(str) {
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };
    return str.replace(/[&<>"']/g, m => map[m]);
}
