#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKET_SIZE 1024
#define CHECKSUM_LENGTH 4

typedef struct PacketHeader {
    uint8_t packet_type;
    uint32_t timestamp;
    uint16_t length;
} PacketHeader;

uint32_t calculate_checksum(const void *data, size_t size) {
    uint32_t sum = 0;
    const uint16_t *ptr = (const uint16_t *)data;
    while (size > 1) {
        sum += *ptr++;
        size -= sizeof(uint16_t);
    }
    if (size) {
        sum += *(uint8_t *)ptr;
    }
    return ~sum;
}

int process_packet_data(const void *packet_stream, size_t stream_length, PacketHeader **headers, uint8_t ***payloads, uint32_t *total_packets) {
    if (!stream_length || stream_length > MAX_PACKET_SIZE * 1024) {
        return -1; // Invalid or too large packet stream
    }

    uint32_t expected_checksum = *(uint32_t *)(packet_stream + stream_length - CHECKSUM_LENGTH);
    uint32_t computed_checksum = calculate_checksum(packet_stream, stream_length - CHECKSUM_LENGTH);

    if (expected_checksum != computed_checksum) {
        return -1; // Packet stream integrity check failed
    }

    *total_packets = 0;
    const uint8_t *ptr = packet_stream;

    while (ptr < packet_stream + stream_length - CHECKSUM_LENGTH) {
        const PacketHeader *header = (const PacketHeader *)ptr;
        if (header->length > MAX_PACKET_SIZE || header->timestamp == 0) {
            return -1; // Invalid packet metadata
        }

        *headers = realloc(*headers, (*total_packets + 1) * sizeof(PacketHeader));
        *payloads = realloc(*payloads, (*total_packets + 1) * sizeof(uint8_t *));
        if (!*headers || !*payloads) {
            return -1; // Memory allocation failed
        }

        (*headers)[*total_packets] = *header;
        (*payloads)[*total_packets] = malloc(header->length);
        if (!(*payloads)[*total_packets]) {
            free(*headers);
            *headers = NULL;
            return -1; // Payload memory allocation failed
        }

        memcpy((*payloads)[*total_packets], ptr + sizeof(PacketHeader), header->length);

        ptr += sizeof(PacketHeader) + header->length;
        (*total_packets)++;
    }

    return 0; // Success
}

int main() {
    // Example usage
    const size_t stream_length = 2048;
    uint32_t total_packets;
    PacketHeader *headers = NULL;
    uint8_t **payloads = NULL;

    int result = process_packet_data(packet_stream, stream_length, &headers, &payloads, &total_packets);
    if (result == 0) {
        printf("Processed %u packets\n", total_packets);
        // Free allocated memory
        for (size_t i = 0; i < total_packets; i++) {
            free(payloads[i]);
        }
        free(headers);
        free(payloads);
    } else {
