['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 10000
#define HEADER_SIZE sizeof(PacketHeader)
#define MIN_PACKET_SIZE 20

typedef struct {
    uint8_t type;
    uint32_t timestamp;
    uint32_t length;
} PacketHeader;

typedef struct {
    PacketHeader header;
    char* payload;
} Packet;

int parse_packet_stream(const unsigned char* stream, size_t length, Packet** packets) {
    if (length == 0 || length > MAX_PACKETS * MIN_PACKET_SIZE) return -1; // Basic validation

    int packet_count = length / MIN_PACKET_SIZE; // Simplified calculation
    *packets = malloc(packet_count * sizeof(Packet));
    if (*packets == NULL) return -2; // Memory allocation failure

    for (int i = 0; i < packet_count; i++) {
        size_t header_end = HEADER_SIZE;
        if (length < header_end + MIN_PACKET_SIZE) break; // Not enough data for a complete packet

        (*packets)[i].header.type = stream[i * MIN_PACKET_SIZE];
        (*packets)[i].header.timestamp = *(uint32_t*)&stream[i * MIN_PACKET_SIZE + 1];
        (*packets)[i].header.length = *(uint32_t*)&stream[i * MIN_PACKET_SIZE + 5];

        if ((*packets)[i].header.length > length - header_end) break; // Malformed packet

        (*packets)[i].payload = malloc((*packets)[i].header.length);
        if ((*packets)[i].payload == NULL) {
            free(*packets); // Clean up allocated memory on failure
            return -3;
        }
        memcpy((*packets)[i].payload, &stream[header_end], (*packets)[i].header.length);

        length -= header_end + (*packets)[i].header.length; // Move past this packet
    }

    return packet_count;
}

void free_packets(Packet* packets, int count) {
    for (int i = 0; i < count; i++) {
        free(packets[i].payload);
    }
    free(packets);
}
```

