typedef struct PacketData {
    int id;
    char* data;
    size_t size;
} PacketData;

typedef struct PayloadList {
    PacketData** packets;
    size_t capacity;
    size_t count;
    size_t packet_id_counter;
} PayloadList;

PayloadList* create_payload_list() {
    PayloadList* list = (PayloadList*)malloc(sizeof(PayloadList));
    list->packets = NULL;
    list->capacity = 0;
    list->count = 0;
    list->packet_id_counter = 1;
    return list;
}

void free_payload_list(PayloadList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->packets[i]->data);
        free(list->packets[i]);
    }
    free(list->packets);
    free(list);
}

void resize_packet_list(PayloadList* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    PacketData** new_packets = (PacketData**)realloc(list->packets, new_capacity * sizeof(PacketData*));
    if (!new_packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (size_t i = list->count; i < new_capacity; ++i) {
        new_packets[i] = NULL;
    }
    list->packets = new_packets;
    list->capacity = new_capacity;
}

void add_packet_to_list(PayloadList* list, const char* data, size_t size) {
    if (list->count >= list->capacity - 1) { // Leave some space for growth
        resize_packet_list(list, list->capacity * 2);
    }

    PacketData* packet = (PacketData*)malloc(sizeof(PacketData));
    packet->id = list->packet_id_counter++;
    packet->data = (char*)malloc(size + 1); // Extra byte for null terminator
    if (!packet->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memcpy(packet->data, data, size);
    packet->data[size] = '\0'; // Null terminate the string
    packet->size = size;

    list->packets[list->count++] = packet;
}

void process_packets(PayloadList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        printf("Packet ID: %d, Data: %s\n", list->packets[i]->id, list->packets[i]->data);
        // Here you would add your logic to process each packet
    }
}

int main() {
    PayloadList* list = create_payload_list();

    // Simulate receiving packets
    const char* packet1 = "Hello";
    size_t size1 = strlen(packet1);
    add_packet_to_list(list, packet1, size1);

    const char* packet2 = "World";
    size_t size2 = strlen(packet2);
    add_packet_to_list(list, packet2, size2);

    process_packets(list);

    free_payload_list(list);
    return 0;
}
