#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PacketData {
    int packet_id;
    time_t timestamp;
    char log_level;
    char *payload;
} PacketData;

typedef struct Node {
    PacketData data;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    size_t count;
    size_t max_size;
} List;

List* create_list(size_t max_size) {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    return list;
}

void free_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data.payload);
        free(current);
        current = next;
    }
    free(list);
}

int add_packet(List *list, int packet_id, time_t timestamp, char log_level, const char *payload) {
    if (list->count >= list->max_size) {
        return -1; // List is full
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data.packet_id = packet_id;
    new_node->data.timestamp = timestamp;
    new_node->data.log_level = log_level;
    new_node->data.payload = strdup(payload);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    return 0;
}

int remove_packet(List *list, int packet_id) {
    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data.payload);
            free(current);
            list->count--;
            return 0;
        }
        prev = current;
        current = current->next;
    }
    return -1; // Packet not found
}

void print_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        printf("Packet ID: %d, Timestamp: %s, Log Level: %c, Payload: %s\n",
               current->data.packet_id, ctime(&current->data.timestamp),
               current->data.log_level, current->data.payload);
        current = current->next;
    }
}

int main() {
    List *list = create_list(1000);

    add_packet(list, 1, time(NULL), 'I', "Hello, World!");
    add_packet(list, 2, time(NULL), 'W', "Warning message");

    print_list(list);

    remove_packet(list, 1);
    print_list(list);

    free_list(list);
    return 0;
}
```

