#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint16_t payload_size;
    char* payload_data;
} Packet;

Packet* process_packet_headers(const char* data, size_t length, size_t max_packets, size_t max_payload_size, size_t* packet_count) {
    if (!data || !packet_count) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Packet* packets = (Packet*)malloc(max_packets * sizeof(Packet));
    if (!packets) {
        fprintf(stderr, "Failed to allocate memory for packets.\n");
        return NULL;
    }

    size_t packet_index = 0;

    while (length > 0 && packet_index < max_packets) {
        // Assuming each packet header is 2 bytes
        if (length < 2) {
            fprintf(stderr, "Incomplete packet header.\n");
            break;
        }
        uint16_t payload_size = *(uint16_t*)data;

        if ((size_t)payload_size > max_payload_size || (payload_size + sizeof(uint16_t)) > length) {
            fprintf(stderr, "Invalid payload size or incomplete data.\n");
            break;
        }

        packets[packet_index].payload_size = payload_size;
        packets[packet_index].payload_data = (char*)malloc(payload_size);
        if (!packets[packet_index].payload_data) {
            fprintf(stderr, "Failed to allocate memory for packet payload.\n");
            free(packets);
            return NULL;
        }

        memcpy(packets[packet_index].payload_data, data + 2, payload_size);

        length -= (payload_size + sizeof(uint16_t));
        data += payload_size + sizeof(uint16_t);
        packet_index++;
    }

    *packet_count = packet_index;
    return packets;
}

int main() {
    const char* data = "\x0A\x05Hello\x0B\x03World"; // Example input
    size_t length = 18;
    size_t max_packets = 10;
    size_t max_payload_size = 256;
    size_t packet_count;

    Packet* packets = process_packet_headers(data, length, max_packets, max_payload_size, &packet_count);

    if (packets) {
        for (size_t i = 0; i < packet_count; i++) {
            printf("Packet %zu: Size = %u, Payload = %s\n", i, packets[i].payload_size, packets[i].payload_data);
            free(packets[i].payload_data);
        }
        free(packets);
    }

    return 0;
}
