        return -1; // Error or invalid input
    }
    return num_images * sizeof(ImageMetadata);
}

ImageMetadata* read_image_metadata(const char* file_path) {
    // Simulate reading metadata from a file, error handling, etc.
    ImageMetadata* metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (!metadata) {
        perror("Failed to allocate memory for image metadata");
        return NULL;
    }
    // Populate metadata fields
    return metadata;
}

int process_image_files(const char** file_paths, int num_files) {
    int total_size = calculate_buffer_size(num_files);
    if (total_size < 0) {
        fprintf(stderr, "Invalid number of files or memory allocation failed.\n");
        return -1;
    }

    ImageMetadata* metadata_buffer = (ImageMetadata*)malloc(total_size);
    if (!metadata_buffer) {
        perror("Failed to allocate buffer for image metadata");
        return -2;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int processed_count = 0;

    for (int i = 0; i < num_files; ++i) {
        ImageMetadata* metadata = read_image_metadata(file_paths[i]);
        if (!metadata) {
            fprintf(stderr, "Failed to read metadata from file: %s\n", file_paths[i]);
            continue;
        }

        pthread_mutex_lock(&mutex);
        // Safely write metadata into the buffer
        memcpy(metadata_buffer + processed_count++, metadata, sizeof(ImageMetadata));
        free(metadata); // Free temporary metadata copy after copying
        pthread_mutex_unlock(&mutex);
    }

    printf("Processed %d out of %d image files.\n", processed_count, num_files);

    // Clean up if necessary (e.g., write to disk, release resources)
    free(metadata_buffer);

    return processed_count;
}

int main() {
    const char* files[] = {"image1.jpg", "image2.png", "image3.bmp"};
    int result = process_image_files(files, 3);
    if (result < 0) {
        fprintf(stderr, "Error processing image files.\n");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
