#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE 1024 * 1024 * 1024 // 1GB
#define MIN_N 1
#define MAX_N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_and_populate_array(int N) {
    if (N < MIN_N || N > MAX_N) {
        fprintf(stderr, "Invalid number of elements: %d\n", N);
        return NULL;
    }

    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Exceeds maximum memory limit: %zu bytes\n", required_memory);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(required_memory);
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&array_lock);

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1024;
        array[i].CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
    }

    pthread_mutex_unlock(&array_lock);

    return array;
}

void free_array(void* array) {
    pthread_mutex_lock(&array_lock);
    free(array);
    pthread_mutex_unlock(&array_lock);
}

int main() {
    srand(time(NULL));

    int N = rand() % (MAX_N - MIN_N + 1) + MIN_N;
    void* allocated_array = allocate_and_populate_array(N);

    if (allocated_array) {
        printf("Array of size %d allocated and populated successfully.\n", N);
        free_array(allocated_array);
    }

    return 0;
}
