#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct NetworkConfig {
    char tag[256];
    char params[1024];
} NetworkConfig;

typedef struct ConfigList {
    NetworkConfig *configs;
    size_t count;
    size_t capacity;
} ConfigList;

ConfigList* create_config_list(size_t initial_capacity) {
    ConfigList *list = malloc(sizeof(ConfigList));
    if (list == NULL) return NULL;

    list->count = 0;
    list->capacity = initial_capacity > 0 ? initial_capacity : 16; // Default to a minimum capacity
    list->configs = malloc(list->capacity * sizeof(NetworkConfig));

    if (list->configs == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_config_list(ConfigList *list) {
    if (list != NULL) {
        free(list->configs);
        free(list);
    }
}

int add_config(ConfigList *list, const char *tag, const char *params) {
    if (list == NULL || tag == NULL || params == NULL) return -1;

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkConfig *new_configs = realloc(list->configs, new_capacity * sizeof(NetworkConfig));
        if (new_configs == NULL) return -1; // Memory allocation failed

        list->configs = new_configs;
        list->capacity = new_capacity;
    }

    strncpy(list->configs[list->count].tag, tag, sizeof(list->configs[list->count].tag) - 1);
    list->configs[list->count].tag[sizeof(list->configs[list->count].tag) - 1] = '\0';
    strncpy(list->configs[list->count].params, params, sizeof(list->configs[list->count].params) - 1);
    list->configs[list->count].params[sizeof(list->configs[list->count].params) - 1] = '\0';

    list->count++;
    return 0;
}

// Example usage:
int main() {
    ConfigList *list = create_config_list(5);
    if (list == NULL) {
        // Handle error
        return 1;
    }

    if (add_config(list, "eth0", "192.168.1.1/24") != 0 || add_config(list, "wlan0", "192.168.1.2/24") != 0) {
        // Handle error
        destroy_config_list(list);
        return 1;
    }

    // Process the list...

    destroy_config_list(list);
    return 0;
}
