#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void* blocks;
};

void* memory_pool_alloc(struct MemoryPool* pool) {
    if (pool->blocks == NULL || pool->num_blocks == 0) {
        return NULL;
    }
    void* ptr = pool->blocks;
    pool->blocks = (char*)pool->blocks + pool->block_size;
    pool->num_blocks--;
    return ptr;
}

void memory_pool_free(struct MemoryPool* pool, void* ptr) {
    if (ptr == NULL || pool->blocks != ptr) {
        return;
    }
    pool->blocks = ptr;
    pool->num_blocks++;
}

struct NFAPI_Crc_Indication_Manager {
    struct MemoryPool* pool;
    pthread_mutex_t mutex;
};

struct NFAPI_Crc_Indication_Manager* create_manager(size_t num_structs, size_t max_rnti) {
    struct NFAPI_Crc_Indication_Manager* manager = malloc(sizeof(struct NFAPI_Crc_Indication_Manager));
    if (manager == NULL) {
        return NULL;
    }
    manager->pool = malloc(sizeof(struct MemoryPool));
    if (manager->pool == NULL) {
        free(manager);
        return NULL;
    }
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    manager->pool->block_size = block_size;
    manager->pool->num_blocks = num_structs;
    manager->pool->blocks = malloc(num_structs * block_size);
    if (manager->pool->blocks == NULL) {
        free(manager->pool);
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_manager(struct NFAPI_Crc_Indication_Manager* manager) {
    if (manager != NULL) {
        if (manager->pool->blocks != NULL) {
            free(manager->pool->blocks);
        }
        free(manager->pool);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

void manage_crc_indications(struct NFAPI_Crc_Indication_Manager* manager, size_t num_structs, uint16_t rnti_range) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < num_structs; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(manager->pool);
        if (pdu == NULL) {
            // Handle memory allocation failure
            continue;
        }
        pdu->RX_UE_INFORMATION_TAG = rand();
        if (rnti_range > 0 && rnti_range <= UINT16_MAX) {
            pdu->RNTI = rand() % (rnti_range + 1);
        } else {
            // Handle out-of-range RNTI value
        }
        pdu->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);
    }
    pthread_mutex_unlock(&manager->mutex);
}

