typedef struct {
    uint32_t *buffer;
    int sequenceNumber;
} FrameMetadata;

FrameMetadata* allocateFrameMetadata(const char *configFile, int maxSequenceSize) {
    FILE *file = fopen(configFile, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    int numFrames;
    if (fscanf(file, "%d", &numFrames) != 1 || numFrames <= 0) {
        fprintf(stderr, "Invalid number of frames in configuration file\n");
        fclose(file);
        return NULL;
    }

    FrameMetadata *metadata = (FrameMetadata *)malloc(numFrames * sizeof(FrameMetadata));
    if (!metadata) {
        perror("Failed to allocate memory for frame metadata");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < numFrames; ++i) {
        uint32_t bufferLength;
        int sequenceNumber;

        if (fscanf(file, "%u %d", &bufferLength, &sequenceNumber) != 2 ||
            sequenceNumber < 0 || sequenceNumber > maxSequenceSize) {
            fprintf(stderr, "Invalid frame metadata in configuration file\n");
            free(metadata);
            fclose(file);
            return NULL;
        }

        if (sequenceNumber == maxSequenceSize) {
            // Implement a memory allocation strategy for large sequence numbers
            // to handle potential performance degradation.
        }

        metadata[i].buffer = (uint32_t *)malloc(bufferLength * sizeof(uint32_t));
        if (!metadata[i].buffer) {
            perror("Failed to allocate memory for frame buffer");
            for (int j = 0; j < i; ++j) {
                free(metadata[j].buffer);
            }
            free(metadata);
            fclose(file);
            return NULL;
        }

        metadata[i].sequenceNumber = sequenceNumber;
    }

    fclose(file);
    return metadata;
}
