ImageMetadataStore* create_image_metadata_store(int max_file_count) {
    if (max_file_count <= 0 || max_file_count > 10000) {
        fprintf(stderr, "Invalid max_file_count. Must be between 1 and 10000.\n");
        return NULL;
    }

    ImageMetadataStore *store = malloc(sizeof(ImageMetadataStore));
    if (!store) {
        fprintf(stderr, "Memory allocation failed for image metadata store.\n");
        return NULL;
    }

    store->images = malloc(max_file_count * sizeof(IMAGE_FILE));
    if (!store->images) {
        fprintf(stderr, "Memory allocation failed for image files.\n");
        free(store);
        return NULL;
    }

    store->count = 0;
    store->max_count = max_file_count;
    store->total_size = 0;

    return store;
}

void add_image_to_store(ImageMetadataStore *store, IMAGE_FILE *image) {
    if (store->count >= store->max_count) {
        fprintf(stderr, "Maximum file count reached. Cannot add more images.\n");
        return;
    }

    size_t new_size = store->total_size + sizeof(IMAGE_FILE);
    if (new_size > MAX_MEM_SIZE) {
        fprintf(stderr, "Memory limit exceeded. Cannot add image to store.\n");
        return;
    }

    memcpy(&store->images[store->count], image, sizeof(IMAGE_FILE));
    store->count++;
    store->total_size = new_size;

    printf("Image '%s' added to store. Total size: %zu bytes\n", image->name, store->total_size);
}

void destroy_image_metadata_store(ImageMetadataStore *store) {
    if (store) {
        free(store->images);
        free(store);
    }
}
