#define MAX_IMAGES 1000
#define MEMORY_LIMIT 1024 * 1024 * 100 // 100 MB

typedef struct {
    int width;
    int height;
    float resolution;
    size_t fileSize;
} ImageMetadata;

int processJpegImages(char **imagePaths, int numImages) {
    if (numImages > MAX_IMAGES) {
        fprintf(stderr, "Error: Number of images exceeds the maximum limit.\n");
        return -1;
    }

    ImageMetadata *metadata = malloc(numImages * sizeof(ImageMetadata));
    if (!metadata) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    size_t totalSize = 0;
    for (int i = 0; i < numImages; i++) {
        FILE *file = fopen(imagePaths[i], "rb");
        if (!file) {
            fprintf(stderr, "Error: Failed to open file %s\n", imagePaths[i]);
            free(metadata);
            return -1;
        }

        struct jpeg_decompress_struct cinfo;
        struct jpeg_error_mgr jerr;
        cinfo.err = jpeg_std_error(&jerr);
        jpeg_create_decompress(&cinfo);

        if (jpeg_stdio_src(&cinfo, file)) {
            if (jpeg_read_header(&cinfo, TRUE)) {
                metadata[i].width = cinfo.output_width;
                metadata[i].height = cinfo.output_height;
                metadata[i].resolution = cinfo.X_density;
                metadata[i].fileSize = fseek(file, 0, SEEK_END), ftell(file);
                totalSize += sizeof(ImageMetadata);

                if (totalSize > MEMORY_LIMIT) {
                    fprintf(stderr, "Error: Adding this entry would exceed the memory limit.\n");
                    free(metadata);
                    fclose(file);
                    return -1;
                }

                jpeg_start_decompress(&cinfo);
                while (cinfo.output_scanline < cinfo.output_height) {
                    jpeg_read_scanlines(&cinfo, &metadata[i], 1);
                }
                jpeg_finish_decompress(&cinfo);
            } else {
                fprintf(stderr, "Error: Failed to read JPEG header for file %s\n", imagePaths[i]);
            }
        } else {
            fprintf(stderr, "Error: Failed to set up source manager for file %s\n", imagePaths[i]);
        }

        jpeg_destroy_decompress(&cinfo);
        fclose(file);
    }

    // Process metadata (e.g., store in database or log)
    // ...

    free(metadata);
    return 0;
}

int main() {
    char *imagePaths[] = {"image1.jpg", "image2.jpg"};
    int numImages = sizeof(imagePaths) / sizeof(imagePaths[0]);

    if (processJpegImages(imagePaths, numImages) == 0) {
        printf("All images processed successfully.\n");
    }

    return 0;
}
