int add_crc_indication(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (cache_size >= MAX_ELEMENTS) {
        return -1; // Buffer overflow
    }

    NFAPI_CRC_INDICATION_PDU_T* new_element;
    if (cache_size > 0 && cache[0] != NULL) { // Reuse existing memory from cache
        new_element = cache[0];
        cache[0] = NULL;
        cache_size--;
    } else {
        new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_element) {
            // Handle memory allocation failure
            return -2; // Memory allocation failed
        }
