    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    srand(time(NULL)); // Seed for random number generation
    new_element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    cache[cache_size++] = new_element;

    return 0;
}

void free_cache() {
    for (int i = 0; i < cache_size; i++) {
        if (cache[i]) {
            free(cache[i]);
        }
    }
