    pthread_mutex_t mutex;
} SafeNFAPICRCIndicationPDU;

SafeNFAPICRCIndicationPDU* create_safe_nfaapi_crc_indication_pdu(NFAPI_RX_UE_INFORMATION_TAG rx_ue_info_tag, uint16_t rnti) {
    SafeNFAPICRCIndicationPDU *new_item = (SafeNFAPICRCIndicationPDU *)malloc(sizeof(SafeNFAPICRCIndicationPDU));
    if (!new_item) return NULL;

    pthread_mutex_init(&new_item->mutex, NULL);
    new_item->data.rx_ue_information_tag = rx_ue_info_tag;
    new_item->data.rnti = rnti;
    new_item->data.crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRC flag
    time(&new_item->last_modified);

    return new_item;
}

void append_to_safe_list(SafeNFAPICRCIndicationPDU **head, SafeNFAPICRCIndicationPDU *item) {
    pthread_mutex_lock(&(*head)->mutex);
    item->next = *head;
    *head = item;
    pthread_mutex_unlock(&(*head)->mutex);
}

int safe_generate_and_populate_list(char *input_string, size_t size_limit, size_t max_memory_budget, SafeNFAPICRCIndicationPDU **head) {
    int total_size = 0;
    char *current_pos = input_string;

    while (current_pos && *current_pos) {
        if (strlen(current_pos) <= size_limit) {
            pthread_mutex_lock(&(*head)->mutex);
            size_t new_item_size = sizeof(SafeNFAPICRCIndicationPDU) + strlen(current_pos) + 1;
            if ((total_size + new_item_size) > max_memory_budget) {
                pthread_mutex_unlock(&(*head)->mutex);
                break;
            }
            total_size += new_item_size;

            SafeNFAPICRCIndicationPDU *new_item = create_safe_nfaapi_crc_indication_pdu(RX_UE_INFORMATION_TAG, rand() % 1024); // Example values
            if (new_item) {
                strcpy(new_item->data.crc_indication_rel8_tag.value, current_pos);
                new_item->data.crc_indication_rel8_tag.length = strlen(current_pos);

                append_to_safe_list(head, new_item);
            }
            pthread_mutex_unlock(&(*head)->mutex);
        }
        current_pos += size_limit + 1;
    }

    return total_size;
}

void free_safe_list(SafeNFAPICRCIndicationPDU **head) {
    while (*head) {
        SafeNFAPICRCIndicationPDU *temp = *head;
        *head = temp->next;
        pthread_mutex_destroy(&temp->mutex);
        free(temp);
    }
}
