#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNode(unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI, unsigned char CRC_INDICATION_REL8_TAG) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->next = NULL;
    return newNode;
}

Node* constructLinkedList(unsigned int numNodes) {
    if (numNodes > MAX_NODES || numNodes == 0) {
        fprintf(stderr, "Invalid number of nodes. Maximum allowed is %u\n", MAX_NODES);
        return NULL;
    }

    Node* head = createNode(rand() % 10000, rand() % 65536, (rand() % 2) ? 'A' : 'B');
    if (head == NULL) {
        return NULL;
    }

    Node* current = head;
    for (unsigned int i = 1; i < numNodes; ++i) {
        Node* newNode = createNode(rand() % 10000, rand() % 65536, (rand() % 2) ? 'A' : 'B');
        if (newNode == NULL) {
            freeLinkedList(head);
            return NULL;
        }
        current->next = newNode;
        current = newNode;
    }

    return head;
}

void freeLinkedList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL));

    unsigned int numNodes;
    printf("Enter the number of nodes: ");
    if (scanf("%u", &numNodes) != 1 || numNodes == 0) {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return EXIT_FAILURE;
    }

    Node* head = constructLinkedList(numNodes);
    if (head == NULL) {
        return EXIT_FAILURE;
    }

    // Process the linked list here
    freeLinkedList(head);

    return EXIT_SUCCESS;
}
