#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024 * 1024 // 1MB

typedef struct PacketInfo {
    uint32_t length;
    char data[MAX_PACKET_SIZE];
    struct PacketInfo* next;
} PacketInfo;

typedef struct PacketQueue {
    PacketInfo* head;
    PacketInfo* tail;
    size_t current_memory_usage;
    size_t max_memory_budget;
} PacketQueue;

PacketQueue* create_packet_queue(size_t max_memory_budget) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;
    queue->head = queue->tail = NULL;
    queue->current_memory_usage = 0;
    queue->max_memory_budget = max_memory_budget;
    return queue;
}

void destroy_packet_queue(PacketQueue* queue) {
    PacketInfo* current = queue->head;
    while (current) {
        PacketInfo* next = current->next;
        free(current);
        current = next;
    }
    free(queue);
}

int add_packet_to_queue(PacketQueue* queue, const char* data, uint32_t length) {
    if (length > MAX_PACKET_SIZE || length > queue->max_memory_budget - queue->current_memory_usage) {
        return -1; // Packet too large or exceeds memory budget
    }

    PacketInfo* new_packet = (PacketInfo*)malloc(sizeof(PacketInfo));
    if (!new_packet) return -2; // Memory allocation failed

    new_packet->length = length;
    memcpy(new_packet->data, data, length);
    new_packet->next = NULL;

    if (queue->tail) {
        queue->tail->next = new_packet;
    } else {
        queue->head = new_packet;
    }
    queue->tail = new_packet;
    queue->current_memory_usage += sizeof(PacketInfo) + length;

    return 0; // Packet added successfully
}

int remove_packets_from_queue(PacketQueue* queue, size_t max_length_to_remove) {
    if (max_length_to_remove > queue->current_memory_usage) {
        max_length_to_remove = queue->current_memory_usage;
    }

    while (queue->head && queue->head->length <= max_length_to_remove) {
        PacketInfo* to_remove = queue->head;
        queue->head = to_remove->next;

        if (!queue->head) {
            queue->tail = NULL;
        }

        free(to_remove);
        queue->current_memory_usage -= sizeof(PacketInfo) + to_remove->length;
        max_length_to_remove -= to_remove->length;
    }

    return 0; // Packets removed successfully
}
