#define MAX_RETRIES 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateCRCIndicationPDUs(int targetCount, size_t maxMemory, const char* logPath) {
    if (targetCount <= 0 || maxMemory == 0) {
        return -1; // Graceful degradation for invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    size_t currentSize = targetCount * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int retries = 0;

    while (currentSize > maxMemory && retries < MAX_RETRIES) {
        currentSize /= 2; // Reduce size estimate for retry
        retries++;
    }

    if (currentSize == 0) {
        return -1; // Insufficient memory even after retries
    }

    pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(currentSize);
    if (pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < currentSize / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
