        pdus[i].RNTI = rand() % 65536; // Example RNTI generation
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }

    FILE* logFile = fopen(logPath, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        free(pdus);
        return -1;
    }

    for (size_t i = 0; i < currentSize / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
