    if (memory_pool.pool == NULL) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.allocated_size = initial_size;
    memory_pool.used_size = 0;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void* memory_alloc(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_size + size > memory_pool.allocated_size) {
