#define MAX_PACKETS 10000

typedef struct {
    size_t payload_length;
    char *payload;
} Packet;

Packet* process_packets(const char *packet_stream, size_t stream_size, size_t *out_count) {
    Packet *packets = (Packet*)malloc(MAX_PACKETS * sizeof(Packet));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return NULL;
    }

    *out_count = 0;

    for (size_t i = 0; i < stream_size;) {
        size_t packet_header_size = 4; // Example header size
        size_t payload_length = 0;

        if (i + packet_header_size > stream_size) {
            fprintf(stderr, "Malformed packet header\n");
            free(packets);
            return NULL;
        }

        memcpy(&payload_length, packet_stream + i, packet_header_size);
        i += packet_header_size;

        // Dynamically allocate payload with overflow check
        if (payload_length < payload_length || payload_length > stream_size - i) {
            fprintf(stderr, "Packet payload length too large or malformed\n");
            free(packets);
            return NULL;
        }

        packets[*out_count].payload = (char*)realloc(packets[*out_count].payload, payload_length + 1);
        if (!packets[*out_count].payload) {
            perror("Failed to allocate memory for packet payload");
            free(packets);
            return NULL;
        }

        memcpy(packets[*out_count].payload, packet_stream + i, payload_length);
        packets[*out_count].payload[payload_length] = '\0';

        i += payload_length;
        (*out_count)++;
    }

    // Resize array if not fully used
    Packet *resized_packets = (Packet*)realloc(packets, (*out_count) * sizeof(Packet));
    if (resized_packets) {
        packets = resized_packets;
    } else {
        fprintf(stderr, "Failed to resize packet array\n");
    }

    return packets;
}

int main() {
    // Example usage
    const char *packet_stream = "..."; // Replace with actual packet stream data
    size_t stream_size = strlen(packet_stream);
    size_t packet_count;

    Packet *processed_packets = process_packets(packet_stream, stream_size, &packet_count);
    if (processed_packets) {
        for (size_t i = 0; i < packet_count; i++) {
            printf("Packet %zu payload: %s\n", i, processed_packets[i].payload);
            free(processed_packets[i].payload);
        }
        free(processed_packets);
    }

    return 0;
}
