typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated;
    size_t used;
    pthread_mutex_t mutex;
} CRC_ARRAY_MANAGER_T;

CRC_ARRAY_MANAGER_T* crc_array_manager_init() {
    CRC_ARRAY_MANAGER_T *manager = (CRC_ARRAY_MANAGER_T*)malloc(sizeof(CRC_ARRAY_MANAGER_T));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->allocated = MAX_ELEMENTS;
    manager->used = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void crc_array_manager_free(CRC_ARRAY_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->array);
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int crc_array_manager_add(CRC_ARRAY_MANAGER_T *manager, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->used >= manager->allocated) {
        size_t new_size = manager->allocated == 0 ? 1 : manager->allocated * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->array = new_array;
        manager->allocated = new_size;
    }

    manager->array[manager->used].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->array[manager->used].RNTI = RNTI;
    manager->array[manager->used].CRC_INDICATION_REL8_TAG = CRCFLAG;
    manager->used++;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int crc_array_manager_size(CRC_ARRAY_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->mutex);
    int size = manager->used;
    pthread_mutex_unlock(&manager->mutex);
    return size;
}
