['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct Packet {
    size_t header_size;
    size_t payload_length;
    char *payload;
    struct Packet *next;
} Packet;

typedef struct ThreadContext {
    pthread_mutex_t lock;
    size_t total_memory_used;
    size_t system_memory_limit;
} ThreadContext;

Packet* create_packet(size_t header_size, size_t payload_length, const char *payload_data) {
    Packet *packet = (Packet *)malloc(sizeof(Packet));
    if (!packet) {
        perror("Failed to allocate memory for packet");
        return NULL;
    }

    packet->header_size = header_size;
    packet->payload_length = payload_length;
    packet->payload = (char *)malloc(payload_length);
    if (!packet->payload) {
        free(packet);
        perror("Failed to allocate memory for payload");
        return NULL;
    }

    memcpy(packet->payload, payload_data, payload_length);
    packet->next = NULL;

    return packet;
}

void destroy_packet(Packet *packet) {
    free(packet->payload);
    free(packet);
}

int process_packets(ThreadContext *context, Packet **input_packets, int num_packets) {
    pthread_mutex_lock(&context->lock);

    for (int i = 0; i < num_packets; ++i) {
        if (context->total_memory_used + input_packets[i]->header_size + input_packets[i]->payload_length > context->system_memory_limit) {
            printf("Memory limit exceeded, dropping packet\n");
            destroy_packet(input_packets[i]);
        } else {
            // Simulate processing of the packet
            printf("Processing packet with payload length %zu\n", input_packets[i]->payload_length);
            // Update memory usage
            context->total_memory_used += input_packets[i]->header_size + input_packets[i]->payload_length;
        }
    }

    pthread_mutex_unlock(&context->lock);

    return 0;
}

int main() {
    ThreadContext context = { .system_memory_limit = 1024 * 1024 }; // 1MB
    pthread_mutex_init(&context.lock, NULL);

    Packet *packet1 = create_packet(16, 512, "Hello");
    Packet *packet2 = create_packet(8, 1024, "World");

    Packet *input_packets[] = { packet1, packet2 };
    int num_packets = sizeof(input_packets) / sizeof(input_packets[0]);

    process_packets(&context, input_packets, num_packets);

    pthread_mutex_destroy(&context.lock);
    destroy_packet(packet1);
    destroy_packet(packet2);

    return 0;
}
```

This code provides a basic structure for processing network packets with dynamic memory allocation and management. It includes functions for creating and destroying packet structures, as well as a function to process a stream of incoming packets while respecting a system-wide memory limit. The use of mutexes ensures thread safety, preventing multiple threads from accessing shared resources concurrently.']

