typedef struct ImageMetadata {
    int width;
    int height;
    size_t data_size;
} ImageMetadata;

typedef struct ImageData {
    void* data;
} ImageData;

typedef struct ImageBatch {
    ImageMetadata metadata[MAX_IMAGES_PER_BATCH];
    ImageData images[MAX_IMAGES_PER_BATCH];
    int count;
} ImageBatch;

void processImageBatch(ImageBatch* batch) {
    for (int i = 0; i < batch->count; i++) {
        // Simulate image processing
        printf("Processing image %d: width=%d, height=%d, data_size=%zu\n",
               i, batch->metadata[i].width, batch->metadata[i].height, batch->images[i].data);
    }
}

void validateAndAdjustBuffer(ImageBatch* batch) {
    for (int i = 0; i < batch->count; i++) {
        size_t new_data_size = batch->metadata[i].width * batch->metadata[i].height;

        // Check for integer overflow
        if (new_data_size <= batch->images[i].data || (new_data_size > SIZE_MAX / sizeof(char))) {
            fprintf(stderr, "Error: Image data size out of bounds\n");
            exit(EXIT_FAILURE);
        }

        // Adjust buffer size if necessary
        if (new_data_size > batch->images[i].data) {
            void* new_data = realloc(batch->images[i].data, new_data_size);
            if (!new_data) {
                fprintf(stderr, "Error: Failed to allocate memory\n");
                exit(EXIT_FAILURE);
            }
            batch->images[i].data = new_data;
        }
    }
}

int main() {
    ImageBatch batch;

    // Simulate receiving a batch of images
    batch.count = 3;
    batch.metadata[0] = (ImageMetadata){1920, 1080, 0};
    batch.images[0].data = malloc(batch.metadata[0].width * batch.metadata[0].height);

    batch.metadata[1] = (ImageMetadata){640, 480, 0};
    batch.images[1].data = malloc(batch.metadata[1].width * batch.metadata[1].height);

    batch.metadata[2] = (ImageMetadata){320, 240, 0};
    batch.images[2].data = malloc(batch.metadata[2].width * batch.metadata[2].height);

    // Validate and adjust buffer sizes
    validateAndAdjustBuffer(&batch);

    // Process the image batch
    processImageBatch(&batch);

    // Free allocated memory
    for (int i = 0; i < batch.count; i++) {
        free(batch.images[i].data);
    }

    return 0;
}
