    }

    size_t new_size = (size_t)num_imgs * sizeof(img_t*);
    if (new_size / num_imgs != sizeof(img_t*)) {
        return NULL; // Handle potential overflow
    }

    img_t** new_img_table = realloc(img_table, new_size);
    if (new_img_table == NULL) {
        return NULL; // Handle memory allocation failure
    }

    size_t total_size = (size_t)new_imgs * sizeof(img_t);
    if (total_size > MAX_SIZE) {
        free(new_img_table);
        return NULL; // Handle exceeding max size limit
    }

    for (int i = 0; i < num_imgs; i++) {
        new_img_table[i] = malloc(sizeof(img_t));
        if (new_img_table[i] == NULL) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(new_img_table[j]);
            }
            free(new_img_table);
            return NULL;
        }
    }

    return new_img_table;
}
