FileBuffer* initialize_file_buffer(size_t max_total_size) {
    FileBuffer* buffer = (FileBuffer*)malloc(sizeof(FileBuffer));
    if (!buffer) {
        perror("Failed to allocate memory for FileBuffer");
        return NULL;
    }
    buffer->file_paths = (char**)calloc(MAX_FILES, sizeof(char*));
    buffer->file_sizes = (size_t*)calloc(MAX_FILES, sizeof(size_t));
    buffer->total_size = 0;
    buffer->num_files = 0;

    if (!buffer->file_paths || !buffer->file_sizes) {
        perror("Failed to allocate memory for file paths or sizes");
        free(buffer);
        return NULL;
    }

    // Allocate initial buffer based on max_total_size
    buffer->file_buffer = (char*)malloc(max_total_size + 1); // Extra byte for null terminator
    if (!buffer->file_buffer) {
        perror("Failed to allocate memory for file buffer");
        free(buffer->file_paths);
        free(buffer->file_sizes);
        free(buffer);
        return NULL;
    }

    return buffer;
}

int add_file_to_buffer(FileBuffer* buffer, const char* path, size_t size) {
    if (buffer->num_files >= MAX_FILES || size > INT_MAX - buffer->total_size) {
        fprintf(stderr, "Error: Too many files or file too large\n");
        return -1;
    }

    if (path == NULL || strlen(path) >= MAX_PATH_LENGTH) {
        fprintf(stderr, "Error: Invalid file path\n");
        return -2;
    }

    buffer->file_paths[buffer->num_files] = strdup(path);
    if (!buffer->file_paths[buffer->num_files]) {
        perror("Failed to duplicate file path");
        return -3;
    }

    buffer->file_sizes[buffer->num_files] = size;
    buffer->total_size += size;
    buffer->num_files++;

    // Resize buffer if necessary
    if (buffer->total_size > strlen(buffer->file_buffer)) {
        char* new_buffer = realloc(buffer->file_buffer, buffer->total_size + 1);
        if (!new_buffer) {
            perror("Failed to reallocate memory for file buffer");
            free(buffer->file_paths[buffer->num_files - 1]);
            buffer->num_files--;
            return -4;
        }
        buffer->file_buffer = new_buffer;
    }

    // Copy file content into buffer
    memcpy(&buffer->file_buffer[strlen(buffer->file_buffer)], path, size);
    buffer->file_buffer[strlen(buffer->file_buffer)] = '\0';

    return 0;
}

void free_file_buffer(FileBuffer* buffer) {
    if (buffer) {
        for (size_t i = 0; i < buffer->num_files; ++i) {
            free(buffer->file_paths[i]);
        }
        free(buffer->file_paths);
        free(buffer->file_sizes);
        free(buffer->file_buffer);
        free(buffer);
    }
}
