    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} MetadataBuffer;

void init_metadata_buffer(MetadataBuffer *buf, size_t initial_capacity) {
    buf->capacity = initial_capacity;
    buf->size = 0;
    buf->packets = (PacketMetadata *)malloc(initial_capacity * sizeof(PacketMetadata));
    if (!buf->packets) {
        perror("Failed to allocate memory for metadata buffer");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&buf->mutex, NULL);
}

void destroy_metadata_buffer(MetadataBuffer *buf) {
    for (size_t i = 0; i < buf->size; ++i) {
        free(buf->packets[i].metadata);
    }
    free(buf->packets);
    pthread_mutex_destroy(&buf->mutex);
}

int add_packet_metadata(MetadataBuffer *buf, const char *metadata, size_t length) {
    if (length > SIZE_MAX - buf->size) {
        fprintf(stderr, "Metadata size exceeds the maximum allowed value\n");
        return -1;
    }

    if (buf->size + 1 > buf->capacity) {
        size_t new_capacity = buf->capacity * 2;
        PacketMetadata *new_packets = (PacketMetadata *)realloc(buf->packets, new_capacity * sizeof(PacketMetadata));
        if (!new_packets) {
            perror("Failed to reallocate memory for metadata buffer");
            return -1;
        }
        buf->packets = new_packets;
        buf->capacity = new_capacity;
    }

    PacketMetadata *packet = &buf->packets[buf->size++];
    packet->length = length;
    packet->metadata = (char *)malloc(length);
    if (!packet->metadata) {
        perror("Failed to allocate memory for metadata");
        return -1;
    }
    memcpy(packet->metadata, metadata, length);

    return 0;
}

void *process_packets(void *arg) {
    MetadataBuffer *buf = (MetadataBuffer *)arg;
    // Simulate packet processing
    pthread_mutex_lock(&buf->mutex);
    for (size_t i = 0; i < buf->size; ++i) {
        printf("Processing packet with metadata length: %zu\n", buf->packets[i].length);
        free(buf->packets[i].metadata);
    }
    pthread_mutex_unlock(&buf->mutex);
    return NULL;
}
