typedef struct slab_node {
    struct slab_node* next;
    NFAPI_CRC_INDICATION_PDU_T data[SLAB_SIZE];
} SlabNode;

typedef struct {
    SlabNode* head;
    pthread_mutex_t lock;
    size_t allocated;
    size_t free;
} SlabAllocator;

SlabAllocator allocator = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, SLAB_SIZE * MAX_THREADS};

void slab_alloc_init() {
    allocator.head = (SlabNode*)malloc(sizeof(SlabNode));
    allocator.head->next = NULL;
    for (int i = 1; i < MAX_THREADS; ++i) {
        SlabNode* new_node = (SlabNode*)malloc(sizeof(SlabNode));
        new_node->next = allocator.head;
        allocator.head = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T* slab_alloc() {
    pthread_mutex_lock(&allocator.lock);
    if (!allocator.free) {
        SlabNode* new_node = (SlabNode*)malloc(sizeof(SlabNode));
        new_node->next = allocator.head;
        allocator.head = new_node;
        allocator.free += SLAB_SIZE;
    }
    NFAPI_CRC_INDICATION_PDU_T* ptr = &allocator.head->data[--allocator.free];
    pthread_mutex_unlock(&allocator.lock);
    return ptr;
}

void slab_free(NFAPI_CRC_INDICATION_PDU_T* ptr) {
    pthread_mutex_lock(&allocator.lock);
    allocator.free++;
    pthread_mutex_unlock(&allocator.lock);
}

void* manage_napi_packets(void* arg) {
    for (int i = 0; i < 1000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* packet = slab_alloc();
        // Initialize packet fields here
        // ...
        slab_free(packet);
    }
    return NULL;
}

int main() {
    slab_alloc_init();
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, manage_napi_packets, NULL);
    }
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
    // Log memory usage statistics here
    return 0;
}
