#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1400
#define MAX_LIST_SIZE 1000000

typedef struct tcp_packet {
    char ip_header[MAX_PACKET_SIZE];
    char tcp_header[MAX_PACKET_SIZE];
    char payload[MAX_PACKET_SIZE];
    int payload_size;
} TCP_Packet;

typedef struct packet_list {
    TCP_Packet *packets;
    int count;
    int capacity;
    pthread_mutex_t lock;
} Packet_List;

void initialize_packet_list(Packet_List *list) {
    list->packets = (TCP_Packet *)malloc(MAX_LIST_SIZE * sizeof(TCP_Packet));
    if (!list->packets) {
        fprintf(stderr, "Failed to allocate memory for packet list\n");
        exit(1);
    }
    list->count = 0;
    list->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_packet_list(Packet_List *list) {
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
}

int add_packet_to_list(Packet_List *list, TCP_Packet *packet) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Dynamically resize the packet list
        int new_capacity = list->capacity * 2;
        TCP_Packet *new_packets = realloc(list->packets, new_capacity * sizeof(TCP_Packet));
        if (!new_packets) {
            fprintf(stderr, "Failed to reallocate memory for packet list\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->packets = new_packets;
        list->capacity = new_capacity;
    }
    memcpy(&list->packets[list->count], packet, sizeof(TCP_Packet));
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main() {
    Packet_List packet_list;
    initialize_packet_list(&packet_list);

    // Example usage
    TCP_Packet packet;
    strcpy(packet.ip_header, "IP_HEADER");
    strcpy(packet.tcp_header, "TCP_HEADER");
    strcpy(packet.payload, "PAYLOAD");
    packet.payload_size = strlen(packet.payload);

    if (add_packet_to_list(&packet_list, &packet) == 0) {
        printf("Packet added successfully\n");
    } else {
        printf("Failed to add packet\n");
    }

    destroy_packet_list(&packet_list);
    return 0;
}
