    // Define the maximum number of PDUs that can be allocated based on system resources
    const int MAX_ALLOCATED_PDUS = 1024; // Example value, adjust as needed

    // Validate input max_pdus to ensure it falls within a reasonable range
    if (max_pdus <= 0 || max_pdus > MAX_ALLOCATED_PDUS) {
        fprintf(stderr, "Invalid max_pdus: %d. Must be greater than 0 and less than or equal to %d.\n", max_pdus, MAX_ALLOCATED_PDUS);
        return NULL;
    }

    // Calculate the number of PDUs that can actually be allocated
    *actual_pdus = (max_pdus > MAX_ALLOCATED_PDUS) ? MAX_ALLOCATED_PDUS : max_pdus;

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*actual_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed. Unable to allocate memory for %d PDUs.\n", *actual_pdus);
        return NULL;
