#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_BUFFER_SIZE 1024
#define BUFFER_EXPANSION_FACTOR 2
#define MAX_BUFFER_SIZE (1024 * 1024) // 1MB

typedef struct {
    char* buffer;
    size_t size;
    size_t capacity;
} PacketBuffer;

void initPacketBuffer(PacketBuffer* buf) {
    buf->buffer = (char*)malloc(INITIAL_BUFFER_SIZE);
    if (!buf->buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    buf->size = 0;
    buf->capacity = INITIAL_BUFFER_SIZE;
}

void freePacketBuffer(PacketBuffer* buf) {
    free(buf->buffer);
    buf->buffer = NULL;
    buf->size = 0;
    buf->capacity = 0;
}

void expandPacketBuffer(PacketBuffer* buf, size_t additionalCapacity) {
    if (buf->capacity + additionalCapacity > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Maximum buffer size exceeded\n");
        return;
    }

    char* newBuffer = realloc(buf->buffer, buf->capacity * BUFFER_EXPANSION_FACTOR);
    if (!newBuffer) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    buf->buffer = newBuffer;
    buf->capacity *= BUFFER_EXPANSION_FACTOR;
}

void addPacketToBuffer(PacketBuffer* buf, const char* packet, size_t packetSize) {
    if (buf->size + packetSize > buf->capacity) {
        expandPacketBuffer(buf, packetSize);
    }

    memcpy(buf->buffer + buf->size, packet, packetSize);
    buf->size += packetSize;
}

// Example usage
int main() {
    PacketBuffer buffer;
    initPacketBuffer(&buffer);

    // Simulate adding packets
    const char* packet1 = "Hello";
    addPacketToBuffer(&buffer, packet1, strlen(packet1) + 1); // Including null terminator

    const char* packet2 = "World!";
    addPacketToBuffer(&buffer, packet2, strlen(packet2) + 1);

    printf("Buffer contains: %.*s\n", (int)buffer.size, buffer.buffer);

    freePacketBuffer(&buffer);
    return 0;
}
