#include <stdint.h>

typedef struct PacketHeader {
    uint16_t headerSize;
    uint32_t checksum;
} PacketHeader;

typedef struct NetworkPacket {
    uint16_t totalHeaders;
    PacketHeader** headers;
    uint32_t* combinedChecksum;
} NetworkPacket;

NetworkPacket* createNetworkPacket(uint16_t totalHeaders) {
    NetworkPacket* packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed for NetworkPacket\n");
        return NULL;
    }

    packet->totalHeaders = totalHeaders;
    packet->headers = (PacketHeader**)malloc(totalHeaders * sizeof(PacketHeader*));
    if (!packet->headers) {
        fprintf(stderr, "Memory allocation failed for headers array\n");
        free(packet);
        return NULL;
    }

    packet->combinedChecksum = (uint32_t*)calloc(1, sizeof(uint32_t));
    if (!packet->combinedChecksum) {
        fprintf(stderr, "Memory allocation failed for combinedChecksum\n");
        free(packet->headers);
        free(packet);
        return NULL;
    }

    for (uint16_t i = 0; i < totalHeaders; ++i) {
        packet->headers[i] = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (!packet->headers[i]) {
            fprintf(stderr, "Memory allocation failed for header %d\n", i);
            // Free previously allocated memory
            for (uint16_t j = 0; j < i; ++j) {
                free(packet->headers[j]);
            }
            free(packet->combinedChecksum);
            free(packet->headers);
            free(packet);
            return NULL;
        }
    }

    return packet;
}

void destroyNetworkPacket(NetworkPacket* packet) {
    if (packet) {
        for (uint16_t i = 0; i < packet->totalHeaders; ++i) {
            free(packet->headers[i]);
        }
        free(packet->combinedChecksum);
        free(packet->headers);
        free(packet);
    }
}

int main() {
    uint16_t totalHeaders = 5;
    NetworkPacket* packet = createNetworkPacket(totalHeaders);
    if (packet) {
        // Process the packet
        destroyNetworkPacket(packet);
    }

    return 0;
}
