#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int width;
    int height;
    unsigned char* pixelData;
} ImageData;

int validateDimensions(int width, int height) {
    // Define reasonable maximum dimensions
    const int MAX_WIDTH = 10240;
    const int MAX_HEIGHT = 7680;

    if (width <= 0 || height <= 0 || width > MAX_WIDTH || height > MAX_HEIGHT) {
        return 0; // Dimensions are invalid
    }
    return 1; // Dimensions are valid
}

unsigned long calculateMemoryUsage(int width, int height) {
    // Calculate memory required for pixel data (assuming each pixel is a single byte)
    unsigned long pixelDataSize = (unsigned long)width * height;

    if (pixelDataSize > UINT_MAX / sizeof(unsigned char)) {
        return 0; // Integer overflow
    }

    return pixelDataSize * sizeof(unsigned char);
}

ImageData* allocateImageData(int width, int height, size_t maxMemoryUsage) {
    if (!validateDimensions(width, height)) {
        printf("Error: Invalid image dimensions.\n");
        return NULL;
    }

    unsigned long memoryUsage = calculateMemoryUsage(width, height);

    if (memoryUsage > maxMemoryUsage) {
        printf("Error: Memory allocation exceeds maximum allowed size.\n");
        return NULL;
    }

    ImageData* imageDataArray = (ImageData*)malloc(sizeof(ImageData));
    if (!imageDataArray) {
        printf("Error: Failed to allocate memory for ImageData structure.\n");
        return NULL;
    }

    imageDataArray->width = width;
    imageDataArray->height = height;

    // Allocate memory for pixel data
    imageDataArray->pixelData = (unsigned char*)malloc(memoryUsage);
    if (!imageDataArray->pixelData) {
        printf("Error: Failed to allocate memory for pixel data.\n");
        free(imageDataArray); // Free previously allocated ImageData structure
        return NULL;
    }

    // Initialize pixel data (optional, depending on requirements)
    for (size_t i = 0; i < memoryUsage; ++i) {
        imageDataArray->pixelData[i] = 0;
    }

    return imageDataArray;
}

void freeImageData(ImageData* imageData) {
    if (imageData) {
        free(imageData->pixelData);
        free(imageData);
    }
}
