#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PacketHeader {
    time_t timestamp;
    size_t length;
    char *payload;
    struct PacketHeader *next;
} PacketHeader;

void processPacketStream(time_t *timestamps, size_t lengths[], char **payloads, size_t numPackets, size_t maxMemory) {
    size_t totalAllocated = 0;
    PacketHeader *head = NULL;
    PacketHeader *tail = NULL;

    for (size_t i = 0; i < numPackets; ++i) {
        if (totalAllocated + lengths[i] > maxMemory) {
            fprintf(stderr, "Memory limit exceeded\n");
            return;
        }

        PacketHeader *newPacket = (PacketHeader *)malloc(sizeof(PacketHeader));
        if (!newPacket) {
            fprintf(stderr, "Failed to allocate memory for packet header\n");
            return;
        }

        newPacket->timestamp = timestamps[i];
        newPacket->length = lengths[i];
        newPacket->payload = (char *)malloc(newPacket->length);
        if (!newPacket->payload) {
            free(newPacket);
            fprintf(stderr, "Failed to allocate memory for packet payload\n");
            return;
        }

        memcpy(newPacket->payload, payloads[i], newPacket->length);
        newPacket->next = NULL;

        totalAllocated += sizeof(PacketHeader) + newPacket->length;

        if (!head) {
            head = newPacket;
            tail = newPacket;
        } else {
            tail->next = newPacket;
            tail = newPacket;
        }

        // Simulate asynchronous processing delay
        usleep(rand() % 100000);
    }

    // Process the linked list of packets
    PacketHeader *current = head;
    while (current) {
        printf("Timestamp: %ld, Length: %zu\n", current->timestamp, current->length);
        free(current->payload);
        PacketHeader *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    time_t timestamps[] = {1633072800, 1633072805, 1633072810};
    size_t lengths[] = {100, 200, 150};
    char *payloads[] = {"Hello", "World", "This is a test payload"};

    processPacketStream(timestamps, lengths, payloads, sizeof(payloads) / sizeof(payloads[0]), 500);

    return 0;
}
```

