#include <stdlib.h>
#include <pthread.h>

#define MAX_NFAPI_PDU 1000
#define DEFAULT_BLOCK_SIZE 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t allocated_count;
    size_t block_size;
    pthread_mutex_t mutex;
} NFAPDUAllocator;

NFAPDUAllocator* nfapdu_allocator_create(size_t initial_block_size) {
    if (initial_block_size == 0 || initial_block_size > MAX_NFAPI_PDU) return NULL;

    NFAPDUAllocator *allocator = (NFAPDUAllocator *)malloc(sizeof(NFAPDUAllocator));
    if (!allocator) return NULL;

    allocator->array = NULL;
    allocator->count = 0;
    allocator->allocated_count = 0;
    allocator->block_size = initial_block_size;
    pthread_mutex_init(&allocator->mutex, NULL);

    return allocator;
}

int nfapdu_allocator_allocate(NFAPDUAllocator *allocator) {
    if (!allocator) return -1;

    pthread_mutex_lock(&allocator->mutex);

    if (allocator->count >= MAX_NFAPI_PDU || allocator->allocated_count >= MAX_NFAPI_PDU) {
        pthread_mutex_unlock(&allocator->mutex);
        return -1; // Reached maximum allowable value
    }

    if (allocator->count == allocator->allocated_count) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(allocator->array, 
            (allocator->allocated_count + allocator->block_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&allocator->mutex);
            return -1; // Memory allocation failure
        }
        allocator->array = new_array;
        allocator->allocated_count += allocator->block_size;
    }

    allocator->array[allocator->count].RX_UE_INFORMATION_TAG = rand();
    allocator->array[allocator->count].RNTI = rand();
    allocator->array[allocator->count].CRC_INDICATION_REL8_TAG = rand();
    allocator->array[allocator->count].CRCFLAG = (rand() % 2 == 0) ? 'Y' : 'N';
    allocator->count++;

    pthread_mutex_unlock(&allocator->mutex);

    return 0;
}

void nfapdu_allocator_free(NFAPDUAllocator *allocator) {
    if (!allocator) return;

    pthread_mutex_lock(&allocator->mutex);

    free(allocator->array);
    allocator->array = NULL;
    allocator->count = 0;
    allocator->allocated_count = 0;

    pthread_mutex_unlock(&allocator->mutex);

    pthread_mutex_destroy(&allocator->mutex);
    free(allocator);
}

void nfapdu_allocator_set_block_size(NFAPDUAllocator *allocator, size_t new_block_size) {
    if (!allocator || new_block_size == 0 || new_block_size > MAX_NFAPI_PDU) return;

    allocator->block_size = new_block_size;
}
