#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/sysinfo.h>
#include <unistd.h>

#define MAX_STRUCTS 1000
#define MEMORY_LIMIT (MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_and_serialize_array(int N, const char* filename) {
    if (N <= 0 || N > MAX_STRUCTS) {
        fprintf(stderr, "Invalid number of structures\n");
        return -1;
    }

    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        perror("Failed to get system information");
        return -1;
    }

    long free_memory = info.freeram * info.mem_unit;
    long total_memory = info.totalram * info.mem_unit;

    if ((N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MEMORY_LIMIT || (total_memory - free_memory) < (N * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for array");
        return -1;
    }

    // Populate the array with random data
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536; // RNTI range is typically 0-65535
        array[i].CRC_INDICATION_REL8_TAG = rand();
    }

    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        free(array);
        return -1;
    }

    size_t result = fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (result != N) {
        fprintf(stderr, "Failed to write all data to file\n");
        fclose(file);
        free(array);
        return -1;
    }

    fclose(file);
    free(array);

    printf("Data serialized successfully to %s\n", filename);
    return 0;
}

int main() {
    int N = 500;
    const char* filename = "output.bin";
    return create_and_serialize_array(N, filename);
}
