        if (*num_files >= MAX_FILE_SIZES - 1) {
            log_error("Too many files. Exiting gracefully.");
            free(metadata_array);
            exit(EXIT_FAILURE);
        }

        if (*num_files % INITIAL_CAPACITY == 0) {
            IMAGE_FILE_METADATA *new_metadata_array = realloc(metadata_array, (*num_files + INITIAL_CAPACITY) * sizeof(IMAGE_FILE_METADATA));
            if (new_metadata_array == NULL) {
                log_error("Memory allocation failed. Exiting gracefully.");
                free(metadata_array);
                exit(EXIT_FAILURE);
            }
            metadata_array = new_metadata_array;
        }

        strcpy(metadata_array[*num_files].name, name);
        metadata_array[*num_files].size = file_size;
        metadata_array[*num_files].creation_timestamp = timestamp;

        (*num_files)++;
    }

    return metadata_array;
}

