file_metadata_t* process_file_paths(const char** paths, int num_paths, int* error_code) {
    if (num_paths > 10000 || num_paths <= 0) {
        *error_code = -1; // Error: Invalid number of paths
        return NULL;
    }

    file_metadata_t* metadata_array = malloc(num_paths * sizeof(file_metadata_t));
    if (!metadata_array) {
        *error_code = -2; // Error: Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < num_paths; ++i) {
        DIR* dir = opendir(paths[i]);
        if (!dir) {
            free(metadata_array);
            *error_code = -3; // Error: Failed to open directory
            return NULL;
        }

        struct dirent* entry;
        while ((entry = readdir(dir)) != NULL) {
            char full_path[256];
            snprintf(full_path, sizeof(full_path), "%s/%s", paths[i], entry->d_name);
            if (strchr(entry->d_name, '/') == NULL && strchr(entry->d_name, ':') == NULL) {
                struct stat file_stat;
                if (stat(full_path, &file_stat) == 0) {
                    strncpy(metadata_array[i].filename, entry->d_name, sizeof(metadata_array[i].filename) - 1);
                    metadata_array[i].size = file_stat.st_size;
                } else {
                    free(metadata_array);
                    closedir(dir);
                    *error_code = -4; // Error: Failed to get file stats
                    return NULL;
                }
            }
        }

        closedir(dir);
    }

    *error_code = 0; // Success
    return metadata_array;
}

int main() {
    const char* paths[] = {"./test_dir", "./another_test_dir"};
    int num_paths = sizeof(paths) / sizeof(paths[0]);
    int error_code;

    file_metadata_t* metadata = process_file_paths(paths, num_paths, &error_code);
    if (metadata) {
        for (int i = 0; i < num_paths; ++i) {
            printf("File: %s, Size: %zu bytes\n", metadata[i].filename, metadata[i].size);
        }
        free(metadata);
    } else {
        switch (error_code) {
            case -1:
                printf("Error: Invalid number of paths.\n");
                break;
            case -2:
                printf("Error: Memory allocation failed.\n");
                break;
            case -3:
                printf("Error: Failed to open directory.\n");
                break;
            case -4:
                printf("Error: Failed to get file stats.\n");
                break;
        }
    }

    return 0;
}
