    uint16_t payload_length;
    uint16_t checksum;
} PacketHeader;

PacketHeader** process_packet_headers(int header_count, ...) {
    if (header_count <= 0) {
        return NULL; // Handle edge case: non-positive header count
    }

    PacketHeader** headers = malloc(header_count * sizeof(PacketHeader*));
    if (!headers) {
        return NULL; // Memory allocation failed
    }

    va_list args;
    va_start(args, header_count);

    for (int i = 0; i < header_count; ++i) {
        uint8_t version = va_arg(args, int);
        uint16_t length = va_arg(args, int);
        uint16_t checksum = va_arg(args, int);

        headers[i] = malloc(sizeof(PacketHeader));
        if (!headers[i]) {
            // Handle memory allocation failure for individual header
            for (int j = 0; j < i; ++j) {
                free(headers[j]);
            }
            free(headers);
            return NULL;
        }

        headers[i]->protocol_version = version;
        headers[i]->payload_length = length;
        headers[i]->checksum = checksum;
    }

    va_end(args);

    // Implement caching mechanism here if needed
    // ...

    return headers;
}

// Example usage:
int main() {
    PacketHeader** headers = process_packet_headers(3, 1, 500, 12345, 2, 1000, 67890, 3, 750, 54321);
    if (headers) {
        // Process headers
        for (int i = 0; i < 3; ++i) {
            free(headers[i]);
        }
        free(headers);
    }

    return 0;
}
