    if (pdu != NULL) {
        // Populate PDU fields with valid data
    }
    return pdu;
}

// Function to allocate memory safely
int allocateMemory(int size) {
    pthread_mutex_lock(&mutex);
    int totalSize = totalMemoryAllocated + size;
    if (totalSize > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation limit exceeded\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    void* ptr = malloc(size);
    if (ptr != NULL) {
        totalMemoryAllocated += size;
    }
    pthread_mutex_unlock(&mutex);
    return ptr;
}

// Function to free memory safely
