use rand::Rng;
use std::num::NonZeroUsize;

#[derive(Debug)]
enum Error {
    MemoryAllocationFailed,
    InvalidInput,
}

struct NFAPICRCIndicationPDU {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: u8,
    crcflag: bool,
}

fn allocate_nfadata() -> Result<(), Error> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let count = input.trim().parse::<NonZeroUsize>().map_err(|_| Error::InvalidInput)?;

    if count.get() > 1000 {
        eprintln!("Error: Number of structures exceeds the limit.");
        return Err(Error::MemoryAllocationFailed);
    }

    let mut data: Vec<NFAPICRCIndicationPDU> = Vec::with_capacity(count.get());

    for _ in 0..count.get() {
        let crcflag = rand::thread_rng().gen();
        data.push(NFAPICRCIndicationPDU {
            rx_ue_information_tag: rand::thread_rng().gen(),
