            crc_indication_rel8_tag: rand::thread_rng().gen(),
            crcflag,
        });
    }

    println!("Generated {} structures.", count.get());
    Ok(())
}

fn setup_directory_env_var(dir_name: &str) -> Result<(), Error> {
    if let Some(path) = env::var_os(dir_name) {
        set_var(dir_name, path);
        return Ok(());
    }

    let mut dir_path = std::env::temp_dir();
    dir_path.push(dir_name);

    create_dir_all(&dir_path).map_err(|_| Error::MemoryAllocationFailed)?;
    set_var(dir_name, &dir_path)?;

    println!("Created directory and set environment variable to {}.", dir_path.display());
    Ok(())
}
