        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_size);
    if (!array) {
        printf("Error: Failed to allocate memory.\n");
        return NULL;
