        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*array, required_size);
    if (!new_array) {
        printf("Error: Failed to reallocate memory.\n");
        return;
