    int BITDEPTH;
} JPEG_IMAGE_T;

int create_images(int N, int MAX_WIDTH, int MAX_HEIGHT, int RESOURCES_AVAIL) {
    srand(time(NULL));
    JPEG_IMAGE_T *images = (JPEG_IMAGE_T *)malloc(N * sizeof(JPEG_IMAGE_T));

    if (!images) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    long total_pixels = 0;

    for (int i = 0; i < N; i++) {
        int width = rand() % (MAX_WIDTH + 1);
        int height = rand() % (MAX_HEIGHT + 1);

        if ((long)width * (long)height > MAX_WIDTH * MAX_HEIGHT) {
            fprintf(stderr, "Image dimensions exceed maximum allowed\n");
            free(images);
            return -2;
        }

        total_pixels += width * height;

        if (total_pixels > RESOURCES_AVAIL * 1048576) {
            fprintf(stderr, "Total pixel count exceeds available resources\n");
            free(images);
            return -3;
        }

        images[i].IMAGE_WIDTH = width;
        images[i].IMAGE_HEIGHT = height;
        images[i].BITDEPTH = rand() % (256 + 1); // Assuming BITDEPTH is in the range [0, 256]
    }

    printf("Images created successfully\n");
    free(images);
    return 0;
}

int main() {
    int N = 5;
    int MAX_WIDTH = 1024;
    int MAX_HEIGHT = 768;
    int RESOURCES_AVAIL = 1;

    int result = create_images(N, MAX_WIDTH, MAX_HEIGHT, RESOURCES_AVAIL);

    if (result == -1) {
        printf("Failed to allocate memory for images\n");
    } else if (result == -2) {
        printf("Image dimensions exceed maximum allowed\n");
    } else if (result == -3) {
        printf("Total pixel count exceeds available resources\n");
    }

    return 0;
}
