#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_FILENAME_LENGTH 256
#define INITIAL_LINKED_LIST_SIZE 100

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    char filename[MAX_FILENAME_LENGTH];
    int width, height;
    uint8_t* pixel_data;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
} LinkedList;

void process_directory(const char* directory_path, LinkedList* linked_list) {
    DIR* dir;
    struct dirent* entry;
    struct stat file_stat;

    if ((dir = opendir(directory_path)) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(linked_list->head->filename, MAX_FILENAME_LENGTH, "%s/%s", directory_path, entry->d_name);
        if (stat(linked_list->head->filename, &file_stat) == -1) {
            perror("stat");
            continue;
        }

        // Validate filename and allocate memory
        if (!S_ISREG(file_stat.st_mode)) {
            continue; // Skip non-regular files
        }

        linked_list->head->pixel_data = (uint8_t*)malloc(file_stat.st_size);
        if (linked_list->head->pixel_data == NULL) {
            perror("malloc");
            continue;
        }

        FILE* file = fopen(linked_list->head->filename, "rb");
        if (file == NULL) {
            perror("fopen");
            free(linked_list->head->pixel_data);
            linked_list->head->pixel_data = NULL;
            continue;
        }

        size_t bytes_read = fread(linked_list->head->pixel_data, 1, file_stat.st_size, file);
        if (bytes_read != file_stat.st_size) {
            perror("fread");
            free(linked_list->head->pixel_data);
            linked_list->head->pixel_data = NULL;
        }

        fclose(file);

        // Initialize structure fields
        linked_list->head->rx_ue_information_tag = /* initialize */;
        linked_list->head->RNTI = /* initialize */;
        linked_list->head->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        // Update linked list size and count
        linked_list->count++;
    }

    closedir(dir);
}

int main() {
    LinkedList* linked_list = (LinkedList*)malloc(sizeof(LinkedList));
    if (linked_list == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    linked_list->head = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_LINKED_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (linked_list->head == NULL) {
        perror("calloc");
        free(linked_list);
        return EXIT_FAILURE;
    }

    linked_list->count = 0;

    process_directory("/path/to/image/directory", linked_list);

    // Free allocated memory
    NFAPI_CRC_INDICATION_PDU_T* current = linked_list->head;
    while (current != NULL) {
        free(current->pixel_data);
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    free(linked_list);

    return EXIT_SUCCESS;
}
