#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_LIST_SIZE 10

typedef struct FileMetadata {
    char* path;
    time_t last_modified;
    size_t size;
    struct FileMetadata* next;
} FileMetadata;

FileMetadata** create_file_list(void) {
    FileMetadata** list = (FileMetadata**)malloc(sizeof(FileMetadata*) * INITIAL_LIST_SIZE);
    if (list == NULL) {
        perror("Failed to allocate memory for file list");
        exit(EXIT_FAILURE);
    }
    memset(list, 0, sizeof(FileMetadata*) * INITIAL_LIST_SIZE);
    return list;
}

void free_file_list(FileMetadata** list) {
    for (int i = 0; list[i] != NULL; i++) {
        free(list[i]->path);
        free(list[i]);
    }
    free(list);
}

int add_file_to_list(FileMetadata** list, const char* path, time_t last_modified, size_t size) {
    // Assuming the list is always large enough to accommodate new entries
    // in a real scenario, you would need to dynamically resize the list
    FileMetadata* new_entry = (FileMetadata*)malloc(sizeof(FileMetadata));
    if (new_entry == NULL) {
        perror("Failed to allocate memory for file entry");
        return -1;
    }
    new_entry->path = strdup(path);
    new_entry->last_modified = last_modified;
    new_entry->size = size;
    new_entry->next = list[0];
    list[0] = new_entry;
    return 0;
}

int process_file_paths(FileMetadata** list, const char* paths[], int num_paths) {
    for (int i = 0; i < num_paths; i++) {
        FILE* file = fopen(paths[i], "r");
        if (file == NULL) {
            perror("Failed to open file");
            continue;
        }
        struct stat file_stat;
        if (stat(paths[i], &file_stat) != 0) {
            perror("Failed to get file stats");
            fclose(file);
            continue;
        }
        time_t last_modified = file_stat.st_mtime;
        size_t size = file_stat.st_size;
        add_file_to_list(list, paths[i], last_modified, size);
        fclose(file);
    }
    return 0;
}

int main() {
    const char* paths[] = {"file1.txt", "file2.txt", "nonexistentfile.txt"};
    FileMetadata** list = create_file_list();
    if (list != NULL) {
        process_file_paths(list, paths, sizeof(paths) / sizeof(paths[0]));
        free_file_list(list);
    }
    return 0;
}
