        fprintf(stderr, "Average size per image is not set\n");
        fclose(file);
        return NULL;
    }

    // Allocate memory for the array of images
    Image* images = malloc(*numImages * sizeof(Image));
    if (!images) {
        perror("Failed to allocate memory for images");
        fclose(file);
        return NULL;
    }

    // Initialize each image structure based on metadata
    for (unsigned int i = 0; i < *numImages; ++i) {
        images[i].width = avgSizePerImage / 4; // Example: assuming each pixel is 4 bytes
        images[i].height = avgSizePerImage / (avgSizePerImage / 4); // Calculate height to maintain aspect ratio

        // Allocate memory for the pixel data array
        size_t totalPixelDataSize = images[i].width * images[i].height;
        if (totalPixelDataSize > SIZE_MAX / sizeof(unsigned char)) {
            fprintf(stderr, "Total pixel data size exceeds maximum allowed\n");
            free(images);
            fclose(file);
            return NULL;
        }

        images[i].pixelData = malloc(totalPixelDataSize * sizeof(unsigned char));
        if (!images[i].pixelData) {
            perror("Failed to allocate memory for pixel data");
            for (unsigned int j = 0; j < i; ++j) {
                free(images[j].pixelData);
            }
            free(images);
            fclose(file);
            return NULL;
        }

        // Read pixel data from file
        if (fread(images[i].pixelData, sizeof(unsigned char), totalPixelDataSize, file) != totalPixelDataSize) {
            perror("Failed to read pixel data");
            for (unsigned int j = 0; j <= i; ++j) {
                free(images[j].pixelData);
            }
            free(images);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return images;
}

void cleanupImages(Image* images, unsigned int numImages) {
    for (unsigned int i = 0; i < numImages; ++i) {
        free(images[i].pixelData);
    }
    free(images);
}
