} NFAPI_CRC_INDICATION_PDU_T;

void* populateNFAPIList(void* args) {
    struct {
        NFAPI_CRC_INDICATION_PDU_T** list;
        size_t limit;
        int minRNTI;
    } *params = (struct { NFAPI_CRC_INDICATION_PDU_T** list; size_t limit; int minRNTI; }) *args;

    if (!params->list || params->limit <= 0 || params->minRNTI < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    *params->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(params->limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*params->list) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Simulate populating the list with data
    for (size_t i = 0; i < params->limit; ++i) {
        (*params->list)[i].rnti = i * 10 + 100; // Example RNTI calculation
        if ((*params->list)[i].rnti < params->minRNTI) {
            params->limit = i;
            break;
        }
    }

    return (void*)params->limit;
}

int main() {
    size_t limit = 1000;
    int minRNTI = 500;
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;

    struct { NFAPI_CRC_INDICATION_PDU_T** list; size_t limit; int minRNTI; } params = { &list, limit, minRNTI };

    pthread_t thread;
    if (pthread_create(&thread, NULL, populateNFAPIList, &params) != 0) {
        perror("Thread creation failed");
        return 1;
