typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pool;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} NFAPI_POOL;

NFAPI_POOL* create_pool() {
    NFAPI_POOL* pool = (NFAPI_POOL*)malloc(sizeof(NFAPI_POOL));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pool->size = 0;
    pool->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_pool(NFAPI_POOL* pool) {
    for (int i = 0; i < pool->size; i++) {
        free(pool->pool[i]);
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(NFAPI_POOL* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == pool->capacity) {
        int new_capacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_pool = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    pool->pool[pool->size++] = pdu;
    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void free_pdu(NFAPI_POOL* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simple implementation for demonstration purposes
