        printf("Invalid number of elements: %d\n", N);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        printf("Memory allocation failed for list of size %d\n", N);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* head = allocate_pdu(pool);
    if (!head) {
        free(list);
        printf("Memory allocation failed for initial node\n");
        return NULL;
    }
    list[0] = head;
    for (int i = 1; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = allocate_pdu(pool);
        if (!new_pdu) {
            for (int j = 0; j < i; j++) {
                free_pdu(pool, list[j]);
            }
            free(list);
            printf("Memory allocation failed for node %d\n", i);
            return NULL;
        }
        new_pdu->prev = head;
        head->next = new_pdu;
        list[i] = new_pdu;
        head = new_pdu;
    }
    return list;
}

void destroy_doubly_linked_list(NFAPI_POOL* pool, NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    for (int i = 0; i < N; i++) {
        free_pdu(pool, list[i]);
    }
    free(list);
}
