#define MAX_PACKET_SIZE 65535 // Assuming maximum packet size

typedef struct {
    int header_size;
    int payload_size;
} Packet;

void process_packets(Packet packets[], int num_packets, char **buffer, size_t *buffer_size) {
    if (num_packets <= 0 || buffer == NULL || buffer_size == NULL) {
        return; // Invalid input
    }

    size_t total_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        if (packets[i].header_size > INT_MAX - packets[i].payload_size) {
            return; // Potential integer overflow
        }
        if (total_size > SIZE_MAX - packets[i].header_size - packets[i].payload_size) {
            return; // Potential integer overflow
        }
        total_size += packets[i].header_size + packets[i].payload_size;
    }

    *buffer = realloc(*buffer, *buffer_size);
    if (*buffer == NULL) {
        return; // Memory allocation failed
    }
    *buffer_size = total_size;

    char *write_ptr = *buffer;
    for (int i = 0; i < num_packets; ++i) {
        memcpy(write_ptr, &packets[i].header_size, sizeof(int));
        write_ptr += sizeof(int);
        memcpy(write_ptr, packets[i].payload, packets[i].payload_size);
        write_ptr += packets[i].payload_size;
    }
}
