typedef struct FrameListNode {
    FRAME_DATA *frame;
    struct FrameListNode *next;
} FrameListNode;

FrameListNode* create_frame_list(int n) {
    FrameListNode *head = NULL;
    for (int i = 0; i < n; i++) {
        FrameListNode *node = (FrameListNode*)malloc(sizeof(FrameListNode));
        if (!node) {
            perror("Memory allocation failed");
            free_list(head);
            return NULL;
        }
        node->frame = (FRAME_DATA*)malloc(sizeof(FRAME_DATA));
        if (!node->frame) {
            perror("Memory allocation failed");
            free_node(node);
            free_list(head);
            return NULL;
