        node->frame->frame_id = i + 1;
        node->frame->timestamp = time(NULL);
        node->frame->payload_size = rand() % 1024; // Random payload size
        node->frame->dependencies = (int*)malloc(5 * sizeof(int)); // Example dependency vector
        if (!node->frame->dependencies) {
            perror("Memory allocation failed");
            free_node(node);
            free_list(head);
            return NULL;
        }
        for (int j = 0; j < 5; j++) {
            node->frame->dependencies[j] = rand() % n; // Random dependency
        }
        node->frame->dependency_count = 5;
        node->next = head;
        head = node;
    }
    return head;
}

void free_list(FrameListNode *head) {
    FrameListNode *current = head;
    while (current) {
        FrameListNode *next = current->next;
        free(current->frame->dependencies);
        free(current->frame);
        free(current);
        current = next;
    }
}

