#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct Packet {
    size_t data_size;
    uint8_t *data;
} Packet;

Packet* process_packet(const uint8_t *packet_buffer, size_t buffer_size) {
    Packet *new_packet = (Packet *)malloc(sizeof(Packet));
    if (!new_packet) {
        fprintf(stderr, "Failed to allocate memory for packet header\n");
        return NULL;
    }

    new_packet->data_size = 0;

    // Calculate the data size from metadata in the packet buffer
    size_t metadata_size = sizeof(size_t);
    if (buffer_size < metadata_size) {
        fprintf(stderr, "Packet buffer too small for metadata\n");
        free(new_packet);
        return NULL;
    }

    new_packet->data_size = *(size_t *)packet_buffer;
    packet_buffer += metadata_size;

    // Allocate memory for the data segment
    new_packet->data = (uint8_t *)malloc(new_packet->data_size);
    if (!new_packet->data) {
        fprintf(stderr, "Failed to allocate memory for packet data\n");
        free(new_packet);
        return NULL;
    }

    // Copy the data from the buffer into the newly allocated segment
    size_t copy_size = (buffer_size - metadata_size < new_packet->data_size) ?
                       buffer_size - metadata_size : new_packet->data_size;

    memcpy(new_packet->data, packet_buffer, copy_size);

    return new_packet;
}

void free_packet(Packet *packet) {
    if (packet) {
        free(packet->data);
        free(packet);
    }
}
```

This code snippet defines a `Packet` structure to hold the data and size of each network packet. The `process_packet` function takes a buffer containing the raw packet data, calculates the required memory for the data segment based on metadata in the buffer, dynamically allocates memory for both the packet header and the data segment, copies the data from the buffer into the allocated memory, and returns a pointer to the new `Packet`. The `free_packet` function is provided to free the allocated memory when it is no longer needed.']

