#define MAX_PACKETS 10000
#define MAX_PAYLOAD_SIZE 4096

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
} Packet;

Packet* process_packets(int total_packets, int* packet_sizes, pthread_mutex_t* lock) {
    if (total_packets <= 0 || total_packets > MAX_PACKETS) {
        return NULL; // Invalid number of packets
    }

    Packet* packet_array = (Packet*)malloc(total_packets * sizeof(Packet));
    if (packet_array == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < total_packets; i++) {
        if (packet_sizes[i] <= 0 || packet_sizes[i] > MAX_PAYLOAD_SIZE) {
            free(packet_array);
            return NULL; // Invalid payload size
        }

        pthread_mutex_lock(lock); // Ensure thread safety during allocation

        Packet* current_packet = &packet_array[i];
        current_packet->id = i + 1;
        current_packet->timestamp = time(NULL);
        current_packet->payload_size = packet_sizes[i];

        pthread_mutex_unlock(lock); // Release the lock after setting up the packet
    }

    return packet_array;
}

int main() {
    int total_packets = 5000;
    int packet_sizes[5000] = {1024, 2048, ..., 4096}; // Initialize with valid sizes

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    Packet* packets = process_packets(total_packets, packet_sizes, &lock);

    if (packets != NULL) {
        printf("Successfully processed %d packets.\n", total_packets);
        free(packets); // Free the allocated memory
    } else {
        printf("Failed to process packets.\n");
    }

    return 0;
}
