#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 1024

typedef struct {
    int data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    if (initial_capacity > MAX_STRUCTS) {
        fprintf(stderr, "Error: Initial capacity exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory for dynamic array.");
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->mutex, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

void add_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? 2 * da->capacity : 1;
        if (new_capacity > MAX_STRUCTS) {
            fprintf(stderr, "Error: New capacity exceeds maximum allowed.\n");
            pthread_mutex_unlock(&da->mutex);
            return;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for dynamic array.");
            pthread_mutex_unlock(&da->mutex);
            return;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = value;
    pthread_mutex_unlock(&da->mutex);
}

void remove_from_dynamic_array(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return;
    }
    pthread_mutex_lock(&da->mutex);
    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }
    --da->size;
    pthread_mutex_unlock(&da->mutex);
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da, 5);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {42};
    add_to_dynamic_array(&da, pdu1);

    remove_from_dynamic_array(&da, 0);

    free_dynamic_array(&da);
    return 0;
}
