    size_t payload_size;
} Packet;

typedef struct {
    JPEG_IMAGE_HEADER *headers;
    size_t num_headers;
} ImageHeaders;

Packet* allocate_packet(size_t payload_size) {
    Packet *packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->payload = (unsigned char*)malloc(payload_size);
    if (!packet->payload) {
        free(packet);
        return NULL;
    }

    packet->payload_size = payload_size;
    return packet;
}

void free_packet(Packet *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

ImageHeaders* allocate_image_headers(size_t num_headers, size_t max_mem_bytes) {
    ImageHeaders *headers = (ImageHeaders*)malloc(sizeof(ImageHeaders));
    if (!headers) return NULL;

    headers->num_headers = num_headers;
    headers->headers = (JPEG_IMAGE_HEADER*)malloc(num_headers * sizeof(JPEG_IMAGE_HEADER));
    if (!headers->headers) {
        free(headers);
        return NULL;
    }

    // Initialize JPEG headers
    for (size_t i = 0; i < num_headers; ++i) {
        memset(&headers->headers[i], 0, JPEG_HEADER_SIZE);
    }

    return headers;
}

void free_image_headers(ImageHeaders *headers) {
    if (headers) {
        free(headers->headers);
        free(headers);
    }
}

int process_packets(size_t max_packets, size_t max_payload_size, size_t max_mem_bytes) {
    pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
    Packet **buffer = (Packet**)malloc(max_packets * sizeof(Packet*));
    if (!buffer) return -1; // Memory allocation failed

    for (size_t i = 0; i < max_packets; ++i) {
        buffer[i] = allocate_packet(max_payload_size);
        if (!buffer[i]) {
            for (size_t j = 0; j < i; ++j) free_packet(buffer[j]);
            free(buffer);
            return -1; // Memory allocation failed
        }
    }

    ImageHeaders *image_headers = allocate_image_headers(5, max_mem_bytes); // Example number of headers
    if (!image_headers) {
        for (size_t i = 0; i < max_packets; ++i) free_packet(buffer[i]);
        free(buffer);
        return -1; // Memory allocation failed
    }

    // Process packets and headers

    // Free resources
    for (size_t i = 0; i < max_packets; ++i) free_packet(buffer[i]);
    free_image_headers(image_headers);
    free(buffer);

    pthread_mutex_destroy(&buffer_mutex);

    return 0;
}
