} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node, *LinkedList;

int create_crc_indication_list(int N, LinkedList* list) {
    if (N < MIN_N || N > MAX_N) {
        return -1; // Invalid range
    }

    srand(time(NULL)); // Seed for random generation

    *list = NULL;
    Node** current = &(*list);

    for (int i = 0; i < N; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            // Handle memory allocation failure
            free_list(*list);
            return -1;
        }

        newNode->data.ue_info_tag = generate_ue_info_tag(); // Implement as needed
        newNode->data.rnti = generate_rnti(); // Implement as needed
        newNode->data.crc_indication_rel8.CRCFLAG = rand() % 2; // Randomly generated

        newNode->next = NULL;
        *current = newNode;
        current = &newNode->next;
    }

    return 0; // Success
}

void free_list(LinkedList list) {
    Node* temp;
    while (list != NULL) {
        temp = list;
        list = list->next;
        free(temp);
    }
}
