typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_linked_list(int N, int seed_range) {
    if (N <= 0 || seed_range <= 0) {
        printf("Invalid input. N and seed_range must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            printf("Memory allocation failed. Insufficient resources.\n");
            return head;
        }

        new_node->RX_UE_INFORMATION_TAG = i;
        new_node->RNTI = (unsigned short)(i % 65535);
        new_node->CRC_INDICATION_REL8_TAG = i % 127;
        new_node->CRCFLAG = rand() % seed_range;

        if (head == NULL) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <number_of_structures> <seed_range>\n", argv[0]);
        return 1;
    }

    int N = atoi(argv[1]);
    int seed_range = atoi(argv[2]);

    NFAPI_CRC_INDICATION_PDU_T* head = create_and_populate_linked_list(N, seed_range);

    if (head != NULL) {
        // Traverse and modify the linked list here
        free_linked_list(head);
    }

    return 0;
}
