// Function to dynamically allocate and initialize a list of ImageMetaData structures
ImageMetaData* allocateImages(int configValue, size_t *imageSize) {
    FILE *configFile = fopen("config.txt", "r");
    if (configFile == NULL) {
        perror("Error opening config file");
        return NULL;
    }

    // Read the configuration value from the file
    fscanf(configFile, "%d", &configValue);
    fclose(configFile);

    // Allocate memory for the ImageMetaData structures
    *imageSize = sizeof(ImageMetaData) * configValue;
    if (*imageSize < configValue) {
        perror("Integer overflow detected");
        return NULL;
    }

    ImageMetaData* images = (ImageMetaData*)malloc(*imageSize);
    if (images == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize each ImageMetaData structure
    for (int i = 0; i < configValue; i++) {
        images[i].width = 0;
        images[i].height = 0;
        images[i].format = NULL;
        images[i].imageData = NULL;
    }

    return images;
}

// Function to deallocate the ImageMetaData structures
void freeImages(ImageMetaData* images, size_t imageSize) {
    if (images != NULL) {
        for (int i = 0; i < imageSize / sizeof(ImageMetaData); i++) {
            // Free any allocated memory for imageData and format
            if (images[i].imageData != NULL) {
                free(images[i].imageData);
            }
            if (images[i].format != NULL) {
                free(images[i].format);
            }
        }
        free(images);
    }
}

int main() {
    size_t imageSize;
    ImageMetaData* images = allocateImages(10, &imageSize); // Example allocation for 10 images

    if (images != NULL) {
        // Use the allocated images
        freeImages(images, imageSize); // Free the allocated images when done
