#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEM_LIMIT 1024 * 1024 // Example limit in bytes

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int n) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int current_memory_usage = 0;
    static int max_memory_limit = MAX_MEM_LIMIT;

    if (n * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_memory_limit - current_memory_usage) {
        printf("Memory allocation limit exceeded. Current usage: %d, Requested: %d\n", current_memory_usage, n);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        printf("Failed to allocate memory for %d structures.\n", n);
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    current_memory_usage += n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&mutex);

    // Populate pdus with random data
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        pdus[i].ue_info = rand();
        pdus[i].rnti = rand() & 0xFFFF;
        pdus[i].crc_indication.crcflag = (rand() % 2) ? 1 : 0;
    }

    printf("Successfully allocated and populated %d structures.\n", n);
    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, int n) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int current_memory_usage = 0;

    pthread_mutex_lock(&mutex);
    if (current_memory_usage < n * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Invalid memory deallocation attempt. Current usage: %d, Attempted to free: %d\n", current_memory_usage, n);
    } else {
        current_memory_usage -= n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        free(pdus);
        printf("Successfully freed %d structures.\n", n);
    }
    pthread_mutex_unlock(&mutex);
}
