        fprintf(stderr, "Invalid JSON format in configuration file\n");
        fclose(config_fp);
        return NULL;
    }

    // Read the number of files from the manifest
    FILE* manifest_fp = fopen(manifest_file, "r");
    if (!manifest_fp) {
        perror("Failed to open manifest file");
        json_object_put(config_json);
        fclose(config_fp);
        return NULL;
    }

    int num_files = fscanf(manifest_fp, "%d", &num_files);
    if (num_files != 1) {
        fprintf(stderr, "Invalid format in manifest file\n");
        fclose(manifest_fp);
        json_object_put(config_json);
        fclose(config_fp);
        return NULL;
    }

    // Dynamically allocate memory for the list of multimedia metadata
    MultimediaMetadata* metadata_list = (MultimediaMetadata*)malloc(num_files * sizeof(MultimediaMetadata));
    if (!metadata_list) {
        perror("Failed to allocate memory for metadata list");
        fclose(manifest_fp);
        json_object_put(config_json);
        fclose(config_fp);
        return NULL;
    }

    // Initialize the multimedia metadata
    for (int i = 0; i < num_files; i++) {
        char file_path[256];
        int type;

        fscanf(manifest_fp, "%s %d", file_path, &type);

        strcpy(metadata_list[i].file_path, file_path);
        metadata_list[i].type = type;

        if (type == 0) { // Image
            json_object* img_data_json = json_object_array_get_idx(config_json, i * 2 + 1);
            int width = json_object_get_int(json_object_array_get_idx(img_data_json, 0));
            int height = json_object_get_int(json_object_array_get_idx(img_data_json, 1));
            metadata_list[i].data.img_data.width = width;
            metadata_list[i].data.img_data.height = height;
        } else if (type == 1) { // Audio
            json_object* aud_data_json = json_object_array_get_idx(config_json, i * 2 + 1);
            int channels = json_object_get_int(json_object_array_get_idx(aud_data_json, 0));
            int sample_rate = json_object_get_int(json_object_array_get_idx(aud_data_json, 1));
            metadata_list[i].data.aud_data.channels = channels;
            metadata_list[i].data.aud_data.sample_rate = sample_rate;
        } else {
            fprintf(stderr, "Invalid metadata type\n");
            free(metadata_list);
            fclose(manifest_fp);
            json_object_put(config_json);
            fclose(config_fp);
            return NULL;
        }
    }

    fclose(manifest_fp);
    json_object_put(config_json);
    fclose(config_fp);

    return metadata_list;
}

// Function to free the allocated memory
void free_multimedia_metadata(MultimediaMetadata* metadata_list, int num_files) {
    free(metadata_list);
}
