typedef struct {
    uint32_t header_size;
    uint8_t *data;
} Header;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    Header headers[MAX_HEADERS];
    int num_headers;
    uint32_t combined_checksum;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaipdu(RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, int num_headers) {
    if (num_headers <= 0 || num_headers > MAX_HEADERS) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Memory allocation failed");
        return NULL;
    }

    pdu->ue_info_tag = ue_info_tag;
    pdu->rnti = rnti;
    pdu->num_headers = num_headers;
    pdu->combined_checksum = 0;

    for (int i = 0; i < num_headers; i++) {
        pdu->headers[i].data = malloc(sizeof(uint8_t) * HEADER_SIZE);
        if (!pdu->headers[i].data) {
            perror("Memory allocation failed");
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(pdu->headers[j].data);
            }
            free(pdu);
            return NULL;
        }
        pdu->headers[i].header_size = HEADER_SIZE;

        // Populate header data (e.g., random CRCFLAG)
        for (int j = 0; j < HEADER_SIZE; j++) {
            pdu->headers[i].data[j] = rand() % 256;
        }

        // Update combined checksum
        for (int j = 0; j < HEADER_SIZE; j++) {
            pdu->combined_checksum += pdu->headers[i].data[j];
        }
    }

    return pdu;
}

void free_nfaipdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        for (int i = 0; i < pdu->num_headers; i++) {
            free(pdu->headers[i].data);
        }
        free(pdu);
    }
}

int main() {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti = 12345;
    int num_headers = 3;

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_nfaipdu(ue_info_tag, rnti, num_headers);
    if (pdu) {
        printf("NFAPI CRC Indication PDU created successfully.\n");
        free_nfaipdu(pdu);
    } else {
        printf("Failed to create NFAPI CRC Indication PDU.\n");
    }

    return 0;
}
