typedef struct {
    uint32_t size;
    void* payload;
} PacketHeader;

PacketHeader** process_packets(uint32_t packet_sizes[], int num_packets) {
    if (num_packets <= 0 || packet_sizes == NULL) {
        return NULL;
    }

    // Calculate total estimated size, handling integer overflow
    uint64_t total_size = 0;
    for (int i = 0; i < num_packets; ++i) {
        if (total_size > UINT32_MAX - packet_sizes[i]) {
            fprintf(stderr, "Error: Integer overflow in total packet size.\n");
            return NULL;
        }
        total_size += packet_sizes[i];
    }

    // Allocate memory for the list of PacketHeader structures
    PacketHeader** packet_headers = (PacketHeader**)malloc(num_packets * sizeof(PacketHeader*));
    if (packet_headers == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for packet headers.\n");
        return NULL;
    }

    // Allocate memory for each packet's payload and fill in the header
    for (int i = 0; i < num_packets; ++i) {
        packet_headers[i] = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (packet_headers[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for packet payload %d.\n", i);
            // Clean up previously allocated headers
            for (int j = 0; j < i; ++j) {
                free(packet_headers[j]);
            }
            free(packet_headers);
            return NULL;
        }

        packet_headers[i]->size = packet_sizes[i];
        packet_headers[i]->payload = malloc(packet_sizes[i]);
        if (packet_headers[i]->payload == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for packet payload %d.\n", i);
            // Clean up previously allocated headers and payloads
            for (int j = 0; j <= i; ++j) {
                free(packet_headers[j]->payload);
                free(packet_headers[j]);
            }
            free(packet_headers);
            return NULL;
        }
    }

    return packet_headers;
}

