#define MAX_MEMORY 1024 * 1024 // 1 MB
#define MAX_STRUCTURES_PER_SECOND 100

int validate_and_allocate_memory(size_t required_size) {
    static size_t allocated_memory = 0;
    if (allocated_memory + required_size > MAX_MEMORY) {
        fprintf(stderr, "Error: Memory allocation exceeds system limit.\n");
        return -1; // Memory allocation failed
    }
    allocated_memory += required_size;
    return 0; // Memory allocation successful
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_structures(const char* input_string) {
    size_t num_structures = strlen(input_string);
    size_t required_size = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (validate_and_allocate_memory(required_size) != 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_size);
    if (!structures) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        validate_and_allocate_memory(-required_size); // Undo allocation
        return NULL;
    }

    srand((unsigned int)time(NULL) + strlen(input_string));
    for (size_t i = 0; i < num_structures; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        structures[i].RNTI = rand() % 65536;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        structures[i].CRCFLAG = (rand() % 2) == 0 ? 1 : 0; // Pseudo-random CRCFLAG
    }

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures, size_t num_structures) {
    validate_and_allocate_memory(-num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(structures);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_string>\n", argv[0]);
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = create_and_populate_structures(argv[1]);
    if (!structures) {
        return 1;
    }

    // Process the structures
    for (size_t i = 0; i < strlen(argv[1]); ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               structures[i].RX_UE_INFORMATION_TAG,
               structures[i].RNTI,
               structures[i].CRC_INDICATION_REL8_TAG,
               structures[i].CRCFLAG);
    }

    free_structures(structures, strlen(argv[1]));
    return 0;
}
