#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 0.95 // 95% of total system memory

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int CRCFLAG;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeStructures(int N, int seed_start, int seed_end) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        newNode->data.CRCFLAG = rand() % (seed_end - seed_start + 1) + seed_start;
        newNode->data.RX_UE_INFORMATION_TAG = i;
        newNode->data.RNTI = i * 2;
        newNode->data.CRC_INDICATION_REL8_TAG = i * 3;
        newNode->next = NULL;

        pthread_mutex_lock(&mutex);
        if (head == NULL) {
            head = newNode;
        } else {
            Node* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
        capacity++;
        pthread_mutex_unlock(&mutex);
    }
}

void resizeList(int newCapacity) {
    Node* oldHead = head;
    capacity = newCapacity;

    head = NULL;
    for (int i = 0; i < capacity; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        pthread_mutex_lock(&mutex);
        if (head == NULL) {
            head = newNode;
        } else {
            Node* temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Copy data from old list to new list
    Node* currentOld = oldHead;
    Node* currentNew = head;
    while (currentOld != NULL && currentNew != NULL) {
        currentNew->data = currentOld->data;
        currentNew = currentNew->next;
        currentOld = currentOld->next;
    }

    // Free the old list
    currentOld = oldHead;
    Node* temp;
    while (currentOld != NULL) {
        temp = currentOld;
        currentOld = currentOld->next;
        free(temp);
    }
}

void* monitorMemory(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        double memoryUsage = (double)capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) / MAX_MEMORY_USAGE;
        if (memoryUsage >= 1.0) {
            printf("Warning: Memory usage is approaching maximum capacity\n");
        }
        pthread_mutex_unlock(&mutex);
        sleep(1); // Check every second
    }
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <N> <seed_start> <seed_end>\n", argv[0]);
        exit(1);
    }

    int N = atoi(argv[1]);
    int seed_start = atoi(argv[2]);
    int seed_end = atoi(argv[3]);

    initializeStructures(N, seed_start, seed_end);

    pthread_t monitorThread;
    pthread_create(&monitorThread, NULL, monitorMemory, NULL);

    // Simulate concurrent access
    for (int i = 0; i < N; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, resizeList, (void*)(i + N));
        pthread_join(thread, NULL);
    }

    pthread_join(monitorThread, NULL);

    return 0;
}
```

This code snippet provides a basic implementation of the described task. It includes a function to initialize structures with random values, a dynamic resizing feature, and a memory monitoring thread. Note that this is a simplified example for demonstration purposes and may require additional features and error handling for production use.']

