#define MAX_FILE_SIZE (1024 * 1024 * 1024) // 1 GB in bytes

typedef struct {
    long long total_size;
    int file_count;
} DirectoryInfo;

DirectoryInfo process_directory(const char* directory_path) {
    DirectoryInfo info = {0, 0};
    DIR* dir;
    struct dirent* entry;

    dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Error opening directory");
        return info;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char file_path[1024];
            snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

            FILE* file = fopen(file_path, "rb");
            if (file == NULL) {
                perror("Error opening file");
                continue;
            }

            fseek(file, 0, SEEK_END);
            long long size = ftell(file);
            fclose(file);

            if (size > MAX_FILE_SIZE) {
                printf("File %s exceeds maximum allowed size\n", entry->d_name);
                continue;
            }

            // Check for potential integer overflow
            if ((LLONG_MAX - info.total_size) < size) {
                printf("Total size would exceed LLONG_MAX, partial processing required\n");
                break; // Handle partial processing here
            }

            info.total_size += size;
            info.file_count++;
        }
    }

    closedir(dir);
    return info;
}

int main() {
    DirectoryInfo result = process_directory("/path/to/large/directory");
    printf("Total size of files: %lld bytes\n", result.total_size);
    printf("Number of files processed: %d\n", result.file_count);
    return 0;
}
