// Define PacketHeaderInfo structure
typedef struct PacketHeaderInfo {
    size_t length;
    double timestamp;
    int checksumValid;
    struct PacketHeaderInfo* next;
} PacketHeaderInfo;

// Function to process incoming packets and populate linked list
void processPackets(PacketHeaderInfo** head, size_t* count, size_t maxCount) {
    // Simulate receiving a packet (in practice, this would be from network)
    PacketHeaderInfo* newPacket = malloc(sizeof(PacketHeaderInfo));
    if (!newPacket) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Populate new packet with simulated data
    newPacket->length = 1500; // Example packet length
    newPacket->timestamp = 1633072800.0; // Current timestamp (example)
    newPacket->checksumValid = 1; // Example checksum status
    newPacket->next = NULL;

    // Add new packet to linked list
    if (*head == NULL) {
        *head = newPacket;
    } else {
        PacketHeaderInfo* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newPacket;
    }

    // Increment count and check for maximum size
    (*count)++;
    if (*count > maxCount) {
        fprintf(stderr, "Packet list exceeds maximum size\n");
        PacketHeaderInfo* overflow = *head;
        *head = (*head)->next;
        free(overflow);
        (*count)--;
    }
}

int main() {
    // Example usage
    PacketHeaderInfo* packetList = NULL;
    size_t packetCount = 0;
    size_t maxPacketCount = 100;

    for (size_t i = 0; i < 150; i++) {
        processPackets(&packetList, &packetCount, maxPacketCount);
    }

    // Clean up
    PacketHeaderInfo* current = packetList;
    while (current != NULL) {
        PacketHeaderInfo* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
```

