#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_FILE_PATHS 100
#define SYSTEM_LIMIT (size_t)(INT_MAX / sizeof(char))

typedef struct {
    char **contents;
    size_t *sizes;
    size_t count;
} FileBuffer;

int process_file_paths(const char *paths[], int num_paths, char **buffer, size_t *total_size) {
    if (num_paths > MAX_FILE_PATHS) {
        fprintf(stderr, "Error: Too many file paths provided.\n");
        return -1;
    }

    FileBuffer file_buffers[MAX_FILE_PATHS];
    for (int i = 0; i < num_paths; ++i) {
        FILE *file = fopen(paths[i], "r");
        if (!file) {
            fprintf(stderr, "Error: Unable to open file %s.\n", paths[i]);
            return -1;
        }

        fseek(file, 0L, SEEK_END);
        size_t size = ftell(file);
        if (size > SIZE_MAX || *total_size + size > SYSTEM_LIMIT) {
            fprintf(stderr, "Error: File size exceeds system limit or causes overflow.\n");
            fclose(file);
            return -1;
        }
        fseek(file, 0L, SEEK_SET);

        char *content = malloc(size + 1);
        if (!content) {
            fprintf(stderr, "Error: Memory allocation failed for file %s.\n", paths[i]);
            fclose(file);
            return -1;
        }

        size_t read_size = fread(content, sizeof(char), size, file);
        if (read_size != size) {
            fprintf(stderr, "Error: Failed to read entire content from file %s.\n", paths[i]);
            free(content);
            fclose(file);
            return -1;
        }
        content[size] = '\0';

        file_buffers[i].contents = &content;
        file_buffers[i].sizes = &size;
        *total_size += size;
    }

    *buffer = malloc(*total_size + 1);
    if (!*buffer) {
        fprintf(stderr, "Error: Memory allocation failed for total buffer.\n");
        for (int i = 0; i < num_paths; ++i) {
            free(file_buffers[i].contents[0]);
        }
        return -1;
    }

    char *current = *buffer;
    for (int i = 0; i < num_paths; ++i) {
        memcpy(current, file_buffers[i].contents[0], *file_buffers[i].sizes);
        current += *file_buffers[i].sizes;
    }
    *current = '\0';

    for (int i = 0; i < num_paths; ++i) {
        free(file_buffers[i].contents[0]);
    }

    return 0;
}
```

This code snippet defines a function `process_file_paths` that takes an array of file paths, the number of paths, and pointers to store the combined buffer and total size. It reads each file into its own dynamically allocated buffer, calculates the total size, and ensures that the allocation does not exceed a system-wide limit. If any errors occur during file opening, reading, or memory allocation, it returns an appropriate error code and logs the issue. The function handles potential integer overflows by checking if the cumulative size exceeds the allowed limit before allocating memory.']

