#define MAX_UES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // Add other necessary fields here
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* process_directory(const char* directory_path, sem_t** semaphore) {
    DIR *dir;
    struct dirent *entry;
    long total_size = 0;
    NFAPI_CRC_INDICATION_PDU_T* ues[MAX_UES];
    int num_ues = 0;

    if ((dir = opendir(directory_path)) == NULL) {
        perror("opendir");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        struct stat file_stat;

        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);
        if (lstat(file_path, &file_stat) == -1) {
            perror("lstat");
            continue;
        }

        if (S_ISREG(file_stat.st_mode)) {
            total_size += file_stat.st_size;

            if (total_size > 2147483647) { // Check for potential integer overflow
                printf("Potential integer overflow detected. Partial processing required.\n");
                closedir(dir);
                return NULL;
            }

            ues[num_ues] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (ues[num_ues] == NULL) {
                perror("malloc");
                continue;
            }

            // Initialize and populate the structure here
            ues[num_ues]->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
            ues[num_ues]->RNTI = rand() % 4096; // Example initialization

            num_ues++;
        }
    }

    closedir(dir);

    *semaphore = sem_open("ue_semaphore", O_CREAT, 0644, MAX_UES);
    if (*semaphore == SEM_FAILED) {
        perror("sem_open");
        return NULL;
    }

    for (int i = 0; i < num_ues; i++) {
        if (sem_wait(*semaphore) == -1) {
            perror("sem_wait");
            free(ues[i]);
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (result == NULL) {
        perror("malloc");
        return NULL;
    }

    for (int i = 0; i < num_ues; i++) {
        memcpy(&result[i], ues[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(ues[i]);
    }

    sem_close(*semaphore);
    sem_unlink("ue_semaphore");

    return result;
}
