size_t calculate_memory_size(size_t N) {
    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_size / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Integer overflow in memory size calculation.\n");
        return 0;
    }
    return required_size;
}

int populate_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % (MAX_TAG_VALUE - MIN_TAG_VALUE + 1) + MIN_TAG_VALUE;
        if (array[i].RX_UE_INFORMATION_TAG < MIN_TAG_VALUE || array[i].RX_UE_INFORMATION_TAG > MAX_TAG_VALUE) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG value: %u\n", array[i].RX_UE_INFORMATION_TAG);
            return -1;
