    size_t max_attempts = 3;
    for (size_t attempt = 1; attempt <= max_attempts; ++attempt) {
        size_t required_size = calculate_memory_size(N);
        if (!required_size) {
            continue;
        }

        *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_size);
        if (*array == NULL) {
            fprintf(stderr, "Memory allocation failed for attempt %zu.\n", attempt);
            continue;
        }

        int result = populate_array(*array, N);
        if (result != 0) {
            free(*array);
            *array = NULL;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to allocate memory after %zu attempts.\n", max_attempts);
    return -1; // Failure
}

int main() {
