    size_t N = 100; // Example size
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    int result = allocate_and_populate_array(N, &array);
    if (result != 0) {
        fprintf(stderr, "Failed to allocate and populate array.\n");
        return EXIT_FAILURE;
    }

    // Use the array...

