#include <stdlib.h>
#include <stdint.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int32_t CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* create_crc_list(size_t N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST *)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            // Handle memory allocation failure
            free_crc_list(list);
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = (uint8_t)(rand() % 256); // Random value within byte range
        new_node->RNTI = (uint16_t)(rand() % 0xFFFF); // Random RNTI value
        new_node->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256); // Random value within byte range
        new_node->CRCFLAG = rand() % 2; // Random CRC flag: 0 or 1

        new_node->next = NULL;

        if (list->head == NULL) {
            list->head = list->tail = new_node;
        } else {
            list->tail->next = new_node;
            list->tail = new_node;
        }

        ++(list->count);
    }

    return list;
}

void free_crc_list(NFAPI_CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

void print_crc_list(NFAPI_CRC_LIST *list) {
    if (!list || !list->head) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG, current->CRCFLAG);
        current = current->next;
    }
}

void reset_crc_list(NFAPI_CRC_LIST *list) {
    free_crc_list(list);
    list->head = list->tail = NULL;
    list->count = 0;
}
```

This code defines a `NFAPI_CRC_INDICATION_PDU_T` structure for the linked list elements and an `NFAPI_CRC_LIST` structure to manage the linked list. The `create_crc_list` function dynamically creates and populates the linked list with up to `N` elements, each containing random values within specified ranges for `RX_UE_INFORMATION_TAG`, `RNTI`, and `CRC_INDICATION_REL8_TAG`. It also handles memory allocation failures by freeing previously allocated nodes. The `free_crc_list` function frees all allocated memory for the entire linked list, ensuring proper resource deallocation. The `print_crc_list` function iterates through the linked list and prints details of each node, avoiding significant performance bottlenecks. Finally, the `reset_crc_list` function resets the linked list by freeing all allocated memory and resetting pointers to NULL.']

