#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_STREAMS 1024

typedef struct StreamMetadata {
    uint32_t stream_id;
    uint64_t start_time;
    uint64_t duration;
    struct StreamMetadata *next;
} StreamMetadata;

StreamMetadata *stream_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void process_udp_packet(uint8_t *packet, int packet_size) {
    // Parse the UDP packet to extract metadata
    uint32_t stream_id = *(uint32_t *)packet;
    uint64_t start_time = *(uint64_t *)(packet + sizeof(uint32_t));
    uint64_t duration = *(uint64_t *)(packet + sizeof(uint32_t) + sizeof(uint64_t));

    // Validate metadata
    if (stream_id == 0 || start_time > UINT64_MAX - duration || duration == 0) {
        return;
    }

    // Allocate memory for new stream metadata
    StreamMetadata *new_stream = malloc(sizeof(StreamMetadata));
    if (!new_stream) {
        perror("Failed to allocate memory for new stream");
        return;
    }
    new_stream->stream_id = stream_id;
    new_stream->start_time = start_time;
    new_stream->duration = duration;
    new_stream->next = NULL;

    // Lock the list mutex
    pthread_mutex_lock(&list_mutex);

    // Add new stream to the list
    if (!stream_list) {
        stream_list = new_stream;
    } else {
        StreamMetadata *current = stream_list;
        while (current->next) {
            current = current->next;
        }
        current->next = new_stream;
    }

    // Unlock the list mutex
    pthread_mutex_unlock(&list_mutex);

    // Save to database
    save_to_database(new_stream);
}

void save_to_database(StreamMetadata *stream) {
    // Simulate database operation
    printf("Saving stream %u to database\n", stream->stream_id);
}

int main() {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to create socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    if (bind(sockfd, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        return -1;
    }

    printf("Listening for incoming UDP packets...\n");

    while (1) {
        uint8_t buffer[1024];
        int packet_size = recvfrom(sockfd, buffer, sizeof(buffer), MSG_WAITALL, (struct sockaddr *)&client_addr, &addr_len);
        if (packet_size > 0) {
            process_udp_packet(buffer, packet_size);
        }
    }

    close(sockfd);
    return 0;
}
