typedef struct ImageMetadata {
    char filePath[MAX_FILENAME_LENGTH];
    size_t requestedSize;
} ImageMetadata;

typedef struct MetadataList {
    ImageMetadata* entries;
    size_t count;
    size_t capacity;
    size_t maxMemory footprint;
} MetadataList;

int addImageMetadata(MetadataList* list, const char* filePath, size_t requestedSize) {
    // Input validation
    if (list == NULL || filePath == NULL || requestedSize < MIN_REQUESTED_SIZE || requestedSize > MAX_REQUESTED_SIZE) {
        return -1; // Invalid input
    }

    // Check if adding this entry would exceed the maximum memory footprint
    size_t newMemoryFootprint = list->count * sizeof(ImageMetadata);
    if (newMemoryFootprint + sizeof(ImageMetadata) > list->maxMemoryFootprint) {
        return -2; // Exceeds max memory limit
    }

    // Resize the list if needed
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity == 0 ? 4 : list->capacity * 2;
        ImageMetadata* newEntries = realloc(list->entries, newCapacity * sizeof(ImageMetadata));
        if (newEntries == NULL) {
            return -3; // Memory allocation failed
        }
        list->entries = newEntries;
        list->capacity = newCapacity;
    }

    // Add the new entry
    strcpy(list->entries[list->count].filePath, filePath);
    list->entries[list->count].requestedSize = requestedSize;
    list->count++;
    return 0; // Success
}

int main() {
    MetadataList metadataList = {NULL, 0, 0, 1024 * 1024 * 1024}; // 1 GB max memory footprint

    if (addImageMetadata(&metadataList, "path/to/image.jpg", 500) != 0) {
        printf("Failed to add image metadata.\n");
    }

    // Clean up
    free(metadataList.entries);

    return 0;
}
