#define MAX_SIZE 1024 * 1024 // Example maximum memory size

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    INVALID_INPUT,
    INSUFFICIENT_MEMORY
} AllocationStatus;

AllocationStatus allocate_ue_information_pdu_array(int N, void** array_ptr, size_t* allocated_size) {
    if (N <= 0 || MAX_SIZE <= 0) {
        return INVALID_INPUT;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t aligned_struct_size = ((struct_size + sizeof(void*) - 1) / sizeof(void*)) * sizeof(void*);

    if (aligned_struct_size == 0) {
        return INVALID_INPUT; // Handle potential integer overflow or alignment issues
    }

    size_t total_required_memory = N * aligned_struct_size;
    if (total_required_memory > MAX_SIZE || total_required_memory < N * struct_size) {
        return INSUFFICIENT_MEMORY;
    }

    void* allocated_memory = malloc(total_required_memory);
    if (!allocated_memory) {
        return INSUFFICIENT_MEMORY; // Handle memory allocation failure
    }

