#define MAX_LIST_SIZE 1024
#define PADDING_FACTOR 2

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

ListNode* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void initDynamicLinkedList(int num_elements, ListNode** head) {
    *head = NULL;
    int required_memory = (num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T) + PADDING_FACTOR) * sizeof(ListNode);
    if (required_memory > MAX_LIST_SIZE * sizeof(ListNode)) {
        printf("Memory overflow\n");
        return;
    }

    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T data = { /* Initialize your fields here */ };
        ListNode* newNode = createNode(data);
        if (!newNode) continue;

        newNode->next = *head;
        *head = newNode;
    }
}

void addElementToList(ListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = createNode(data);
    if (!newNode) return;

    newNode->next = *head;
    *head = newNode;
}

void removeElementFromList(ListNode** head, int RNTI) {
    ListNode* current = *head;
    ListNode* previous = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (previous != NULL)
                previous->next = current->next;
            else
                *head = current->next;
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void iterateThroughList(ListNode* head) {
    ListNode* current = head;
    while (current != NULL) {
        // Process each element here
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG);
        current = current->next;
    }
}

void freeDynamicLinkedList(ListNode** head) {
    ListNode* current = *head;
    ListNode* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}
