#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int current_elements = 0;
pthread_mutex_t mutex;

void initialize_linked_list() {
    pthread_mutex_init(&mutex, NULL);
}

int add_element_to_list(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&mutex);
    if (current_elements >= MAX_ELEMENTS) {
        printf("Error: Maximum elements limit reached.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    current_elements++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

void* process_packets(void* arg) {
    int rx_tag, rnti;
    // Simulate packet processing logic
    for (int i = 0; i < 100; i++) {
        rx_tag = rand() % 1000;
        rnti = rand() % 500;
        add_element_to_list(rx_tag, rnti);
    }
    return NULL;
}

int main() {
    initialize_linked_list();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_packets, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total elements added: %d\n", current_elements);

    // Clean up
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
